INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01','DA-01','Device Alarm','Device beeps, red light flashing; software shows "Test Card Expired"/"Chip Expired"','ម៉ាស៊ីនរោទិ៍ ភ្លើងក្រហមលោត ហើយអេក្រង់បង្ហាញ «Test Card Expired» ឬ «Chip Expired»។ ត្រូវធ្វើម៉េច?','Discard the card and use a new, non-expired card','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q01','DA-01','Device Alarm','The device says "Test Card Expired" — what should I do?','ម៉ាស៊ីនបង្ហាញ "Test Card Expired"។ ត្រូវធ្វើម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q02','DA-01','Device Alarm','Can I still use a reaction card that''s past its expiry date?','តើខ្ញុំនៅតែអាចប្រើកាតប្រតិកម្មដែលផុតកំណត់បានទេ?','No. The test can''t run on an expired card. Discard it and use a new, non-expired card.','មិនបានទេ។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q03','DA-01','Device Alarm','chip expired error','អេក្រង់ឡើង «Chip Expired»។ ត្រូវធ្វើម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q04','DA-01','Device Alarm','My card is only a few days out of date, will the test still run?','កាតរបស់ខ្ញុំផុតកំណត់តែប៉ុន្មានថ្ងៃទេ តើនៅតែធ្វើតេស្តបានទេ?','No. The test can''t run on an expired card. Discard it and use a new, non-expired card.','មិនបានទេ។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q05','DA-01','Device Alarm','Red light starts flashing right after I insert the card and the software mentions expiry. Help?','ដាក់កាតចូលភ្លាម ភ្លើងក្រហមក៏លោត ហើយកម្មវិធីប្រាប់ថាកាតផុតកំណត់។ ត្រូវធ្វើម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q06','DA-01','Device Alarm','card expired wat do','កាតផុតកំណត់ ធ្វើម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q07','DA-01','Device Alarm','Test Card Expired','«Test Card Expired» មានន័យថាម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q08','DA-01','Device Alarm','I''m new — the screen says the chip expired. What''s the next step?','ខ្ញុំទើបប្រើ Pluslife។ អេក្រង់បង្ហាញថា chip ផុតកំណត់។ ជំហានបន្ទាប់ធ្វើអ្វី?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q09','DA-01','Device Alarm','The reagent card is out of date — what now?','កាតប្រតិកម្មផុតកំណត់ — ឥឡូវធ្វើម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q10','DA-01','Device Alarm','Red light, beeping, something about expiry on the screen.','ភ្លើងក្រហម សំឡេងប៊ីប មានអ្វីមួយនិយាយពីផុតកំណត់លើអេក្រង់។ ត្រូវធ្វើម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q11','DA-01','Device Alarm','card is expire, device not test, how to do?','កាតផុតកំណត់ ម៉ាស៊ីនមិនធ្វើតេស្ត ធ្វើម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q12','DA-01','Device Alarm','Inserted a card and got an expiry warning. Should I try a different card?','ដាក់កាតហើយ ចេញសារព្រមានផុតកំណត់។ តើគួរសាកកាតផ្សេងទេ?','Yes. Discard the expired card and use a new, non-expired card.','បាទ/ចាស។ បោះចោលកាតដែលផុតកំណត់ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q13','DA-01','Device Alarm','So if the chip has expired I just throw it away and use a new one?','មានន័យថា បើ chip ផុតកំណត់ ខ្ញុំគ្រាន់តែបោះចោល ហើយប្រើកាតថ្មី?','Yes. Discard the expired card and use a new, non-expired card.','បាទ/ចាស។ បោះចោលកាតដែលផុតកំណត់ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q14','DA-01','Device Alarm','Software shows "Chip Expired" after I insert the card. What do I do?','កម្មវិធីបង្ហាញ "Chip Expired" ក្រោយខ្ញុំដាក់កាត។ ត្រូវធ្វើម៉េច?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q15','DA-01','Device Alarm','The reaction card is expired. Can I still run the test with it?','កាតប្រតិកម្មផុតកំណត់។ តើនៅតែអាចធ្វើតេស្តជាមួយវាបានទេ?','No. The test can''t run on an expired card. Discard it and use a new, non-expired card.','មិនបានទេ។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q16','DA-01','Device Alarm','What should I do when the device flags an expired test card?','ត្រូវធ្វើអ្វី ពេលម៉ាស៊ីនបង្ហាញថាកាតតេស្តផុតកំណត់?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q17','DA-01','Device Alarm','expired reaction card what to do','កាតប្រតិកម្មផុតកំណត់ ធ្វើអ្វី?','Discard the card and use a new, non-expired card. The test can''t run on an expired card.','បោះចោលកាតនេះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q18','DA-01','Device Alarm','Do I need to replace an expired card with a new one?','តើត្រូវប្តូរកាតផុតកំណត់ ដោយកាតថ្មីទេ?','Yes. Discard the expired card and use a new, non-expired card.','បាទ/ចាស។ បោះចោលកាតដែលផុតកំណត់ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-01-Q19','DA-01','Device Alarm','Is it OK to keep using cards after the expiry date?','តើអាចបន្តប្រើកាតក្រោយថ្ងៃផុតកំណត់បានទេ?','No. The test can''t run on an expired card. Discard it and use a new, non-expired card.','មិនបានទេ។ ម៉ាស៊ីនមិនអាចធ្វើតេស្តលើកាតដែលផុតកំណត់បានទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មីដែលនៅមានសុពលភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02','DA-02','Device Alarm','Device beeps, red light flashing; software shows "Test Card Reuse"/"Chip Duplication"','ដាក់កាតចូលហើយ ម៉ាស៊ីនរោទិ៍ ភ្លើងក្រហមលោត ហើយអេក្រង់បង្ហាញ «Test Card Reuse» ឬ «Chip Duplication»។ ត្រូវធ្វើម៉េច?','Discard used cards immediately after testing; never reinsert a used card','បោះចោលកាតដែលប្រើរួចភ្លាមៗក្រោយធ្វើតេស្ត។ កុំដាក់កាតដែលប្រើរួចចូលម៉ាស៊ីនម្តងទៀតជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02-Q01','DA-02','Device Alarm','I accidentally put a used card back in and now it''s beeping. What now?','ខ្ញុំច្រឡំដាក់កាតប្រើរួចចូលវិញ ហើយឥឡូវវាប៊ីប។ ធ្វើម៉េចទៅ?','This card has already been tested. Remove and discard it, and use a new, unused card. A used card can''t be tested again.','កាតនេះបានធ្វើតេស្តរួចហើយ។ ដកវាចេញ ហើយបោះចោល រួចប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ កាតដែលប្រើរួច មិនអាចធ្វើតេស្តម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02-Q02','DA-02','Device Alarm','chip duplication alarm','ម៉ាស៊ីនរោទិ៍ ហើយបង្ហាញ «Chip Duplication»។ មានន័យថាម៉េច?','This card has already been tested. Remove and discard it, and use a new, unused card. A used card can''t be tested again.','កាតនេះបានធ្វើតេស្តរួចហើយ។ ដកវាចេញ ហើយបោះចោល រួចប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ កាតដែលប្រើរួច មិនអាចធ្វើតេស្តម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02-Q03','DA-02','Device Alarm','card reuse error pls help','ម៉ាស៊ីនបង្ហាញ «Test Card Reuse»។ ត្រូវធ្វើម៉េច?','This card has already been tested. Remove and discard it, and use a new, unused card. A used card can''t be tested again.','កាតនេះបានធ្វើតេស្តរួចហើយ។ ដកវាចេញ ហើយបោះចោល រួចប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ កាតដែលប្រើរួច មិនអាចធ្វើតេស្តម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02-Q04','DA-02','Device Alarm','Test Card Reuse','អេក្រង់ឡើង «Test Card Reuse»។ ត្រូវធ្វើម៉េច?','This card has already been tested. Remove and discard it, and use a new, unused card. A used card can''t be tested again.','កាតនេះបានធ្វើតេស្តរួចហើយ។ ដកវាចេញ ហើយបោះចោល រួចប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ កាតដែលប្រើរួច មិនអាចធ្វើតេស្តម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02-Q05','DA-02','Device Alarm','It''s alarming after I put the same card back in.','វារោទិ៍ក្រោយខ្ញុំដាក់កាតដដែលចូលវិញ។ ត្រូវធ្វើម៉េច?','This card has already been tested. Remove and discard it, and use a new, unused card. A used card can''t be tested again.','កាតនេះបានធ្វើតេស្តរួចហើយ។ ដកវាចេញ ហើយបោះចោល រួចប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ កាតដែលប្រើរួច មិនអាចធ្វើតេស្តម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02-Q06','DA-02','Device Alarm','The duplication alarm won''t go away. Do I need a new card?','សំឡេងរោទិ៍ duplication មិនបាត់។ តើត្រូវប្រើកាតថ្មីទេ?','Yes. This card has already been tested. Discard it and use a new, unused card.','បាទ/ចាស។ កាតនេះបានធ្វើតេស្តរួចហើយ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មីដែលមិនទាន់ប្រើ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02-Q07','DA-02','Device Alarm','Software shows "Chip Duplication". What should I do?','កម្មវិធីបង្ហាញ "Chip Duplication"។ ត្រូវធ្វើម៉េច?','This card has already been tested. Remove and discard it, and use a new, unused card. A used card can''t be tested again.','កាតនេះបានធ្វើតេស្តរួចហើយ។ ដកវាចេញ ហើយបោះចោល រួចប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ កាតដែលប្រើរួច មិនអាចធ្វើតេស្តម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-02-Q08','DA-02','Device Alarm','test card reuse alarm what to do','សំឡេងរោទិ៍ test card reuse ធ្វើម៉េច?','This card has already been tested. Remove and discard it, and use a new, unused card. A used card can''t be tested again.','កាតនេះបានធ្វើតេស្តរួចហើយ។ ដកវាចេញ ហើយបោះចោល រួចប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ កាតដែលប្រើរួច មិនអាចធ្វើតេស្តម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03','DA-03','Device Alarm','Device beeps, red light flashing; software shows "Test Card Scan Timeout"','ម៉ាស៊ីនរោទិ៍ ភ្លើងក្រហមលោត ហើយអេក្រង់បង្ហាញ «Test Card Scan Timeout»។ ត្រូវធ្វើម៉េច?','Inspect the card label/QR code; if damaged, discard and use a new card','ពិនិត្យស្លាក/កូដ QR លើកាត។ បើខូច សូមបោះចោល ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q01','DA-03','Device Alarm','I''m getting "Test Card Scan Timeout" — how do I fix it?','ខ្ញុំជួប "Test Card Scan Timeout" — ដោះស្រាយយ៉ាងម៉េច?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q02','DA-03','Device Alarm','The device can''t read the QR code on my card.','ម៉ាស៊ីនអានកូដ QR លើកាតខ្ញុំមិនបាន?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q03','DA-03','Device Alarm','The label on the card is scratched, will it still work?','ស្លាកលើកាតមានស្នាមកោស តើនៅប្រើបានទេ?','No. A damaged or misapplied label can stop the device from identifying the card. Discard it and use a new card.','មិនបានទេ។ ស្លាកដែលខូច ឬបិទមិនត្រឹមត្រូវ អាចធ្វើឱ្យម៉ាស៊ីនមិនស្គាល់កាត។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q04','DA-03','Device Alarm','scan timeout error','អេក្រង់ឡើង «Test Card Scan Timeout»។ ត្រូវធ្វើម៉េច?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q05','DA-03','Device Alarm','Device beeps with a red light and says it can''t identify the card.','ម៉ាស៊ីនរោទិ៍ ភ្លើងក្រហម ហើយថាមិនស្គាល់កាត?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q06','DA-03','Device Alarm','qr code not reading','កូដ QR អានមិនបាន។ ត្រូវធ្វើម៉េច?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q07','DA-03','Device Alarm','What should I check on the card when it won''t be recognized?','ត្រូវពិនិត្យអ្វីលើកាត ពេលម៉ាស៊ីនមិនស្គាល់វា?','Check the QR code and label: is the code scratched or dirty, or the label misapplied? If so, discard the card and use a new one.','ពិនិត្យកូដ QR និងស្លាក៖ តើកូដមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវទេ? បើដូច្នេះ សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q08','DA-03','Device Alarm','Test Card Scan Timeout','អេក្រង់ឡើង «Test Card Scan Timeout»។ ត្រូវធ្វើម៉េច?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q09','DA-03','Device Alarm','I''m new — the device keeps saying scan timeout. What should I check?','ខ្ញុំទើបប្រើ Pluslife។ ម៉ាស៊ីននៅតែថា scan timeout។ គួរពិនិត្យអ្វី?','Check the QR code and label: is the code scratched or dirty, or the label misapplied? If so, discard the card and use a new one.','ពិនិត្យកូដ QR និងស្លាក៖ តើកូដមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវទេ? បើដូច្នេះ សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q10','DA-03','Device Alarm','The barcode on the cartridge won''t scan.','បាកូដលើកាតស្កែនមិនចូល។ ត្រូវធ្វើម៉េច?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q11','DA-03','Device Alarm','It beeps and times out when reading the card.','វាប៊ីប ហើយ timeout ពេលអានកាត។ ត្រូវធ្វើម៉េច?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q12','DA-03','Device Alarm','card cannot scan, qr code have scratch','កាតស្កែនមិនបាន កូដ QR មានស្នាមកោស','A damaged QR code can''t be read reliably. Discard the card and use a new one.','កូដ QR ដែលខូច មិនអាចអានបានត្រឹមត្រូវទេ។ បោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q13','DA-03','Device Alarm','So if the QR code is damaged I should switch to a new card?','មានន័យថា បើកូដ QR ខូច ខ្ញុំគួរប្តូរកាតថ្មី?','Yes. If the QR code is damaged, discard the card and use a new one.','បាទ/ចាស។ បើកូដ QR ខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q14','DA-03','Device Alarm','Software shows "Test Card Scan Timeout" after I insert the card.','កម្មវិធីបង្ហាញ "Test Card Scan Timeout" ក្រោយខ្ញុំដាក់កាត។ ត្រូវធ្វើម៉េច?','The device can''t read the card''s QR code. It may be scratched or dirty, or the label may be misapplied. Check the QR code and label; if damaged, discard the card and use a new one.','ម៉ាស៊ីនមិនអាចអានកូដ QR លើកាតបានទេ។ កូដអាចមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ ពិនិត្យកូដ QR និងស្លាក។ បើខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q15','DA-03','Device Alarm','The QR code on the reaction card is damaged. What should I do?','កូដ QR លើកាតប្រតិកម្មខូច។ ត្រូវធ្វើម៉េច?','A damaged QR code can''t be read reliably. Discard the card and use a new one.','កូដ QR ដែលខូច មិនអាចអានបានត្រឹមត្រូវទេ។ បោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q16','DA-03','Device Alarm','The card label is peeling off. Can I still use the card?','ស្លាកកាតកំពុងរបក។ តើនៅប្រើកាតនោះបានទេ?','No. A damaged or misapplied label can stop the device from identifying the card. Discard it and use a new card.','មិនបានទេ។ ស្លាកដែលខូច ឬបិទមិនត្រឹមត្រូវ អាចធ្វើឱ្យម៉ាស៊ីនមិនស្គាល់កាត។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q17','DA-03','Device Alarm','card QR code damaged','កូដ QR កាតខូច','A damaged QR code can''t be read reliably. Discard the card and use a new one.','កូដ QR ដែលខូច មិនអាចអានបានត្រឹមត្រូវទេ។ បោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q18','DA-03','Device Alarm','What should I inspect when the device can''t scan the card?','ត្រូវពិនិត្យអ្វី ពេលម៉ាស៊ីនស្កែនកាតមិនបាន?','Check the QR code and label: is the code scratched or dirty, or the label misapplied? If so, discard the card and use a new one.','ពិនិត្យកូដ QR និងស្លាក៖ តើកូដមានស្នាមកោស ឬប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវទេ? បើដូច្នេះ សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-03-Q19','DA-03','Device Alarm','The QR code is scratched — should I use a new card?','កូដ QR មានស្នាមកោស — គួរប្រើកាតថ្មីទេ?','Yes. If the QR code is damaged, discard the card and use a new one.','បាទ/ចាស។ បើកូដ QR ខូច សូមបោះចោលកាត ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04','DA-04','Device Alarm','Device beeps, red light flashing; software shows "Card Inserted But Lid Not Closed"','ដាក់កាតចូលហើយ ម៉ាស៊ីនរោទិ៍ ភ្លើងក្រហមលោត ហើយអេក្រង់បង្ហាញ «Card Inserted But Lid Not Closed»។ ត្រូវធ្វើម៉េច?','Close the device lid immediately after inserting the card (right after the first beep)','បិទគម្របម៉ាស៊ីនភ្លាមៗក្រោយដាក់កាតចូល (ភ្លាមក្រោយសំឡេងប៊ីបលើកទី១)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q01','DA-04','Device Alarm','The device says "Card Inserted But Lid Not Closed".','ម៉ាស៊ីនបង្ហាញ "Card Inserted But Lid Not Closed"។ ត្រូវធ្វើម៉េច?','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q02','DA-04','Device Alarm','lid not closed alarm','សំឡេងរោទិ៍គម្របមិនបិទ','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q03','DA-04','Device Alarm','Device alarms about the lid even though the card is in correctly.','ម៉ាស៊ីនរោទិ៍ពីគម្រប ទោះបីដាក់កាតត្រឹមត្រូវក៏ដោយ។ ត្រូវធ្វើម៉េច?','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q04','DA-04','Device Alarm','Card Inserted But Lid Not Closed','អេក្រង់ឡើង «Card Inserted But Lid Not Closed»។ ត្រូវធ្វើម៉េច?','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q05','DA-04','Device Alarm','The cover isn''t shut and the device is beeping.','គម្របមិនទាន់បិទ ហើយម៉ាស៊ីនកំពុងប៊ីប។ ត្រូវធ្វើម៉េច?','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q06','DA-04','Device Alarm','Something about the lid on screen, red light flashing.','មានអ្វីមួយនិយាយពីគម្របលើអេក្រង់ ភ្លើងក្រហមលោត។ ត្រូវធ្វើម៉េច?','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q07','DA-04','Device Alarm','lid open alarm, card already inside','រោទិ៍គម្របបើក កាតនៅខាងក្នុងហើយ','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q08','DA-04','Device Alarm','Software shows "Card Inserted But Lid Not Closed". What do I do?','កម្មវិធីបង្ហាញ "Card Inserted But Lid Not Closed"។ ធ្វើម៉េច?','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q09','DA-04','Device Alarm','The device beeps and flashes red because the lid is open. What should I do?','ម៉ាស៊ីនរោទិ៍ ហើយភ្លើងក្រហមលោត ព្រោះគម្របបើក។ ត្រូវធ្វើម៉េច?','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q10','DA-04','Device Alarm','lid alarm after inserting card','រោទិ៍គម្របក្រោយដាក់កាត','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-04-Q11','DA-04','Device Alarm','How do I stop the lid-not-closed alarm?','ធ្វើម៉េចឱ្យឈប់រោទិ៍គម្របមិនបិទ?','Close the lid now. The test only starts with the lid closed, and becomes invalid if the lid stays open for more than about 30 seconds.','បិទគម្របឥឡូវនេះ។ តេស្តចាប់ផ្តើមតែពេលគម្របបិទប៉ុណ្ណោះ ហើយតេស្តនឹងគ្មានសុពលភាព បើគម្របនៅបើកលើសពីប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05','DA-05','Device Alarm','Device beeps, red light flashing; software shows "Test Item Not Supported"','ម៉ាស៊ីនរោទិ៍ ភ្លើងក្រហមលោត ហើយអេក្រង់បង្ហាញ «Test Item Not Supported»។ ត្រូវធ្វើម៉េច?','Update firmware using the "Arrow of Update" icon shown on the device card in the software','ធ្វើបច្ចុប្បន្នភាព Firmware ដោយចុចរូបព្រួញ "Arrow of Update" ដែលបង្ហាញលើកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q01','DA-05','Device Alarm','My device says it doesn''t support this test.','ម៉ាស៊ីនរបស់ខ្ញុំថាវាមិនគាំទ្រតេស្តនេះ។ ត្រូវធ្វើម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q02','DA-05','Device Alarm','test not supported error','អេក្រង់ឡើង «Test Item Not Supported»។ មានន័យថាម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q03','DA-05','Device Alarm','I just got a new type of card and the device refuses it.','ខ្ញុំទើបទទួលកាតប្រភេទថ្មី ហើយម៉ាស៊ីនមិនទទួលវា។ ត្រូវធ្វើម៉េច?','If the software shows "Test Item Not Supported", the firmware is out of date. Update it with the "Arrow of Update" icon on the device card in the software.','បើកម្មវិធីបង្ហាញ "Test Item Not Supported" មានន័យថា Firmware ហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាពដោយចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q04','DA-05','Device Alarm','How do I update the device firmware?','ធ្វើបច្ចុប្បន្នភាព Firmware ម៉ាស៊ីនយ៉ាងម៉េច?','In the software, click the "Arrow of Update" icon on the device card to update the firmware.','ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card) ដើម្បីធ្វើបច្ចុប្បន្នភាព Firmware។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q05','DA-05','Device Alarm','firmware update','ត្រូវអាប់ដេត firmware របស់ម៉ាស៊ីនយ៉ាងម៉េច?','In the software, click the "Arrow of Update" icon on the device card to update the firmware.','ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card) ដើម្បីធ្វើបច្ចុប្បន្នភាព Firmware។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q06','DA-05','Device Alarm','Where is the update arrow for firmware in the software?','រូបព្រួញអាប់ដេត firmware នៅឯណាក្នុងកម្មវិធី?','In the software, on the device card. Click the "Arrow of Update" icon.','នៅក្នុងកម្មវិធី លើកាតឧបករណ៍ (device card)។ ចុចរូបព្រួញ "Arrow of Update"។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q07','DA-05','Device Alarm','Test Item Not Supported','អេក្រង់ឡើង «Test Item Not Supported»។ ត្រូវធ្វើម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q08','DA-05','Device Alarm','How do I keep the device firmware up to date?','ធ្វើម៉េចឱ្យ Firmware ម៉ាស៊ីនទាន់សម័យជានិច្ច?','Whenever the "Arrow of Update" icon appears on the device card in the software, click it to update.','រាល់ពេលរូបព្រួញ "Arrow of Update" លេចឡើងលើកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី សូមចុចវាដើម្បីធ្វើបច្ចុប្បន្នភាព។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q09','DA-05','Device Alarm','I''m new — the device says the test isn''t supported. What do I do?','ខ្ញុំទើបប្រើ Pluslife។ ម៉ាស៊ីនថាមិនគាំទ្រតេស្ត។ ធ្វើម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q10','DA-05','Device Alarm','The analyzer says this assay isn''t supported.','ម៉ាស៊ីនវិភាគថាមិនគាំទ្រការវិភាគនេះ។ ត្រូវធ្វើម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q11','DA-05','Device Alarm','Red light, beeping, says the test type isn''t supported.','ភ្លើងក្រហម ប៊ីប ថាប្រភេទតេស្តមិនគាំទ្រ។ ត្រូវធ្វើម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q12','DA-05','Device Alarm','device say not support test, how update?','ម៉ាស៊ីនថាមិនគាំទ្រតេស្ត អាប់ដេតយ៉ាងម៉េច?','In the software, click the "Arrow of Update" icon on the device card to update the firmware.','ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card) ដើម្បីធ្វើបច្ចុប្បន្នភាព Firmware។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q13','DA-05','Device Alarm','I see an arrow icon on the device card in the software — what is it?','ខ្ញុំឃើញរូបព្រួញលើ device card ក្នុងកម្មវិធី — វាជាអ្វី?','That''s the firmware update. Click it to update the device.','នោះជាការធ្វើបច្ចុប្បន្នភាព Firmware។ ចុចវាដើម្បីធ្វើបច្ចុប្បន្នភាពម៉ាស៊ីន។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q14','DA-05','Device Alarm','So I just need to update the firmware to run this test?','មានន័យថា ខ្ញុំគ្រាន់តែអាប់ដេត firmware ទើបធ្វើតេស្តនេះបាន?','Yes. "Test Item Not Supported" means the firmware is out of date. Update it with the "Arrow of Update" icon on the device card in the software.','បាទ/ចាស។ "Test Item Not Supported" មានន័យថា Firmware ហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាពដោយចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q15','DA-05','Device Alarm','Software shows "Test Item Not Supported". What should I do?','កម្មវិធីបង្ហាញ "Test Item Not Supported"។ ត្រូវធ្វើម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q16','DA-05','Device Alarm','How do I fix the test item not supported alarm?','ដោះស្រាយការរោទិ៍ test item not supported យ៉ាងម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q17','DA-05','Device Alarm','Do I need to update the firmware when a test isn''t supported?','តើត្រូវអាប់ដេត firmware ពេលតេស្តមិនគាំទ្រទេ?','Yes. "Test Item Not Supported" means the firmware is out of date. Update it with the "Arrow of Update" icon on the device card in the software.','បាទ/ចាស។ "Test Item Not Supported" មានន័យថា Firmware ហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាពដោយចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q18','DA-05','Device Alarm','Where do I update the MiniDock firmware?','អាប់ដេត firmware MiniDock នៅឯណា?','In the software, on the device card. Click the "Arrow of Update" icon.','នៅក្នុងកម្មវិធី លើកាតឧបករណ៍ (device card)។ ចុចរូបព្រួញ "Arrow of Update"។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q19','DA-05','Device Alarm','test item not supported fix','បើអេក្រង់ឡើង «Test Item Not Supported» ត្រូវធ្វើម៉េច?','The device firmware is out of date. Update it: in the software, click the "Arrow of Update" icon on the device card.','Firmware របស់ម៉ាស៊ីនហួសសម័យ។ សូមធ្វើបច្ចុប្បន្នភាព៖ ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card)។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-05-Q20','DA-05','Device Alarm','How do I use the Arrow of Update icon?','ប្រើរូបព្រួញ Arrow of Update យ៉ាងម៉េច?','In the software, click the "Arrow of Update" icon on the device card to update the firmware.','ក្នុងកម្មវិធី ចុចរូបព្រួញ "Arrow of Update" លើកាតឧបករណ៍ (device card) ដើម្បីធ្វើបច្ចុប្បន្នភាព Firmware។','Routine','Supervisor if no internet');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-06','DA-06','Device Alarm','Lid alarm still on; the lid was left open more than ~30 seconds after inserting the card','ខ្ញុំដាក់កាតចូល ហើយទុកគម្របចំហលើសប្រហែល ៣០ វិនាទី។ ម៉ាស៊ីននៅតែរោទិ៍ ត្រូវធ្វើម៉េច?','Close the lid now if it is still open. If it was open more than ~30 seconds, treat the test as invalid and contact Pluslife support for what to do with that card and sample','បិទគម្របឥឡូវនេះ បើវានៅបើក។ បើគម្របបើកលើសពីប្រហែល ៣០ វិនាទី ចាត់ទុកតេស្តនេះថាគ្មានសុពលភាព ហើយសូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីសួរ Pluslife support ថាត្រូវធ្វើអ្វីជាមួយកាត និងសំណាកនោះ។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-06-Q01','DA-06','Device Alarm','I got distracted after inserting the card and now there''s an alarm.','ខ្ញុំរវល់អ្វីផ្សេងក្រោយដាក់កាត ហើយឥឡូវមានសំឡេងរោទិ៍។ ត្រូវធ្វើម៉េច?','Close the lid now if it''s still open. If the lid was open for more than about 30 seconds, the test is invalid. The guidance doesn''t say what to do with that card next (reuse it, or start again with a new sample). Please contact Pluslife support.','បិទគម្របឥឡូវនេះ បើវានៅបើក។ បើគម្របបើកលើសពីប្រហែល ៣០ វិនាទី តេស្តនេះគ្មានសុពលភាព។ ការណែនាំមិនបានបញ្ជាក់ថាត្រូវធ្វើអ្វីបន្តជាមួយកាតនោះទេ (ប្រើវាម្តងទៀត ឬចាប់ផ្តើមថ្មីជាមួយសំណាកថ្មី)។ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-06-Q02','DA-06','Device Alarm','forgot to close lid','ភ្លេចបិទគម្រប','Close the lid now if it''s still open. If the lid was open for more than about 30 seconds, the test is invalid. The guidance doesn''t say what to do with that card next (reuse it, or start again with a new sample). Please contact Pluslife support.','បិទគម្របឥឡូវនេះ បើវានៅបើក។ បើគម្របបើកលើសពីប្រហែល ៣០ វិនាទី តេស្តនេះគ្មានសុពលភាព។ ការណែនាំមិនបានបញ្ជាក់ថាត្រូវធ្វើអ្វីបន្តជាមួយកាតនោះទេ (ប្រើវាម្តងទៀត ឬចាប់ផ្តើមថ្មីជាមួយសំណាកថ្មី)។ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-06-Q03','DA-06','Device Alarm','I closed the lid late and the alarm is still on. What should I do?','ខ្ញុំបិទគម្របយឺត ហើយសំឡេងរោទិ៍នៅតែមាន។ ត្រូវធ្វើម៉េច?','Close the lid now if it''s still open. If the lid was open for more than about 30 seconds, the test is invalid. The guidance doesn''t say what to do with that card next (reuse it, or start again with a new sample). Please contact Pluslife support.','បិទគម្របឥឡូវនេះ បើវានៅបើក។ បើគម្របបើកលើសពីប្រហែល ៣០ វិនាទី តេស្តនេះគ្មានសុពលភាព។ ការណែនាំមិនបានបញ្ជាក់ថាត្រូវធ្វើអ្វីបន្តជាមួយកាតនោះទេ (ប្រើវាម្តងទៀត ឬចាប់ផ្តើមថ្មីជាមួយសំណាកថ្មី)។ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-06-Q04','DA-06','Device Alarm','I left the lid open after inserting the card. What now?','ខ្ញុំទុកគម្របបើកក្រោយដាក់កាត។ ឥឡូវធ្វើម៉េច?','Close the lid now if it''s still open. If the lid was open for more than about 30 seconds, the test is invalid. The guidance doesn''t say what to do with that card next (reuse it, or start again with a new sample). Please contact Pluslife support.','បិទគម្របឥឡូវនេះ បើវានៅបើក។ បើគម្របបើកលើសពីប្រហែល ៣០ វិនាទី តេស្តនេះគ្មានសុពលភាព។ ការណែនាំមិនបានបញ្ជាក់ថាត្រូវធ្វើអ្វីបន្តជាមួយកាតនោះទេ (ប្រើវាម្តងទៀត ឬចាប់ផ្តើមថ្មីជាមួយសំណាកថ្មី)។ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-07','DA-07','Device Alarm','"Test Card Scan Timeout" persists after reinserting the card, and the QR code and label look fine','ខ្ញុំដកកាតដាក់ចូលវិញហើយ ស្លាកនិងកូដ QR មើលទៅធម្មតា តែនៅតែចេញ «Test Card Scan Timeout»។ ត្រូវធ្វើម៉េច?','Re-check the QR code and label for scratches, dirt or a misapplied label; if found, discard and use a new card. If none found and it still times out, contact Pluslife support','ពិនិត្យកូដ QR និងស្លាកម្តងទៀត មើលស្នាមកោស ប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ បើឃើញ សូមបោះចោល ហើយប្រើកាតថ្មី។ បើមិនឃើញអ្វីខុស ហើយនៅតែ Timeout សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-07-Q01','DA-07','Device Alarm','I tried reinserting the card and it still times out. What now?','ខ្ញុំសាកដាក់កាតចូលម្តងទៀត ហើយវានៅតែ timeout។ ឥឡូវធ្វើម៉េច?','Check the QR code and label for scratches, dirt or a misapplied label. If you find any, discard the card and use a new one. If the code looks fine and it still times out, the guidance doesn''t cover further steps. Please contact Pluslife support.','ពិនិត្យកូដ QR និងស្លាក មើលស្នាមកោស ប្រឡាក់ ឬស្លាកបិទមិនត្រឹមត្រូវ។ បើឃើញ សូមបោះចោលកាត ហើយប្រើកាតថ្មី។ បើកូដមើលទៅល្អ ហើយនៅតែ Timeout ការណែនាំមិនបានពន្យល់ជំហានបន្តទេ។ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-08','DA-08','Device Alarm','"Chip Duplication" / reuse alarm won''t clear','អេក្រង់នៅតែបង្ហាញ «Chip Duplication» ថាកាតធ្លាប់ប្រើរួច។ ត្រូវធ្វើម៉េច?','Remove and discard the card, then insert a new, unused card','ដកកាតចេញ ហើយបោះចោល រួចដាក់កាតថ្មីដែលមិនទាន់ប្រើ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-08-Q01','DA-08','Device Alarm','How do I clear the "Chip Duplication" warning?','ធ្វើម៉េចលុបសារព្រមាន "Chip Duplication"?','Remove the card (it has already been tested) and discard it, then use a new, unused card. The guidance doesn''t describe a separate step to reset the alarm.','ដកកាតចេញ (វាបានធ្វើតេស្តរួចហើយ) ហើយបោះចោល រួចប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ ការណែនាំមិនបានពន្យល់ពីជំហានដាច់ដោយឡែកសម្រាប់បិទសំឡេងរោទិ៍ទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-09','DA-09','Device Alarm','Device beeps with a red flashing light (any alarm)','ម៉ាស៊ីនរោទិ៍ ហើយភ្លើងក្រហមលោត។ ត្រូវពិនិត្យអ្វីមុន?','Check the error message shown in the software, then follow the matching DA row','មើលសារកំហុសដែលបង្ហាញក្នុងកម្មវិធី រួចធ្វើតាមជួរ DA ដែលត្រូវគ្នា។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01','MO-01','Mis-operation','Card inserted before device shows ready (blue light)','ខ្ញុំដាក់កាតចូល មុនភ្លើងខៀវភ្លឺជាប់។ ត្រូវធ្វើម៉េច?','Wait for the device light to turn solid blue (ready) before inserting the card','រង់ចាំរហូតភ្លើងម៉ាស៊ីនប្តូរជាពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) ទើបដាក់កាតចូល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q01','MO-01','Mis-operation','Can I insert the card while the device is still warming up?','អាចដាក់កាត ពេលម៉ាស៊ីននៅកំពុងកម្តៅបានទេ?','No. Wait until the light is solid blue (ready) before inserting the card. Inserting it during warm-up can activate the reaction improperly.','មិនបានទេ។ រង់ចាំរហូតភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) ទើបដាក់កាតចូល។ ការដាក់កាតពេលម៉ាស៊ីនកំពុងកម្តៅ អាចធ្វើឱ្យប្រតិកម្មចាប់ផ្តើមមិនត្រឹមត្រូវ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q02','MO-01','Mis-operation','How do I know when the device is ready?','ធ្វើម៉េចដឹងថាម៉ាស៊ីនរួចរាល់?','The light turns solid blue after warm-up (red flashing), about 2 minutes after power-on.','ភ្លើងប្តូរជាពណ៌ខៀវភ្លឺជាប់ ក្រោយពេលកម្តៅម៉ាស៊ីនរួច (ភ្លើងក្រហមភ្លឹបភ្លែត) ប្រហែល ២ នាទីក្រោយបើកម៉ាស៊ីន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q03','MO-01','Mis-operation','How do I avoid inserting the card too early?','ធ្វើម៉េចកុំឱ្យដាក់កាតលឿនពេក?','Insert the card only when the light is solid blue (ready).','ដាក់កាតចូល តែពេលភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) ប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q04','MO-01','Mis-operation','I''m new — when is the right moment to insert the card?','ខ្ញុំទើបប្រើ Pluslife។ ពេលណាជាពេលត្រឹមត្រូវដើម្បីដាក់កាត?','Insert the card only when the light is solid blue (ready).','ដាក់កាតចូល តែពេលភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) ប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q05','MO-01','Mis-operation','When can I insert the card after turning on the device?','ក្រោយបើកម៉ាស៊ីន ពេលណាអាចដាក់កាតបាន?','After warm-up, about 2 minutes after power-on, when the light is solid blue.','ក្រោយកម្តៅម៉ាស៊ីនរួច ប្រហែល ២ នាទីក្រោយបើកម៉ាស៊ីន ពេលភ្លើងពណ៌ខៀវភ្លឺជាប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q06','MO-01','Mis-operation','Should I wait for the blue light before inserting the card?','តើគួររង់ចាំភ្លើងខៀវ មុនដាក់កាតទេ?','Yes. Wait for the solid blue light (ready) before inserting the card.','បាទ/ចាស។ រង់ចាំភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) សិន ទើបដាក់កាតចូល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q07','MO-01','Mis-operation','Do I have to wait for the device to be ready before inserting the card?','តើត្រូវរង់ចាំម៉ាស៊ីនរួចរាល់ មុនដាក់កាតទេ?','Yes. Wait for the solid blue light (ready) before inserting the card.','បាទ/ចាស។ រង់ចាំភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) សិន ទើបដាក់កាតចូល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q08','MO-01','Mis-operation','What light should I see before I insert the card?','ត្រូវឃើញភ្លើងអ្វី មុនដាក់កាត?','A solid blue light (ready).','ភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q09','MO-01','Mis-operation','Is it OK to insert the card before the blue light comes on?','តើអាចដាក់កាត មុនភ្លើងខៀវឡើងបានទេ?','No. Wait until the light is solid blue (ready) before inserting the card. Inserting it during warm-up can activate the reaction improperly.','មិនបានទេ។ រង់ចាំរហូតភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) ទើបដាក់កាតចូល។ ការដាក់កាតពេលម៉ាស៊ីនកំពុងកម្តៅ អាចធ្វើឱ្យប្រតិកម្មចាប់ផ្តើមមិនត្រឹមត្រូវ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q10','MO-01','Mis-operation','I''m new — what should the device show before I put the card in?','ខ្ញុំទើបប្រើ Pluslife។ ម៉ាស៊ីនគួរបង្ហាញអ្វី មុនខ្ញុំដាក់កាត?','A solid blue light (ready).','ភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q11','MO-01','Mis-operation','So I insert the card only when the light is solid blue?','មានន័យថា ខ្ញុំដាក់កាត តែពេលភ្លើងខៀវភ្លឺជាប់ប៉ុណ្ណោះ?','Yes. Wait for the solid blue light (ready) before inserting the card.','បាទ/ចាស។ រង់ចាំភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) សិន ទើបដាក់កាតចូល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-01-Q12','MO-01','Mis-operation','Can I insert the card right after pressing the power button?','តើអាចដាក់កាតភ្លាមៗក្រោយចុចប៊ូតុងបើកបានទេ?','No. Wait until the light is solid blue (ready) before inserting the card. Inserting it during warm-up can activate the reaction improperly.','មិនបានទេ។ រង់ចាំរហូតភ្លើងពណ៌ខៀវភ្លឺជាប់ (រួចរាល់) ទើបដាក់កាតចូល។ ការដាក់កាតពេលម៉ាស៊ីនកំពុងកម្តៅ អាចធ្វើឱ្យប្រតិកម្មចាប់ផ្តើមមិនត្រឹមត្រូវ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02','MO-02','Mis-operation','Card inserted but device does not start; test shows invalid after ~30s','ដាក់កាតចូលហើយ តេស្តមិនចាប់ផ្តើម។ ប្រហែល ៣០ វិនាទីក្រោយ អេក្រង់បង្ហាញ Invalid។ ត្រូវធ្វើម៉េច?','Close the lid immediately after inserting the card','បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q01','MO-02','Mis-operation','How do I avoid the lid-not-closed alarm?','ធ្វើម៉េចកុំឱ្យមានការរោទិ៍គម្របមិនបិទ?','Close the lid immediately every time you insert a card.','បិទគម្របភ្លាមៗ រាល់ពេលដាក់កាតចូល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q02','MO-02','Mis-operation','I''m new — when exactly should I close the lid?','ខ្ញុំទើបប្រើ Pluslife។ ពេលណាពិតប្រាកដត្រូវបិទគម្រប?','Immediately after inserting the card.','ភ្លាមៗក្រោយដាក់កាតចូល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q03','MO-02','Mis-operation','So I should close the lid right after inserting the card?','មានន័យថា ខ្ញុំគួរបិទគម្របភ្លាមក្រោយដាក់កាត?','Yes. Close the lid immediately after inserting the card; otherwise the test becomes invalid after about 30 seconds.','បាទ/ចាស។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ បើមិនដូច្នោះទេ តេស្តនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q04','MO-02','Mis-operation','When should I close the lid after inserting the card?','ពេលណាត្រូវបិទគម្រប ក្រោយដាក់កាត?','Immediately after inserting the card.','ភ្លាមៗក្រោយដាក់កាតចូល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q05','MO-02','Mis-operation','Do I close the lid straight after putting the card in?','តើខ្ញុំបិទគម្របភ្លាមៗក្រោយដាក់កាតមែនទេ?','Yes. Close the lid immediately after inserting the card; otherwise the test becomes invalid after about 30 seconds.','បាទ/ចាស។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ បើមិនដូច្នោះទេ តេស្តនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q06','MO-02','Mis-operation','Do I need to close the lid for the test to begin?','តើត្រូវបិទគម្របទើបតេស្តចាប់ផ្តើមទេ?','Yes. Close the lid immediately after inserting the card. The test only starts then, and becomes invalid after about 30 seconds if the lid stays open.','បាទ/ចាស។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ តេស្តចាប់ផ្តើមតែពេលនោះ ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី បើគម្របនៅបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q07','MO-02','Mis-operation','What''s the correct way to start a test after inserting the card?','របៀបត្រឹមត្រូវដើម្បីចាប់ផ្តើមតេស្តក្រោយដាក់កាតយ៉ាងម៉េច?','Close the lid immediately after inserting the card. The test then starts automatically.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q08','MO-02','Mis-operation','So the test only starts once the lid is closed?','មានន័យថា តេស្តចាប់ផ្តើមតែពេលគម្របបិទ?','Yes. Close the lid immediately after inserting the card. The test only starts then, and becomes invalid after about 30 seconds if the lid stays open.','បាទ/ចាស។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ តេស្តចាប់ផ្តើមតែពេលនោះ ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី បើគម្របនៅបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q09','MO-02','Mis-operation','Do I have to close the lid after inserting the card?','តើត្រូវបិទគម្របក្រោយដាក់កាតទេ?','Yes. Close the lid immediately after inserting the card. The test only starts then, and becomes invalid after about 30 seconds if the lid stays open.','បាទ/ចាស។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ តេស្តចាប់ផ្តើមតែពេលនោះ ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី បើគម្របនៅបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q10','MO-02','Mis-operation','Should I close the lid right away after inserting the card?','តើគួរបិទគម្របភ្លាមៗក្រោយដាក់កាតទេ?','Yes. Close the lid immediately after inserting the card. The test only starts then, and becomes invalid after about 30 seconds if the lid stays open.','បាទ/ចាស។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ តេស្តចាប់ផ្តើមតែពេលនោះ ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី បើគម្របនៅបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q11','MO-02','Mis-operation','Can I leave the lid open after putting the card in?','តើអាចទុកគម្របបើកក្រោយដាក់កាតបានទេ?','No. Close the lid immediately after inserting the card. With the lid open, the test won''t start and becomes invalid after about 30 seconds.','មិនបានទេ។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ បើគម្របបើក តេស្តនឹងមិនចាប់ផ្តើម ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q12','MO-02','Mis-operation','Will the test start with the lid open?','តើតេស្តចាប់ផ្តើមទេ បើគម្របបើក?','No. Close the lid immediately after inserting the card. With the lid open, the test won''t start and becomes invalid after about 30 seconds.','មិនបានទេ។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ បើគម្របបើក តេស្តនឹងមិនចាប់ផ្តើម ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q13','MO-02','Mis-operation','Is closing the lid the next step after inserting the card?','តើការបិទគម្រប ជាជំហានបន្ទាប់ក្រោយដាក់កាតមែនទេ?','Yes. Close the lid immediately after inserting the card. The test only starts then, and becomes invalid after about 30 seconds if the lid stays open.','បាទ/ចាស។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ តេស្តចាប់ផ្តើមតែពេលនោះ ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី បើគម្របនៅបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q14','MO-02','Mis-operation','I''m new — what do I need to do after inserting the card so the test begins?','ខ្ញុំទើបប្រើ Pluslife។ ក្រោយដាក់កាត ត្រូវធ្វើអ្វីទើបតេស្តចាប់ផ្តើម?','Close the lid immediately after inserting the card. The test then starts automatically.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q15','MO-02','Mis-operation','Can I wait a while before closing the lid?','តើអាចរង់ចាំមួយសន្ទុះ មុនបិទគម្របបានទេ?','No. Close the lid immediately after inserting the card. With the lid open, the test won''t start and becomes invalid after about 30 seconds.','មិនបានទេ។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ បើគម្របបើក តេស្តនឹងមិនចាប់ផ្តើម ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q16','MO-02','Mis-operation','insert card then close lid?','ដាក់កាត ហើយបិទគម្រប?','Yes. Close the lid immediately after inserting the card. The test only starts then, and becomes invalid after about 30 seconds if the lid stays open.','បាទ/ចាស។ បិទគម្របភ្លាមៗក្រោយដាក់កាតចូល។ តេស្តចាប់ផ្តើមតែពេលនោះ ហើយនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី បើគម្របនៅបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-02-Q17','MO-02','Mis-operation','How quickly should I close the lid?','ត្រូវបិទគម្របលឿនប៉ុណ្ណា?','Immediately. If the lid stays open, the test becomes invalid after about 30 seconds.','ភ្លាមៗ។ បើគម្របនៅបើក តេស្តនឹងគ្មានសុពលភាពក្រោយប្រហែល ៣០ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03','MO-03','Mis-operation','Lid opened or device moved mid-test','ពេលតេស្តកំពុងដំណើរការ ខ្ញុំបើកគម្រប ឬរើម៉ាស៊ីនដោយចៃដន្យ។ ត្រូវធ្វើម៉េច?','Never open the lid or move the device while a test is running','កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q01','MO-03','Mis-operation','Can I open the lid during a test?','តើអាចបើកគម្របពេលកំពុងធ្វើតេស្តបានទេ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q02','MO-03','Mis-operation','Is it okay to move the device while it''s running?','តើអាចរើម៉ាស៊ីនពេលវាកំពុងដំណើរការបានទេ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q03','MO-03','Mis-operation','I need to move the device to another bench — can I do it while a test is running?','ខ្ញុំត្រូវរើម៉ាស៊ីនទៅតុផ្សេង — តើធ្វើបានទេ ពេលតេស្តកំពុងដំណើរការ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q04','MO-03','Mis-operation','Can I check on the card halfway through the run?','តើអាចពិនិត្យមើលកាតពាក់កណ្តាលការធ្វើតេស្តបានទេ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q05','MO-03','Mis-operation','How do I avoid disturbing a test in progress?','ធ្វើម៉េចកុំឱ្យរំខានតេស្តដែលកំពុងដំណើរការ?','Don''t open the lid or move the device until the test is finished (second beep).','កុំបើកគម្រប ឬរើម៉ាស៊ីន រហូតដល់តេស្តចប់ (សំឡេងប៊ីបលើកទី២)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q06','MO-03','Mis-operation','I''m new — is it okay to touch the device during a run?','ខ្ញុំទើបប្រើ Pluslife។ តើអាចប៉ះម៉ាស៊ីនពេលកំពុងធ្វើតេស្តបានទេ?','No. Don''t open the lid or move the device while the test is running; either can make the result invalid or false. The guidance doesn''t mention light touching.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ ទាំងពីរនេះអាចធ្វើឱ្យលទ្ធផលគ្មានសុពលភាព ឬខុស។ ការណែនាំមិនបាននិយាយពីការប៉ះស្រាលៗទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q07','MO-03','Mis-operation','Can I relocate the analyzer while it''s processing a sample?','តើអាចប្តូរទីតាំងម៉ាស៊ីនវិភាគ ពេលកំពុងដំណើរការសំណាកបានទេ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q08','MO-03','Mis-operation','So I shouldn''t open the lid or move the device until the test finishes?','មានន័យថា ខ្ញុំមិនគួរបើកគម្រប ឬរើម៉ាស៊ីន រហូតតេស្តចប់?','Yes. Keep the lid closed and the device still until the test finishes.','បាទ/ចាស។ ទុកគម្របឱ្យបិទ និងទុកម៉ាស៊ីនឱ្យនៅស្ងៀម រហូតដល់តេស្តចប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q09','MO-03','Mis-operation','Can I open the device lid before the test is finished?','តើអាចបើកគម្របម៉ាស៊ីន មុនតេស្តចប់បានទេ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q10','MO-03','Mis-operation','Is it OK to carry the device while it''s testing?','តើអាចលីម៉ាស៊ីន ពេលវាកំពុងធ្វើតេស្តបានទេ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q11','MO-03','Mis-operation','What should I avoid doing while a test is running?','ត្រូវជៀសវាងធ្វើអ្វីខ្លះ ពេលតេស្តកំពុងដំណើរការ?','Don''t open the lid or move the device until the test is finished (second beep).','កុំបើកគម្រប ឬរើម៉ាស៊ីន រហូតដល់តេស្តចប់ (សំឡេងប៊ីបលើកទី២)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q12','MO-03','Mis-operation','Can I lift the lid during a test to check the card is in properly?','តើអាចលើកគម្របពេលធ្វើតេស្ត ដើម្បីពិនិត្យថាកាតដាក់ត្រូវទេ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q13','MO-03','Mis-operation','Should the device stay still during the whole test?','តើម៉ាស៊ីនគួរនៅស្ងៀមពេញមួយតេស្តទេ?','Yes. Keep the lid closed and the device still until the test finishes.','បាទ/ចាស។ ទុកគម្របឱ្យបិទ និងទុកម៉ាស៊ីនឱ្យនៅស្ងៀម រហូតដល់តេស្តចប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-03-Q14','MO-03','Mis-operation','Can I reposition the device during a run?','តើអាចប្តូរទីតាំងម៉ាស៊ីនពេលកំពុងដំណើរការបានទេ?','No. Don''t open the lid or move the device while a test is running. The test will be invalid or give a false result.','មិនបានទេ។ កុំបើកគម្រប ឬរើម៉ាស៊ីន ពេលតេស្តកំពុងដំណើរការ។ តេស្តនឹងគ្មានសុពលភាព ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04','MO-04','Mis-operation','Tested cards left in the device or on the bench after result appears','ចេញលទ្ធផលហើយ តែកាតនៅក្នុងម៉ាស៊ីន ឬលើតុ។ ត្រូវធ្វើម៉េចជាមួយកាត?','Discard the tested card into the waste bag immediately and seal the bag','បោះកាតដែលធ្វើតេស្តរួចចូលថង់កាកសំណល់ភ្លាមៗ ហើយចងបិទថង់ឱ្យជិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q01','MO-04','Mis-operation','What do I do with the card after the result comes out?','ក្រោយលទ្ធផលចេញ ត្រូវធ្វើអ្វីជាមួយកាត?','Remove the card right away, put it in the waste bag, seal the bag, and dispose of it per local regulations.','ដកកាតចេញភ្លាមៗ ដាក់ចូលថង់កាកសំណល់ ចងបិទថង់ឱ្យជិត ហើយបោះចោលតាមបទប្បញ្ញត្តិគ្រប់គ្រងកាកសំណល់វេជ្ជសាស្ត្ររបស់ក្រសួងសុខាភិបាល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q02','MO-04','Mis-operation','Can I leave the used card in the device until the next test?','តើអាចទុកកាតប្រើរួចក្នុងម៉ាស៊ីន រហូតដល់តេស្តបន្ទាប់បានទេ?','No. Put the card in the waste bag right after the result and seal the bag. Leaving cards around increases the risk of contamination.','មិនបានទេ។ ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយចេញលទ្ធផល ហើយចងបិទថង់ឱ្យជិត។ ការទុកកាតចោលនៅជុំវិញ បង្កើនហានិភ័យនៃការចម្លងរោគ (contamination)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q03','MO-04','Mis-operation','How should I dispose of tested cards?','ត្រូវបោះចោលកាតដែលធ្វើតេស្តរួចយ៉ាងម៉េច?','Remove the card right away, put it in the waste bag, seal the bag, and dispose of it per local regulations.','ដកកាតចេញភ្លាមៗ ដាក់ចូលថង់កាកសំណល់ ចងបិទថង់ឱ្យជិត ហើយបោះចោលតាមបទប្បញ្ញត្តិគ្រប់គ្រងកាកសំណល់វេជ្ជសាស្ត្ររបស់ក្រសួងសុខាភិបាល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q04','MO-04','Mis-operation','used card disposal','កាតដែលប្រើរួច ត្រូវបោះចោលនៅឯណា?','Remove the card right away, put it in the waste bag, seal the bag, and dispose of it per local regulations.','ដកកាតចេញភ្លាមៗ ដាក់ចូលថង់កាកសំណល់ ចងបិទថង់ឱ្យជិត ហើយបោះចោលតាមបទប្បញ្ញត្តិគ្រប់គ្រងកាកសំណល់វេជ្ជសាស្ត្ររបស់ក្រសួងសុខាភិបាល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q05','MO-04','Mis-operation','I usually leave old cards on the bench and clean up at the end of the day. Is that OK?','ខ្ញុំធ្លាប់ទុកកាតចាស់លើតុ ហើយសម្អាតពេលល្ងាច។ តើបានទេ?','No. Put the card in the waste bag right after the result and seal the bag. Leaving cards around increases the risk of contamination.','មិនបានទេ។ ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយចេញលទ្ធផល ហើយចងបិទថង់ឱ្យជិត។ ការទុកកាតចោលនៅជុំវិញ បង្កើនហានិភ័យនៃការចម្លងរោគ (contamination)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q06','MO-04','Mis-operation','Do used cards need to go in a sealed bag?','តើកាតប្រើរួចត្រូវដាក់ក្នុងថង់បិទជិតទេ?','Yes. Put the card in the waste bag right after the result and seal the bag.','បាទ/ចាស។ ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយចេញលទ្ធផល ហើយចងបិទថង់ឱ្យជិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q07','MO-04','Mis-operation','where to throw used cards','បោះកាតប្រើរួចនៅឯណា?','Remove the card right away, put it in the waste bag, seal the bag, and dispose of it per local regulations.','ដកកាតចេញភ្លាមៗ ដាក់ចូលថង់កាកសំណល់ ចងបិទថង់ឱ្យជិត ហើយបោះចោលតាមបទប្បញ្ញត្តិគ្រប់គ្រងកាកសំណល់វេជ្ជសាស្ត្ររបស់ក្រសួងសុខាភិបាល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q08','MO-04','Mis-operation','How soon after the result should I remove the card?','ក្រោយលទ្ធផលចេញ ត្រូវដកកាតចេញលឿនប៉ុណ្ណា?','Immediately after the result appears.','ភ្លាមៗក្រោយលទ្ធផលចេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q09','MO-04','Mis-operation','I''m new — what''s the cleanup step after each test?','ខ្ញុំទើបប្រើ Pluslife។ ការសម្អាតក្រោយតេស្តនីមួយៗធ្វើយ៉ាងម៉េច?','Remove the card right away, put it in the waste bag, seal the bag, and dispose of it per local regulations.','ដកកាតចេញភ្លាមៗ ដាក់ចូលថង់កាកសំណល់ ចងបិទថង់ឱ្យជិត ហើយបោះចោលតាមបទប្បញ្ញត្តិគ្រប់គ្រងកាកសំណល់វេជ្ជសាស្ត្ររបស់ក្រសួងសុខាភិបាល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q10','MO-04','Mis-operation','Where do spent cartridges go?','កាតដែលប្រើអស់ហើយ ដាក់នៅឯណា?','Remove the card right away, put it in the waste bag, seal the bag, and dispose of it per local regulations.','ដកកាតចេញភ្លាមៗ ដាក់ចូលថង់កាកសំណល់ ចងបិទថង់ឱ្យជិត ហើយបោះចោលតាមបទប្បញ្ញត្តិគ្រប់គ្រងកាកសំណល់វេជ្ជសាស្ត្ររបស់ក្រសួងសុខាភិបាល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q11','MO-04','Mis-operation','after result, card throw where?','ក្រោយលទ្ធផល បោះកាតនៅណា?','Remove the card right away, put it in the waste bag, seal the bag, and dispose of it per local regulations.','ដកកាតចេញភ្លាមៗ ដាក់ចូលថង់កាកសំណល់ ចងបិទថង់ឱ្យជិត ហើយបោះចោលតាមបទប្បញ្ញត្តិគ្រប់គ្រងកាកសំណល់វេជ្ជសាស្ត្ររបស់ក្រសួងសុខាភិបាល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q12','MO-04','Mis-operation','So I should put the card in the waste bag and seal it right after the result?','មានន័យថា ខ្ញុំគួរដាក់កាតក្នុងថង់កាកសំណល់ ហើយបិទភ្លាមក្រោយលទ្ធផល?','Yes. Put the card in the waste bag right after the result and seal the bag.','បាទ/ចាស។ ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយចេញលទ្ធផល ហើយចងបិទថង់ឱ្យជិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q13','MO-04','Mis-operation','When should I discard the tested card?','ពេលណាត្រូវបោះចោលកាតដែលធ្វើតេស្តរួច?','Immediately after the result appears.','ភ្លាមៗក្រោយលទ្ធផលចេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q14','MO-04','Mis-operation','Do I need to seal the waste bag after discarding the card?','តើត្រូវបិទថង់កាកសំណល់ ក្រោយបោះកាតចោលទេ?','Yes. Put the card in the waste bag right after the result and seal the bag.','បាទ/ចាស។ ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយចេញលទ្ធផល ហើយចងបិទថង់ឱ្យជិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q15','MO-04','Mis-operation','Can I collect used cards and throw them away later?','តើអាចប្រមូលកាតប្រើរួច ហើយបោះចោលពេលក្រោយបានទេ?','No. Put the card in the waste bag right after the result and seal the bag. Leaving cards around increases the risk of contamination.','មិនបានទេ។ ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយចេញលទ្ធផល ហើយចងបិទថង់ឱ្យជិត។ ការទុកកាតចោលនៅជុំវិញ បង្កើនហានិភ័យនៃការចម្លងរោគ (contamination)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-04-Q16','MO-04','Mis-operation','Test finished — should I take the card out right away?','តេស្តចប់ហើយ — តើគួរដកកាតចេញភ្លាមទេ?','Yes. Put the card in the waste bag right after the result and seal the bag.','បាទ/ចាស។ ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយចេញលទ្ធផល ហើយចងបិទថង់ឱ្យជិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05','MO-05','Mis-operation','Card was unpacked well before the sample was ready','ខ្ញុំបើកកញ្ចប់កាតយូរហើយ តែសំណាកមិនទាន់រួច។ នៅប្រើកាតនេះបានទេ?','Only unpack/open a reaction card immediately before adding the sample','ហែក/បើកកាតប្រតិកម្ម តែភ្លាមៗមុនពេលដាក់សំណាកប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q01','MO-05','Mis-operation','Can I open the card packaging ahead of time?','តើអាចបើកថង់កាតទុកមុនបានទេ?','No. Only open the reaction card right before adding the sample. Opening it too early may cause false negative results.','មិនបានទេ។ បើកកាតប្រតិកម្ម តែភ្លាមៗមុនពេលដាក់សំណាកប៉ុណ្ណោះ។ ការបើកលឿនពេក អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q02','MO-05','Mis-operation','How early can I unpack the reaction card?','អាចហែកកាតប្រតិកម្មមុនបានយូរប៉ុណ្ណា?','Only right before adding the sample, once sample pretreatment is finished. Keep the foil bag closed until then.','តែភ្លាមៗមុនពេលដាក់សំណាក ក្រោយការរៀបចំសំណាក (pretreatment) រួចរាល់។ ទុកថង់អាលុយមីញ៉ូមឱ្យបិទជិតរហូតដល់ពេលនោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q03','MO-05','Mis-operation','I opened a batch of cards in the morning to save time — is that OK?','ខ្ញុំបើកកាតមួយឡូតិ៍នៅពេលព្រឹក ដើម្បីចំណេញពេល — តើបានទេ?','No. Only open the reaction card right before adding the sample. Opening it too early may cause false negative results.','មិនបានទេ។ បើកកាតប្រតិកម្ម តែភ្លាមៗមុនពេលដាក់សំណាកប៉ុណ្ណោះ។ ការបើកលឿនពេក អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q04','MO-05','Mis-operation','When is the right time to open the card pouch?','ពេលណាជាពេលត្រឹមត្រូវដើម្បីបើកថង់កាត?','Only right before adding the sample, once sample pretreatment is finished. Keep the foil bag closed until then.','តែភ្លាមៗមុនពេលដាក់សំណាក ក្រោយការរៀបចំសំណាក (pretreatment) រួចរាល់។ ទុកថង់អាលុយមីញ៉ូមឱ្យបិទជិតរហូតដល់ពេលនោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q05','MO-05','Mis-operation','Should I prepare the sample first or open the card first?','គួររៀបចំសំណាកមុន ឬបើកកាតមុន?','Prepare the sample first. Open the card only when the sample is ready to be added.','រៀបចំសំណាកមុនសិន។ បើកកាត តែពេលសំណាករួចរាល់សម្រាប់ដាក់ប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q06','MO-05','Mis-operation','I''m new — when should I take the card out of its pouch?','ខ្ញុំទើបប្រើ Pluslife។ ពេលណាត្រូវយកកាតចេញពីថង់?','Only right before adding the sample, once sample pretreatment is finished. Keep the foil bag closed until then.','តែភ្លាមៗមុនពេលដាក់សំណាក ក្រោយការរៀបចំសំណាក (pretreatment) រួចរាល់។ ទុកថង់អាលុយមីញ៉ូមឱ្យបិទជិតរហូតដល់ពេលនោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q07','MO-05','Mis-operation','Can I pre-open the test cartridges for a busy session?','តើអាចបើកកាតទុកមុន សម្រាប់ថ្ងៃមានអ្នកជំងឺច្រើនបានទេ?','No. Only open the reaction card right before adding the sample. Opening it too early may cause false negative results.','មិនបានទេ។ បើកកាតប្រតិកម្ម តែភ្លាមៗមុនពេលដាក់សំណាកប៉ុណ្ណោះ។ ការបើកលឿនពេក អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q08','MO-05','Mis-operation','open card first then wait sample ok?','បើកកាតមុន ហើយរង់ចាំសំណាក បានទេ?','No. Only open the reaction card right before adding the sample. Opening it too early may cause false negative results.','មិនបានទេ។ បើកកាតប្រតិកម្ម តែភ្លាមៗមុនពេលដាក់សំណាកប៉ុណ្ណោះ។ ការបើកលឿនពេក អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q09','MO-05','Mis-operation','So I should only open the card right before adding the sample?','មានន័យថា ខ្ញុំគួរបើកកាត តែភ្លាមមុនដាក់សំណាកប៉ុណ្ណោះ?','Yes. Open the card only when the sample is ready to be added.','បាទ/ចាស។ បើកកាត តែពេលសំណាករួចរាល់សម្រាប់ដាក់ប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q10','MO-05','Mis-operation','When should I unpack the reaction card?','ពេលណាត្រូវហែកកាតប្រតិកម្ម?','Only right before adding the sample, once sample pretreatment is finished. Keep the foil bag closed until then.','តែភ្លាមៗមុនពេលដាក់សំណាក ក្រោយការរៀបចំសំណាក (pretreatment) រួចរាល់។ ទុកថង់អាលុយមីញ៉ូមឱ្យបិទជិតរហូតដល់ពេលនោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q11','MO-05','Mis-operation','Should I open the card only when the sample is ready?','តើគួរបើកកាត តែពេលសំណាករួចរាល់ទេ?','Yes. Open the card only when the sample is ready to be added.','បាទ/ចាស។ បើកកាត តែពេលសំណាករួចរាល់សម្រាប់ដាក់ប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q12','MO-05','Mis-operation','Can I take the card out of the foil bag before collecting the sample?','តើអាចយកកាតចេញពីថង់អាលុយមីញ៉ូម មុនយកសំណាកបានទេ?','No. Only open the reaction card right before adding the sample. Opening it too early may cause false negative results.','មិនបានទេ។ បើកកាតប្រតិកម្ម តែភ្លាមៗមុនពេលដាក់សំណាកប៉ុណ្ណោះ។ ការបើកលឿនពេក អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q13','MO-05','Mis-operation','Is it OK to unpack several cards at once in advance?','តើអាចហែកកាតច្រើនក្នុងពេលតែមួយទុកមុនបានទេ?','No. Only open the reaction card right before adding the sample. Opening it too early may cause false negative results.','មិនបានទេ។ បើកកាតប្រតិកម្ម តែភ្លាមៗមុនពេលដាក់សំណាកប៉ុណ្ណោះ។ ការបើកលឿនពេក អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-05-Q14','MO-05','Mis-operation','How long before adding the sample should I open the card?','គួរបើកកាតមុនដាក់សំណាកប៉ុន្មាននាទី?','Only right before adding the sample, once sample pretreatment is finished. Keep the foil bag closed until then.','តែភ្លាមៗមុនពេលដាក់សំណាក ក្រោយការរៀបចំសំណាក (pretreatment) រួចរាល់។ ទុកថង់អាលុយមីញ៉ូមឱ្យបិទជិតរហូតដល់ពេលនោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06','MO-06','Mis-operation','Device alarms when a card is inserted','គ្រាន់តែដាក់កាតចូល ម៉ាស៊ីនក៏រោទិ៍។ ត្រូវពិនិត្យអ្វីមុន?','Confirm the card is new/unused before inserting; discard used cards right away','ពិនិត្យឱ្យប្រាកដថាកាតជាកាតថ្មី/មិនទាន់ប្រើ មុនដាក់ចូល។ បោះចោលកាតដែលប្រើរួចភ្លាមៗ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q01','MO-06','Mis-operation','How do I make sure I never reinsert a used card?','ធ្វើម៉េចឱ្យប្រាកដថាមិនដាក់កាតប្រើរួចចូលវិញ?','Discard each card into the waste bag right after testing, so a used card is never reinserted.','បោះកាតនីមួយៗចូលថង់កាកសំណល់ភ្លាមៗក្រោយធ្វើតេស្ត ដើម្បីកុំឱ្យកាតដែលប្រើរួច ត្រូវដាក់ចូលម៉ាស៊ីនម្តងទៀត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q02','MO-06','Mis-operation','What should I do with a card right after testing so this alarm doesn''t happen again?','ក្រោយធ្វើតេស្តភ្លាម ត្រូវធ្វើអ្វីជាមួយកាត ដើម្បីកុំឱ្យរោទិ៍ម្តងទៀត?','Discard each card into the waste bag right after testing, so a used card is never reinserted.','បោះកាតនីមួយៗចូលថង់កាកសំណល់ភ្លាមៗក្រោយធ្វើតេស្ត ដើម្បីកុំឱ្យកាតដែលប្រើរួច ត្រូវដាក់ចូលម៉ាស៊ីនម្តងទៀត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q03','MO-06','Mis-operation','I mixed up used and new cards and the device keeps alarming.','ខ្ញុំច្រឡំកាតប្រើរួច និងកាតថ្មី ហើយម៉ាស៊ីននៅតែរោទិ៍។ ត្រូវធ្វើម៉េច?','Any card that has already been tested triggers the reuse alarm. Discard the cards that trigger it and use new, unused cards. From now on, discard each card right after testing.','កាតណាដែលបានធ្វើតេស្តរួចហើយ នឹងធ្វើឱ្យម៉ាស៊ីនរោទិ៍ (reuse alarm)។ បោះចោលកាតដែលធ្វើឱ្យរោទិ៍ ហើយប្រើកាតថ្មីដែលមិនទាន់ប្រើ។ ចាប់ពីពេលនេះទៅ សូមបោះចោលកាតនីមួយៗភ្លាមៗក្រោយធ្វើតេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q04','MO-06','Mis-operation','What should I do right after a test so I don''t reuse the card?','ក្រោយតេស្តភ្លាម ត្រូវធ្វើអ្វីដើម្បីកុំប្រើកាតម្តងទៀត?','Put the card in the waste bag right after testing, so it can''t be reinserted.','ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយធ្វើតេស្ត ដើម្បីកុំឱ្យវាត្រូវដាក់ចូលម៉ាស៊ីនម្តងទៀត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q05','MO-06','Mis-operation','So I should confirm the card is unused before inserting it?','មានន័យថា ខ្ញុំគួរពិនិត្យថាកាតមិនទាន់ប្រើ មុនដាក់ចូល?','Yes. Confirm the card is new and unused before inserting it.','បាទ/ចាស។ ពិនិត្យឱ្យប្រាកដថាកាតជាកាតថ្មី និងមិនទាន់ប្រើ មុនដាក់ចូល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q06','MO-06','Mis-operation','What should I confirm about a card before inserting it?','ត្រូវពិនិត្យអ្វីលើកាត មុនដាក់ចូល?','That it''s new and unused.','ថាវាជាកាតថ្មី និងមិនទាន់ប្រើ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q07','MO-06','Mis-operation','Should I check that a card hasn''t been used before inserting it?','តើគួរពិនិត្យថាកាតមិនទាន់ប្រើ មុនដាក់ចូលទេ?','Yes. Confirm the card is new and unused before inserting it.','បាទ/ចាស។ ពិនិត្យឱ្យប្រាកដថាកាតជាកាតថ្មី និងមិនទាន់ប្រើ មុនដាក់ចូល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q08','MO-06','Mis-operation','How do I keep used and new cards from getting mixed up?','ធ្វើម៉េចកុំឱ្យកាតប្រើរួច និងកាតថ្មីច្រឡំគ្នា?','Put the card in the waste bag right after testing, so it can''t be reinserted.','ដាក់កាតចូលថង់កាកសំណល់ភ្លាមៗក្រោយធ្វើតេស្ត ដើម្បីកុំឱ្យវាត្រូវដាក់ចូលម៉ាស៊ីនម្តងទៀត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q09','MO-06','Mis-operation','Should used cards be thrown away right after testing?','តើកាតប្រើរួចគួរបោះចោលភ្លាមក្រោយធ្វើតេស្តទេ?','Yes. Discard used cards right after testing.','បាទ/ចាស។ បោះចោលកាតដែលប្រើរួចភ្លាមៗក្រោយធ្វើតេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-06-Q10','MO-06','Mis-operation','The device alarms because I inserted a used card. What should I do?','ម៉ាស៊ីនរោទិ៍ ព្រោះខ្ញុំដាក់កាតប្រើរួច។ ត្រូវធ្វើម៉េច?','Remove the used card and insert a new, unused one. Discard used cards right after testing.','ដកកាតដែលប្រើរួចចេញ ហើយដាក់កាតថ្មីដែលមិនទាន់ប្រើ។ បោះចោលកាតដែលប្រើរួចភ្លាមៗក្រោយធ្វើតេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-07','MO-07','Mis-operation','Expired cards still kept in stock','ក្នុងស្តុកនៅមានកាតផុតកំណត់។ ត្រូវធ្វើម៉េចជាមួយកាតទាំងនេះ?','Discard expired cards; only use cards within their expiry date','បោះចោលកាតដែលផុតកំណត់។ ប្រើតែកាតដែលនៅក្នុងកាលកំណត់ប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-07-Q01','MO-07','Mis-operation','What should I do with expired cards I still have in stock?','ត្រូវធ្វើអ្វីជាមួយកាតផុតកំណត់ដែលនៅក្នុងស្តុក?','Discard expired cards and only use cards that are within their expiry date.','បោះចោលកាតដែលផុតកំណត់ ហើយប្រើតែកាតដែលនៅក្នុងកាលកំណត់ប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08','MO-08','Mis-operation','Operator wants to retest the same card (first run failed, or to double-check the result)','បើតេស្តមិនបាន ឬចង់ពិនិត្យលទ្ធផលម្តងទៀត អាចប្រើកាតដដែលបានទេ?','Each card is single-use. Discard it and use a new card with a fresh sample','កាតនីមួយៗប្រើបានតែម្តងប៉ុណ្ណោះ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មីជាមួយសំណាកថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q01','MO-08','Mis-operation','Can I reuse a test card if the first run failed?','តើអាចប្រើកាតតេស្តម្តងទៀតបានទេ បើលើកទីមួយបរាជ័យ?','No. Each card can only be tested once. The device alarms and won''t run a used card. Discard it and use a new card.','មិនបានទេ។ កាតនីមួយៗធ្វើតេស្តបានតែម្តងប៉ុណ្ណោះ។ ម៉ាស៊ីននឹងរោទិ៍ ហើយមិនដំណើរការកាតដែលប្រើរួចទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q02','MO-08','Mis-operation','Is it OK to retest the same card just to double-check the result?','តើអាចធ្វើតេស្តកាតដដែលម្តងទៀត ដើម្បីផ្ទៀងផ្ទាត់លទ្ធផលបានទេ?','No. Each card can only be tested once. The device alarms and won''t run a used card. Discard it and use a new card.','មិនបានទេ។ កាតនីមួយៗធ្វើតេស្តបានតែម្តងប៉ុណ្ណោះ។ ម៉ាស៊ីននឹងរោទិ៍ ហើយមិនដំណើរការកាតដែលប្រើរួចទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q03','MO-08','Mis-operation','Can I override the reuse alarm and run the test anyway?','តើអាចរំលងការរោទិ៍ reuse ហើយធ្វើតេស្តតែម្តងបានទេ?','No. Each card can only be tested once. The device alarms and won''t run a used card. Discard it and use a new card.','មិនបានទេ។ កាតនីមួយៗធ្វើតេស្តបានតែម្តងប៉ុណ្ណោះ។ ម៉ាស៊ីននឹងរោទិ៍ ហើយមិនដំណើរការកាតដែលប្រើរួចទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q04','MO-08','Mis-operation','I''m new — can a card be used more than once?','ខ្ញុំទើបប្រើ Pluslife។ តើកាតមួយប្រើបានច្រើនដងទេ?','No. Each card can only be tested once. The device alarms and won''t run a used card. Discard it and use a new card.','មិនបានទេ។ កាតនីមួយៗធ្វើតេស្តបានតែម្តងប៉ុណ្ណោះ។ ម៉ាស៊ីននឹងរោទិ៍ ហើយមិនដំណើរការកាតដែលប្រើរួចទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q05','MO-08','Mis-operation','Can a test cartridge be used twice?','តើកាតតេស្តប្រើបានពីរដងទេ?','No. Each card can only be tested once. The device alarms and won''t run a used card. Discard it and use a new card.','មិនបានទេ។ កាតនីមួយៗធ្វើតេស្តបានតែម្តងប៉ុណ្ណោះ។ ម៉ាស៊ីននឹងរោទិ៍ ហើយមិនដំណើរការកាតដែលប្រើរួចទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q06','MO-08','Mis-operation','same card test again possible?','កាតដដែល តេស្តម្តងទៀតបានទេ?','No. Each card can only be tested once. The device alarms and won''t run a used card. Discard it and use a new card.','មិនបានទេ។ កាតនីមួយៗធ្វើតេស្តបានតែម្តងប៉ុណ្ណោះ។ ម៉ាស៊ីននឹងរោទិ៍ ហើយមិនដំណើរការកាតដែលប្រើរួចទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q07','MO-08','Mis-operation','So every card is single-use and must be discarded after testing?','មានន័យថា កាតនីមួយៗប្រើបានតែម្តង ហើយត្រូវបោះចោលក្រោយតេស្ត?','Yes. Each card is single-use. Discard it right after testing and use a new card for the next test.','បាទ/ចាស។ កាតនីមួយៗប្រើបានតែម្តងប៉ុណ្ណោះ។ បោះចោលវាភ្លាមៗក្រោយធ្វើតេស្ត ហើយប្រើកាតថ្មីសម្រាប់តេស្តបន្ទាប់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q08','MO-08','Mis-operation','Can I put a tested card back into the device?','តើអាចដាក់កាតដែលធ្វើតេស្តរួច ចូលម៉ាស៊ីនវិញបានទេ?','No. Each card can only be tested once. The device alarms and won''t run a used card. Discard it and use a new card.','មិនបានទេ។ កាតនីមួយៗធ្វើតេស្តបានតែម្តងប៉ុណ្ណោះ។ ម៉ាស៊ីននឹងរោទិ៍ ហើយមិនដំណើរការកាតដែលប្រើរួចទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-08-Q09','MO-08','Mis-operation','Can I insert the same reaction card a second time?','តើអាចដាក់កាតប្រតិកម្មដដែលលើកទីពីរបានទេ?','No. Each card can only be tested once. The device alarms and won''t run a used card. Discard it and use a new card.','មិនបានទេ។ កាតនីមួយៗធ្វើតេស្តបានតែម្តងប៉ុណ្ណោះ។ ម៉ាស៊ីននឹងរោទិ៍ ហើយមិនដំណើរការកាតដែលប្រើរួចទេ។ បោះចោលកាតនោះ ហើយប្រើកាតថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-09','MO-09','Mis-operation','Several cards unpacked or prepared in advance for a busy session','ថ្ងៃនេះមានអ្នកជំងឺច្រើន។ អាចបើកកញ្ចប់កាតច្រើនទុកជាមុនបានទេ?','Unpack each card only after sample pretreatment is finished, right before adding the sample, and test it immediately after mixing','ហែកកាតនីមួយៗ តែក្រោយការរៀបចំសំណាក (pretreatment) រួចរាល់ ភ្លាមៗមុនពេលដាក់សំណាក ហើយធ្វើតេស្តភ្លាមៗក្រោយលាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-09-Q01','MO-09','Mis-operation','Can I wait before inserting the prepared card?','តើអាចរង់ចាំ មុនដាក់កាតដែលរៀបចំរួចបានទេ?','No. Test the card immediately after mixing.','មិនបានទេ។ ធ្វើតេស្តកាតភ្លាមៗក្រោយលាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-09-Q02','MO-09','Mis-operation','How soon after mixing do I need to test the card?','ក្រោយលាយ ត្រូវធ្វើតេស្តកាតលឿនប៉ុណ្ណា?','Immediately.','ភ្លាមៗ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-09-Q03','MO-09','Mis-operation','Can I prepare several cards and test them later?','តើអាចរៀបចំកាតច្រើន ហើយធ្វើតេស្តពេលក្រោយបានទេ?','No. Each card must be tested immediately after mixing.','មិនបានទេ។ កាតនីមួយៗត្រូវធ្វើតេស្តភ្លាមៗក្រោយលាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-09-Q04','MO-09','Mis-operation','Should the device be ready before I prepare the card?','តើម៉ាស៊ីនគួររួចរាល់ មុនខ្ញុំរៀបចំកាតទេ?','Yes. The device should be ready (solid blue) before you prepare the card.','បាទ/ចាស។ ម៉ាស៊ីនគួរតែរួចរាល់ (ភ្លើងពណ៌ខៀវភ្លឺជាប់) មុនពេលអ្នករៀបចំកាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-09-Q05','MO-09','Mis-operation','prepared card waiting time','រៀបចំកាតរួច អាចទុកបានប៉ុន្មាននាទីមុនធ្វើតេស្ត?','None. Test it immediately after mixing.','មិនត្រូវរង់ចាំទេ។ ធ្វើតេស្តភ្លាមៗក្រោយលាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01','PC-01','Power & Connectivity','Device won''t reach ready status, disconnects frequently, or produces inconsistent/false results','ម៉ាស៊ីនមិនឡើងភ្លើងខៀវ ដាច់ការតភ្ជាប់ញឹកញាប់ ឬលទ្ធផលមិនទៀង។ ត្រូវពិនិត្យអ្វីមុន?','Use only the original Pluslife power adapter and Type-C data cable supplied with the device','ប្រើតែអាដាប់ទ័រភ្លើង (power adapter) និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q01','PC-01','Power & Connectivity','Can I use my phone charger to power the device?','តើអាចប្រើឆ្នាំងសាកទូរស័ព្ទ ដើម្បីដោតភ្លើងម៉ាស៊ីនបានទេ?','No. Use only the original Pluslife power adapter and Type-C cable supplied with the device. Others can stop the device reaching ready status, cause frequent disconnections, or even give false results.','មិនបានទេ។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។ អាដាប់ទ័រផ្សេង អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ដាច់ការតភ្ជាប់ញឹកញាប់ ឬសូម្បីតែផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q02','PC-01','Power & Connectivity','The device never reaches ready status.','ម៉ាស៊ីនមិនដែលឡើងស្ថានភាពរួចរាល់ទេ?','Check that you''re using the original Pluslife power adapter and Type-C cable. Non-original ones can stop the device reaching ready status or cause frequent disconnections.','ពិនិត្យថាអ្នកកំពុងប្រើអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife។ អាដាប់ទ័រមិនមែនដើម អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ឬដាច់ការតភ្ជាប់ញឹកញាប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q03','PC-01','Power & Connectivity','My device keeps disconnecting.','ម៉ាស៊ីនរបស់ខ្ញុំដាច់ការតភ្ជាប់រហូត។ ត្រូវធ្វើម៉េច?','Check that you''re using the original Pluslife power adapter and Type-C cable. Non-original ones can stop the device reaching ready status or cause frequent disconnections.','ពិនិត្យថាអ្នកកំពុងប្រើអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife។ អាដាប់ទ័រមិនមែនដើម អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ឬដាច់ការតភ្ជាប់ញឹកញាប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q04','PC-01','Power & Connectivity','power adapter compatibility','អាដាប់ទ័រប្រភេទណាខ្លះអាចប្រើជាមួយម៉ាស៊ីននេះបាន?','Use only the original Pluslife power adapter and Type-C data cable supplied with the device.','ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q05','PC-01','Power & Connectivity','I lost the original cable — can I use any USB-C cable?','ខ្ញុំបាត់ខ្សែដើម — តើអាចប្រើខ្សែ USB-C ណាក៏បានទេ?','No. Use only the original Pluslife power adapter and Type-C cable supplied with the device. Others can stop the device reaching ready status, cause frequent disconnections, or even give false results.','មិនបានទេ។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។ អាដាប់ទ័រផ្សេង អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ដាច់ការតភ្ជាប់ញឹកញាប់ ឬសូម្បីតែផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q06','PC-01','Power & Connectivity','What power supply should I use with the device?','គួរប្រើប្រភពភ្លើងអ្វីជាមួយម៉ាស៊ីន?','Use only the original Pluslife power adapter and Type-C data cable supplied with the device.','ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q07','PC-01','Power & Connectivity','device keeps dropping connection','ម៉ាស៊ីនដាច់ការតភ្ជាប់រហូត','Check that you''re using the original Pluslife power adapter and Type-C cable. Non-original ones can stop the device reaching ready status or cause frequent disconnections.','ពិនិត្យថាអ្នកកំពុងប្រើអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife។ អាដាប់ទ័រមិនមែនដើម អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ឬដាច់ការតភ្ជាប់ញឹកញាប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q08','PC-01','Power & Connectivity','Do I have to use the cable that came in the box?','តើត្រូវប្រើខ្សែដែលមកជាមួយប្រអប់ទេ?','Yes. Use only the original Pluslife power adapter and Type-C cable supplied with the device.','បាទ/ចាស។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q09','PC-01','Power & Connectivity','Non-original power adapter.','អាដាប់ទ័រភ្លើងមិនមែនដើម។ ត្រូវធ្វើម៉េច?','Don''t use one. Use only the original Pluslife power adapter and Type-C cable; others can cause failure to reach ready status, disconnections or false results.','កុំប្រើ។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ប៉ុណ្ណោះ។ អាដាប់ទ័រផ្សេង អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ ដាច់ការតភ្ជាប់ ឬផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q10','PC-01','Power & Connectivity','How do I avoid power-related issues with the device?','ធ្វើម៉េចជៀសវាងបញ្ហាភ្លើងជាមួយម៉ាស៊ីន?','Use only the original Pluslife power adapter and Type-C data cable supplied with the device.','ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q11','PC-01','Power & Connectivity','I''m new — does it matter which charger I plug the device into?','ខ្ញុំទើបប្រើ Pluslife។ តើដោតម៉ាស៊ីនជាមួយឆ្នាំងសាកណាក៏បានមែនទេ?','Yes. Use only the original Pluslife power adapter and Type-C cable supplied with the device.','បាទ/ចាស។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q12','PC-01','Power & Connectivity','Can I use a generic power brick?','តើអាចប្រើអាដាប់ទ័រភ្លើងធម្មតាបានទេ?','No. Use only the original Pluslife power adapter and Type-C cable supplied with the device. Others can stop the device reaching ready status, cause frequent disconnections, or even give false results.','មិនបានទេ។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។ អាដាប់ទ័រផ្សេង អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ដាច់ការតភ្ជាប់ញឹកញាប់ ឬសូម្បីតែផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q13','PC-01','Power & Connectivity','The device keeps dropping out and won''t get to ready.','ម៉ាស៊ីនដាច់ៗរហូត ហើយមិនឡើងរួចរាល់។ ត្រូវធ្វើម៉េច?','Check that you''re using the original Pluslife power adapter and Type-C cable. Non-original ones can stop the device reaching ready status or cause frequent disconnections.','ពិនិត្យថាអ្នកកំពុងប្រើអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife។ អាដាប់ទ័រមិនមែនដើម អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ឬដាច់ការតភ្ជាប់ញឹកញាប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q14','PC-01','Power & Connectivity','use other charger ok?','ប្រើឆ្នាំងសាកផ្សេង បានទេ?','No. Use only the original Pluslife power adapter and Type-C cable supplied with the device. Others can stop the device reaching ready status, cause frequent disconnections, or even give false results.','មិនបានទេ។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។ អាដាប់ទ័រផ្សេង អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ដាច់ការតភ្ជាប់ញឹកញាប់ ឬសូម្បីតែផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q15','PC-01','Power & Connectivity','So I should only use the Pluslife adapter and Type-C cable that came with it?','មានន័យថា ខ្ញុំគួរប្រើតែអាដាប់ទ័រ Pluslife និងខ្សែ Type-C ដែលមកជាមួយប៉ុណ្ណោះ?','Yes. Use only the original Pluslife power adapter and Type-C cable supplied with the device.','បាទ/ចាស។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q16','PC-01','Power & Connectivity','Which power adapter should I use for the MiniDock?','គួរប្រើអាដាប់ទ័រភ្លើងមួយណាសម្រាប់ MiniDock?','Use only the original Pluslife power adapter and Type-C data cable supplied with the device.','ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q17','PC-01','Power & Connectivity','Can I use a different Type-C data cable?','តើអាចប្រើខ្សែ Type-C ផ្សេងបានទេ?','No. Use only the original Pluslife power adapter and Type-C cable supplied with the device. Others can stop the device reaching ready status, cause frequent disconnections, or even give false results.','មិនបានទេ។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។ អាដាប់ទ័រផ្សេង អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ដាច់ការតភ្ជាប់ញឹកញាប់ ឬសូម្បីតែផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q18','PC-01','Power & Connectivity','Is it OK to use a non-Pluslife adapter?','តើអាចប្រើអាដាប់ទ័រមិនមែន Pluslife បានទេ?','No. Use only the original Pluslife power adapter and Type-C cable supplied with the device. Others can stop the device reaching ready status, cause frequent disconnections, or even give false results.','មិនបានទេ។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។ អាដាប់ទ័រផ្សេង អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ដាច់ការតភ្ជាប់ញឹកញាប់ ឬសូម្បីតែផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q19','PC-01','Power & Connectivity','The device disconnects often. What should I check?','ម៉ាស៊ីនដាច់ការតភ្ជាប់ញឹកញាប់។ គួរពិនិត្យអ្វី?','Check that you''re using the original Pluslife power adapter and Type-C cable. Non-original ones can stop the device reaching ready status or cause frequent disconnections.','ពិនិត្យថាអ្នកកំពុងប្រើអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife។ អាដាប់ទ័រមិនមែនដើម អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ឬដាច់ការតភ្ជាប់ញឹកញាប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-01-Q20','PC-01','Power & Connectivity','Can I borrow a charger from another device to power the MiniDock?','តើអាចខ្ចីឆ្នាំងសាកពីឧបករណ៍ផ្សេង មកដោតភ្លើង MiniDock បានទេ?','No. Use only the original Pluslife power adapter and Type-C cable supplied with the device. Others can stop the device reaching ready status, cause frequent disconnections, or even give false results.','មិនបានទេ។ ប្រើតែអាដាប់ទ័រភ្លើង និងខ្សែ Type-C ដើមរបស់ Pluslife ដែលភ្ជាប់មកជាមួយម៉ាស៊ីនប៉ុណ្ណោះ។ អាដាប់ទ័រផ្សេង អាចធ្វើឱ្យម៉ាស៊ីនមិនឡើងភ្លើងខៀវ (រួចរាល់) ដាច់ការតភ្ជាប់ញឹកញាប់ ឬសូម្បីតែផ្តល់លទ្ធផលខុស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02','PC-02','Power & Connectivity','Device/app cannot find or connect to the MiniDock over WiFi','កម្មវិធីរក MiniDock មិនឃើញ ឬភ្ជាប់តាម Wi‑Fi មិនបាន។ ត្រូវធ្វើម៉េច?','Confirm router broadcasts a 2.4GHz signal and that the connecting PC/mobile shares the same IP segment as the device','ពិនិត្យថា Router បញ្ចេញរលក WiFi 2.4GHz ហើយកុំព្យូទ័រ/ទូរស័ព្ទ នៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q01','PC-02','Power & Connectivity','The app can''t find my MiniDock over WiFi.','កម្មវិធី រកមិនឃើញ MiniDock របស់ខ្ញុំតាម Wi‑Fi?','Check two things: (1) the router broadcasts a 2.4GHz signal; (2) your PC/phone is on the same IP segment as the device (first 3 parts of the IP address match).','ពិនិត្យ ២ ចំណុច៖ (១) Router បញ្ចេញរលក WiFi 2.4GHz។ (២) កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក នៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q02','PC-02','Power & Connectivity','Does the device support 5GHz WiFi?','តើម៉ាស៊ីនគាំទ្រ Wi‑Fi 5GHz ទេ?','No. The device needs a 2.4GHz WiFi signal.','មិនបានទេ។ ម៉ាស៊ីនត្រូវការរលក WiFi 2.4GHz។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q03','PC-02','Power & Connectivity','wifi not connecting','ម៉ាស៊ីនភ្ជាប់ Wi‑Fi មិនបាន។ ត្រូវធ្វើម៉េច?','Check two things: (1) the router broadcasts a 2.4GHz signal; (2) your PC/phone is on the same IP segment as the device (first 3 parts of the IP address match).','ពិនិត្យ ២ ចំណុច៖ (១) Router បញ្ចេញរលក WiFi 2.4GHz។ (២) កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក នៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q04','PC-02','Power & Connectivity','My PC and the device are on the same network but still can''t connect.','កុំព្យូទ័រ និងម៉ាស៊ីននៅលើបណ្តាញតែមួយ តែនៅតែភ្ជាប់មិនបាន?','Check that the router broadcasts 2.4GHz and that the first 3 parts of both IP addresses match.','ពិនិត្យថា Router បញ្ចេញរលក 2.4GHz ហើយលេខ ៣ ផ្នែកដំបូងនៃ IP ទាំងពីរដូចគ្នា។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q05','PC-02','Power & Connectivity','Will the device connect if my router only has 5GHz?','តើម៉ាស៊ីនភ្ជាប់បានទេ បើ Router មានតែ 5GHz?','No. The device needs a 2.4GHz WiFi signal.','មិនបានទេ។ ម៉ាស៊ីនត្រូវការរលក WiFi 2.4GHz។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q06','PC-02','Power & Connectivity','minidock not found','កម្មវិធីរក MiniDock មិនឃើញ។ ត្រូវធ្វើម៉េច?','Check two things: (1) the router broadcasts a 2.4GHz signal; (2) your PC/phone is on the same IP segment as the device (first 3 parts of the IP address match).','ពិនិត្យ ២ ចំណុច៖ (១) Router បញ្ចេញរលក WiFi 2.4GHz។ (២) កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក នៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q07','PC-02','Power & Connectivity','Does my phone need to be on the same WiFi as the device?','តើទូរស័ព្ទខ្ញុំត្រូវនៅលើ Wi‑Fi តែមួយជាមួយម៉ាស៊ីនទេ?','Yes. Your PC/phone must be on the same IP segment as the device (first 3 parts of the IP address match).','បាទ/ចាស។ កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក ត្រូវនៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q08','PC-02','Power & Connectivity','MiniDock WiFi connection failed.','ការភ្ជាប់ Wi‑Fi របស់ MiniDock បរាជ័យ។ ត្រូវធ្វើម៉េច?','Check two things: (1) the router broadcasts a 2.4GHz signal; (2) your PC/phone is on the same IP segment as the device (first 3 parts of the IP address match).','ពិនិត្យ ២ ចំណុច៖ (១) Router បញ្ចេញរលក WiFi 2.4GHz។ (២) កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក នៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q09','PC-02','Power & Connectivity','How do I set up WiFi correctly for the MiniDock?','ធ្វើម៉េចកំណត់ Wi‑Fi ឱ្យត្រឹមត្រូវសម្រាប់ MiniDock?','The network must have a 2.4GHz signal, and your PC/phone must be on the same IP segment as the device (first 3 parts of the IP address match). WiFi is set up from the device card in the software.','បណ្តាញត្រូវមានរលក 2.4GHz ហើយកុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក ត្រូវនៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។ ការកំណត់ WiFi ធ្វើនៅលើកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q10','PC-02','Power & Connectivity','Does a 5GHz network stop the device from connecting?','តើបណ្តាញ 5GHz ធ្វើឱ្យម៉ាស៊ីនភ្ជាប់មិនបានទេ?','Yes, if there''s no 2.4GHz signal. The device needs 2.4GHz.','បាទ/ចាស បើគ្មានរលក 2.4GHz។ ម៉ាស៊ីនត្រូវការ 2.4GHz។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q11','PC-02','Power & Connectivity','I''m new — what are the WiFi requirements for the device?','ខ្ញុំទើបប្រើ Pluslife។ តម្រូវការ Wi‑Fi សម្រាប់ម៉ាស៊ីនមានអ្វីខ្លះ?','The network must have a 2.4GHz signal, and your PC/phone must be on the same IP segment as the device (first 3 parts of the IP address match). WiFi is set up from the device card in the software.','បណ្តាញត្រូវមានរលក 2.4GHz ហើយកុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក ត្រូវនៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។ ការកំណត់ WiFi ធ្វើនៅលើកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q12','PC-02','Power & Connectivity','The device doesn''t show up on the wireless network.','ម៉ាស៊ីនមិនបង្ហាញលើបណ្តាញឥតខ្សែ។ ត្រូវធ្វើម៉េច?','Check two things: (1) the router broadcasts a 2.4GHz signal; (2) your PC/phone is on the same IP segment as the device (first 3 parts of the IP address match).','ពិនិត្យ ២ ចំណុច៖ (១) Router បញ្ចេញរលក WiFi 2.4GHz។ (២) កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក នៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q13','PC-02','Power & Connectivity','App searching forever, never finds the device.','កម្មវិធី ស្វែងរករហូត ហើយរកមិនឃើញម៉ាស៊ីនសោះ។ ត្រូវធ្វើម៉េច?','Check two things: (1) the router broadcasts a 2.4GHz signal; (2) your PC/phone is on the same IP segment as the device (first 3 parts of the IP address match).','ពិនិត្យ ២ ចំណុច៖ (១) Router បញ្ចេញរលក WiFi 2.4GHz។ (២) កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក នៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q14','PC-02','Power & Connectivity','wifi cannot find device','Wi‑Fi រកម៉ាស៊ីនមិនឃើញ។ ត្រូវធ្វើម៉េច?','Check two things: (1) the router broadcasts a 2.4GHz signal; (2) your PC/phone is on the same IP segment as the device (first 3 parts of the IP address match).','ពិនិត្យ ២ ចំណុច៖ (១) Router បញ្ចេញរលក WiFi 2.4GHz។ (២) កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក នៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q15','PC-02','Power & Connectivity','My PC''s IP is 192.168.1.x and the device is 192.168.0.x. Is that the issue?','IP កុំព្យូទ័រខ្ញុំគឺ 192.168.1.x ហើយម៉ាស៊ីនគឺ 192.168.0.x។ តើនេះជាបញ្ហាមែនទេ?','Yes. The first 3 parts of the IP must match. 192.168.1.x and 192.168.0.x are different segments.','បាទ/ចាស។ លេខ ៣ ផ្នែកដំបូងនៃ IP ត្រូវតែដូចគ្នា។ 192.168.1.x និង 192.168.0.x ជា segment ខុសគ្នា។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q16','PC-02','Power & Connectivity','So the router must broadcast 2.4GHz and my PC or phone must be on the same IP segment as the device?','មានន័យថា Router ត្រូវបញ្ចេញ 2.4GHz ហើយកុំព្យូទ័រ ឬទូរស័ព្ទត្រូវនៅ IP segment តែមួយជាមួយម៉ាស៊ីន?','Yes. Both are required.','បាទ/ចាស។ ត្រូវការទាំងពីរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q17','PC-02','Power & Connectivity','What WiFi band does the device need?','ម៉ាស៊ីនត្រូវការ Wi‑Fi រលកប៉ុន្មាន?','2.4GHz.','2.4GHz។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q18','PC-02','Power & Connectivity','My router is dual-band. Which band should I use?','Router ខ្ញុំមានពីររលក (dual-band)។ គួរប្រើរលកមួយណា?','2.4GHz.','2.4GHz។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q19','PC-02','Power & Connectivity','Do my computer and the device need to be on the same IP segment?','តើកុំព្យូទ័រ និងម៉ាស៊ីនត្រូវនៅ IP segment តែមួយទេ?','Yes. Your PC/phone must be on the same IP segment as the device (first 3 parts of the IP address match).','បាទ/ចាស។ កុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក ត្រូវនៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-02-Q20','PC-02','Power & Connectivity','What are the network requirements for the WiFi connection?','តម្រូវការបណ្តាញសម្រាប់ការភ្ជាប់ Wi‑Fi មានអ្វីខ្លះ?','The network must have a 2.4GHz signal, and your PC/phone must be on the same IP segment as the device (first 3 parts of the IP address match). WiFi is set up from the device card in the software.','បណ្តាញត្រូវមានរលក 2.4GHz ហើយកុំព្យូទ័រ/ទូរស័ព្ទរបស់អ្នក ត្រូវនៅក្នុង IP segment តែមួយជាមួយម៉ាស៊ីន (លេខ ៣ ផ្នែកដំបូងនៃ IP ដូចគ្នា)។ ការកំណត់ WiFi ធ្វើនៅលើកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03','PC-03','Power & Connectivity','Worker unsure how to connect the device, or whether a PC/phone is needed','ភ្ជាប់ MiniDock ដោយរបៀបណា? ត្រូវការកុំព្យូទ័រ ឬទូរស័ព្ទទេ?','The MiniDock Ultra can run standalone (lights show the result); connecting to PluslifePad is recommended. PC: USB Type-C cable (the one supplied) or WiFi. Mobile: WiFi or Bluetooth. Results sync automatically','MiniDock Ultra អាចដំណើរការតែឯងបាន (ភ្លើងលើម៉ាស៊ីនបង្ហាញលទ្ធផល)។ គួរភ្ជាប់ជាមួយកម្មវិធី PluslifePad។ ភ្ជាប់កុំព្យូទ័រ៖ ខ្សែ USB Type-C (ខ្សែដែលភ្ជាប់មកជាមួយ) ឬ WiFi។ ភ្ជាប់ទូរស័ព្ទ៖ WiFi ឬ Bluetooth។ លទ្ធផលនឹងធ្វើសមកាលកម្ម (sync) ដោយស្វ័យប្រវត្តិ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q01','PC-03','Power & Connectivity','Do I need a computer to run the test?','តើត្រូវការកុំព្យូទ័រ ដើម្បីធ្វើតេស្តទេ?','No. The MiniDock Ultra can run standalone. Connecting it to PluslifePad is recommended.','មិនចាំបាច់ទេ។ MiniDock Ultra អាចដំណើរការតែឯងបាន។ ប៉ុន្តែគួរភ្ជាប់ជាមួយកម្មវិធី PluslifePad។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q02','PC-03','Power & Connectivity','Can the MiniDock work without a PC?','តើ MiniDock អាចដំណើរការដោយគ្មានកុំព្យូទ័របានទេ?','Yes. It can run standalone; no computer is required.','បាទ/ចាស។ វាអាចដំណើរការតែឯងបាន មិនត្រូវការកុំព្យូទ័រទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q03','PC-03','Power & Connectivity','How do I connect the device to a computer?','ភ្ជាប់ម៉ាស៊ីនជាមួយកុំព្យូទ័រយ៉ាងម៉េច?','Connect it with the USB Type-C cable and open PluslifePad. It can also connect to a PC over WiFi.','ភ្ជាប់ដោយខ្សែ USB Type-C ហើយបើកកម្មវិធី PluslifePad។ វាក៏អាចភ្ជាប់ជាមួយកុំព្យូទ័រតាម WiFi បានដែរ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q04','PC-03','Power & Connectivity','Can I connect the device to my phone?','តើអាចភ្ជាប់ម៉ាស៊ីនជាមួយទូរស័ព្ទបានទេ?','Yes. It connects to a mobile via WiFi or Bluetooth.','បាទ/ចាស។ វាភ្ជាប់ជាមួយទូរស័ព្ទតាម WiFi ឬ Bluetooth។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q05','PC-03','Power & Connectivity','Does the device support Bluetooth?','តើម៉ាស៊ីនគាំទ្រ Bluetooth ទេ?','Yes. Bluetooth is used for connecting to a mobile.','បាទ/ចាស។ Bluetooth ប្រើសម្រាប់ភ្ជាប់ជាមួយទូរស័ព្ទ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q06','PC-03','Power & Connectivity','Do I have to use the software?','តើត្រូវប្រើកម្មវិធីទេ?','No. The device can run standalone, but using the software is recommended.','មិនចាំបាច់ទេ។ ម៉ាស៊ីនអាចដំណើរការតែឯងបាន ប៉ុន្តែគួរប្រើកម្មវិធី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q07','PC-03','Power & Connectivity','Do results sync to the software automatically?','តើលទ្ធផល sync ទៅកម្មវិធីដោយស្វ័យប្រវត្តិទេ?','Yes. Results sync automatically.','បាទ/ចាស។ លទ្ធផលធ្វើសមកាលកម្ម (sync) ដោយស្វ័យប្រវត្តិ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q08','PC-03','Power & Connectivity','standalone mode','អាចប្រើម៉ាស៊ីនដោយមិនភ្ជាប់កុំព្យូទ័រ ឬទូរស័ព្ទបានទេ?','The MiniDock Ultra can run standalone, without a computer. The device lights show the result.','MiniDock Ultra អាចដំណើរការតែឯងបាន ដោយគ្មានកុំព្យូទ័រ។ ភ្លើងលើម៉ាស៊ីនបង្ហាញលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q09','PC-03','Power & Connectivity','What connection options does the MiniDock have?','MiniDock មានជម្រើសភ្ជាប់អ្វីខ្លះ?','USB Type-C or WiFi to a PC; WiFi or Bluetooth to a mobile.','USB Type-C ឬ WiFi សម្រាប់កុំព្យូទ័រ។ WiFi ឬ Bluetooth សម្រាប់ទូរស័ព្ទ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-03-Q10','PC-03','Power & Connectivity','Which cable connects the device to the computer?','ខ្សែមួយណាភ្ជាប់ម៉ាស៊ីនជាមួយកុំព្យូទ័រ?','The USB Type-C data cable supplied with the device.','ខ្សែ USB Type-C ដែលភ្ជាប់មកជាមួយម៉ាស៊ីន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04','PC-04','Power & Connectivity','Mains power is unreliable, or the site is off-grid','មណ្ឌលសុខភាពខ្ញុំដាច់ភ្លើងញឹកញាប់ ឬគ្មានភ្លើងបណ្តាញ។ តើប្រើ MiniDock ដោយរបៀបណា?','Use the Pluslife Portable UPS. For 1 MiniDock Ultra + 1 Thermolyse: 600W ≈ 20+ h (40+ tests); 1200W ≈ 40+ h (80+ tests). Recharge by solar panel (12-24 V DC, 5 A max, DC5521) or Type-C PD; 10%→100% takes ≈ 5-6 h (600W) or 10-11 h (1200W)','ប្រើ Pluslife Portable UPS (ថ្មបម្រុងភ្លើង)។ សម្រាប់ MiniDock Ultra ១ គ្រឿង + Thermolyse ១ គ្រឿង៖ UPS 600W ប្រើបានប្រហែល ២០ ម៉ោងជាង (ជាង ៤០ តេស្ត)។ UPS 1200W ប្រើបានប្រហែល ៤០ ម៉ោងជាង (ជាង ៨០ តេស្ត)។ សាកថ្មដោយផ្ទាំងសូឡា (12-24 V DC, អតិបរមា 5 A, DC5521) ឬ Type-C PD។ សាកពី ១០% ដល់ ១០០% ចំណាយប្រហែល ៥-៦ ម៉ោង (600W) ឬ ១០-១១ ម៉ោង (1200W)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04-Q01','PC-04','Power & Connectivity','How long can the UPS power the MiniDock?','UPS អាចផ្គត់ផ្គង់ភ្លើងឱ្យ MiniDock បានយូរប៉ុណ្ណា?','For 1 MiniDock Ultra + 1 Thermolyse: 600W UPS about 20+ hours (40+ tests); 1200W UPS about 40+ hours (80+ tests).','សម្រាប់ MiniDock Ultra ១ គ្រឿង + Thermolyse ១ គ្រឿង៖ UPS 600W ប្រហែល ២០ ម៉ោងជាង (ជាង ៤០ តេស្ត)។ UPS 1200W ប្រហែល ៤០ ម៉ោងជាង (ជាង ៨០ តេស្ត)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04-Q02','PC-04','Power & Connectivity','How many tests can I run on the 600W UPS?','UPS 600W ធ្វើតេស្តបានប៉ុន្មាន?','40+ tests (about 20+ hours, for 1 MiniDock Ultra + 1 Thermolyse).','ជាង ៤០ តេស្ត (ប្រហែល ២០ ម៉ោងជាង សម្រាប់ MiniDock Ultra ១ គ្រឿង + Thermolyse ១ គ្រឿង)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04-Q03','PC-04','Power & Connectivity','How many tests can the 1200W UPS support?','UPS 1200W ធ្វើតេស្តបានប៉ុន្មាន?','80+ tests (about 40+ hours, for 1 MiniDock Ultra + 1 Thermolyse).','ជាង ៨០ តេស្ត (ប្រហែល ៤០ ម៉ោងជាង សម្រាប់ MiniDock Ultra ១ គ្រឿង + Thermolyse ១ គ្រឿង)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04-Q04','PC-04','Power & Connectivity','Can the UPS be charged with solar panels?','តើ UPS អាចសាកដោយផ្ទាំងសូឡាបានទេ?','Yes. Both UPS models support solar recharging (12-24 V DC input).','បាទ/ចាស។ UPS ទាំងពីរម៉ូដែល អាចសាកថ្មដោយផ្ទាំងសូឡាបាន (ចរន្តចូល 12-24 V DC)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04-Q05','PC-04','Power & Connectivity','How long does it take to charge the UPS?','សាក UPS ចំណាយពេលប៉ុន្មាន?','From 10% to 100%: about 5-6 h (600W) or 10-11 h (1200W).','ពី ១០% ដល់ ១០០%៖ ប្រហែល ៥-៦ ម៉ោង (600W) ឬ ១០-១១ ម៉ោង (1200W)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04-Q06','PC-04','Power & Connectivity','What can I use if the power supply is unreliable?','អាចប្រើអ្វី បើភ្លើងមិនទៀង?','The Pluslife Portable UPS (600W or 1200W). It can be recharged by solar panel for off-grid use.','Pluslife Portable UPS (600W ឬ 1200W)។ វាអាចសាកថ្មដោយផ្ទាំងសូឡា សម្រាប់កន្លែងដែលគ្មានភ្លើងរដ្ឋ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04-Q07','PC-04','Power & Connectivity','UPS backup time','ពេលដាច់ភ្លើង UPS អាចផ្គត់ផ្គង់ភ្លើងបានយូរប៉ុន្មាន?','For 1 MiniDock Ultra + 1 Thermolyse: 600W UPS about 20+ hours (40+ tests); 1200W UPS about 40+ hours (80+ tests).','សម្រាប់ MiniDock Ultra ១ គ្រឿង + Thermolyse ១ គ្រឿង៖ UPS 600W ប្រហែល ២០ ម៉ោងជាង (ជាង ៤០ តេស្ត)។ UPS 1200W ប្រហែល ៤០ ម៉ោងជាង (ជាង ៨០ តេស្ត)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-04-Q08','PC-04','Power & Connectivity','What solar input does the UPS accept?','UPS ទទួលចរន្តពីសូឡាប៉ុន្មាន?','12-24 V DC (5 A max, DC5521).','12-24 V DC (អតិបរមា 5 A, DC5521)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01','SC-01','Sample Collection','Sputum sample looks blood-stained (hemoptysis) or is actually saliva','កំហាកមានលាយឈាម ឬមើលទៅដូចទឹកមាត់។ អាចយកទៅធ្វើតេស្តបានទេ?','Only accept mucoid, purulent, or caseous sputum; reject blood-stained or saliva specimens and recollect','ទទួលយកតែកំហាកខាប់ស្អិត (mucoid) កំហាកមានខ្ទុះ (purulent) ឬកំហាកដូចឈីស (caseous) ប៉ុណ្ណោះ។ បដិសេធសំណាកដែលមានជាប់ឈាម ឬជាទឹកមាត់ ហើយយកសំណាកម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q01','SC-01','Sample Collection','The sputum has blood in it — can I still test it?','កំហាកមានឈាម — តើនៅតែធ្វើតេស្តបានទេ?','No. Blood-stained (hemoptysis) sputum isn''t acceptable. Recollect mucoid, purulent or caseous sputum.','មិនបានទេ។ កំហាកដែលមានជាប់ឈាម (ក្អកចេញឈាម/hemoptysis) មិនអាចទទួលយកបានទេ។ យកកំហាកខាប់ស្អិត កំហាកមានខ្ទុះ ឬកំហាកដូចឈីស ម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q02','SC-01','Sample Collection','What counts as a good sputum sample?','កំហាកបែបណាដែលចាត់ទុកថាល្អ?','Visible mucoid, purulent or caseous sputum. Blood-stained sputum and saliva are not acceptable.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q03','SC-01','Sample Collection','bloody sputum sample','កំហាកមានលាយឈាម។ អាចយកទៅធ្វើតេស្តបានទេ?','Not acceptable. Reject blood-stained sputum and recollect.','មិនអាចទទួលយកបានទេ។ បដិសេធកំហាកដែលមានជាប់ឈាម ហើយយកសំណាកម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q04','SC-01','Sample Collection','Which types of sputum are acceptable?','កំហាកប្រភេទណាខ្លះដែលអាចទទួលយកបាន?','Visible mucoid, purulent or caseous sputum. Blood-stained sputum and saliva are not acceptable.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q05','SC-01','Sample Collection','sputum quality requirements','កំហាកបែបណាទើបអាចយកមកធ្វើតេស្តបាន?','Visible mucoid, purulent or caseous sputum. Blood-stained sputum and saliva are not acceptable.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q06','SC-01','Sample Collection','When should I reject a sputum sample?','ពេលណាត្រូវបដិសេធសំណាកកំហាក?','Reject blood-stained (hemoptysis) specimens and saliva, and recollect.','បដិសេធសំណាកដែលមានជាប់ឈាម (hemoptysis) និងទឹកមាត់ ហើយយកសំណាកម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q07','SC-01','Sample Collection','Blood-stained sputum.','កំហាកមានជាប់ឈាម។ ត្រូវធ្វើម៉េច?','Not acceptable. Reject blood-stained sputum and recollect.','មិនអាចទទួលយកបានទេ។ បដិសេធកំហាកដែលមានជាប់ឈាម ហើយយកសំណាកម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q08','SC-01','Sample Collection','I''m new — what does acceptable sputum look like?','ខ្ញុំទើបប្រើ Pluslife។ កំហាកដែលទទួលយកបាន មើលទៅបែបណា?','Visible mucoid, purulent or caseous sputum. Blood-stained sputum and saliva are not acceptable.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q09','SC-01','Sample Collection','sputum have blood, can test?','កំហាកមានឈាម តេស្តបានទេ?','No. Blood-stained (hemoptysis) sputum isn''t acceptable. Recollect mucoid, purulent or caseous sputum.','មិនបានទេ។ កំហាកដែលមានជាប់ឈាម (ក្អកចេញឈាម/hemoptysis) មិនអាចទទួលយកបានទេ។ យកកំហាកខាប់ស្អិត កំហាកមានខ្ទុះ ឬកំហាកដូចឈីស ម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q10','SC-01','Sample Collection','The patient coughed up blood with the sputum. Should we recollect?','អ្នកជំងឺក្អកចេញឈាមជាមួយកំហាក។ តើគួរយកសំណាកម្តងទៀតទេ?','Yes. Blood-stained sputum isn''t acceptable. Recollect.','បាទ/ចាស។ កំហាកដែលមានជាប់ឈាម មិនអាចទទួលយកបានទេ។ សូមយកសំណាកម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q11','SC-01','Sample Collection','So only mucoid, purulent or caseous sputum is acceptable?','មានន័យថា ទទួលយកតែកំហាកខាប់ស្អិត មានខ្ទុះ ឬដូចឈីសប៉ុណ្ណោះ?','Yes. Only mucoid, purulent or caseous sputum is acceptable.','បាទ/ចាស។ ទទួលយកតែកំហាកខាប់ស្អិត (mucoid) កំហាកមានខ្ទុះ (purulent) ឬកំហាកដូចឈីស (caseous) ប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q12','SC-01','Sample Collection','Are hemoptysis samples acceptable?','តើសំណាកក្អកចេញឈាម (hemoptysis) អាចទទួលយកបានទេ?','No. Blood-stained (hemoptysis) sputum isn''t acceptable. Recollect mucoid, purulent or caseous sputum.','មិនបានទេ។ កំហាកដែលមានជាប់ឈាម (ក្អកចេញឈាម/hemoptysis) មិនអាចទទួលយកបានទេ។ យកកំហាកខាប់ស្អិត កំហាកមានខ្ទុះ ឬកំហាកដូចឈីស ម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q13','SC-01','Sample Collection','The sputum is purulent. Is that acceptable?','កំហាកមានខ្ទុះ។ តើទទួលយកបានទេ?','Yes. Purulent sputum is acceptable.','បាទ/ចាស។ កំហាកមានខ្ទុះ (purulent) អាចទទួលយកបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q14','SC-01','Sample Collection','Can I use mucoid sputum?','តើអាចប្រើកំហាកខាប់ស្អិតបានទេ?','Yes. Mucoid sputum is acceptable.','បាទ/ចាស។ កំហាកខាប់ស្អិត (mucoid) អាចទទួលយកបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q15','SC-01','Sample Collection','Is caseous sputum acceptable?','តើកំហាកដូចឈីស ទទួលយកបានទេ?','Yes. Caseous sputum is acceptable.','បាទ/ចាស។ កំហាកដូចឈីស (caseous) អាចទទួលយកបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-01-Q16','SC-01','Sample Collection','Which sputum specimens should be rejected?','សំណាកកំហាកប្រភេទណាដែលត្រូវបដិសេធ?','Reject blood-stained (hemoptysis) specimens and saliva, and recollect.','បដិសេធសំណាកដែលមានជាប់ឈាម (hemoptysis) និងទឹកមាត់ ហើយយកសំណាកម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02','SC-02','Sample Collection','Tongue swab or sputum specimen produces a negative result that seems inconsistent with symptoms','តេស្តកំហាក ឬសំណាកអណ្តាតចេញអវិជ្ជមាន តែអ្នកជំងឺនៅមានរោគសញ្ញា។ ត្រូវធ្វើម៉េច?','Follow full collection procedure: sputum ≥1 mL; tongue swab wiped/rotated for the full 30 seconds across ~3/4 of the tongue dorsum','អនុវត្តនីតិវិធីយកសំណាកឱ្យពេញលេញ៖ កំហាកយ៉ាងតិច ១ mL។ សំណាកអណ្តាត ត្រូវជូត/បង្វិលពេញ ៣០ វិនាទី លើប្រហែល ៣/៤ នៃផ្ទៃខាងលើអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q01','SC-02','Sample Collection','How long should I swab the tongue?','ត្រូវជូតអណ្តាតយូរប៉ុណ្ណា?','At least 30 seconds, wiping and rotating across about three-quarters of the tongue dorsum.','យ៉ាងតិច ៣០ វិនាទី ដោយជូត និងបង្វិល លើប្រហែល ៣/៤ នៃផ្ទៃខាងលើអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q02','SC-02','Sample Collection','How much sputum do I need?','ត្រូវការកំហាកប៉ុន្មាន?','At least 1 mL.','យ៉ាងតិច ១ mL។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q03','SC-02','Sample Collection','Which area of the tongue should I swab?','ត្រូវជូតផ្នែកណានៃអណ្តាត?','The tongue dorsum, covering about three-quarters of it.','ផ្ទៃខាងលើអណ្តាត ឱ្យគ្របដណ្តប់ប្រហែល ៣/៤ នៃផ្ទៃនោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q04','SC-02','Sample Collection','min sputum volume','ត្រូវការកំហាកយ៉ាងតិចប៉ុន្មាន mL?','At least 1 mL.','យ៉ាងតិច ១ mL។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q05','SC-02','Sample Collection','How do I avoid false negatives from sample collection?','ធ្វើម៉េចជៀសវាងលទ្ធផលអវិជ្ជមានក្លែងក្លាយពីការស្រង់សំណាក?','Follow the full collection procedure: at least 1 mL of sputum; for a tongue swab, swab the full 30 seconds across about three-quarters of the tongue dorsum.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q06','SC-02','Sample Collection','I''m new — what''s the minimum sputum volume and swab time?','ខ្ញុំទើបប្រើ Pluslife។ បរិមាណកំហាកតិចបំផុត និងពេលជូតអណ្តាតប៉ុន្មាន?','Sputum: at least 1 mL. Tongue swab: at least 30 seconds.','កំហាក៖ យ៉ាងតិច ១ mL។ សំណាកអណ្តាត៖ យ៉ាងតិច ៣០ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q07','SC-02','Sample Collection','How thoroughly do I need to swab the tongue?','ត្រូវជូតអណ្តាតឱ្យល្អិតល្អន់ប៉ុណ្ណា?','For the full 30 seconds, wiping and rotating across about three-quarters of the tongue dorsum.','ពេញ ៣០ វិនាទី ដោយជូត និងបង្វិល លើប្រហែល ៣/៤ នៃផ្ទៃខាងលើអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q08','SC-02','Sample Collection','swab tongue how many second?','ជូតអណ្តាតប៉ុន្មានវិនាទី?','At least 30 seconds, wiping and rotating across about three-quarters of the tongue dorsum.','យ៉ាងតិច ៣០ វិនាទី ដោយជូត និងបង្វិល លើប្រហែល ៣/៤ នៃផ្ទៃខាងលើអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q09','SC-02','Sample Collection','So I need at least 1 mL of sputum and 30 seconds of swabbing?','មានន័យថា ត្រូវការកំហាកយ៉ាងតិច ១ mL និងជូត ៣០ វិនាទី?','Yes. At least 1 mL of sputum, and at least 30 seconds of tongue swabbing.','បាទ/ចាស។ កំហាកយ៉ាងតិច ១ mL និងជូតអណ្តាតយ៉ាងតិច ៣០ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q10','SC-02','Sample Collection','What''s the minimum amount of sputum for the test?','បរិមាណកំហាកតិចបំផុតសម្រាប់តេស្តគឺប៉ុន្មាន?','At least 1 mL.','យ៉ាងតិច ១ mL។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q11','SC-02','Sample Collection','How long does tongue swabbing need to take?','ការជូតអណ្តាតត្រូវចំណាយពេលប៉ុន្មាន?','At least 30 seconds, wiping and rotating across about three-quarters of the tongue dorsum.','យ៉ាងតិច ៣០ វិនាទី ដោយជូត និងបង្វិល លើប្រហែល ៣/៤ នៃផ្ទៃខាងលើអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q12','SC-02','Sample Collection','How much of the tongue should the swab cover?','ដងសំឡីត្រូវគ្របដណ្តប់អណ្តាតប៉ុណ្ណា?','The tongue dorsum, covering about three-quarters of it.','ផ្ទៃខាងលើអណ្តាត ឱ្យគ្របដណ្តប់ប្រហែល ៣/៤ នៃផ្ទៃនោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q13','SC-02','Sample Collection','Is less than 1 mL of sputum enough?','កំហាកតិចជាង ១ mL គ្រប់គ្រាន់ទេ?','No. You need at least 1 mL. Less may cause a false negative.','មិនគ្រប់ទេ។ ត្រូវការយ៉ាងតិច ១ mL។ តិចជាងនេះ អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-02-Q14','SC-02','Sample Collection','Can I swab the tongue for just 10 seconds?','តើអាចជូតអណ្តាតតែ ១០ វិនាទីបានទេ?','No. Swab for at least 30 seconds. Insufficient swabbing may cause a false negative.','មិនបានទេ។ ត្រូវជូតយ៉ាងតិច ៣០ វិនាទី។ ការជូតមិនគ្រប់គ្រាន់ អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03','SC-03','Sample Collection','Patient cannot produce sputum, or only produces saliva','អ្នកជំងឺក្អកយកកំហាកមិនចេញ ឬចេញតែទឹកមាត់។ ត្រូវធ្វើម៉េច?','Recollect sputum if possible; if the patient can''t produce sputum, use a tongue swab. Sputum is preferred; one kit covers both. Use direct samples, not samples stored in VTM','យកកំហាកម្តងទៀត បើអាចធ្វើបាន។ បើអ្នកជំងឺមិនអាចបញ្ចេញកំហាកបាន សូមប្រើសំណាកអណ្តាត។ កំហាកត្រូវបានគេពេញចិត្តជាង។ កញ្ចប់តេស្តមួយប្រើបានទាំងពីរប្រភេទ។ ប្រើសំណាកផ្ទាល់ មិនមែនសំណាកដែលរក្សាទុកក្នុង VTM ទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q01','SC-03','Sample Collection','Is saliva acceptable instead of sputum?','តើទឹកមាត់អាចប្រើជំនួសកំហាកបានទេ?','No. Saliva isn''t acceptable. Recollect sputum; if the patient can''t produce sputum, use a tongue swab instead.','មិនបានទេ។ ទឹកមាត់មិនអាចទទួលយកបានទេ។ យកកំហាកម្តងទៀត។ បើអ្នកជំងឺមិនអាចបញ្ចេញកំហាកបាន សូមប្រើសំណាកអណ្តាតជំនួស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q02','SC-03','Sample Collection','The patient only spat out saliva. Should I use it or recollect?','អ្នកជំងឺស្តោះតែទឹកមាត់។ គួរប្រើវា ឬយកសំណាកម្តងទៀត?','Recollect. Saliva isn''t acceptable; you need mucoid, purulent or caseous sputum. If the patient can''t produce sputum, use a tongue swab instead.','យកសំណាកម្តងទៀត។ ទឹកមាត់មិនអាចទទួលយកបានទេ។ ត្រូវការកំហាកខាប់ស្អិត កំហាកមានខ្ទុះ ឬកំហាកដូចឈីស។ បើអ្នកជំងឺមិនអាចបញ្ចេញកំហាកបាន សូមប្រើសំណាកអណ្តាតជំនួស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q03','SC-03','Sample Collection','The sample looks like spit, not phlegm.','សំណាកមើលទៅដូចទឹកមាត់ មិនមែនកំហាកទេ?','Recollect. Saliva isn''t acceptable; you need mucoid, purulent or caseous sputum. If the patient can''t produce sputum, use a tongue swab instead.','យកសំណាកម្តងទៀត។ ទឹកមាត់មិនអាចទទួលយកបានទេ។ ត្រូវការកំហាកខាប់ស្អិត កំហាកមានខ្ទុះ ឬកំហាកដូចឈីស។ បើអ្នកជំងឺមិនអាចបញ្ចេញកំហាកបាន សូមប្រើសំណាកអណ្តាតជំនួស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q04','SC-03','Sample Collection','What should I do if the specimen is just saliva?','ត្រូវធ្វើម៉េច បើសំណាកគ្រាន់តែជាទឹកមាត់?','Recollect. Saliva isn''t acceptable; you need mucoid, purulent or caseous sputum. If the patient can''t produce sputum, use a tongue swab instead.','យកសំណាកម្តងទៀត។ ទឹកមាត់មិនអាចទទួលយកបានទេ។ ត្រូវការកំហាកខាប់ស្អិត កំហាកមានខ្ទុះ ឬកំហាកដូចឈីស។ បើអ្នកជំងឺមិនអាចបញ្ចេញកំហាកបាន សូមប្រើសំណាកអណ្តាតជំនួស។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q05','SC-03','Sample Collection','What sample types can I use?','អាចប្រើសំណាកប្រភេទណាខ្លះ?','Sputum or tongue swab; one kit covers both. Sputum is preferred.','កំហាក ឬសំណាកអណ្តាត។ កញ្ចប់តេស្តមួយប្រើបានទាំងពីរ។ កំហាកត្រូវបានគេពេញចិត្តជាង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q06','SC-03','Sample Collection','Can I use a tongue swab instead of sputum?','តើអាចប្រើសំណាកអណ្តាតជំនួសកំហាកបានទេ?','Yes, when sputum can''t be obtained. Sputum is preferred.','បាទ/ចាស ពេលមិនអាចយកកំហាកបាន។ កំហាកត្រូវបានគេពេញចិត្តជាង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q07','SC-03','Sample Collection','When should I use a tongue swab?','ពេលណាគួរប្រើសំណាកអណ្តាត?','When sputum can''t be obtained.','ពេលមិនអាចយកកំហាកបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q08','SC-03','Sample Collection','Which sample is preferred, sputum or tongue swab?','សំណាកមួយណាល្អជាង កំហាក ឬសំណាកអណ្តាត?','Sputum is preferred.','កំហាកត្រូវបានគេពេញចិត្តជាង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q09','SC-03','Sample Collection','Does one kit work for both sputum and tongue swab?','តើកញ្ចប់តេស្តមួយប្រើបានទាំងកំហាក និងសំណាកអណ្តាតទេ?','Yes. One kit works for both sputum and tongue swab.','បាទ/ចាស។ កញ្ចប់តេស្តមួយប្រើបានទាំងកំហាក និងសំណាកអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q10','SC-03','Sample Collection','The patient can''t produce sputum. What sample can I use?','អ្នកជំងឺបញ្ចេញកំហាកមិនបាន។ អាចប្រើសំណាកអ្វី?','Use a tongue swab.','ប្រើសំណាកអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q11','SC-03','Sample Collection','Can I use samples stored in VTM?','តើអាចប្រើសំណាកដែលរក្សាទុកក្នុង VTM បានទេ?','No. Use direct samples, not samples in VTM.','មិនបានទេ។ ប្រើសំណាកផ្ទាល់ មិនមែនសំណាកក្នុង VTM ទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-03-Q12','SC-03','Sample Collection','sample type','តេស្តនេះអាចប្រើសំណាកប្រភេទណាខ្លះ?','Sputum or tongue swab; one kit covers both. Sputum is preferred.','កំហាក ឬសំណាកអណ្តាត។ កញ្ចប់តេស្តមួយប្រើបានទាំងពីរ។ កំហាកត្រូវបានគេពេញចិត្តជាង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04','SC-04','Sample Collection','Sputum collected without mouth rinse, in a non-sterile cup, or below 1 mL','អ្នកជំងឺមិនបានខ្ពុរមាត់មុនស្រង់កំហាក ប្រើកែវមិនស្ទេរីល ឬបានកំហាកតិចជាង ១ mL។ ត្រូវធ្វើម៉េច?','1) Patient rinses with clear water for 10-15 s and spits it out. 2) Collect raw sputum in a sterile, leak-proof sputum cup. 3) At least 1 mL. Clinical procedure: https://docs.google.com/document/d/1d9w2ffsIa9-XLKiivnDRyfWvPhNWLOBp/edit','១) អ្នកជំងឺខ្ពុរមាត់ដោយទឹកស្អាត ១០-១៥ វិនាទី ហើយស្តោះចោល។ ២) យកកំហាកដើម ដាក់ក្នុងកែវដាក់កំហាកដែលស្អាតគ្មានមេរោគ (sterile) និងមិនលេចធ្លាយ។ ៣) យ៉ាងតិច ១ mL។ នីតិវិធីគ្លីនិក (Clinical procedure)៖ https://docs.google.com/document/d/1d9w2ffsIa9-XLKiivnDRyfWvPhNWLOBp/edit','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q01','SC-04','Sample Collection','Should the patient rinse their mouth before giving sputum?','តើអ្នកជំងឺគួរខ្ពុរមាត់ មុនផ្តល់កំហាកទេ?','Yes. The patient should rinse thoroughly with clear water for 10-15 seconds, then spit out the water.','បាទ/ចាស។ អ្នកជំងឺគួរខ្ពុរមាត់ឱ្យស្អាតដោយទឹកស្អាត ១០-១៥ វិនាទី រួចស្តោះទឹកចោល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q02','SC-04','Sample Collection','How long should the patient rinse?','អ្នកជំងឺគួរខ្ពុរមាត់យូរប៉ុណ្ណា?','10-15 seconds.','១០-១៥ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q03','SC-04','Sample Collection','What should the patient rinse with?','អ្នកជំងឺគួរខ្ពុរមាត់ដោយអ្វី?','Clear water.','ទឹកស្អាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q04','SC-04','Sample Collection','rinse before sputum collection','តើត្រូវឱ្យអ្នកជំងឺខ្ពុរមាត់មុនស្រង់កំហាកទេ?','Rinse the mouth thoroughly with clear water for 10-15 seconds, then spit the water out.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q05','SC-04','Sample Collection','What should the patient do before sputum collection?','អ្នកជំងឺគួរធ្វើអ្វី មុនស្រង់កំហាក?','Rinse the mouth thoroughly with clear water for 10-15 seconds, then spit the water out.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q06','SC-04','Sample Collection','Should the patient swallow the rinse water?','តើអ្នកជំងឺគួរលេបទឹកខ្ពុរមាត់ទេ?','No. The patient should spit out the rinse water.','មិនត្រូវទេ។ អ្នកជំងឺត្រូវស្តោះទឹកខ្ពុរមាត់ចោល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q07','SC-04','Sample Collection','How do I make sure I collect a proper sputum sample?','ធ្វើម៉េចឱ្យប្រាកដថាយកសំណាកកំហាកបានត្រឹមត្រូវ?','Have the patient rinse first, then collect raw sputum in a sterile, leak-proof sputum cup (at least 1 mL). Only mucoid, purulent or caseous sputum is acceptable.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q08','SC-04','Sample Collection','What container should sputum be collected in?','កំហាកគួរដាក់ក្នុងប្រដាប់អ្វី?','A sterile, leak-proof sputum cup.','កែវដាក់កំហាកដែលស្អាតគ្មានមេរោគ (sterile) និងមិនលេចធ្លាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q09','SC-04','Sample Collection','What kind of sputum cup do I need?','ត្រូវការកែវកំហាកប្រភេទណា?','A sterile, leak-proof sputum cup.','កែវដាក់កំហាកដែលស្អាតគ្មានមេរោគ (sterile) និងមិនលេចធ្លាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q10','SC-04','Sample Collection','sputum collection steps','ការស្រង់កំហាកត្រូវធ្វើតាមជំហានណាខ្លះ?','1) Patient rinses with clear water for 10-15 seconds and spits it out.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q11','SC-04','Sample Collection','I''m new — how do I collect sputum for the MTB test?','ខ្ញុំទើបប្រើ Pluslife។ ធ្វើម៉េចយកកំហាកសម្រាប់តេស្ត MTB?','1) Patient rinses with clear water for 10-15 seconds and spits it out.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q12','SC-04','Sample Collection','Does the sputum cup need to be sterile?','តើកែវកំហាកត្រូវស្អាតគ្មានមេរោគ (sterile) ទេ?','Yes. Use a sterile, leak-proof sputum cup.','បាទ/ចាស។ ប្រើកែវដាក់កំហាកដែលស្អាតគ្មានមេរោគ (sterile) និងមិនលេចធ្លាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-04-Q13','SC-04','Sample Collection','What is the sputum collection procedure?','នីតិវិធីយកកំហាកមានអ្វីខ្លះ?','1) Patient rinses with clear water for 10-15 seconds and spits it out.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-05','SC-05','Sample Collection','Sputum swab tip not evenly saturated after dipping','ជ្រលក់ដងសំឡីក្នុងកំហាកហើយ តែចុងសំឡីជោគមិនសព្វ។ ត្រូវធ្វើម៉េច?','With clean hands, take out the swab without touching the tip. Swirl it in the sputum cup at least 10 times for 10-15 s, touching all areas and depths of the sputum, until the tip is evenly saturated','លាងដៃឱ្យស្អាត រួចយកដងសំឡីចេញ ដោយមិនប៉ះចុងរបស់វា។ កូរដងសំឡីក្នុងកែវកំហាក យ៉ាងតិច ១០ ដង រយៈពេល ១០-១៥ វិនាទី ឱ្យប៉ះគ្រប់ផ្នែក និងគ្រប់ជម្រៅនៃកំហាក រហូតចុងសំឡីជោគស្មើគ្នា។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-05-Q01','SC-05','Sample Collection','How do I make a sputum swab?','ធ្វើម៉េចធ្វើ swab កំហាក?','With clean hands, take out the swab without touching the tip. Swirl it in the sputum cup at least 10 times for 10-15 seconds, touching all areas and depths of the sputum, until the tip is evenly saturated.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-05-Q02','SC-05','Sample Collection','How many times should I swirl the swab in the sputum cup?','ត្រូវកូរដងសំឡីក្នុងកែវកំហាកប៉ុន្មានដង?','At least 10 times.','យ៉ាងតិច ១០ ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-05-Q03','SC-05','Sample Collection','How long do I swirl the swab in the sputum?','ត្រូវកូរដងសំឡីក្នុងកំហាកយូរប៉ុណ្ណា?','10-15 seconds.','១០-១៥ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-05-Q04','SC-05','Sample Collection','How do I dip the swab into the sputum?','ធ្វើម៉េចជ្រលក់ដងសំឡីក្នុងកំហាក?','With clean hands, take out the swab without touching the tip. Swirl it in the sputum cup at least 10 times for 10-15 seconds, touching all areas and depths of the sputum, until the tip is evenly saturated.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-05-Q05','SC-05','Sample Collection','sputum swab steps','ត្រូវប្រើដងសំឡីស្រង់សំណាកពីកែវកំហាកយ៉ាងម៉េច?','With clean hands, take out the swab without touching the tip. Swirl it in the sputum cup at least 10 times for 10-15 seconds, touching all areas and depths of the sputum, until the tip is evenly saturated.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-05-Q06','SC-05','Sample Collection','Should the swab touch all parts of the sputum?','តើដងសំឡីគួរប៉ះគ្រប់ផ្នែកនៃកំហាកទេ?','Yes. Make contact with all areas and depths of the sputum.','បាទ/ចាស។ ឱ្យប៉ះគ្រប់ផ្នែក និងគ្រប់ជម្រៅនៃកំហាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-05-Q07','SC-05','Sample Collection','I''m new — how do I transfer sputum onto the swab?','ខ្ញុំទើបប្រើ Pluslife។ ធ្វើម៉េចផ្ទេរកំហាកទៅលើដងសំឡី?','With clean hands, take out the swab without touching the tip. Swirl it in the sputum cup at least 10 times for 10-15 seconds, touching all areas and depths of the sputum, until the tip is evenly saturated.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-06','SC-06','Sample Collection','Patient brushed, rinsed, smoked, ate or drank within the last 30 minutes before a tongue swab','មិនទាន់បាន ៣០ នាទីផង តាំងពីអ្នកជំងឺដុសធ្មេញ ខ្ពុរមាត់ ជក់បារី ញ៉ាំអាហារ ឬផឹកទឹក។ អាចស្រង់សំណាកអណ្តាតបានទេ?','Wait 30 minutes after brushing, rinsing, tobacco use, food or drink before taking the tongue swab','រង់ចាំ ៣០ នាទី ក្រោយការដុសធ្មេញ ខ្ពុរមាត់ ជក់បារី/ប្រើថ្នាំជក់ ញ៉ាំអាហារ ឬផឹកភេសជ្ជៈ ទើបស្រង់សំណាកអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-06-Q01','SC-06','Sample Collection','Can I collect a tongue swab right after the patient eats?','តើអាចស្រង់សំណាកអណ្តាត ភ្លាមក្រោយអ្នកជំងឺញ៉ាំបានទេ?','No. Wait 30 minutes after the patient has eaten or drunk anything.','មិនបានទេ។ រង់ចាំ ៣០ នាទី ក្រោយអ្នកជំងឺញ៉ាំ ឬផឹកអ្វីមួយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-06-Q02','SC-06','Sample Collection','The patient just brushed their teeth. When can I take a tongue swab?','អ្នកជំងឺទើបដុសធ្មេញ។ ពេលណាអាចស្រង់សំណាកអណ្តាតបាន?','Wait 30 minutes after brushing.','រង់ចាំ ៣០ នាទី ក្រោយដុសធ្មេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-06-Q03','SC-06','Sample Collection','How long should the patient avoid food and drink before a tongue swab?','អ្នកជំងឺគួរជៀសវាងញ៉ាំ និងផឹកយូរប៉ុណ្ណា មុនស្រង់សំណាកអណ្តាត?','30 minutes.','៣០ នាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-06-Q04','SC-06','Sample Collection','Can a smoker give a tongue swab right after smoking?','តើអ្នកជក់បារីអាចផ្តល់សំណាកអណ្តាតភ្លាមក្រោយជក់បានទេ?','No. Wait 30 minutes after tobacco use.','មិនបានទេ។ រង់ចាំ ៣០ នាទី ក្រោយជក់បារី/ប្រើថ្នាំជក់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-06-Q05','SC-06','Sample Collection','tongue swab pre-collection check','មុនស្រង់សំណាកអណ្តាត ត្រូវសួរឬពិនិត្យអ្វីខ្លះ?','Check the patient hasn''t brushed, rinsed, used tobacco, or had food or drink in the past 30 minutes. If they have, wait 30 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-06-Q06','SC-06','Sample Collection','What should I check before taking a tongue swab?','ត្រូវពិនិត្យអ្វី មុនស្រង់សំណាកអណ្តាត?','Check the patient hasn''t brushed, rinsed, used tobacco, or had food or drink in the past 30 minutes. If they have, wait 30 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-06-Q07','SC-06','Sample Collection','Can the patient rinse their mouth before a tongue swab?','តើអ្នកជំងឺអាចខ្ពុរមាត់ មុនស្រង់សំណាកអណ្តាតបានទេ?','No. If the patient has rinsed, wait 30 minutes before taking the tongue swab.','មិនបានទេ។ បើអ្នកជំងឺបានខ្ពុរមាត់ សូមរង់ចាំ ៣០ នាទី ទើបស្រង់សំណាកអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-07','SC-07','Sample Collection','Swab held below the breakpoint, tip touched, or swab broken before sampling','ខ្ញុំកាន់ដងសំឡីក្រោមស្នាមសម្រាប់កាច់ ប៉ះចុងសំឡី ឬកាច់ដងសំឡីមុនស្រង់សំណាក។ ត្រូវធ្វើម៉េច?','Hold the swab only by the upper shaft, above the breakpoint. Don''t touch the tip or the shaft between the breakpoint and the tip, and don''t break the swab','កាន់ដងសំឡី តែត្រង់ដងខាងលើ ពីលើចំណុចបំបាក់ (breakpoint) ប៉ុណ្ណោះ។ កុំប៉ះចុងសំឡី ឬដងចន្លោះចំណុចបំបាក់ និងចុងសំឡី ហើយកុំបំបាក់ដងសំឡី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-07-Q01','SC-07','Sample Collection','How should I hold the tongue swab?','ត្រូវកាន់ដងសំឡីអណ្តាតយ៉ាងម៉េច?','Hold it only by the upper shaft, above the breakpoint. Don''t touch the tip or the shaft between the breakpoint and the tip.','កាន់តែត្រង់ដងខាងលើ ពីលើចំណុចបំបាក់ (breakpoint) ប៉ុណ្ណោះ។ កុំប៉ះចុងសំឡី ឬដងចន្លោះចំណុចបំបាក់ និងចុងសំឡី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-07-Q02','SC-07','Sample Collection','Can I touch the swab tip?','តើអាចប៉ះចុងដងសំឡីបានទេ?','No. Never touch the swab tip.','មិនបានទេ។ កុំប៉ះចុងសំឡីជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-07-Q03','SC-07','Sample Collection','Where on the shaft should I hold the swab?','ត្រូវកាន់ដងសំឡីត្រង់ផ្នែកណានៃដង?','The upper shaft, above the breakpoint.','ដងខាងលើ ពីលើចំណុចបំបាក់ (breakpoint)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-07-Q04','SC-07','Sample Collection','Can I break the swab before sampling?','តើអាចបំបាក់ដងសំឡី មុនយកសំណាកបានទេ?','No. Don''t break the swab.','មិនបានទេ។ កុំបំបាក់ដងសំឡី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-07-Q05','SC-07','Sample Collection','Which part of the swab must I not touch?','ផ្នែកណានៃដងសំឡីដែលមិនត្រូវប៉ះ?','The tip, and the shaft between the breakpoint and the tip.','ចុងសំឡី និងដងចន្លោះចំណុចបំបាក់ និងចុងសំឡី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-07-Q06','SC-07','Sample Collection','swab handling','ត្រូវកាន់ដងសំឡីត្រង់ណាពេលស្រង់សំណាក?','Hold it only by the upper shaft, above the breakpoint. Don''t touch the tip or the shaft between the breakpoint and the tip.','កាន់តែត្រង់ដងខាងលើ ពីលើចំណុចបំបាក់ (breakpoint) ប៉ុណ្ណោះ។ កុំប៉ះចុងសំឡី ឬដងចន្លោះចំណុចបំបាក់ និងចុងសំឡី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-07-Q07','SC-07','Sample Collection','I''m new — how do I take the swab out of the pouch?','ខ្ញុំទើបប្រើ Pluslife។ ធ្វើម៉េចយកដងសំឡីចេញពីថង់?','Open the sterile pouch and take out the swab, holding only the upper shaft (above the breakpoint). Don''t touch the tip and don''t break the swab.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08','SC-08','Sample Collection','Tongue swab head only partly coated, or swabbing shorter than 30 seconds','ខ្ញុំជូតអណ្តាតមិនដល់ ៣០ វិនាទី ឬចុងសំឡីសើមតែម្ខាង។ ត្រូវធ្វើម៉េច?','Place the swab on the posterior dorsal tongue (≈3/4 of the visible length) without triggering a gag reflex. Press enough to slightly bend the stem. Wipe back and forth 3-4 times, rotate, repeat until the head is fully coated; at least 30 s in total (brief pauses OK, use a timer)','ដាក់ដងសំឡីលើផ្ទៃខាងលើផ្នែកខាងក្រោយនៃអណ្តាត (ប្រហែល ៣/៤ នៃប្រវែងដែលមើលឃើញ) ដោយកុំឱ្យអ្នកជំងឺចង់ក្អួត។ សង្កត់ល្មមឱ្យដងកោងបន្តិច។ ជូតទៅមក ៣-៤ ដង បង្វិល ហើយធ្វើម្តងទៀត រហូតក្បាលសំឡីជាប់សំណាកពេញ។ សរុបយ៉ាងតិច ៣០ វិនាទី (អាចឈប់បន្តិចបាន សូមប្រើនាឡិកាកំណត់ម៉ោង)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q01','SC-08','Sample Collection','tongue swab technique','ត្រូវជូតអណ្តាតយ៉ាងម៉េច ដើម្បីស្រង់សំណាក?','Place the swab on the posterior dorsal tongue (about three-quarters of the visible length), without triggering a gag reflex. Press enough to slightly bend the stem. Wipe back and forth 3-4 times, rotate, and repeat until the swab head is fully coated: at least 30 seconds in total.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q02','SC-08','Sample Collection','What''s the correct procedure for collecting a tongue swab?','នីតិវិធីត្រឹមត្រូវក្នុងការស្រង់សំណាកអណ្តាតយ៉ាងម៉េច?','Place the swab on the posterior dorsal tongue (about three-quarters of the visible length), without triggering a gag reflex. Press enough to slightly bend the stem. Wipe back and forth 3-4 times, rotate, and repeat until the swab head is fully coated: at least 30 seconds in total.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q03','SC-08','Sample Collection','How hard should I press the swab on the tongue?','ត្រូវសង្កត់ដងសំឡីលើអណ្តាតខ្លាំងប៉ុណ្ណា?','Just enough to slightly bend the swab stem.','ល្មមតែឱ្យដងសំឡីកោងបន្តិច។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q04','SC-08','Sample Collection','Should I wipe back and forth or rotate the swab?','គួរជូតទៅមក ឬបង្វិលដងសំឡី?','Both. Wipe back and forth 3-4 times, rotate the swab, and repeat until the swab head is fully coated.','ទាំងពីរ។ ជូតទៅមក ៣-៤ ដង បង្វិលដងសំឡី ហើយធ្វើម្តងទៀត រហូតក្បាលសំឡីជាប់សំណាកពេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q05','SC-08','Sample Collection','How many times do I wipe the tongue before rotating?','ត្រូវជូតអណ្តាតប៉ុន្មានដង មុនបង្វិល?','3-4 times.','៣-៤ ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q06','SC-08','Sample Collection','Where exactly on the tongue do I place the swab?','ត្រូវដាក់ដងសំឡីត្រង់ណាពិតប្រាកដលើអណ្តាត?','On the posterior dorsal tongue, at about three-quarters of the visible length, covering the entire sampling area.','លើផ្ទៃខាងលើផ្នែកខាងក្រោយនៃអណ្តាត ប្រហែល ៣/៤ នៃប្រវែងដែលមើលឃើញ ឱ្យគ្របដណ្តប់តំបន់យកសំណាកទាំងមូល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q07','SC-08','Sample Collection','How do I avoid triggering a gag reflex?','ធ្វើម៉េចកុំឱ្យអ្នកជំងឺចង់ក្អួត?','The guidance only says to place the swab on the posterior dorsal tongue (about three-quarters of the visible length) without triggering a gag reflex. It gives no further technique.','ការណែនាំគ្រាន់តែប្រាប់ឱ្យដាក់ដងសំឡីលើផ្ទៃខាងលើផ្នែកខាងក្រោយនៃអណ្តាត (ប្រហែល ៣/៤ នៃប្រវែងដែលមើលឃើញ) ដោយកុំឱ្យអ្នកជំងឺចង់ក្អួត។ វាមិនបានផ្តល់បច្ចេកទេសបន្ថែមទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q08','SC-08','Sample Collection','Can I pause during the 30 seconds of swabbing?','តើអាចឈប់បន្តិច ក្នុងអំឡុង ៣០ វិនាទីនៃការជូតបានទេ?','Yes. Brief pauses are allowed. Use a timer so the total is at least 30 seconds.','បាទ/ចាស។ អាចឈប់បន្តិចបាន។ ប្រើនាឡិកាកំណត់ម៉ោង ដើម្បីឱ្យសរុបយ៉ាងតិច ៣០ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q09','SC-08','Sample Collection','Should the swab stem bend when swabbing?','តើដងសំឡីគួរកោងពេលជូតទេ?','Yes. Press enough to slightly bend the swab stem.','បាទ/ចាស។ សង្កត់ល្មមឱ្យដងសំឡីកោងបន្តិច។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q10','SC-08','Sample Collection','How do I know the swab has enough sample?','ធ្វើម៉េចដឹងថាដងសំឡីមានសំណាកគ្រប់គ្រាន់?','The whole swab tip should be evenly saturated/coated with the specimen.','ចុងសំឡីទាំងមូល គួរតែជោគ/ជាប់សំណាកស្មើគ្នា។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q11','SC-08','Sample Collection','What should a properly collected swab look like?','ដងសំឡីដែលយកសំណាកត្រឹមត្រូវ គួរមើលទៅបែបណា?','The whole swab tip should be evenly saturated/coated with the specimen.','ចុងសំឡីទាំងមូល គួរតែជោគ/ជាប់សំណាកស្មើគ្នា។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q12','SC-08','Sample Collection','Should the whole swab tip be coated?','តើចុងសំឡីទាំងមូលគួរជាប់សំណាកទេ?','Yes. The entire tip should be evenly coated. Improper collection may cause a false negative.','បាទ/ចាស។ ចុងសំឡីទាំងមូលគួរជាប់សំណាកស្មើគ្នា។ ការស្រង់សំណាកមិនត្រឹមត្រូវ អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q13','SC-08','Sample Collection','swab saturation check','មើលយ៉ាងម៉េចដឹងថាចុងសំឡីជោគសព្វ?','The whole swab tip should be evenly saturated/coated with the specimen.','ចុងសំឡីទាំងមូល គួរតែជោគ/ជាប់សំណាកស្មើគ្នា។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q14','SC-08','Sample Collection','Only part of the swab tip has sample on it. Is that enough?','មានសំណាកតែលើផ្នែកខ្លះនៃចុងសំឡី។ តើគ្រប់គ្រាន់ទេ?','No. The entire swab tip should be evenly saturated. Improper collection may cause a false negative.','មិនគ្រប់ទេ។ ចុងសំឡីទាំងមូលគួរតែជោគស្មើគ្នា។ ការស្រង់សំណាកមិនត្រឹមត្រូវ អាចបណ្តាលឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-08-Q15','SC-08','Sample Collection','How do I check swab quality after sampling?','ធ្វើម៉េចពិនិត្យគុណភាពដងសំឡីក្រោយយកសំណាក?','The whole swab tip should be evenly saturated/coated with the specimen.','ចុងសំឡីទាំងមូល គួរតែជោគ/ជាប់សំណាកស្មើគ្នា។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01','SS-01','Sample Storage','Sample can''t be tested right away','ស្រង់សំណាកបានហើយ តែធ្វើតេស្តភ្លាមៗមិនបាន។ ត្រូវទុកសំណាកដោយរបៀបណា?','Test immediately for best results. If delayed: room temp ≤24 h; 2-8°C ≤5 days; -20°C ≤6 months (≤5 freeze-thaw cycles). Transport at 2-8°C, tightly capped, labelled with ID and time. Tongue swab: sterile, leak-proof transport tube without preservation medium. See the IFU for full conditions','ធ្វើតេស្តភ្លាមៗ ដើម្បីទទួលបានលទ្ធផលល្អបំផុត។ បើពន្យារពេល៖ សីតុណ្ហភាពបន្ទប់ មិនលើស ២៤ ម៉ោង។ 2-8°C មិនលើស ៥ ថ្ងៃ។ -20°C មិនលើស ៦ ខែ (បង្កក-រំលាយមិនលើស ៥ ដង)។ ដឹកជញ្ជូននៅ 2-8°C បិទគម្របឱ្យជិត ហើយបិទស្លាក ID និងម៉ោង។ សំណាកអណ្តាត៖ ដាក់ក្នុងបំពង់ដឹកជញ្ជូនស្អាតគ្មានមេរោគ មិនលេចធ្លាយ និងគ្មានសារធាតុរក្សាសំណាក។ សូមមើល IFU (សៀវភៅណែនាំការប្រើប្រាស់) សម្រាប់លក្ខខណ្ឌពេញលេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q01','SS-01','Sample Storage','Can I test the sample later?','តើអាចធ្វើតេស្តសំណាកពេលក្រោយបានទេ?','Yes, though testing immediately gives the best results. If delayed: room temperature up to 24 h, 2-8°C up to 5 days, -20°C up to 6 months.','បាទ/ចាស ប៉ុន្តែការធ្វើតេស្តភ្លាមៗផ្តល់លទ្ធផលល្អបំផុត។ បើពន្យារពេល៖ សីតុណ្ហភាពបន្ទប់ រហូតដល់ ២៤ ម៉ោង។ 2-8°C រហូតដល់ ៥ ថ្ងៃ។ -20°C រហូតដល់ ៦ ខែ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q02','SS-01','Sample Storage','How long can a sputum sample be stored at room temperature?','សំណាកកំហាកអាចទុកនៅសីតុណ្ហភាពបន្ទប់បានយូរប៉ុណ្ណា?','Up to 24 hours.','រហូតដល់ ២៤ ម៉ោង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q03','SS-01','Sample Storage','How long can I keep a tongue swab in the fridge?','អាចទុកសំណាកអណ្តាតក្នុងទូទឹកកកបានយូរប៉ុណ្ណា?','Up to 5 days at 2-8°C.','រហូតដល់ ៥ ថ្ងៃ នៅ 2-8°C។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q04','SS-01','Sample Storage','Can samples be frozen?','តើអាចបង្កកសំណាកបានទេ?','Yes. At -20°C for up to 6 months, with no more than 5 freeze-thaw cycles.','បាទ/ចាស។ នៅ -20°C រហូតដល់ ៦ ខែ ដោយបង្កក-រំលាយមិនលើស ៥ ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q05','SS-01','Sample Storage','How many freeze-thaw cycles are allowed?','អនុញ្ញាតឱ្យបង្កក-រំលាយបានប៉ុន្មានដង?','Up to 5 freeze-thaw cycles.','រហូតដល់ ៥ ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q06','SS-01','Sample Storage','How should samples be transported?','គួរដឹកជញ្ជូនសំណាកយ៉ាងម៉េច?','Transport at 2-8°C before processing, tightly capped and labelled with ID and time.','ដឹកជញ្ជូននៅ 2-8°C មុនពេលដំណើរការ បិទគម្របឱ្យជិត ហើយបិទស្លាក ID និងម៉ោង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q07','SS-01','Sample Storage','What should I put a tongue swab in if testing is delayed?','គួរដាក់សំណាកអណ្តាតក្នុងអ្វី បើពន្យារពេលធ្វើតេស្ត?','A sterile, leak-proof transport tube without preservation medium. Cap it tightly and label it with ID and time.','បំពង់ដឹកជញ្ជូនស្អាតគ្មានមេរោគ មិនលេចធ្លាយ និងគ្មានសារធាតុរក្សាសំណាក។ បិទគម្របឱ្យជិត ហើយបិទស្លាក ID និងម៉ោង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q08','SS-01','Sample Storage','Do I need to label delayed samples?','តើត្រូវបិទស្លាកលើសំណាកដែលពន្យារពេលទេ?','Yes. Label with ID and time.','បាទ/ចាស។ បិទស្លាក ID និងម៉ោង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q09','SS-01','Sample Storage','sample storage conditions','បើធ្វើតេស្តភ្លាមៗមិនបាន ត្រូវទុកសំណាកក្នុងលក្ខខណ្ឌបែបណា?','Test immediately for best results. If delayed: room temperature up to 24 h; 2-8°C up to 5 days; -20°C up to 6 months (max 5 freeze-thaw cycles). Transport at 2-8°C. See the IFU for full conditions.','ធ្វើតេស្តភ្លាមៗ ដើម្បីទទួលបានលទ្ធផលល្អបំផុត។ បើពន្យារពេល៖ សីតុណ្ហភាពបន្ទប់ រហូតដល់ ២៤ ម៉ោង។ 2-8°C រហូតដល់ ៥ ថ្ងៃ។ -20°C រហូតដល់ ៦ ខែ (បង្កក-រំលាយអតិបរមា ៥ ដង)។ ដឹកជញ្ជូននៅ 2-8°C។ សូមមើល IFU សម្រាប់លក្ខខណ្ឌពេញលេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-01-Q10','SS-01','Sample Storage','Can I put the tongue swab in a preservation medium for transport?','តើអាចដាក់សំណាកអណ្តាតក្នុងសារធាតុរក្សាសំណាក សម្រាប់ដឹកជញ្ជូនបានទេ?','No. Use a sterile, leak-proof transport tube without preservation medium.','មិនបានទេ។ ប្រើបំពង់ដឹកជញ្ជូនស្អាតគ្មានមេរោគ មិនលេចធ្លាយ និងគ្មានសារធាតុរក្សាសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01','SP-01','Sample Pretreatment','Result seems unreliable or contamination suspected','ខ្ញុំសង្ស័យថាសំណាកមានការចម្លងរោគ ឬលទ្ធផលមិនសូវទុកចិត្តបាន។ ត្រូវពិនិត្យអ្វីខ្លះ?','Elute by rotating and squeezing the swab against the tube ~10 times, then remove and discard the swab — never leave it in the tube','លាងសំណាកចេញ (elute) ដោយបង្វិល និងច្របាច់ដងសំឡីទល់នឹងជញ្ជាំងបំពង់ ប្រហែល ១០ ដង រួចដកដងសំឡីចេញ ហើយបោះចោល។ កុំទុកវាក្នុងបំពង់ជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q01','SP-01','Sample Pretreatment','Should I leave the swab in the elution tube?','តើគួរទុកដងសំឡីក្នុងបំពង់ elution ទេ?','No. Remove and discard the swab after elution. Never leave it in the tube.','មិនត្រូវទេ។ ដកដងសំឡីចេញ ហើយបោះចោល ក្រោយការលាងសំណាកចេញ (elution)។ កុំទុកវាក្នុងបំពង់ជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q02','SP-01','Sample Pretreatment','How do I elute the swab properly?','ធ្វើម៉េចលាងសំណាកចេញពីដងសំឡី (elute) ឱ្យត្រឹមត្រូវ?','Rotate the swab and squeeze it against the tube about 10 times, then remove and discard the swab.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q03','SP-01','Sample Pretreatment','How many times should I squeeze the swab?','ត្រូវច្របាច់ដងសំឡីប៉ុន្មានដង?','About 10 times.','ប្រហែល ១០ ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q04','SP-01','Sample Pretreatment','What do I do with the swab after elution?','ក្រោយ elution ត្រូវធ្វើអ្វីជាមួយដងសំឡី?','Remove it from the tube and discard it.','ដកវាចេញពីបំពង់ ហើយបោះចោល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q05','SP-01','Sample Pretreatment','elution steps','ត្រូវកូរដងសំឡីក្នុងសូលុយស្យុងដោយរបៀបណា ដើម្បីឱ្យសំណាកចេញពីចុងសំឡី (elution)?','Rotate the swab and squeeze it against the tube about 10 times, then remove and discard the swab.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q06','SP-01','Sample Pretreatment','What''s the right way to rotate and squeeze the swab?','របៀបត្រឹមត្រូវក្នុងការបង្វិល និងច្របាច់ដងសំឡីយ៉ាងម៉េច?','Rotate the swab while squeezing it against the tube walls, about 10 times.','បង្វិលដងសំឡី ពេលកំពុងច្របាច់វាទល់នឹងជញ្ជាំងបំពង់ ប្រហែល ១០ ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q07','SP-01','Sample Pretreatment','Do I keep the swab in the buffer tube?','តើទុកដងសំឡីក្នុងបំពង់ buffer ទេ?','No. Remove and discard the swab after elution. Never leave it in the tube.','មិនត្រូវទេ។ ដកដងសំឡីចេញ ហើយបោះចោល ក្រោយការលាងសំណាកចេញ (elution)។ កុំទុកវាក្នុងបំពង់ជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q08','SP-01','Sample Pretreatment','swab put in tube, then what?','ដាក់ដងសំឡីក្នុងបំពង់ហើយ បន្ទាប់ធ្វើអ្វី?','Rotate the swab and squeeze it against the tube about 10 times, then remove and discard the swab.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q09','SP-01','Sample Pretreatment','So I rotate and squeeze about 10 times, then throw the swab away?','មានន័យថា បង្វិល និងច្របាច់ប្រហែល ១០ ដង រួចបោះដងសំឡីចោល?','Yes. Rotate and squeeze about 10 times, then remove and discard the swab.','បាទ/ចាស។ បង្វិល និងច្របាច់ប្រហែល ១០ ដង រួចដកដងសំឡីចេញ ហើយបោះចោល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q10','SP-01','Sample Pretreatment','Do I remove the swab from the tube after elution?','តើត្រូវដកដងសំឡីចេញពីបំពង់ក្រោយ elution ទេ?','Yes. Remove and discard it. Never leave the swab in the tube.','បាទ/ចាស។ ដកវាចេញ ហើយបោះចោល។ កុំទុកដងសំឡីក្នុងបំពង់ជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q11','SP-01','Sample Pretreatment','Can I leave the swab in the tube during heating?','តើអាចទុកដងសំឡីក្នុងបំពង់ពេលកម្តៅបានទេ?','No. Remove and discard the swab after elution. Never leave it in the tube.','មិនត្រូវទេ។ ដកដងសំឡីចេញ ហើយបោះចោល ក្រោយការលាងសំណាកចេញ (elution)។ កុំទុកវាក្នុងបំពង់ជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q12','SP-01','Sample Pretreatment','How many times do I rotate the swab in the tube?','ត្រូវបង្វិលដងសំឡីក្នុងបំពង់ប៉ុន្មានដង?','About 10 times.','ប្រហែល ១០ ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q13','SP-01','Sample Pretreatment','Is it OK to cap the tube with the swab still inside?','តើអាចបិទគម្របបំពង់ ទាំងដងសំឡីនៅខាងក្នុងបានទេ?','No. Remove and discard the swab after elution. Never leave it in the tube.','មិនត្រូវទេ។ ដកដងសំឡីចេញ ហើយបោះចោល ក្រោយការលាងសំណាកចេញ (elution)។ កុំទុកវាក្នុងបំពង់ជាដាច់ខាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-01-Q14','SP-01','Sample Pretreatment','Should I squeeze the swab against the tube wall?','តើគួរច្របាច់ដងសំឡីទល់នឹងជញ្ជាំងបំពង់ទេ?','Yes. Rotate the swab while squeezing it against the tube, about 10 times.','បាទ/ចាស។ បង្វិលដងសំឡី ពេលកំពុងច្របាច់វាទល់នឹងបំពង់ ប្រហែល ១០ ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02','SP-02','Sample Pretreatment','Worker unsure of pretreatment steps or Thermolyse settings','ត្រូវរៀបចំសំណាកតាមជំហានណាខ្លះ ហើយត្រូវកំណត់ Thermolyse ដូចម្តេច?','1) Open the Releasing Agent tube carefully. 2) Insert the swab so the tip is fully in the liquid. 3) Rotate 10 times while squeezing the tube walls. 4) Lift above the liquid and squeeze out residual liquid. 5) Discard the swab into the biohazard waste bag (never into the tube); cap the tube tightly. 6) Thermolyse: 3000 rpm, 75°C, 5 min, then press RUN/STOP','១) បើកបំពង់ Releasing Agent ដោយប្រុងប្រយ័ត្ន។ ២) ដាក់ដងសំឡីចូល ឱ្យចុងសំឡីលិចក្នុងទឹកទាំងស្រុង។ ៣) បង្វិល ១០ ដង ពេលច្របាច់ជញ្ជាំងបំពង់។ ៤) លើកឡើងពីលើទឹក ហើយច្របាច់ទឹកដែលនៅសល់ចេញ។ ៥) បោះដងសំឡីចូលថង់កាកសំណល់ជីវគ្រោះថ្នាក់ (biohazard) (កុំបោះចូលបំពង់ជាដាច់ខាត) ហើយបិទគម្របបំពង់ឱ្យជិត។ ៦) Thermolyse៖ 3000 rpm, 75°C, ៥ នាទី រួចចុច RUN/STOP។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q01','SP-02','Sample Pretreatment','What are the Thermolyse settings?','ការកំណត់ Thermolyse មានអ្វីខ្លះ?','3000 rpm, 75°C, 5 minutes.','3000 rpm, 75°C, ៥ នាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q02','SP-02','Sample Pretreatment','What temperature is used for pretreatment?','pretreatment ប្រើសីតុណ្ហភាពប៉ុន្មាន?','75°C.','75°C។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q03','SP-02','Sample Pretreatment','How long is the heating step?','ជំហានកម្តៅយូរប៉ុណ្ណា?','5 minutes.','៥ នាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q04','SP-02','Sample Pretreatment','What speed should the Thermolyse run at?','Thermolyse គួរដំណើរការល្បឿនប៉ុន្មាន?','3000 rpm.','3000 rpm។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q05','SP-02','Sample Pretreatment','How do I start the Thermolyse?','ធ្វើម៉េចចាប់ផ្តើម Thermolyse?','Place the tube in the Thermolyse, set 3000 rpm / 75°C / 5 min, then press RUN/STOP.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q06','SP-02','Sample Pretreatment','thermolyse settings','ត្រូវកំណត់ Thermolyse យ៉ាងម៉េច?','3000 rpm, 75°C, 5 minutes.','3000 rpm, 75°C, ៥ នាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q07','SP-02','Sample Pretreatment','Is it 75°C for 5 minutes?','តើ 75°C រយៈពេល ៥ នាទីមែនទេ?','Yes. 75°C for 5 minutes, at 3000 rpm.','បាទ/ចាស។ 75°C រយៈពេល ៥ នាទី នៅ 3000 rpm។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q08','SP-02','Sample Pretreatment','I''m new — how do I run the heating and vortex step?','ខ្ញុំទើបប្រើ Pluslife។ ធ្វើម៉េចដំណើរការជំហានកម្តៅ និង vortex?','Place the tube in the Thermolyse, set 3000 rpm / 75°C / 5 min, then press RUN/STOP.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q09','SP-02','Sample Pretreatment','I''m new — what are the steps after putting the swab into the tube?','ខ្ញុំទើបប្រើ Pluslife។ ក្រោយដាក់ដងសំឡីក្នុងបំពង់ ជំហានបន្ទាប់មានអ្វីខ្លះ?','Rotate the swab along the bottom and sides 10 times while squeezing the tube walls. Lift it above the liquid and squeeze the tube to express residual liquid. Discard the swab into the waste bag, cap the tube tightly, then run the Thermolyse (3000 rpm, 75°C, 5 min).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q10','SP-02','Sample Pretreatment','What are the sample pretreatment steps?','មុនដាក់សំណាកចូលកាត ត្រូវរៀបចំសំណាកតាមជំហានណាខ្លះ?','1) Open the Releasing Agent tube carefully.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q11','SP-02','Sample Pretreatment','How do I open the Releasing Agent tube?','ធ្វើម៉េចបើកបំពង់ Releasing Agent?','Open the seal carefully to avoid spilling the liquid.','បើកត្រាបិទដោយប្រុងប្រយ័ត្ន ដើម្បីកុំឱ្យទឹកកំពប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q12','SP-02','Sample Pretreatment','How deep should the swab go into the Releasing Agent?','ដងសំឡីគួរដាក់ចូលក្នុង Releasing Agent ជ្រៅប៉ុណ្ណា?','Deep enough that the absorbent tip is fully in the liquid.','ជ្រៅល្មមឱ្យចុងសំឡីដែលស្រូបទឹក លិចក្នុងទឹកទាំងស្រុង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q13','SP-02','Sample Pretreatment','How do I get as much liquid as possible out of the swab?','ធ្វើម៉េចបញ្ចេញទឹកពីដងសំឡីឱ្យបានច្រើនបំផុត?','Lift the swab above the liquid, squeeze the tube firmly and withdraw the swab.','លើកដងសំឡីឡើងពីលើទឹក ច្របាច់បំពង់ឱ្យខ្លាំង ហើយទាញដងសំឡីចេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q14','SP-02','Sample Pretreatment','Can I discard the swab into the Releasing Agent tube?','តើអាចបោះដងសំឡីចូលក្នុងបំពង់ Releasing Agent បានទេ?','No. Never discard the swab into the tube. Put it in the biohazard waste bag.','មិនបានទេ។ កុំបោះដងសំឡីចូលបំពង់ជាដាច់ខាត។ ដាក់វាចូលថង់កាកសំណល់ជីវគ្រោះថ្នាក់ (biohazard)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q15','SP-02','Sample Pretreatment','Do I need to cap the tube after removing the swab?','តើត្រូវបិទគម្របបំពង់ ក្រោយដកដងសំឡីចេញទេ?','Yes. Cap the tube tightly.','បាទ/ចាស។ បិទគម្របបំពង់ឱ្យជិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-02-Q16','SP-02','Sample Pretreatment','pretreatment procedure','តើការរៀបចំសំណាកមុនធ្វើតេស្តមានជំហានអ្វីខ្លះ?','1) Open the Releasing Agent tube carefully.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01','CP-01','Card Preparation','Large bubble(s) visible in the card chambers, or chambers not fully filled','ឃើញពពុះខ្យល់ធំៗក្នុងបន្ទប់តូចៗលើកាត ឬមានបន្ទប់ខ្លះមិនពេញ។ ត្រូវធ្វើម៉េច?','Press the airbag fully, shake the card vertically and quickly for 10s, and confirm no large bubbles/chambers are all filled before inserting into the device','សង្កត់ថង់ខ្យល់ (airbag) ឱ្យអស់ អង្រួនកាតឡើងចុះលឿនៗ ១០ វិនាទី ហើយពិនិត្យថាគ្មានពពុះធំ និងរន្ធ (chamber) ទាំងអស់ពេញ មុនដាក់ចូលម៉ាស៊ីន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q01','CP-01','Card Preparation','The chambers aren''t fully filled.','រន្ធកាតមិនពេញ។ ត្រូវធ្វើម៉េច?','Press the airbag fully, then shake the card vertically and quickly for 10 seconds. Before inserting, check all chambers are filled and there are no large bubbles.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q02','CP-01','Card Preparation','How long should I shake the card?','ត្រូវអង្រួនកាតយូរប៉ុណ្ណា?','10 seconds, vertically and quickly.','១០ វិនាទី ឡើងចុះ និងលឿនៗ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q03','CP-01','Card Preparation','How do I press the airbag correctly?','ធ្វើម៉េចសង្កត់ថង់ខ្យល់ (airbag) ឱ្យត្រឹមត្រូវ?','Press it fully, all the way down.','សង្កត់ឱ្យអស់ ដល់បាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q04','CP-01','Card Preparation','card not filling','កាតមិនពេញ។ ត្រូវធ្វើម៉េច?','Press the airbag fully, then shake the card vertically and quickly for 10 seconds. Before inserting, check all chambers are filled and there are no large bubbles.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q05','CP-01','Card Preparation','What should I check on the card before putting it in the device?','ត្រូវពិនិត្យអ្វីលើកាត មុនដាក់ចូលម៉ាស៊ីន?','Check that all chambers are filled and there are no large bubbles.','ពិនិត្យថារន្ធ (chamber) ទាំងអស់ពេញ ហើយគ្មានពពុះធំ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q06','CP-01','Card Preparation','How do I avoid bubbles when filling the card?','ធ្វើម៉េចកុំឱ្យមានពពុះពេលបំពេញកាត?','Press the airbag fully and shake the card vertically and quickly for 10 seconds.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q07','CP-01','Card Preparation','Should I shake the cartridge after loading?','តើគួរអង្រួនកាតក្រោយដាក់សំណាកទេ?','Yes. Shake the card vertically and quickly for 10 seconds.','បាទ/ចាស។ អង្រួនកាតឡើងចុះលឿនៗ ១០ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q08','CP-01','Card Preparation','Some wells look empty after filling.','រន្ធខ្លះមើលទៅទទេ ក្រោយបំពេញ។ ត្រូវធ្វើម៉េច?','Press the airbag fully, then shake the card vertically and quickly for 10 seconds. Before inserting, check all chambers are filled and there are no large bubbles.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q09','CP-01','Card Preparation','So I press the airbag fully and shake vertically for 10 seconds?','មានន័យថា ខ្ញុំសង្កត់ airbag ឱ្យអស់ ហើយអង្រួនឡើងចុះ ១០ វិនាទី?','Yes. Then check all chambers are filled with no large bubbles before inserting.','បាទ/ចាស។ បន្ទាប់មក ពិនិត្យថារន្ធទាំងអស់ពេញ និងគ្មានពពុះធំ មុនដាក់ចូល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q10','CP-01','Card Preparation','How do I make sure all chambers are filled?','ធ្វើម៉េចឱ្យប្រាកដថារន្ធទាំងអស់ពេញ?','Press the airbag fully, then shake the card vertically and quickly for 10 seconds. Before inserting, check all chambers are filled and there are no large bubbles.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q11','CP-01','Card Preparation','Do I need to shake the card before inserting it?','តើត្រូវអង្រួនកាត មុនដាក់ចូលទេ?','Yes. Shake the card vertically and quickly for 10 seconds.','បាទ/ចាស។ អង្រួនកាតឡើងចុះលឿនៗ ១០ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q12','CP-01','Card Preparation','How should I shake the card?','ត្រូវអង្រួនកាតយ៉ាងម៉េច?','Vertically and quickly, for 10 seconds.','ឡើងចុះ និងលឿនៗ រយៈពេល ១០ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q13','CP-01','Card Preparation','Do I press the airbag all the way down?','តើសង្កត់ airbag ឱ្យដល់បាតមែនទេ?','Yes. Press the airbag fully.','បាទ/ចាស។ សង្កត់ថង់ខ្យល់ (airbag) ឱ្យអស់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-01-Q14','CP-01','Card Preparation','card chambers half empty','បន្ទប់តូចៗលើកាតមានសំណាកតែពាក់កណ្តាល។ ត្រូវធ្វើម៉េច?','Press the airbag fully, then shake the card vertically and quickly for 10 seconds. Before inserting, check all chambers are filled and there are no large bubbles.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02','CP-02','Card Preparation','Bubbles still in the chambers after shaking','អង្រួនកាតហើយ តែនៅមានពពុះខ្យល់ក្នុងបន្ទប់លើកាត។ ត្រូវធ្វើម៉េច?','If bubbles (one big or many small) take up more than 1/3 of the chamber volume, discard the card. If less, you can continue','បើពពុះ (ធំមួយ ឬតូចៗច្រើន) មានទំហំលើសពី ១/៣ នៃមាឌរន្ធ (chamber) សូមបោះចោលកាត។ បើតិចជាងនេះ អាចបន្តបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q01','CP-02','Card Preparation','There''s a big bubble in the card chamber.','មានពពុះធំក្នុងរន្ធកាត។ ត្រូវធ្វើម៉េច?','If bubbles take up more than one-third of the chamber volume, discard the card. If less, you can continue.','បើពពុះមានទំហំលើសពី ១/៣ នៃមាឌរន្ធ (chamber) សូមបោះចោលកាត។ បើតិចជាងនេះ អាចបន្តបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q02','CP-02','Card Preparation','bubbles in card','ក្នុងកាតមានពពុះខ្យល់។ ត្រូវធ្វើម៉េច?','If bubbles take up more than one-third of the chamber volume, discard the card. If less, you can continue.','បើពពុះមានទំហំលើសពី ១/៣ នៃមាឌរន្ធ (chamber) សូមបោះចោលកាត។ បើតិចជាងនេះ អាចបន្តបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q03','CP-02','Card Preparation','Is a small bubble in the card okay before inserting it?','ពពុះតូចក្នុងកាត តើអាចដាក់ចូលបានទេ?','Yes, as long as bubbles take up no more than one-third of the chamber volume.','បាទ/ចាស ដរាបណាពពុះមិនលើសពី ១/៣ នៃមាឌរន្ធ (chamber)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q04','CP-02','Card Preparation','Air bubbles in reaction chambers.','មានពពុះខ្យល់ក្នុងរន្ធប្រតិកម្ម។ ត្រូវធ្វើម៉េច?','If bubbles take up more than one-third of the chamber volume, discard the card. If less, you can continue.','បើពពុះមានទំហំលើសពី ១/៣ នៃមាឌរន្ធ (chamber) សូមបោះចោលកាត។ បើតិចជាងនេះ អាចបន្តបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q05','CP-02','Card Preparation','card have big bubble, can use?','កាតមានពពុះធំ ប្រើបានទេ?','No, if it takes up more than one-third of the chamber. Discard the card.','មិនបានទេ បើវាមានទំហំលើសពី ១/៣ នៃរន្ធ។ សូមបោះចោលកាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q06','CP-02','Card Preparation','I shook the card but the bubble is still there. What should I do?','ខ្ញុំអង្រួនកាតហើយ តែពពុះនៅតែមាន។ ត្រូវធ្វើម៉េច?','If bubbles take up more than one-third of the chamber volume, discard the card. If less, you can continue.','បើពពុះមានទំហំលើសពី ១/៣ នៃមាឌរន្ធ (chamber) សូមបោះចោលកាត។ បើតិចជាងនេះ អាចបន្តបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q07','CP-02','Card Preparation','How big a bubble is too big?','ពពុះធំប៉ុនណាទើបចាត់ទុកថាធំពេក?','More than one-third of the chamber volume.','លើសពី ១/៣ នៃមាឌរន្ធ (chamber)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q08','CP-02','Card Preparation','When should I discard a card because of bubbles?','ពេលណាត្រូវបោះកាតចោល ដោយសារពពុះ?','When bubbles (one big or many small) take up more than one-third of the chamber volume.','ពេលពពុះ (ធំមួយ ឬតូចៗច្រើន) មានទំហំលើសពី ១/៣ នៃមាឌរន្ធ (chamber)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q09','CP-02','Card Preparation','There are many small bubbles in the chamber — can I still use the card?','មានពពុះតូចៗច្រើនក្នុងរន្ធ — តើនៅប្រើកាតបានទេ?','No, if together they take up more than one-third of the chamber. Discard the card.','មិនបានទេ បើពពុះទាំងនោះរួមគ្នាមានទំហំលើសពី ១/៣ នៃរន្ធ។ សូមបោះចោលកាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-02-Q10','CP-02','Card Preparation','What is the bubble limit for the chambers?','ដែនកំណត់ពពុះក្នុងរន្ធគឺប៉ុន្មាន?','Bubbles must not take up more than one-third of the chamber volume.','ពពុះមិនត្រូវមានទំហំលើសពី ១/៣ នៃមាឌរន្ធ (chamber) ទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-03','CP-03','Card Preparation','Chambers still not filled after pressing the airbag fully and shaking','ខ្ញុំចុចថង់ខ្យល់ដល់បាត ហើយអង្រួនកាតរួច តែបន្ទប់លើកាតនៅតែមិនពេញ។ ត្រូវធ្វើម៉េច?','Make sure the airbag is pressed until it recesses and shake vertically and quickly for 10 s. If chambers still aren''t filled, contact Pluslife support','ធ្វើឱ្យប្រាកដថាសង្កត់ថង់ខ្យល់ (airbag) រហូតវាផតចូល ហើយអង្រួនកាតឡើងចុះលឿនៗ ១០ វិនាទី។ បើរន្ធនៅតែមិនពេញ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-03-Q01','CP-03','Card Preparation','I pressed the airbag but some chambers are still empty.','ខ្ញុំសង្កត់ airbag ហើយ តែរន្ធខ្លះនៅតែទទេ?','Make sure the airbag is pressed fully, until it recesses, then shake the card vertically and quickly for 10 seconds. If chambers still aren''t filled, the guidance doesn''t say whether the card can be used. Please contact Pluslife support.','ធ្វើឱ្យប្រាកដថាសង្កត់ថង់ខ្យល់ (airbag) ឱ្យអស់ រហូតវាផតចូល រួចអង្រួនកាតឡើងចុះលឿនៗ ១០ វិនាទី។ បើរន្ធនៅតែមិនពេញ ការណែនាំមិនបានបញ្ជាក់ថាអាចប្រើកាតនោះបានឬអត់ទេ។ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04','CP-04','Card Preparation','Worker unsure how to add the sample and prepare the card','ត្រូវបញ្ចូលសំណាកទៅក្នុងកាត និងរៀបចំកាតដោយរបៀបណា?','1) After pretreatment, open the foil bag and place the card on the holder. 2) Unscrew the sample-tube cap and dispense the Releasing Agent along the inner wall, between the two injection lines. 3) Screw the cap on tightly; let it stand 15 s. 4) Press the airbag until it recesses; check all chambers are filled. 5) Shake hard up and down 10 times (≈5 s), then test immediately','១) ក្រោយ pretreatment រួច បើកថង់អាលុយមីញ៉ូម ហើយដាក់កាតលើជើងទ្រ (holder)។ ២) មួលគម្របបំពង់សំណាកចេញ ហើយចាក់ Releasing Agent តាមជញ្ជាំងខាងក្នុង ឱ្យនៅចន្លោះបន្ទាត់ចាក់ទាំងពីរ។ ៣) មួលគម្របឱ្យជិត ហើយទុកចោល ១៥ វិនាទី។ ៤) សង្កត់ថង់ខ្យល់ (airbag) រហូតវាផតចូល ហើយពិនិត្យថារន្ធទាំងអស់ពេញ។ ៥) អង្រួនខ្លាំងៗឡើងចុះ ១០ ដង (ប្រហែល ៥ វិនាទី) រួចធ្វើតេស្តភ្លាមៗ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q01','CP-04','Card Preparation','I''m new — how do I prepare the card after adding the sample?','ខ្ញុំទើបប្រើ Pluslife។ ក្រោយដាក់សំណាក ធ្វើម៉េចរៀបចំកាត?','Screw the card cap on tightly and let it stand 15 seconds. Press the airbag until it recesses and check all chambers are filled. Shake hard up and down 10 times (about 5 seconds), then test immediately.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q02','CP-04','Card Preparation','How do I prepare the reaction card?','ធ្វើម៉េចរៀបចំកាតប្រតិកម្ម?','1) After pretreatment, open the foil bag and place the card on the holder.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q03','CP-04','Card Preparation','How do I add the sample to the reaction card?','ធ្វើម៉េចដាក់សំណាកចូលកាតប្រតិកម្ម?','Place the card on the holder and unscrew the sample-tube cap. Dispense the Releasing Agent (the processed sample) along the inner wall so the liquid flows between the two injection lines.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q04','CP-04','Card Preparation','How should I dispense the Releasing Agent into the card?','ត្រូវចាក់ Releasing Agent ចូលកាតយ៉ាងម៉េច?','Steady the holder and dispense along the inner wall, so the liquid flows between the two injection lines.','កាន់ជើងទ្រឱ្យនឹង ហើយចាក់តាមជញ្ជាំងខាងក្នុង ដើម្បីឱ្យទឹកហូរនៅចន្លោះបន្ទាត់ចាក់ទាំងពីរ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q05','CP-04','Card Preparation','How high should the liquid level be in the card?','កម្រិតទឹកក្នុងកាតគួរខ្ពស់ប៉ុណ្ណា?','Between the two lines.','នៅចន្លោះបន្ទាត់ទាំងពីរ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q06','CP-04','Card Preparation','card preparation steps','ត្រូវរៀបចំកាតតេស្តតាមជំហានណាខ្លះ?','1) After pretreatment, open the foil bag and place the card on the holder.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q07','CP-04','Card Preparation','What do I do after unscrewing the card''s sample tube cap?','ក្រោយមួលគម្របបំពង់សំណាករបស់កាតចេញ ត្រូវធ្វើអ្វី?','Dispense the Releasing Agent along the inner wall, screw the cap on tightly and let the card stand 15 seconds. Then press the airbag and shake.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q08','CP-04','Card Preparation','Where should the card be placed while adding the sample?','គួរដាក់កាតនៅឯណា ពេលដាក់សំណាក?','On the holder.','លើជើងទ្រ (holder)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-04-Q09','CP-04','Card Preparation','How long should the card stand after closing the cap?','ក្រោយបិទគម្រប ត្រូវទុកកាតចោលយូរប៉ុណ្ណា?','15 seconds.','១៥ វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-05','CP-05','Card Preparation','Card cap not screwed on tightly','ខ្ញុំបង្វិលគម្របកាតមិនជិត។ ត្រូវធ្វើម៉េច?','Screw the cap on tightly, then let the card stand for 15 seconds before pressing the airbag','មួលគម្របឱ្យជិត រួចទុកកាតចោល ១៥ វិនាទី មុនសង្កត់ថង់ខ្យល់ (airbag)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-05-Q01','CP-05','Card Preparation','Do I need to tighten the card cap?','តើត្រូវមួលគម្របកាតឱ្យជិតទេ?','Yes. Screw it on tightly. A loose cap may cause invalid detection.','បាទ/ចាស។ មួលវាឱ្យជិត។ គម្របរលុង អាចធ្វើឱ្យការធ្វើតេស្តគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-05-Q02','CP-05','Card Preparation','What happens if the card cap isn''t sealed properly?','មានអ្វីកើតឡើង បើគម្របកាតបិទមិនជិត?','It may result in invalid detection.','វាអាចធ្វើឱ្យការធ្វើតេស្តគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-05-Q03','CP-05','Card Preparation','card cap not tight','គម្របកាតបិទមិនជិត។ ត្រូវធ្វើម៉េច?','Screw the cap on tightly. A loose cap may cause invalid detection.','មួលគម្របឱ្យជិត។ គម្របរលុង អាចធ្វើឱ្យការធ្វើតេស្តគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-05-Q04','CP-05','Card Preparation','Should I wait before pressing the airbag?','តើគួររង់ចាំ មុនសង្កត់ airbag ទេ?','Yes. Let the card stand still for 15 seconds after closing the cap.','បាទ/ចាស។ ទុកកាតឱ្យនៅស្ងៀម ១៥ វិនាទី ក្រោយបិទគម្រប។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-05-Q05','CP-05','Card Preparation','Can a loose cap cause an invalid result?','តើគម្របរលុងអាចធ្វើឱ្យលទ្ធផលចេញ Invalid ទេ?','Yes. An improperly sealed cap may result in invalid detection.','បាទ/ចាស។ គម្របដែលបិទមិនជិត អាចធ្វើឱ្យការធ្វើតេស្តគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01','DO-01','Device Operation','Worker unsure how to start the device or how long to wait before testing','បើកម៉ាស៊ីនដោយរបៀបណា ហើយត្រូវរង់ចាំប៉ុន្មាន ទើបអាចធ្វើតេស្តបាន?','Place the device on a flat, stable surface, connect power and press the front power button. Red light flashes during warm-up; after about 2 minutes it turns solid blue (ready)','ដាក់ម៉ាស៊ីនលើផ្ទៃរាបស្មើ និងនឹង ភ្ជាប់ភ្លើង ហើយចុចប៊ូតុងបើកនៅខាងមុខ។ ភ្លើងក្រហមភ្លឹបភ្លែតពេលកំពុងកម្តៅ។ ប្រហែល ២ នាទីក្រោយ វាប្តូរជាពណ៌ខៀវភ្លឺជាប់ (រួចរាល់)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q01','DO-01','Device Operation','How long should I wait after powering on before I start testing?','ក្រោយបើកម៉ាស៊ីន ត្រូវរង់ចាំយូរប៉ុណ្ណា ទើបចាប់ផ្តើមធ្វើតេស្ត?','About 2 minutes. Wait until the light turns solid blue (standby).','ប្រហែល ២ នាទី។ រង់ចាំរហូតភ្លើងប្តូរជាពណ៌ខៀវភ្លឺជាប់ (standby)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q02','DO-01','Device Operation','How do I turn on the MiniDock?','ធ្វើម៉េចបើក MiniDock?','Place the device on a flat, stable surface, connect the power and press the front power button. The red light flashes during warm-up; after about 2 minutes it turns solid blue (ready).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q03','DO-01','Device Operation','How long does the device take to warm up?','ម៉ាស៊ីនត្រូវកម្តៅយូរប៉ុណ្ណា?','About 2 minutes. Wait until the light turns solid blue (standby).','ប្រហែល ២ នាទី។ រង់ចាំរហូតភ្លើងប្តូរជាពណ៌ខៀវភ្លឺជាប់ (standby)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q04','DO-01','Device Operation','What do I do after pressing the power button?','ក្រោយចុចប៊ូតុងបើក ត្រូវធ្វើអ្វី?','Wait while it warms up (red light flashes). After about 2 minutes the light turns solid blue and the device is ready.','រង់ចាំពេលវាកំពុងកម្តៅ (ភ្លើងក្រហមភ្លឹបភ្លែត)។ ប្រហែល ២ នាទីក្រោយ ភ្លើងប្តូរជាពណ៌ខៀវភ្លឺជាប់ ហើយម៉ាស៊ីនរួចរាល់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q05','DO-01','Device Operation','Which button turns the device on?','ប៊ូតុងមួយណាសម្រាប់បើកម៉ាស៊ីន?','The power button on the front.','ប៊ូតុងបើកនៅខាងមុខម៉ាស៊ីន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q06','DO-01','Device Operation','How do I set up the device before testing?','ធ្វើម៉េចរៀបចំម៉ាស៊ីន មុនធ្វើតេស្ត?','Place the device on a flat, stable surface, connect the power and press the front power button. The red light flashes during warm-up; after about 2 minutes it turns solid blue (ready).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q07','DO-01','Device Operation','Where should I place the device?','គួរដាក់ម៉ាស៊ីននៅឯណា?','On a flat, stable surface.','លើផ្ទៃរាបស្មើ និងនឹង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q08','DO-01','Device Operation','How do I know the warm-up is finished?','ធ្វើម៉េចដឹងថាការកម្តៅបានចប់?','The light turns solid blue, about 2 minutes after power-on.','ភ្លើងប្តូរជាពណ៌ខៀវភ្លឺជាប់ ប្រហែល ២ នាទីក្រោយបើកម៉ាស៊ីន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q09','DO-01','Device Operation','About 2 minutes after power-on the light turned solid blue — is that standby?','ប្រហែល ២ នាទីក្រោយបើក ភ្លើងប្តូរជាខៀវភ្លឺជាប់ — តើនោះជា standby មែនទេ?','Yes. Solid blue means standby: the device is ready for the card.','បាទ/ចាស។ ពណ៌ខៀវភ្លឺជាប់ មានន័យថា standby៖ ម៉ាស៊ីនរួចរាល់សម្រាប់ដាក់កាត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-01-Q10','DO-01','Device Operation','I''m new — how do I get the device ready for a test?','ខ្ញុំទើបប្រើ Pluslife។ ធ្វើម៉េចរៀបចំម៉ាស៊ីនឱ្យរួចរាល់សម្រាប់តេស្ត?','Place the device on a flat, stable surface, connect the power and press the front power button. The red light flashes during warm-up; after about 2 minutes it turns solid blue (ready).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02','DO-02','Device Operation','Worker unsure what the device lights mean','ភ្លើងពណ៌នីមួយៗលើម៉ាស៊ីនមានន័យថាម៉េច?','Red flashing after power-on: warming up. Solid blue: ready, insert the card. Blue flashing: test running, don''t open the lid. Beeping + red flashing: alarm, check the software message. After the test: Positive / Negative light shows the result','ភ្លើងក្រហមភ្លឹបភ្លែតក្រោយបើកម៉ាស៊ីន៖ កំពុងកម្តៅ។ ពណ៌ខៀវភ្លឺជាប់៖ រួចរាល់ ដាក់កាតបាន។ ពណ៌ខៀវភ្លឹបភ្លែត៖ កំពុងធ្វើតេស្ត កុំបើកគម្រប។ សំឡេងប៊ីប + ភ្លើងក្រហមភ្លឹបភ្លែត៖ ម៉ាស៊ីនរោទិ៍ សូមមើលសារក្នុងកម្មវិធី។ ក្រោយតេស្តចប់៖ ភ្លើង Positive (វិជ្ជមាន) / Negative (អវិជ្ជមាន) បង្ហាញលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q01','DO-02','Device Operation','What does the solid blue light mean?','ភ្លើងខៀវភ្លឺជាប់ មានន័យថាម៉េច?','Standby/ready. You can insert the card.','Standby/រួចរាល់។ អ្នកអាចដាក់កាតបាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q02','DO-02','Device Operation','What does a flashing red light mean?','ភ្លើងក្រហមលោត មានន័យថាម៉េច?','The device is warming up. (Red flashing together with beeping is an alarm; check the message in the software.)','ម៉ាស៊ីនកំពុងកម្តៅ។ (ភ្លើងក្រហមភ្លឹបភ្លែត ព្រមជាមួយសំឡេងប៊ីប គឺជាការរោទិ៍ សូមមើលសារក្នុងកម្មវិធី។)','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q03','DO-02','Device Operation','What do the different light colors on the device mean?','ពណ៌ភ្លើងផ្សេងៗលើម៉ាស៊ីន មានន័យថាម៉េច?','Red flashing (after power-on): warming up.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q04','DO-02','Device Operation','So red flashing means warm-up and solid blue means ready?','មានន័យថា ភ្លើងក្រហមលោតគឺកំពុងកម្តៅ ហើយខៀវភ្លឺជាប់គឺរួចរាល់?','Yes. Red flashing means warming up; solid blue means ready.','បាទ/ចាស។ ភ្លើងក្រហមភ្លឹបភ្លែត មានន័យថាកំពុងកម្តៅ។ ពណ៌ខៀវភ្លឺជាប់ មានន័យថារួចរាល់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q05','DO-02','Device Operation','What does the flashing blue light mean?','ភ្លើងខៀវលោត មានន័យថាម៉េច?','A test is running. Don''t open the lid.','កំពុងធ្វើតេស្ត។ កុំបើកគម្រប។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q06','DO-02','Device Operation','The blue light started flashing after I closed the lid — is that normal?','ភ្លើងខៀវចាប់ផ្តើមលោត ក្រោយខ្ញុំបិទគម្រប — តើធម្មតាទេ?','Yes. Flashing blue means the test is running. Don''t open the lid.','បាទ/ចាស។ ពណ៌ខៀវភ្លឹបភ្លែត មានន័យថាតេស្តកំពុងដំណើរការ។ កុំបើកគម្រប។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q07','DO-02','Device Operation','What does beeping with a red flashing light mean?','សំឡេងប៊ីប និងភ្លើងក្រហមលោត មានន័យថាម៉េច?','A device alarm. Check the error message shown in the software.','ម៉ាស៊ីនរោទិ៍។ សូមមើលសារកំហុសដែលបង្ហាញក្នុងកម្មវិធី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q08','DO-02','Device Operation','What do the Positive and Negative lights show?','ភ្លើង Positive និង Negative បង្ហាញអ្វី?','When the test is finished, the lights show the result: Positive or Negative. It also appears in PluslifePad if connected.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q09','DO-02','Device Operation','device light indicator meaning','ភ្លើងសញ្ញានីមួយៗលើម៉ាស៊ីនមានន័យថាម៉េច?','Red flashing (after power-on): warming up.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-02-Q10','DO-02','Device Operation','How can I tell from the lights whether the device is warming up, ready or testing?','ធ្វើម៉េចដឹងពីភ្លើង ថាម៉ាស៊ីនកំពុងកម្តៅ រួចរាល់ ឬកំពុងធ្វើតេស្ត?','Red flashing (after power-on): warming up.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03','DO-03','Device Operation','Worker unsure how to insert the card and start the test','ត្រូវដាក់កាតចូលម៉ាស៊ីន និងចាប់ផ្តើមតេស្តដោយរបៀបណា?','1) Check the light is solid blue. 2) Open the lid and push the card fully into the bottom slot in the indicated direction (1 beep). 3) Close the lid immediately; the test starts automatically (blue flashing), no button needed. 4) Don''t open the lid during the test. 5) A second beep means it''s finished; the lights show the result','១) ពិនិត្យថាភ្លើងពណ៌ខៀវភ្លឺជាប់។ ២) បើកគម្រប ហើយរុញកាតចូលរន្ធខាងក្រោមឱ្យដល់បាត តាមទិសដៅដែលបានបង្ហាញ (ប៊ីប ១ ដង)។ ៣) បិទគម្របភ្លាមៗ។ តេស្តចាប់ផ្តើមដោយស្វ័យប្រវត្តិ (ពណ៌ខៀវភ្លឹបភ្លែត) មិនចាំបាច់ចុចប៊ូតុងទេ។ ៤) កុំបើកគម្របពេលកំពុងធ្វើតេស្ត។ ៥) សំឡេងប៊ីបលើកទី២ មានន័យថាតេស្តចប់។ ភ្លើងបង្ហាញលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q01','DO-03','Device Operation','What is the second beep after inserting the card for?','សំឡេងប៊ីបលើកទីពីរ ក្រោយដាក់កាត មានន័យអ្វី?','It means the test is finished. The lights then show the result.','វាមានន័យថាតេស្តចប់ហើយ។ បន្ទាប់មក ភ្លើងបង្ហាញលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q02','DO-03','Device Operation','Do I close the lid before or after the beep?','តើបិទគម្របមុន ឬក្រោយសំឡេងប៊ីប?','After. Insert the card (1 beep), then close the lid immediately.','ក្រោយ។ ដាក់កាតចូល (ប៊ីប ១ ដង) រួចបិទគម្របភ្លាមៗ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q03','DO-03','Device Operation','How do I insert the reaction card into the device?','ធ្វើម៉េចដាក់កាតប្រតិកម្មចូលម៉ាស៊ីន?','Open the lid, insert the card in the indicated direction and push it fully into the bottom slot (1 beep). Close the lid immediately.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q04','DO-03','Device Operation','Which way does the card go into the device?','ដាក់កាតចូលម៉ាស៊ីនតាមទិសណា?','In the direction indicated on the device, pushed fully into the bottom slot.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q05','DO-03','Device Operation','How do I start the test?','ធ្វើម៉េចចាប់ផ្តើមតេស្ត?','When the light is solid blue, insert the card (1 beep) and close the lid. The test starts automatically and the blue light flashes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q06','DO-03','Device Operation','Do I need to press a button to start the test?','តើត្រូវចុចប៊ូតុង ដើម្បីចាប់ផ្តើមតេស្តទេ?','No. The test starts automatically once the card is inserted and the lid is closed.','មិនចាំបាច់ទេ។ តេស្តចាប់ផ្តើមដោយស្វ័យប្រវត្តិ ពេលដាក់កាតចូល ហើយបិទគម្រប។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q07','DO-03','Device Operation','How many beeps should I hear during a test?','ពេលធ្វើតេស្ត គួរឮសំឡេងប៊ីបប៉ុន្មានដង?','Two: one when you insert the card, and a second when the test is finished.','ពីរដង៖ ម្តងពេលដាក់កាតចូល និងម្តងទៀតពេលតេស្តចប់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q08','DO-03','Device Operation','How do I know the test is finished?','ធ្វើម៉េចដឹងថាតេស្តចប់?','You''ll hear a second beep, and the lights show the result.','អ្នកនឹងឮសំឡេងប៊ីបលើកទី២ ហើយភ្លើងបង្ហាញលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q09','DO-03','Device Operation','insert card steps','ត្រូវដាក់កាតចូលម៉ាស៊ីនយ៉ាងម៉េច?','Open the lid, insert the card in the indicated direction and push it fully into the bottom slot (1 beep). Close the lid immediately.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q10','DO-03','Device Operation','How far should I push the card in?','ត្រូវរុញកាតចូលជ្រៅប៉ុណ្ណា?','All the way into the bottom slot.','រុញចូលរន្ធខាងក្រោមឱ្យដល់បាត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q11','DO-03','Device Operation','What happens after I close the lid?','មានអ្វីកើតឡើង ក្រោយខ្ញុំបិទគម្រប?','The test starts automatically and the blue light flashes. Don''t open the lid until the test is finished (second beep).','តេស្តចាប់ផ្តើមដោយស្វ័យប្រវត្តិ ហើយភ្លើងពណ៌ខៀវភ្លឹបភ្លែត។ កុំបើកគម្រប រហូតដល់តេស្តចប់ (សំឡេងប៊ីបលើកទី២)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-03-Q12','DO-03','Device Operation','I''m new — walk me through running a test once the card is ready.','ខ្ញុំទើបប្រើ Pluslife។ សូមប្រាប់ជំហានធ្វើតេស្ត ពេលកាតរួចរាល់។ ត្រូវធ្វើម៉េច?','1) Check the light is solid blue.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-04','DO-04','Device Operation','Short press of the power button doesn''t turn the device off','ខ្ញុំចុចប៊ូតុងមួយភ្លែត តែម៉ាស៊ីនមិនរលត់។ ត្រូវបិទដោយរបៀបណា?','Press and hold the power button for more than 3 seconds','ចុចប៊ូតុងបើក/បិទ ឱ្យជាប់លើសពី ៣ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-04-Q01','DO-04','Device Operation','How do I turn off the device?','ធ្វើម៉េចបិទម៉ាស៊ីន?','Press and hold the power button for more than 3 seconds.','ចុចប៊ូតុងបើក/បិទ ឱ្យជាប់លើសពី ៣ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-04-Q02','DO-04','Device Operation','How long do I hold the power button to switch off?','ត្រូវចុចប៊ូតុងបើក/បិទជាប់យូរប៉ុណ្ណា ដើម្បីបិទ?','More than 3 seconds.','លើសពី ៣ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-04-Q03','DO-04','Device Operation','device power off','ត្រូវចុចប៊ូតុងយ៉ាងម៉េចដើម្បីបិទម៉ាស៊ីន?','Press and hold the power button for more than 3 seconds.','ចុចប៊ូតុងបើក/បិទ ឱ្យជាប់លើសពី ៣ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-04-Q04','DO-04','Device Operation','Is a short press enough to power off?','តើចុចខ្លីៗគ្រប់គ្រាន់ដើម្បីបិទទេ?','No. Press and hold the power button for more than 3 seconds.','មិនគ្រប់ទេ។ ចុចប៊ូតុងបើក/បិទ ឱ្យជាប់លើសពី ៣ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-04-Q05','DO-04','Device Operation','How do I shut down the MiniDock after testing?','ធ្វើម៉េចបិទ MiniDock ក្រោយធ្វើតេស្ត?','Press and hold the power button for more than 3 seconds.','ចុចប៊ូតុងបើក/បិទ ឱ្យជាប់លើសពី ៣ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-04-Q06','DO-04','Device Operation','I''m new — what''s the correct way to power off?','ខ្ញុំទើបប្រើ Pluslife។ របៀបបិទម៉ាស៊ីនឱ្យត្រឹមត្រូវយ៉ាងម៉េច?','Press and hold the power button for more than 3 seconds.','ចុចប៊ូតុងបើក/បិទ ឱ្យជាប់លើសពី ៣ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-04-Q07','DO-04','Device Operation','Long press or short press to turn it off?','ចុចជាប់ ឬចុចខ្លី ដើម្បីបិទ?','Long press: hold the power button for more than 3 seconds.','ចុចឱ្យជាប់៖ សង្កត់ប៊ូតុងបើក/បិទ លើសពី ៣ វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-05','DO-05','Device Operation','Worker wants to run another test','តេស្តមុនចប់ហើយ។ បើចង់ធ្វើតេស្តបន្ទាប់ ត្រូវធ្វើអ្វីខ្លះ?','Every test needs a new reaction card and a fresh sample; repeat the card preparation steps. If the device is off, power it on and wait for solid blue first','តេស្តនីមួយៗ ត្រូវការកាតប្រតិកម្មថ្មី និងសំណាកថ្មី។ ធ្វើជំហានរៀបចំកាតម្តងទៀត។ បើម៉ាស៊ីនបិទ សូមបើកវា ហើយរង់ចាំភ្លើងពណ៌ខៀវភ្លឺជាប់សិន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-05-Q01','DO-05','Device Operation','How do I start another test?','ធ្វើម៉េចចាប់ផ្តើមតេស្តមួយទៀត?','Prepare a new Reaction Card with a fresh sample and repeat the card preparation steps. If the device is off, power it on and wait for the solid blue light first.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-05-Q02','DO-05','Device Operation','Can I run a new test right after the last one?','តើអាចធ្វើតេស្តថ្មី ភ្លាមក្រោយតេស្តមុនបានទេ?','Yes. Prepare a new card with a fresh sample and repeat the card preparation steps.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-05-Q03','DO-05','Device Operation','Do I need a new card and a fresh sample for each test?','តើតេស្តនីមួយៗ ត្រូវការកាតថ្មី និងសំណាកថ្មីទេ?','Yes. Every test needs a new card and a fresh sample.','បាទ/ចាស។ តេស្តនីមួយៗ ត្រូវការកាតថ្មី និងសំណាកថ្មី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-05-Q04','DO-05','Device Operation','next test steps','តេស្តមុនចប់ហើយ។ ត្រូវធ្វើអ្វីខ្លះមុនតេស្តបន្ទាប់?','Prepare a new Reaction Card with a fresh sample and repeat the card preparation steps. If the device is off, power it on and wait for the solid blue light first.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-05-Q05','DO-05','Device Operation','The device was turned off — how do I start a new test?','ម៉ាស៊ីនត្រូវបានបិទ។ ធ្វើម៉េចចាប់ផ្តើមតេស្តថ្មី?','Power it on and wait for the solid blue light (about 2 minutes). Then prepare a new card with a fresh sample.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-05-Q06','DO-05','Device Operation','What''s the procedure for running several tests in a row?','នីតិវិធីធ្វើតេស្តច្រើនជាប់ៗគ្នាយ៉ាងម៉េច?','Prepare a new Reaction Card with a fresh sample and repeat the card preparation steps. If the device is off, power it on and wait for the solid blue light first.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01','RS-01','Results & Clinical Decision','Worker unsure where to read or record the result','តើមើលលទ្ធផលនៅឯណា ហើយត្រូវកត់ត្រានៅឯណា?','When the run is complete, the Positive / Negative light on the device shows the result (no computer needed); it also appears in PluslifePad if connected. Record the result; a report can be printed from the software. Result decision guide: [Result Decision Guide - Pending]','ពេលតេស្តចប់ ភ្លើង Positive (វិជ្ជមាន) / Negative (អវិជ្ជមាន) លើម៉ាស៊ីនបង្ហាញលទ្ធផល (មិនត្រូវការកុំព្យូទ័រ)។ លទ្ធផលក៏បង្ហាញក្នុង PluslifePad ដែរ បើបានភ្ជាប់។ សូមកត់ត្រាលទ្ធផល។ អាចបោះពុម្ពរបាយការណ៍ពីកម្មវិធីបាន។ សៀវភៅណែនាំការសម្រេចលទ្ធផល (Result decision guide)៖ [ឯកសារកំពុងរៀបចំ - Pending]','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01-Q01','RS-01','Results & Clinical Decision','Where can I see the test result?','អាចមើលលទ្ធផលតេស្តនៅឯណា?','On the MiniDock Ultra (indicator lights), or in PluslifePad if the device is connected.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01-Q02','RS-01','Results & Clinical Decision','How do I read the result?','ធ្វើម៉េចអានលទ្ធផល?','When the run is complete, the Positive / Negative indicator on the device shows the result; it also appears in PluslifePad if connected. Record the result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01-Q03','RS-01','Results & Clinical Decision','Can I see the result without a computer?','តើអាចមើលលទ្ធផល ដោយគ្មានកុំព្យូទ័របានទេ?','Yes. The device lights show the result (Positive / Negative). A computer isn''t required.','បាទ/ចាស។ ភ្លើងលើម៉ាស៊ីនបង្ហាញលទ្ធផល (Positive វិជ្ជមាន / Negative អវិជ្ជមាន)។ មិនត្រូវការកុំព្យូទ័រទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01-Q04','RS-01','Results & Clinical Decision','Can I print a test report?','តើអាចបោះពុម្ពរបាយការណ៍តេស្តបានទេ?','Yes. You can print a report from the software.','បាទ/ចាស។ អ្នកអាចបោះពុម្ពរបាយការណ៍ពីកម្មវិធីបាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01-Q05','RS-01','Results & Clinical Decision','Is the result shown in PluslifePad?','តើលទ្ធផលបង្ហាញក្នុង PluslifePad ទេ?','Yes, if the device is connected to PluslifePad.','បាទ/ចាស បើម៉ាស៊ីនបានភ្ជាប់ជាមួយ PluslifePad។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01-Q06','RS-01','Results & Clinical Decision','Should I record the result?','តើគួរកត់ត្រាលទ្ធផលទេ?','Yes. Read and record the result when the run is complete.','បាទ/ចាស។ អាន និងកត់ត្រាលទ្ធផល ពេលតេស្តចប់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01-Q07','RS-01','Results & Clinical Decision','view result','ត្រូវចូលមើលលទ្ធផលនៅឯណា?','On the MiniDock Ultra (indicator lights), or in PluslifePad if the device is connected.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-01-Q08','RS-01','Results & Clinical Decision','The test is complete — where do I find the result?','តេស្តចប់ហើយ — រកលទ្ធផលនៅឯណា?','On the MiniDock Ultra (indicator lights), or in PluslifePad if the device is connected.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-02','RS-02','Results & Clinical Decision','Pluslife is negative but the patient still has symptoms','Pluslife ចេញអវិជ្ជមាន តែអ្នកជំងឺនៅមានរោគសញ្ញា។ ត្រូវធ្វើអ្វីបន្ទាប់?','Clinical assessment / follow-up. If GeneXpert/TrueNat is positive, treat on that result; if both are negative, no treatment is required. Result decision guide: [Result Decision Guide - Pending]','ការវាយតម្លៃគ្លីនិក / ការតាមដាន។ បើ GeneXpert/TrueNat វិជ្ជមាន សូមព្យាបាលផ្អែកលើលទ្ធផលនោះ។ បើទាំងពីរអវិជ្ជមាន មិនតម្រូវឱ្យព្យាបាលទេ។ សៀវភៅណែនាំការសម្រេចលទ្ធផល (Result decision guide)៖ [ឯកសារកំពុងរៀបចំ - Pending]','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-02-Q01','RS-02','Results & Clinical Decision','What should happen after a negative result?','ក្រោយលទ្ធផលអវិជ្ជមាន ត្រូវធ្វើអ្វីបន្ត?','Clinical assessment / follow-up. Per the clinical decision guide: if GeneXpert/TrueNat is also negative, no treatment is required; if GeneXpert/TrueNat is positive, start treatment on that result (standard regimen, or drug-resistant TB regimen if resistance is detected).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-02-Q02','RS-02','Results & Clinical Decision','Pluslife is negative — do I need further tests?','Pluslife អវិជ្ជមាន — តើត្រូវធ្វើតេស្តបន្ថែមទេ?','Clinical assessment / follow-up. Per the clinical decision guide: if GeneXpert/TrueNat is also negative, no treatment is required; if GeneXpert/TrueNat is positive, start treatment on that result (standard regimen, or drug-resistant TB regimen if resistance is detected).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-02-Q03','RS-02','Results & Clinical Decision','pluslife negative what next','Pluslife អវិជ្ជមាន បន្ទាប់ធ្វើអ្វី?','Clinical assessment / follow-up. Per the clinical decision guide: if GeneXpert/TrueNat is also negative, no treatment is required; if GeneXpert/TrueNat is positive, start treatment on that result (standard regimen, or drug-resistant TB regimen if resistance is detected).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-02-Q04','RS-02','Results & Clinical Decision','The patient still has symptoms but Pluslife is negative. What should I do?','អ្នកជំងឺនៅតែមានរោគសញ្ញា តែ Pluslife អវិជ្ជមាន។ ត្រូវធ្វើម៉េច?','Clinical assessment / follow-up. Per the clinical decision guide: if GeneXpert/TrueNat is also negative, no treatment is required; if GeneXpert/TrueNat is positive, start treatment on that result (standard regimen, or drug-resistant TB regimen if resistance is detected).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-02-Q05','RS-02','Results & Clinical Decision','Does a negative Pluslife result rule out TB?','តើលទ្ធផល Pluslife អវិជ្ជមាន អាចបដិសេធជំងឺរបេងបានទេ?','Not on its own. In the clinical study, sputum swab sensitivity was 86.7% and tongue swab 80.7%, so some TB cases test negative. Per the clinical decision guide, if GeneXpert/TrueNat is positive, start treatment on that result; if both are negative, no treatment is required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-02-Q06','RS-02','Results & Clinical Decision','If Pluslife is negative, when does treatment start?','បើ Pluslife អវិជ្ជមាន ពេលណាចាប់ផ្តើមព្យាបាល?','Only if GeneXpert/TrueNat is positive: start treatment on that result (standard regimen, or drug-resistant TB regimen if resistance is detected). If both tests are negative, no treatment is required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03','RS-03','Results & Clinical Decision','Worker expects Pluslife to show drug resistance','លទ្ធផល Pluslife អាចប្រាប់ថាមេរោគស៊ាំនឹងថ្នាំបានទេ?','After a positive result, link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance); switch to the drug-resistant TB regimen if resistance is found. Specific drugs: follow national DR-TB guidelines','ក្រោយលទ្ធផលវិជ្ជមាន បញ្ជូនអ្នកជំងឺទៅធ្វើតេស្តរកភាពស៊ាំនឹងថ្នាំ (DST) (ដូចជា GeneXpert/TrueNat រួមទាំងភាពស៊ាំនឹងថ្នាំ Rifampicin)។ ប្តូរទៅរបបព្យាបាលជំងឺរបេងស៊ាំនឹងថ្នាំ (DR-TB) បើរកឃើញភាពស៊ាំនឹងថ្នាំ។ ថ្នាំជាក់លាក់៖ អនុវត្តតាមគោលការណ៍ណែនាំជាតិស្តីពីជំងឺរបេងស៊ាំនឹងថ្នាំ (CENAT)។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03-Q01','RS-03','Results & Clinical Decision','Can Pluslife detect drug resistance?','តើ Pluslife អាចរកភាពស៊ាំនឹងថ្នាំបានទេ?','No. The MiniDock MTB Test detects Mycobacterium tuberculosis complex (MTBC) DNA (targets gyrB and IS6110); it doesn''t detect drug resistance. After a positive result, link the patient to drug-susceptibility testing (including rifampicin resistance).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03-Q02','RS-03','Results & Clinical Decision','Does the MiniDock MTB Test detect rifampicin resistance?','តើ MiniDock MTB Test រកភាពស៊ាំនឹងថ្នាំ Rifampicin បានទេ?','No. The MiniDock MTB Test detects Mycobacterium tuberculosis complex (MTBC) DNA (targets gyrB and IS6110); it doesn''t detect drug resistance. After a positive result, link the patient to drug-susceptibility testing (including rifampicin resistance).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03-Q03','RS-03','Results & Clinical Decision','Can it detect MDR-TB?','តើវាអាចរក MDR-TB បានទេ?','No. The MiniDock MTB Test detects Mycobacterium tuberculosis complex (MTBC) DNA (targets gyrB and IS6110); it doesn''t detect drug resistance. After a positive result, link the patient to drug-susceptibility testing (including rifampicin resistance).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03-Q04','RS-03','Results & Clinical Decision','pluslife RIF resistance','Pluslife អាចរកឃើញភាពស៊ាំនឹង rifampicin (RIF) ទេ?','No. The MiniDock MTB Test detects Mycobacterium tuberculosis complex (MTBC) DNA (targets gyrB and IS6110); it doesn''t detect drug resistance. After a positive result, link the patient to drug-susceptibility testing (including rifampicin resistance).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03-Q05','RS-03','Results & Clinical Decision','Does the test detect isoniazid resistance?','តើតេស្តនេះរកភាពស៊ាំនឹងថ្នាំ Isoniazid បានទេ?','No. The MiniDock MTB Test detects Mycobacterium tuberculosis complex (MTBC) DNA (targets gyrB and IS6110); it doesn''t detect drug resistance. After a positive result, link the patient to drug-susceptibility testing (including rifampicin resistance).
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03-Q06','RS-03','Results & Clinical Decision','I''m new — does a positive result tell me which drugs will work?','ខ្ញុំទើបប្រើ Pluslife។ តើលទ្ធផលវិជ្ជមាន ប្រាប់ថាថ្នាំណាមានប្រសិទ្ធភាពទេ?','No. The test only detects MTBC DNA; it doesn''t show drug resistance. Link the patient to drug-susceptibility testing (including rifampicin resistance) to guide treatment.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03-Q07','RS-03','Results & Clinical Decision','How do I check for resistance after a positive Pluslife result?','ក្រោយ Pluslife វិជ្ជមាន ធ្វើម៉េចពិនិត្យភាពស៊ាំនឹងថ្នាំ?','Link the patient to drug-susceptibility testing (including rifampicin resistance). The MiniDock MTB Test itself doesn''t detect resistance.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-03-Q08','RS-03','Results & Clinical Decision','Can Pluslife replace GeneXpert?','តើ Pluslife អាចជំនួស GeneXpert បានទេ?','Per the clinical decision guide, they''re used together: treatment can start immediately on a Pluslife positive, and GeneXpert/TrueNat provides the drug-resistance result (Pluslife doesn''t detect resistance). If GeneXpert/TrueNat shows resistance, switch to the drug-resistant TB regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-04','RS-04','Results & Clinical Decision','Worker doubts the result and wants to retest','ខ្ញុំមិនសូវទុកចិត្តលទ្ធផលនេះ។ បើចង់ធ្វើតេស្តម្តងទៀត ត្រូវធ្វើម៉េច?','The guidance doesn''t say when to repeat the test. If retesting, use a new card and a fresh sample. Result decision guide: [Result Decision Guide - Pending]; Operation procedure: [Operation Procedure Document - Pending]','ការណែនាំមិនបានបញ្ជាក់ថាពេលណាត្រូវធ្វើតេស្តឡើងវិញទេ។ បើធ្វើតេស្តឡើងវិញ សូមប្រើកាតថ្មី និងសំណាកថ្មី។ សៀវភៅណែនាំការសម្រេចលទ្ធផល (Result decision guide)៖ [ឯកសារកំពុងរៀបចំ - Pending]។ នីតិវិធីប្រតិបត្តិការ (Operation procedure)៖ [ឯកសារកំពុងរៀបចំ - Pending]','Routine','Study focal point');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-04-Q01','RS-04','Results & Clinical Decision','Can I repeat the Pluslife test if I doubt the result?','តើអាចធ្វើតេស្ត Pluslife ម្តងទៀតបានទេ បើសង្ស័យលទ្ធផល?','The guidance doesn''t say when to repeat the test. If you do retest, use a new card and a fresh sample; a used card can''t be tested again.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-04-Q02','RS-04','Results & Clinical Decision','retest pluslife same patient','អាចធ្វើតេស្ត Pluslife ម្តងទៀតលើអ្នកជំងឺដដែលបានទេ?','The guidance doesn''t say when to repeat the test. If you do retest, use a new card and a fresh sample; a used card can''t be tested again.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01','CD-01','Results & Clinical Decision','Pluslife +; GeneXpert/TrueNat TB +; drug resistance +','Pluslife និង GeneXpert ឬ Truenat សុទ្ធតែវិជ្ជមាន ហើយរកឃើញភាពស៊ាំនឹងថ្នាំ។ ត្រូវធ្វើអ្វីបន្ទាប់?','Start treatment immediately on the Pluslife result; switch to the drug-resistant TB regimen as soon as the drug-resistance-positive result is available','ចាប់ផ្តើមព្យាបាលភ្លាមៗផ្អែកលើលទ្ធផល Pluslife។ ប្តូរទៅរបបព្យាបាលជំងឺរបេងស៊ាំនឹងថ្នាំ (DR-TB) ភ្លាមៗពេលមានលទ្ធផលភាពស៊ាំនឹងថ្នាំវិជ្ជមាន។','Safety-critical','TB focal person / OD / CENAT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q01','CD-01','Results & Clinical Decision','Pluslife can''t tell me about resistance, but GeneXpert shows rifampicin resistance. What should I do?','Pluslife មិនអាចប្រាប់ពីភាពស៊ាំនឹងថ្នាំ តែ GeneXpert បង្ហាញភាពស៊ាំនឹងថ្នាំ Rifampicin។ ត្រូវធ្វើម៉េច?','Pluslife doesn''t detect drug resistance, so use the GeneXpert/TrueNat resistance result. Per the clinical decision guide: if Pluslife was positive, treatment has already started on the Pluslife result; switch to the drug-resistant TB regimen as soon as the resistance result is available. If Pluslife was negative, start drug-resistant TB treatment on the GeneXpert/TrueNat result. The guide doesn''t list specific drugs; follow your national DR-TB guidelines.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q02','CD-01','Results & Clinical Decision','pluslife no resistance info, xpert rif resistant','Pluslife គ្មានព័ត៌មានភាពស៊ាំ, Xpert ស៊ាំនឹង RIF។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Pluslife doesn''t detect drug resistance, so use the GeneXpert/TrueNat resistance result. Per the clinical decision guide: if Pluslife was positive, treatment has already started on the Pluslife result; switch to the drug-resistant TB regimen as soon as the resistance result is available. If Pluslife was negative, start drug-resistant TB treatment on the GeneXpert/TrueNat result. The guide doesn''t list specific drugs; follow your national DR-TB guidelines.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q03','CD-01','Results & Clinical Decision','Xpert detected rifampicin resistance. Can I use Pluslife to check it?','Xpert រកឃើញភាពស៊ាំនឹងថ្នាំ Rifampicin។ តើអាចប្រើ Pluslife ពិនិត្យវាបានទេ?','Pluslife doesn''t detect drug resistance, so use the GeneXpert/TrueNat resistance result. Per the clinical decision guide: if Pluslife was positive, treatment has already started on the Pluslife result; switch to the drug-resistant TB regimen as soon as the resistance result is available. If Pluslife was negative, start drug-resistant TB treatment on the GeneXpert/TrueNat result. The guide doesn''t list specific drugs; follow your national DR-TB guidelines.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q04','CD-01','Results & Clinical Decision','The patient was tested on Pluslife and GeneXpert found resistance. How should I handle it?','អ្នកជំងឺធ្វើតេស្ត Pluslife ហើយ GeneXpert រកឃើញភាពស៊ាំនឹងថ្នាំ។ គួរដោះស្រាយយ៉ាងម៉េច?','Pluslife doesn''t detect drug resistance, so use the GeneXpert/TrueNat resistance result. Per the clinical decision guide: if Pluslife was positive, treatment has already started on the Pluslife result; switch to the drug-resistant TB regimen as soon as the resistance result is available. If Pluslife was negative, start drug-resistant TB treatment on the GeneXpert/TrueNat result. The guide doesn''t list specific drugs; follow your national DR-TB guidelines.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q05','CD-01','Results & Clinical Decision','Which treatment should I start if GeneXpert shows resistance?','គួរចាប់ផ្តើមការព្យាបាលអ្វី បើ GeneXpert បង្ហាញភាពស៊ាំនឹងថ្នាំ?','Pluslife doesn''t detect drug resistance, so use the GeneXpert/TrueNat resistance result. Per the clinical decision guide: if Pluslife was positive, treatment has already started on the Pluslife result; switch to the drug-resistant TB regimen as soon as the resistance result is available. If Pluslife was negative, start drug-resistant TB treatment on the GeneXpert/TrueNat result. The guide doesn''t list specific drugs; follow your national DR-TB guidelines.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q06','CD-01','Results & Clinical Decision','Pluslife is positive and GeneXpert shows rifampicin resistance. Do the results conflict?','Pluslife វិជ្ជមាន ហើយ GeneXpert បង្ហាញភាពស៊ាំនឹងថ្នាំ Rifampicin។ តើលទ្ធផលផ្ទុយគ្នាទេ?','There''s no conflict. Pluslife shows whether MTBC DNA is detected; GeneXpert/TrueNat provides the resistance result. Per the clinical decision guide, start treatment immediately on the Pluslife result, then switch to the drug-resistant TB regimen as soon as the resistance result is available.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q07','CD-01','Results & Clinical Decision','pluslife positive xpert rif resistant','Pluslife វិជ្ជមាន Xpert ស៊ាំនឹង RIF។ តើត្រូវធ្វើអ្វីបន្ទាប់?','There''s no conflict. Pluslife shows whether MTBC DNA is detected; GeneXpert/TrueNat provides the resistance result. Per the clinical decision guide, start treatment immediately on the Pluslife result, then switch to the drug-resistant TB regimen as soon as the resistance result is available.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q08','CD-01','Results & Clinical Decision','GeneXpert says RIF resistant — what does the Pluslife result add?','GeneXpert ថាស៊ាំនឹង RIF — តើលទ្ធផល Pluslife បន្ថែមអ្វី?','There''s no conflict. Pluslife shows whether MTBC DNA is detected; GeneXpert/TrueNat provides the resistance result. Per the clinical decision guide, start treatment immediately on the Pluslife result, then switch to the drug-resistant TB regimen as soon as the resistance result is available.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q09','CD-01','Results & Clinical Decision','What is the clinical decision guide for Pluslife and GeneXpert/TrueNat results?','សៀវភៅណែនាំការសម្រេចគ្លីនិក សម្រាប់លទ្ធផល Pluslife និង GeneXpert/TrueNat យ៉ាងម៉េច?','Clinical decision guide (Pluslife / GeneXpert-TrueNat TB / GeneXpert-TrueNat drug resistance):
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q10','CD-01','Results & Clinical Decision','How do I decide on treatment using Pluslife and GeneXpert/TrueNat results?','ធ្វើម៉េចសម្រេចការព្យាបាល ដោយប្រើលទ្ធផល Pluslife និង GeneXpert/TrueNat?','Clinical decision guide (Pluslife / GeneXpert-TrueNat TB / GeneXpert-TrueNat drug resistance):
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q11','CD-01','Results & Clinical Decision','treatment decision table','មានតារាងណែនាំសម្រាប់សម្រេចពីការព្យាបាលទេ?','Clinical decision guide (Pluslife / GeneXpert-TrueNat TB / GeneXpert-TrueNat drug resistance):
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q12','CD-01','Results & Clinical Decision','I''m new — how do I combine Pluslife and GeneXpert results?','ខ្ញុំទើបប្រើ Pluslife។ ធ្វើម៉េចបញ្ចូលលទ្ធផល Pluslife និង GeneXpert ជាមួយគ្នា?','Clinical decision guide (Pluslife / GeneXpert-TrueNat TB / GeneXpert-TrueNat drug resistance):
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q13','CD-01','Results & Clinical Decision','Pluslife positive, GeneXpert positive with drug resistance. How should I treat?','Pluslife វិជ្ជមាន GeneXpert វិជ្ជមានមានភាពស៊ាំនឹងថ្នាំ។ គួរព្យាបាលយ៉ាងម៉េច?','Start treatment immediately on the Pluslife result. Switch to the drug-resistant TB regimen as soon as the GeneXpert/TrueNat drug-resistance-positive result is available.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q14','CD-01','Results & Clinical Decision','pluslife + xpert + resistant treatment','Pluslife + Xpert + ស៊ាំនឹងថ្នាំ ការព្យាបាល។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Start treatment immediately on the Pluslife result. Switch to the drug-resistant TB regimen as soon as the GeneXpert/TrueNat drug-resistance-positive result is available.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q15','CD-01','Results & Clinical Decision','Both tests detect TB and TrueNat shows resistance. What regimen?','តេស្តទាំងពីររកឃើញជំងឺរបេង ហើយ TrueNat បង្ហាញភាពស៊ាំនឹងថ្នាំ។ ប្រើរបបព្យាបាលអ្វី?','Start treatment immediately on the Pluslife result. Switch to the drug-resistant TB regimen as soon as the GeneXpert/TrueNat drug-resistance-positive result is available.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q16','CD-01','Results & Clinical Decision','When should I switch to the drug-resistant TB regimen?','ពេលណាគួរប្តូរទៅរបបព្យាបាលជំងឺរបេងស៊ាំនឹងថ្នាំ?','As soon as the GeneXpert/TrueNat drug-resistance-positive result is available.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-01-Q17','CD-01','Results & Clinical Decision','The patient is on the standard regimen and GeneXpert now shows resistance. When do I switch?','អ្នកជំងឺកំពុងប្រើរបបព្យាបាលស្តង់ដារ ហើយឥឡូវ GeneXpert បង្ហាញភាពស៊ាំនឹងថ្នាំ។ ពេលណាត្រូវប្តូរ?','As soon as the GeneXpert/TrueNat drug-resistance-positive result is available.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-02','CD-02','Results & Clinical Decision','Pluslife +; GeneXpert/TrueNat TB +; drug resistance −','Pluslife និង GeneXpert ឬ Truenat សុទ្ធតែវិជ្ជមាន ហើយរកមិនឃើញភាពស៊ាំនឹងថ្នាំ។ ត្រូវធ្វើអ្វីបន្ទាប់?','Start the standard regimen immediately on the Pluslife result','ចាប់ផ្តើមរបបព្យាបាលស្តង់ដារភ្លាមៗ ផ្អែកលើលទ្ធផល Pluslife។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-02-Q01','CD-02','Results & Clinical Decision','Pluslife and GeneXpert are both positive with no drug resistance. What treatment?','Pluslife និង GeneXpert វិជ្ជមានទាំងពីរ គ្មានភាពស៊ាំនឹងថ្នាំ។ ព្យាបាលអ្វី?','Start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-02-Q02','CD-02','Results & Clinical Decision','pluslife positive xpert positive no resistance','Pluslife វិជ្ជមាន Xpert វិជ្ជមាន គ្មានភាពស៊ាំ។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-02-Q03','CD-02','Results & Clinical Decision','Both tests positive and rifampicin-sensitive — which regimen?','តេស្តទាំងពីរចេញវិជ្ជមាន ហើយរកមិនឃើញភាពស៊ាំនឹង rifampicin។ ត្រូវប្រើរបបព្យាបាលមួយណា?','Start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03','CD-03','Results & Clinical Decision','Pluslife +; GeneXpert/TrueNat TB −; drug resistance −','Pluslife វិជ្ជមាន តែ GeneXpert ឬ Truenat អវិជ្ជមាន ហើយរកមិនឃើញភាពស៊ាំនឹងថ្នាំ។ ត្រូវធ្វើអ្វីបន្ទាប់?','Start the standard regimen immediately on the Pluslife result','ចាប់ផ្តើមរបបព្យាបាលស្តង់ដារភ្លាមៗ ផ្អែកលើលទ្ធផល Pluslife។','Safety-critical','TB focal person / OD / Study PI');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q01','CD-03','Results & Clinical Decision','Pluslife is positive but GeneXpert is negative. What should I do?','Pluslife វិជ្ជមាន តែ GeneXpert អវិជ្ជមាន។ ត្រូវធ្វើម៉េច?','Per the clinical decision guide (Pluslife +, GeneXpert/TrueNat −, no drug resistance): start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q02','CD-03','Results & Clinical Decision','Pluslife positive, Truenat negative — which result do I trust?','Pluslife វិជ្ជមាន TrueNat អវិជ្ជមាន — ជឿលទ្ធផលមួយណា?','Per the clinical decision guide, act on the Pluslife positive: when Pluslife is positive and GeneXpert/TrueNat is negative, start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q03','CD-03','Results & Clinical Decision','pluslife positive xpert negative','Pluslife វិជ្ជមាន Xpert អវិជ្ជមាន។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Per the clinical decision guide (Pluslife +, GeneXpert/TrueNat −, no drug resistance): start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q04','CD-03','Results & Clinical Decision','The MiniDock says positive but Xpert Ultra came back negative.','MiniDock ថាវិជ្ជមាន តែ Xpert Ultra ចេញអវិជ្ជមាន។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Per the clinical decision guide (Pluslife +, GeneXpert/TrueNat −, no drug resistance): start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q05','CD-03','Results & Clinical Decision','Should I start TB treatment if Pluslife is positive and Truenat is negative?','តើគួរចាប់ផ្តើមព្យាបាលជំងឺរបេង បើ Pluslife វិជ្ជមាន ហើយ TrueNat អវិជ្ជមាន?','Per the clinical decision guide (Pluslife +, GeneXpert/TrueNat −, no drug resistance): start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q06','CD-03','Results & Clinical Decision','Is a Pluslife positive a false positive if GeneXpert is negative?','តើ Pluslife វិជ្ជមាន ជាវិជ្ជមានក្លែងក្លាយ បើ GeneXpert អវិជ្ជមានមែនទេ?','Per the clinical decision guide, act on the Pluslife positive: when Pluslife is positive and GeneXpert/TrueNat is negative, start the standard treatment regimen immediately on the Pluslife result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q07','CD-03','Results & Clinical Decision','Pluslife and GeneXpert/Truenat results don''t match. How should I handle it?','លទ្ធផល Pluslife និង GeneXpert/TrueNat មិនដូចគ្នា។ គួរដោះស្រាយយ៉ាងម៉េច?','Per the clinical decision guide:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q08','CD-03','Results & Clinical Decision','discordant results pluslife xpert','លទ្ធផលមិនស៊ីគ្នា Pluslife Xpert។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Per the clinical decision guide:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-03-Q09','CD-03','Results & Clinical Decision','What if Pluslife and another molecular test give different results?','បើ Pluslife និងតេស្តម៉ូលេគុលផ្សេង ផ្តល់លទ្ធផលខុសគ្នា ធ្វើម៉េច?','Per the clinical decision guide:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-04','CD-04','Results & Clinical Decision','Pluslife −; GeneXpert/TrueNat TB −; drug resistance −','Pluslife និង GeneXpert ឬ Truenat សុទ្ធតែអវិជ្ជមាន ហើយរកមិនឃើញភាពស៊ាំនឹងថ្នាំ។ ត្រូវធ្វើអ្វីបន្ទាប់?','No treatment required','មិនតម្រូវឱ្យព្យាបាលទេ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-04-Q01','CD-04','Results & Clinical Decision','Pluslife and GeneXpert are both negative. Does the patient need treatment?','Pluslife និង GeneXpert អវិជ្ជមានទាំងពីរ។ តើអ្នកជំងឺត្រូវការព្យាបាលទេ?','No treatment required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-04-Q02','CD-04','Results & Clinical Decision','both negative pluslife xpert','អវិជ្ជមានទាំងពីរ Pluslife Xpert។ តើត្រូវធ្វើអ្វីបន្ទាប់?','No treatment required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-04-Q03','CD-04','Results & Clinical Decision','Pluslife negative and TrueNat negative — what now?','Pluslife អវិជ្ជមាន និង TrueNat អវិជ្ជមាន — ឥឡូវធ្វើម៉េច?','No treatment required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-05','CD-05','Results & Clinical Decision','Pluslife −; GeneXpert/TrueNat TB +; drug resistance −','Pluslife អវិជ្ជមាន តែ GeneXpert ឬ Truenat វិជ្ជមាន ហើយរកមិនឃើញភាពស៊ាំនឹងថ្នាំ។ ត្រូវធ្វើអ្វីបន្ទាប់?','Start standard treatment on the GeneXpert/TrueNat result','ចាប់ផ្តើមការព្យាបាលស្តង់ដារ ផ្អែកលើលទ្ធផល GeneXpert/TrueNat។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-05-Q01','CD-05','Results & Clinical Decision','Pluslife is negative but GeneXpert is positive. What now?','Pluslife អវិជ្ជមាន តែ GeneXpert វិជ្ជមាន។ ឥឡូវធ្វើម៉េច?','Per the clinical decision guide, treat based on the GeneXpert/TrueNat result: standard treatment if no drug resistance is detected, drug-resistant TB treatment if resistance is detected.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-05-Q02','CD-05','Results & Clinical Decision','pluslife negative truenat positive','Pluslife អវិជ្ជមាន TrueNat វិជ្ជមាន។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Per the clinical decision guide, treat based on the GeneXpert/TrueNat result: standard treatment if no drug resistance is detected, drug-resistant TB treatment if resistance is detected.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-05-Q03','CD-05','Results & Clinical Decision','Xpert detected TB but the MiniDock result was negative. Which is right?','Xpert រកឃើញជំងឺរបេង តែលទ្ធផល MiniDock អវិជ្ជមាន។ មួយណាត្រូវ?','Per the clinical decision guide, treat based on the GeneXpert/TrueNat result: standard treatment if no drug resistance is detected, drug-resistant TB treatment if resistance is detected.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-05-Q04','CD-05','Results & Clinical Decision','Can I rule out TB if Pluslife is negative even though Truenat is positive?','តើអាចបដិសេធជំងឺរបេងបានទេ បើ Pluslife អវិជ្ជមាន ទោះបី TrueNat វិជ្ជមាន?','No. Per the clinical decision guide, treat based on the GeneXpert/TrueNat result: standard treatment if no drug resistance is detected, drug-resistant TB treatment if resistance is detected.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-05-Q05','CD-05','Results & Clinical Decision','Pluslife negative, GeneXpert positive, no resistance. Should I treat?','Pluslife អវិជ្ជមាន GeneXpert វិជ្ជមាន គ្មានភាពស៊ាំ។ តើគួរព្យាបាលទេ?','Start standard treatment on the GeneXpert/TrueNat result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-05-Q06','CD-05','Results & Clinical Decision','pluslife negative xpert positive rif sensitive','Pluslife ចេញអវិជ្ជមាន តែ Xpert ចេញវិជ្ជមាន ហើយរកមិនឃើញភាពស៊ាំនឹង rifampicin។ ត្រូវធ្វើអ្វីបន្ទាប់?','Start standard treatment on the GeneXpert/TrueNat result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-06','CD-06','Results & Clinical Decision','Pluslife −; GeneXpert/TrueNat TB +; drug resistance +','Pluslife អវិជ្ជមាន តែ GeneXpert ឬ Truenat វិជ្ជមាន ហើយរកឃើញភាពស៊ាំនឹងថ្នាំ។ ត្រូវធ្វើអ្វីបន្ទាប់?','Start drug-resistant TB treatment on the GeneXpert/TrueNat result','ចាប់ផ្តើមព្យាបាលជំងឺរបេងស៊ាំនឹងថ្នាំ ផ្អែកលើលទ្ធផល GeneXpert/TrueNat។','Safety-critical','TB focal person / OD / CENAT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-06-Q01','CD-06','Results & Clinical Decision','Pluslife is negative but GeneXpert shows TB with rifampicin resistance. What now?','Pluslife អវិជ្ជមាន តែ GeneXpert បង្ហាញជំងឺរបេងស៊ាំនឹងថ្នាំ Rifampicin។ ឥឡូវធ្វើម៉េច?','Per the clinical decision guide (Pluslife −, GeneXpert/TrueNat + with drug resistance): start drug-resistant TB treatment on the GeneXpert/TrueNat result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-06-Q02','CD-06','Results & Clinical Decision','pluslife negative xpert rif resistant','Pluslife អវិជ្ជមាន Xpert ស៊ាំនឹង RIF។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Per the clinical decision guide (Pluslife −, GeneXpert/TrueNat + with drug resistance): start drug-resistant TB treatment on the GeneXpert/TrueNat result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07','CD-07','Results & Clinical Decision','Pluslife is positive and the worker is waiting for GeneXpert/TrueNat before starting treatment','Pluslife ចេញវិជ្ជមានហើយ តែលទ្ធផល GeneXpert ឬ Truenat មិនទាន់ចេញ។ តើត្រូវរង់ចាំមុនចាប់ផ្តើមព្យាបាលទេ?','Don''t wait: start the standard regimen immediately on the Pluslife result. GeneXpert/TrueNat is still needed for drug resistance; switch to the drug-resistant TB regimen if resistance is detected','កុំរង់ចាំ៖ ចាប់ផ្តើមរបបព្យាបាលស្តង់ដារភ្លាមៗ ផ្អែកលើលទ្ធផល Pluslife។ នៅតែត្រូវការ GeneXpert/TrueNat ដើម្បីរកភាពស៊ាំនឹងថ្នាំ។ ប្តូរទៅរបបព្យាបាលជំងឺរបេងស៊ាំនឹងថ្នាំ (DR-TB) បើរកឃើញភាពស៊ាំនឹងថ្នាំ។','Safety-critical','TB focal person / OD / Study PI');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q01','CD-07','Results & Clinical Decision','What should happen after a positive result?','ក្រោយលទ្ធផលវិជ្ជមាន ត្រូវធ្វើអ្វីបន្ត?','Start the standard treatment regimen immediately on the Pluslife result, and link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance). If resistance is found, switch to the drug-resistant TB regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q02','CD-07','Results & Clinical Decision','Do I need further testing after a Pluslife result?','តើត្រូវធ្វើតេស្តបន្ថែម ក្រោយលទ្ធផល Pluslife ទេ?','It depends on the result. Positive → start the standard treatment regimen immediately, and link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance); switch to the drug-resistant TB regimen if resistance is found. Negative → clinical assessment / follow-up; if GeneXpert/TrueNat is also negative, no treatment is required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q03','CD-07','Results & Clinical Decision','Is the Pluslife result final, or do I need more tests?','តើលទ្ធផល Pluslife ជាលទ្ធផលចុងក្រោយ ឬត្រូវការតេស្តបន្ថែម?','It depends on the result. Positive → start the standard treatment regimen immediately, and link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance); switch to the drug-resistant TB regimen if resistance is found. Negative → clinical assessment / follow-up; if GeneXpert/TrueNat is also negative, no treatment is required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q04','CD-07','Results & Clinical Decision','after pluslife result, next test?','ក្រោយលទ្ធផល Pluslife តេស្តបន្ទាប់?','It depends on the result. Positive → start the standard treatment regimen immediately, and link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance); switch to the drug-resistant TB regimen if resistance is found. Negative → clinical assessment / follow-up; if GeneXpert/TrueNat is also negative, no treatment is required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q05','CD-07','Results & Clinical Decision','I''m new — what happens after I get the Pluslife result?','ខ្ញុំទើបប្រើ Pluslife។ ក្រោយទទួលលទ្ធផល Pluslife ត្រូវធ្វើអ្វី?','It depends on the result. Positive → start the standard treatment regimen immediately, and link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance); switch to the drug-resistant TB regimen if resistance is found. Negative → clinical assessment / follow-up; if GeneXpert/TrueNat is also negative, no treatment is required.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q06','CD-07','Results & Clinical Decision','Pluslife is positive — do I need any further tests?','Pluslife វិជ្ជមាន — តើត្រូវធ្វើតេស្តបន្ថែមទេ?','Yes, for drug resistance. Start the standard treatment regimen immediately on the Pluslife result, and link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance). If resistance is found, switch to the drug-resistant TB regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q07','CD-07','Results & Clinical Decision','Do I need drug-susceptibility testing after a positive Pluslife result?','តើត្រូវធ្វើតេស្តរកភាពស៊ាំនឹងថ្នាំ (DST) ក្រោយ Pluslife វិជ្ជមានទេ?','Yes, for drug resistance. Start the standard treatment regimen immediately on the Pluslife result, and link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance). If resistance is found, switch to the drug-resistant TB regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q08','CD-07','Results & Clinical Decision','pluslife positive next step','Pluslife វិជ្ជមាន ជំហានបន្ទាប់។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Yes, for drug resistance. Start the standard treatment regimen immediately on the Pluslife result, and link the patient to drug-susceptibility testing (such as GeneXpert/TrueNat, including rifampicin resistance). If resistance is found, switch to the drug-resistant TB regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q09','CD-07','Results & Clinical Decision','Do I need to confirm a Pluslife positive with GeneXpert?','តើត្រូវបញ្ជាក់ Pluslife វិជ្ជមាន ដោយ GeneXpert ទេ?','Per the clinical decision guide, you don''t need to wait for it to start treatment: standard treatment starts immediately on a Pluslife positive, even if GeneXpert/TrueNat is negative. GeneXpert/TrueNat provides the drug-resistance result; if resistance is detected, switch to the drug-resistant TB regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q10','CD-07','Results & Clinical Decision','Should a positive MiniDock result be confirmed by Xpert or Truenat?','តើលទ្ធផល MiniDock វិជ្ជមាន គួរបញ្ជាក់ដោយ Xpert ឬ TrueNat ទេ?','Per the clinical decision guide, you don''t need to wait for it to start treatment: standard treatment starts immediately on a Pluslife positive, even if GeneXpert/TrueNat is negative. GeneXpert/TrueNat provides the drug-resistance result; if resistance is detected, switch to the drug-resistant TB regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q11','CD-07','Results & Clinical Decision','Should I wait for the GeneXpert/TrueNat result before starting treatment?','តើគួររង់ចាំលទ្ធផល GeneXpert/TrueNat មុនចាប់ផ្តើមព្យាបាលទេ?','No, not if Pluslife is positive. Start the standard regimen immediately on the Pluslife result. If GeneXpert/TrueNat later shows drug resistance, switch to the drug-resistant TB regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q12','CD-07','Results & Clinical Decision','Can I start TB treatment based on a positive Pluslife result alone?','តើអាចចាប់ផ្តើមព្យាបាលជំងឺរបេង ផ្អែកតែលើលទ្ធផល Pluslife វិជ្ជមានបានទេ?','Yes. Per the clinical decision guide, a positive Pluslife result is enough to start the standard regimen immediately, even if GeneXpert/TrueNat is negative. Switch to the drug-resistant TB regimen if GeneXpert/TrueNat shows resistance.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q13','CD-07','Results & Clinical Decision','When should treatment start after a positive Pluslife result?','ក្រោយ Pluslife វិជ្ជមាន ពេលណាគួរចាប់ផ្តើមព្យាបាល?','Immediately on the Pluslife result, with the standard regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q14','CD-07','Results & Clinical Decision','treatment timing pluslife positive','ពេលចាប់ផ្តើមព្យាបាល Pluslife វិជ្ជមាន។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Immediately on the Pluslife result, with the standard regimen.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q15','CD-07','Results & Clinical Decision','Which regimen do I start on a positive Pluslife result?','ចាប់ផ្តើមរបបព្យាបាលអ្វី ពេល Pluslife វិជ្ជមាន?','The standard regimen. Switch to the drug-resistant TB regimen if GeneXpert/TrueNat shows drug resistance.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q16','CD-07','Results & Clinical Decision','Is GeneXpert/TrueNat still needed if Pluslife is positive?','តើនៅតែត្រូវការ GeneXpert/TrueNat ទេ បើ Pluslife វិជ្ជមាន?','Yes, for drug resistance. Pluslife doesn''t detect resistance. Treatment starts on the Pluslife result, and the regimen is switched to the drug-resistant TB regimen if GeneXpert/TrueNat shows resistance.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CD-07-Q17','CD-07','Results & Clinical Decision','Do I still send a sample for GeneXpert after a positive Pluslife result?','តើនៅតែបញ្ជូនសំណាកទៅ GeneXpert ក្រោយ Pluslife វិជ្ជមានទេ?','Yes, for drug resistance. Pluslife doesn''t detect resistance. Treatment starts on the Pluslife result, and the regimen is switched to the drug-resistant TB regimen if GeneXpert/TrueNat shows resistance.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01','IT-01','Installation/Setup','PluslifePad software fails to run or install correctly','ខ្ញុំដំឡើង PluslifePad មិនបាន ឬដំឡើងហើយបើកមិនចេញ។ ត្រូវពិនិត្យអ្វីខ្លះ?','Install the Microsoft C++ runtime library as prompted during PluslifePad setup','ដំឡើង Microsoft C++ runtime library តាមការណែនាំ ពេលដំឡើង PluslifePad។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q01','IT-01','Installation/Setup','PluslifePad won''t open.','PluslifePad បើកមិនឡើង។ ត្រូវធ្វើម៉េច?','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q02','IT-01','Installation/Setup','The software installation keeps failing.','ការដំឡើងកម្មវិធីបរាជ័យរហូត។ ត្រូវធ្វើម៉េច?','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q03','IT-01','Installation/Setup','Do I need any extra components to install PluslifePad?','តើត្រូវការធាតុបន្ថែមអ្វី ដើម្បីដំឡើង PluslifePad ទេ?','Yes. PluslifePad needs the Microsoft C++ runtime library. Install it when setup prompts you.','បាទ/ចាស។ PluslifePad ត្រូវការ Microsoft C++ runtime library។ ដំឡើងវាពេលកម្មវិធីដំឡើងសួរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q04','IT-01','Installation/Setup','C++ runtime','តើត្រូវដំឡើង Microsoft C++ runtime ទើបអាចបើក PluslifePad បានមែនទេ?','Install the Microsoft C++ runtime library (offered during PluslifePad setup), then try again.','ដំឡើង Microsoft C++ runtime library (ត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q05','IT-01','Installation/Setup','I installed the software but nothing happens when I double-click it.','ខ្ញុំដំឡើងកម្មវិធីហើយ តែចុចពីរដងគ្មានអ្វីកើតឡើងសោះ។ ត្រូវធ្វើម៉េច?','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q06','IT-01','Installation/Setup','The software crashes on launch on Windows.','កម្មវិធីគាំងពេលបើកលើ Windows។ ត្រូវធ្វើម៉េច?','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q07','IT-01','Installation/Setup','The installer asks for Microsoft C++ — do I need it?','កម្មវិធីដំឡើងសួររក Microsoft C++ — តើត្រូវការវាទេ?','Yes. PluslifePad needs the Microsoft C++ runtime library. Install it when setup prompts you.','បាទ/ចាស។ PluslifePad ត្រូវការ Microsoft C++ runtime library។ ដំឡើងវាពេលកម្មវិធីដំឡើងសួរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q08','IT-01','Installation/Setup','pluslifepad install error','កំហុសដំឡើង PluslifePad','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q09','IT-01','Installation/Setup','Which runtime library does PluslifePad need?','PluslifePad ត្រូវការ runtime library មួយណា?','The Microsoft C++ runtime library.','Microsoft C++ runtime library។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q10','IT-01','Installation/Setup','How do I install the Microsoft C++ runtime library?','ធ្វើម៉េចដំឡើង Microsoft C++ runtime library?','Install it when prompted during PluslifePad setup.','ដំឡើងវាពេលមានការសួរ ក្នុងពេលដំឡើង PluslifePad។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q11','IT-01','Installation/Setup','PluslifePad not launching.','PluslifePad មិនបើក។ ត្រូវធ្វើម៉េច?','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q12','IT-01','Installation/Setup','I''m new — what do I need to install before PluslifePad works?','ខ្ញុំទើបប្រើ Pluslife។ ត្រូវដំឡើងអ្វីខ្លះ មុន PluslifePad ដំណើរការ?','The Microsoft C++ runtime library. It''s installed as part of PluslifePad setup.','Microsoft C++ runtime library។ វាត្រូវបានដំឡើងជាផ្នែកមួយនៃការដំឡើង PluslifePad។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q13','IT-01','Installation/Setup','Is the Visual C++ redistributable required?','តើត្រូវការ Visual C++ redistributable ទេ?','Yes. PluslifePad needs the Microsoft C++ runtime library. Install it when setup prompts you.','បាទ/ចាស។ PluslifePad ត្រូវការ Microsoft C++ runtime library។ ដំឡើងវាពេលកម្មវិធីដំឡើងសួរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q14','IT-01','Installation/Setup','Setup finished but the app won''t open.','ដំឡើងរួច តែ កម្មវិធី បើកមិនឡើង។ ត្រូវធ្វើម៉េច?','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q15','IT-01','Installation/Setup','software no open after install','កម្មវិធីមិនបើក ក្រោយដំឡើង','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q16','IT-01','Installation/Setup','So I should install the C++ runtime when the setup prompts me?','មានន័យថា ខ្ញុំគួរដំឡើង C++ runtime ពេលកម្មវិធីដំឡើងសួរ?','Yes. PluslifePad needs the Microsoft C++ runtime library. Install it when setup prompts you.','បាទ/ចាស។ PluslifePad ត្រូវការ Microsoft C++ runtime library។ ដំឡើងវាពេលកម្មវិធីដំឡើងសួរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q17','IT-01','Installation/Setup','PluslifePad won''t run on my computer.','PluslifePad មិនដំណើរការលើកុំព្យូទ័រខ្ញុំ។ ត្រូវធ្វើម៉េច?','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q18','IT-01','Installation/Setup','What should I install if PluslifePad fails to launch?','គួរដំឡើងអ្វី បើ PluslifePad បើកមិនឡើង?','The Microsoft C++ runtime library.','Microsoft C++ runtime library។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q19','IT-01','Installation/Setup','Do I need the Microsoft C++ runtime for PluslifePad?','តើ PluslifePad ត្រូវការ Microsoft C++ runtime ទេ?','Yes. PluslifePad needs the Microsoft C++ runtime library. Install it when setup prompts you.','បាទ/ចាស។ PluslifePad ត្រូវការ Microsoft C++ runtime library។ ដំឡើងវាពេលកម្មវិធីដំឡើងសួរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-01-Q20','IT-01','Installation/Setup','PluslifePad setup failed','ការដំឡើង PluslifePad បរាជ័យ','The documented fix is the Microsoft C++ runtime library: make sure it''s installed (it''s offered during PluslifePad setup), then try again. If that doesn''t help, please contact Pluslife support.','ដំណោះស្រាយដែលមានក្នុងឯកសារ គឺ Microsoft C++ runtime library៖ ធ្វើឱ្យប្រាកដថាវាត្រូវបានដំឡើង (វាត្រូវបានផ្តល់ជូនពេលដំឡើង PluslifePad) រួចសាកល្បងម្តងទៀត។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-02','IT-02','Installation/Setup','Installing PluslifePad for the first time','ខ្ញុំទើបប្រើ PluslifePad លើកដំបូង។ ត្រូវដំឡើងដោយរបៀបណា?','1) Download and extract the PluslifePad package. 2) Double-click PluslifePad.exe. 3) Choose English and accept the agreement. 4) Click Next through setup. 5) Install the Microsoft C++ runtime library. 6) Install the remote assistant software if possible','១) ទាញយក ហើយពន្លា (extract) កញ្ចប់ PluslifePad។ ២) ចុចពីរដងលើ PluslifePad.exe។ ៣) ជ្រើសរើសភាសាអង់គ្លេស ហើយយល់ព្រមលើកិច្ចព្រមព្រៀង។ ៤) ចុច Next រហូតដល់ចប់។ ៥) ដំឡើង Microsoft C++ runtime library។ ៦) ដំឡើងកម្មវិធីជំនួយពីចម្ងាយ (remote assistant) បើអាចធ្វើបាន។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-02-Q01','IT-02','Installation/Setup','How do I install PluslifePad without errors?','ធ្វើម៉េចដំឡើង PluslifePad ដោយគ្មានកំហុស?','1) Download and extract the PluslifePad package.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-02-Q02','IT-02','Installation/Setup','How do I install PluslifePad?','ធ្វើម៉េចដំឡើង PluslifePad?','1) Download and extract the PluslifePad package.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-02-Q03','IT-02','Installation/Setup','What are the installation steps for the software?','ជំហានដំឡើងកម្មវិធីមានអ្វីខ្លះ?','1) Download and extract the PluslifePad package.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-02-Q04','IT-02','Installation/Setup','Which file do I run to install PluslifePad?','ត្រូវបើកឯកសារមួយណា ដើម្បីដំឡើង PluslifePad?','PluslifePad.exe (after extracting the downloaded package).','PluslifePad.exe (ក្រោយពន្លាកញ្ចប់ដែលបានទាញយក)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-02-Q05','IT-02','Installation/Setup','What language should I choose during setup?','គួរជ្រើសភាសាអ្វី ពេលដំឡើង?','English.','ភាសាអង់គ្លេស (English)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-02-Q06','IT-02','Installation/Setup','Do I need to install the remote assistant software?','តើត្រូវដំឡើងកម្មវិធីជំនួយពីចម្ងាយ (remote assistant) ទេ?','Yes, if possible. It''s the last step of setup.','បាទ/ចាស បើអាចធ្វើបាន។ វាជាជំហានចុងក្រោយនៃការដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-02-Q07','IT-02','Installation/Setup','software installation','ការដំឡើងកម្មវិធី','1) Download and extract the PluslifePad package.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-03','IT-03','Installation/Setup','PluslifePad still won''t open after the Microsoft C++ runtime library is installed','ខ្ញុំដំឡើង Microsoft C++ runtime រួចហើយ តែ PluslifePad នៅតែបើកមិនចេញ។ ត្រូវធ្វើម៉េច?','Contact Pluslife support','សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ Pluslife support។','Routine','Supervisor → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-04','IT-04','Installation/Setup','Need to reconnect a device, view its details, set up WiFi, update firmware or delete history in the software','ក្នុង PluslifePad ត្រូវចូលម៉ឺនុយណា ដើម្បីភ្ជាប់ម៉ាស៊ីនវិញ មើលព័ត៌មានម៉ាស៊ីន កំណត់ Wi‑Fi អាប់ដេត firmware ឬលុបប្រវត្តិ?','Use the device card in PluslifePad: delete the device to reconnect it, update firmware ("Arrow of Update" icon), view details, set up WiFi, delete history results (history can also be deleted in the app)','ប្រើកាតឧបករណ៍ (device card) ក្នុង PluslifePad៖ លុបឧបករណ៍ដើម្បីភ្ជាប់ឡើងវិញ ធ្វើបច្ចុប្បន្នភាព Firmware (រូបព្រួញ "Arrow of Update") មើលព័ត៌មានលម្អិត កំណត់ WiFi លុបលទ្ធផលចាស់ (ក៏អាចលុបក្នុង App បានដែរ)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-04-Q01','IT-04','Installation/Setup','What can I do from the device card in PluslifePad?','អាចធ្វើអ្វីខ្លះពី device card ក្នុង PluslifePad?','From the device card you can: delete the device to reconnect it, update its firmware, view its details, set up WiFi, and delete history results.','ពីកាតឧបករណ៍ (device card) អ្នកអាច៖ លុបឧបករណ៍ដើម្បីភ្ជាប់ឡើងវិញ ធ្វើបច្ចុប្បន្នភាព Firmware មើលព័ត៌មានលម្អិត កំណត់ WiFi និងលុបលទ្ធផលចាស់។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-04-Q02','IT-04','Installation/Setup','How do I reconnect a device in the software?','ធ្វើម៉េចភ្ជាប់ម៉ាស៊ីនឡើងវិញក្នុងកម្មវិធី?','Delete the device from the device card in PluslifePad, then reconnect it.','លុបឧបករណ៍ពីកាតឧបករណ៍ (device card) ក្នុង PluslifePad រួចភ្ជាប់វាឡើងវិញ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-04-Q03','IT-04','Installation/Setup','How do I see device details in the software?','ធ្វើម៉េចមើលព័ត៌មានលម្អិតម៉ាស៊ីនក្នុងកម្មវិធី?','On the device card in PluslifePad.','នៅលើកាតឧបករណ៍ (device card) ក្នុង PluslifePad។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-04-Q04','IT-04','Installation/Setup','Where do I set up WiFi in the software?','កំណត់ Wi‑Fi នៅឯណាក្នុងកម្មវិធី?','On the device card in PluslifePad.','នៅលើកាតឧបករណ៍ (device card) ក្នុង PluslifePad។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-04-Q05','IT-04','Installation/Setup','device settings in software','ការកំណត់ម៉ាស៊ីនក្នុងកម្មវិធី','From the device card you can: delete the device to reconnect it, update its firmware, view its details, set up WiFi, and delete history results.','ពីកាតឧបករណ៍ (device card) អ្នកអាច៖ លុបឧបករណ៍ដើម្បីភ្ជាប់ឡើងវិញ ធ្វើបច្ចុប្បន្នភាព Firmware មើលព័ត៌មានលម្អិត កំណត់ WiFi និងលុបលទ្ធផលចាស់។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01','DM-01','Data & Device Management','Device or app reports storage full or history hard to manage','ម៉ាស៊ីន ឬកម្មវិធីប្រាប់ថាកន្លែងផ្ទុកពេញ ឬប្រវត្តិលទ្ធផលច្រើនពិបាករក។ ត្រូវធ្វើម៉េច?','Clear historical data periodically via the software or app once no longer needed','លុបទិន្នន័យចាស់ជាប្រចាំ តាមកម្មវិធី ឬ App ពេលលែងត្រូវការ។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q01','DM-01','Data & Device Management','I''m getting a storage full message.','ខ្ញុំទទួលសារថាពេញទំហំផ្ទុក។ ត្រូវធ្វើម៉េច?','Clear historical data you no longer need, in the software or the app.','លុបទិន្នន័យចាស់ដែលអ្នកលែងត្រូវការ ក្នុងកម្មវិធី ឬ App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q02','DM-01','Data & Device Management','How do I delete old test records?','ធ្វើម៉េចលុបកំណត់ត្រាតេស្តចាស់?','Delete history results from the device card in the software, or in the app.','លុបលទ្ធផលចាស់ពីកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី ឬក្នុង App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q03','DM-01','Data & Device Management','New results aren''t saving.','លទ្ធផលថ្មីមិន save។ ត្រូវធ្វើម៉េច?','The device may be at its storage limit. Clear historical data you no longer need, in the software or the app.','ម៉ាស៊ីនប្រហែលជាពេញទំហំផ្ទុកហើយ។ លុបទិន្នន័យចាស់ដែលអ្នកលែងត្រូវការ ក្នុងកម្មវិធី ឬ App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q04','DM-01','Data & Device Management','How often should I clear historical data?','គួរលុបទិន្នន័យចាស់ញឹកញាប់ប៉ុណ្ណា?','There''s no fixed schedule. Clear historical data periodically, once it''s no longer needed.','គ្មានកាលវិភាគជាក់លាក់ទេ។ លុបទិន្នន័យចាស់ជាប្រចាំ ពេលលែងត្រូវការ។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q05','DM-01','Data & Device Management','device memory full','memory ម៉ាស៊ីនពេញ','Clear historical data you no longer need, in the software or the app.','លុបទិន្នន័យចាស់ដែលអ្នកលែងត្រូវការ ក្នុងកម្មវិធី ឬ App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q06','DM-01','Data & Device Management','Can I clear history from the app as well as the software?','តើអាចលុបប្រវត្តិពី កម្មវិធី ក៏ដូចពីកម្មវិធីដែរទេ?','Yes. History can be cleared from both the software and the app.','បាទ/ចាស។ អាចលុបប្រវត្តិទាំងពីកម្មវិធី និងពី App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q07','DM-01','Data & Device Management','Storage full.','ពេញទំហំផ្ទុក។ ត្រូវធ្វើម៉េច?','Clear historical data you no longer need, in the software or the app.','លុបទិន្នន័យចាស់ដែលអ្នកលែងត្រូវការ ក្នុងកម្មវិធី ឬ App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q08','DM-01','Data & Device Management','How do I avoid running out of storage?','ធ្វើម៉េចកុំឱ្យអស់ទំហំផ្ទុក?','Clear historical data periodically in the software or app.','លុបទិន្នន័យចាស់ជាប្រចាំ ក្នុងកម្មវិធី ឬ App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q09','DM-01','Data & Device Management','The history list is huge and hard to manage.','បញ្ជីប្រវត្តិច្រើនពេក ពិបាកគ្រប់គ្រង។ ត្រូវធ្វើម៉េច?','Clear historical data you no longer need, in the software or the app.','លុបទិន្នន័យចាស់ដែលអ្នកលែងត្រូវការ ក្នុងកម្មវិធី ឬ App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q10','DM-01','Data & Device Management','Results stopped saving after a lot of tests. What should I do?','លទ្ធផលឈប់ save ក្រោយធ្វើតេស្តច្រើន។ ត្រូវធ្វើម៉េច?','The device may be at its storage limit. Clear historical data you no longer need, in the software or the app.','ម៉ាស៊ីនប្រហែលជាពេញទំហំផ្ទុកហើយ។ លុបទិន្នន័យចាស់ដែលអ្នកលែងត្រូវការ ក្នុងកម្មវិធី ឬ App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q11','DM-01','Data & Device Management','How do I clear the device''s test history?','ធ្វើម៉េចលុបប្រវត្តិតេស្តរបស់ម៉ាស៊ីន?','Delete history results from the device card in the software, or in the app.','លុបលទ្ធផលចាស់ពីកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី ឬក្នុង App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q12','DM-01','Data & Device Management','Can I delete old results from the device?','តើអាចលុបលទ្ធផលចាស់ពីម៉ាស៊ីនបានទេ?','Yes. Delete history results from the device card in the software, or in the app.','បាទ/ចាស។ លុបលទ្ធផលចាស់ពីកាតឧបករណ៍ (device card) ក្នុងកម្មវិធី ឬក្នុង App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q13','DM-01','Data & Device Management','The device storage is full. What should I do?','ទំហំផ្ទុកម៉ាស៊ីនពេញ។ ត្រូវធ្វើម៉េច?','Clear historical data you no longer need, in the software or the app.','លុបទិន្នន័យចាស់ដែលអ្នកលែងត្រូវការ ក្នុងកម្មវិធី ឬ App។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-01-Q14','DM-01','Data & Device Management','Should I clear historical data regularly?','តើគួរលុបទិន្នន័យចាស់ជាប្រចាំទេ?','Yes. Clear historical data periodically once it''s no longer needed.','បាទ/ចាស។ លុបទិន្នន័យចាស់ជាប្រចាំ ពេលលែងត្រូវការ។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02','DM-02','Data & Device Management','Only some devices respond when multiple MiniDocks are connected to one PC','ខ្ញុំភ្ជាប់ MiniDock ច្រើនទៅកុំព្យូទ័រតែមួយ តែកម្មវិធីស្គាល់តែម៉ាស៊ីនខ្លះ។ ត្រូវធ្វើម៉េច?','Use no more than 15 devices per PC via the 5-port hub, with correct 110-240V/50Hz power supply','ប្រើមិនលើស ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz ត្រឹមត្រូវ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q01','DM-02','Data & Device Management','How many devices can one PC control?','កុំព្យូទ័រមួយ គ្រប់គ្រងម៉ាស៊ីនបានប៉ុន្មាន?','Up to 15 devices per PC.','រហូតដល់ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q02','DM-02','Data & Device Management','Only some of my MiniDocks respond.','MiniDock របស់ខ្ញុំខ្លះប៉ុណ្ណោះដែលឆ្លើយតប។ ត្រូវធ្វើម៉េច?','Check that no more than 15 devices are on one PC, connected via the 5-port hub, with a 110-240V/50Hz power supply.','ពិនិត្យថាមិនលើស ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ ភ្ជាប់តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q03','DM-02','Data & Device Management','Can I connect 20 devices to one computer?','តើអាចភ្ជាប់ម៉ាស៊ីន ២០ ទៅកុំព្យូទ័រមួយបានទេ?','No. One PC can control up to 15 devices.','មិនបានទេ។ កុំព្យូទ័រមួយ គ្រប់គ្រងបានរហូតដល់ ១៥ ម៉ាស៊ីន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q04','DM-02','Data & Device Management','multiple devices one PC','ម៉ាស៊ីនច្រើន កុំព្យូទ័រមួយ','Connect up to 15 devices per PC via the 5-port hub, with a 110-240V/50Hz power supply.','ភ្ជាប់រហូតដល់ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q05','DM-02','Data & Device Management','We connected a lot of devices to one PC and some stopped responding.','យើងភ្ជាប់ម៉ាស៊ីនច្រើនទៅកុំព្យូទ័រមួយ ហើយខ្លះឈប់ឆ្លើយតប។ ត្រូវធ្វើម៉េច?','Check that no more than 15 devices are on one PC, connected via the 5-port hub, with a 110-240V/50Hz power supply.','ពិនិត្យថាមិនលើស ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ ភ្ជាប់តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q06','DM-02','Data & Device Management','Some devices aren''t showing up in the software.','ម៉ាស៊ីនខ្លះមិនបង្ហាញក្នុងកម្មវិធី។ ត្រូវធ្វើម៉េច?','Check that no more than 15 devices are on one PC, connected via the 5-port hub, with a 110-240V/50Hz power supply.','ពិនិត្យថាមិនលើស ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ ភ្ជាប់តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q07','DM-02','Data & Device Management','What hub do I need to run several devices?','ត្រូវការ Hub អ្វី ដើម្បីដំណើរការម៉ាស៊ីនច្រើន?','A 5-port hub.','Hub ៥ រន្ធ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q08','DM-02','Data & Device Management','max devices per pc','ម៉ាស៊ីនច្រើនបំផុតក្នុងកុំព្យូទ័រមួយ','Up to 15 devices per PC.','រហូតដល់ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q09','DM-02','Data & Device Management','What power supply is needed for a multi-device setup?','ត្រូវការប្រភពភ្លើងអ្វី សម្រាប់ម៉ាស៊ីនច្រើន?','110-240V / 50Hz.','110-240V / 50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q10','DM-02','Data & Device Management','How do I set up multiple MiniDocks on one computer?','ធ្វើម៉េចរៀបចំ MiniDock ច្រើនលើកុំព្យូទ័រមួយ?','Connect up to 15 devices per PC via the 5-port hub, with a 110-240V/50Hz power supply.','ភ្ជាប់រហូតដល់ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q11','DM-02','Data & Device Management','Multiple MiniDocks not responding.','MiniDock ច្រើនមិនឆ្លើយតប។ ត្រូវធ្វើម៉េច?','Check that no more than 15 devices are on one PC, connected via the 5-port hub, with a 110-240V/50Hz power supply.','ពិនិត្យថាមិនលើស ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ ភ្ជាប់តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q12','DM-02','Data & Device Management','How do I set up many devices without connection issues?','ធ្វើម៉េចរៀបចំម៉ាស៊ីនច្រើន ដោយគ្មានបញ្ហាការតភ្ជាប់?','Connect up to 15 devices per PC via the 5-port hub, with a 110-240V/50Hz power supply.','ភ្ជាប់រហូតដល់ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q13','DM-02','Data & Device Management','I''m new — what''s the maximum number of devices per computer?','ខ្ញុំទើបប្រើ Pluslife។ ចំនួនម៉ាស៊ីនច្រើនបំផុតក្នុងកុំព្យូទ័រមួយគឺប៉ុន្មាន?','Up to 15 devices per PC.','រហូតដល់ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q14','DM-02','Data & Device Management','How many units can I daisy-chain to one PC?','អាចភ្ជាប់ម៉ាស៊ីនជាខ្សែសង្វាក់ទៅកុំព្យូទ័រមួយបានប៉ុន្មាន?','Up to 15 devices per PC.','រហូតដល់ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q15','DM-02','Data & Device Management','Some of the connected devices aren''t controllable.','ម៉ាស៊ីនខ្លះដែលបានភ្ជាប់ មិនអាចបញ្ជាបាន។ ត្រូវធ្វើម៉េច?','Check that no more than 15 devices are on one PC, connected via the 5-port hub, with a 110-240V/50Hz power supply.','ពិនិត្យថាមិនលើស ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ ភ្ជាប់តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q16','DM-02','Data & Device Management','many device one computer, some no work','ម៉ាស៊ីនច្រើន កុំព្យូទ័រមួយ ខ្លះមិនដើរ','Check that no more than 15 devices are on one PC, connected via the 5-port hub, with a 110-240V/50Hz power supply.','ពិនិត្យថាមិនលើស ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ ភ្ជាប់តាម Hub ៥ រន្ធ ជាមួយភ្លើង 110-240V/50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q17','DM-02','Data & Device Management','I have 18 devices on one PC and a few won''t respond. Is that too many?','ខ្ញុំមានម៉ាស៊ីន ១៨ លើកុំព្យូទ័រមួយ ហើយខ្លះមិនឆ្លើយតប។ តើច្រើនពេកទេ?','Yes. The limit is 15 devices per PC.','បាទ/ចាស។ ដែនកំណត់គឺ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q18','DM-02','Data & Device Management','So the limit is 15 devices per PC using the 5-port hub?','មានន័យថា ដែនកំណត់គឺ ១៥ ម៉ាស៊ីនក្នុងកុំព្យូទ័រមួយ ដោយប្រើ Hub ៥ រន្ធ?','Yes. Up to 15 devices per PC, via the 5-port hub.','បាទ/ចាស។ រហូតដល់ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ តាម Hub ៥ រន្ធ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q19','DM-02','Data & Device Management','Is there a limit on devices per computer?','តើមានដែនកំណត់ម៉ាស៊ីនក្នុងកុំព្យូទ័រមួយទេ?','Yes. The limit is 15 devices per PC.','បាទ/ចាស។ ដែនកំណត់គឺ ១៥ ម៉ាស៊ីន ក្នុងកុំព្យូទ័រមួយ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-02-Q20','DM-02','Data & Device Management','What voltage does the multi-device setup need?','ការរៀបចំម៉ាស៊ីនច្រើនត្រូវការតង់ស្យុងប៉ុន្មាន?','110-240V / 50Hz.','110-240V / 50Hz។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01','MT-01','Maintenance','Device needs cleaning after testing, or the card leaked / liquid is left inside','ធ្វើតេស្តរួច ត្រូវសម្អាតម៉ាស៊ីនដោយរបៀបណា? បើកាតលេចទឹក ឬមានទឹកនៅក្នុងម៉ាស៊ីន ត្រូវធ្វើម៉េច?','1) Turn off the device and remove the card; check for leaks or liquid inside. 2) Wipe the surface, power button, inside of the lid and outside of the reaction module with a soft, lint-free cloth moistened with neutral detergent or 75% alcohol. 3) Dry with a dry cloth. 4) UV-disinfect the surface for more than 30 minutes. Video: https://www.youtube.com/watch?v=aiZtZ1tIBig','១) បិទម៉ាស៊ីន ហើយដកកាតចេញ។ ពិនិត្យមើលការលេចធ្លាយ ឬទឹកនៅខាងក្នុង។ ២) ជូតផ្ទៃខាងក្រៅ ប៊ូតុងបើក/បិទ ខាងក្នុងគម្រប និងខាងក្រៅម៉ូឌុលប្រតិកម្ម ដោយក្រណាត់ទន់ គ្មានរោម ជ្រលក់សាប៊ូអព្យាក្រឹត (neutral detergent) ឬអាល់កុល 75%។ ៣) ជូតឱ្យស្ងួតដោយក្រណាត់ស្ងួត។ ៤) សម្លាប់មេរោគផ្ទៃដោយកាំរស្មី UV លើសពី ៣០ នាទី។ វីដេអូថែទាំប្រចាំថ្ងៃ៖ https://www.youtube.com/watch?v=aiZtZ1tIBig','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q01','MT-01','Maintenance','How do I clean the device?','ធ្វើម៉េចសម្អាតម៉ាស៊ីន?','1) Turn off the device and remove the card; check whether the card is leaking or liquid is left inside.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q02','MT-01','Maintenance','What should I use to wipe the device?','គួរប្រើអ្វីជូតម៉ាស៊ីន?','A soft, lint-free cloth moistened with neutral detergent or 75% alcohol, then dry with a dry cloth.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q03','MT-01','Maintenance','Can I use alcohol to clean the MiniDock?','តើអាចប្រើអាល់កុលសម្អាត MiniDock បានទេ?','Yes. Use a soft, lint-free cloth moistened with 75% alcohol (or neutral detergent), then dry it.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q04','MT-01','Maintenance','What daily maintenance does the device need?','ម៉ាស៊ីនត្រូវការការថែទាំប្រចាំថ្ងៃអ្វីខ្លះ?','1) Turn off the device and remove the card; check whether the card is leaking or liquid is left inside.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q05','MT-01','Maintenance','How do I disinfect the device?','ធ្វើម៉េចសម្លាប់មេរោគម៉ាស៊ីន?','Wipe with 75% alcohol, then UV-disinfect the surface for more than 30 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q06','MT-01','Maintenance','How long should UV disinfection take?','ការសម្លាប់មេរោគដោយ UV ត្រូវចំណាយពេលប៉ុន្មាន?','More than 30 minutes.','លើសពី ៣០ នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q07','MT-01','Maintenance','What should I check inside the device after testing?','ក្រោយធ្វើតេស្ត ត្រូវពិនិត្យអ្វីខាងក្នុងម៉ាស៊ីន?','Whether the card is leaking, and whether any liquid is left inside the instrument.','ថាតើកាតលេចធ្លាយ និងថាតើមានទឹកនៅសល់ខាងក្នុងម៉ាស៊ីនឬអត់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q08','MT-01','Maintenance','daily maintenance','ការថែទាំប្រចាំថ្ងៃ','1) Turn off the device and remove the card; check whether the card is leaking or liquid is left inside.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-01-Q09','MT-01','Maintenance','Which parts of the device should I wipe?','ត្រូវជូតផ្នែកណាខ្លះនៃម៉ាស៊ីន?','The surface, the power button, the inside of the lid, and the outside of the reaction module.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01','PI-01','Product Information','Worker asks what the test detects or which technology it uses','តេស្ត Pluslife រកឃើញអ្វី ហើយប្រើបច្ចេកវិទ្យាអ្វី?','Detects Mycobacterium tuberculosis complex (MTBC) DNA. Targets gyrB and IS6110 (wells 1-3 and 5-7); well 4 is the internal control; the card has 7 wells. Technology: RHAM (RNase Hybridization-Assisted aMplification), a one-step isothermal method, extraction-free, not PCR','រកឃើញ DNA របស់ Mycobacterium tuberculosis complex (MTBC)។ គោលដៅ gyrB និង IS6110 (រន្ធ ១-៣ និង ៥-៧)។ រន្ធទី ៤ ជាការត្រួតពិនិត្យខាងក្នុង (internal control)។ កាតមាន ៧ រន្ធ។ បច្ចេកវិទ្យា៖ RHAM (RNase Hybridization-Assisted aMplification) ជាវិធីពង្រីកសីតុណ្ហភាពថេរ (isothermal) មួយជំហាន មិនចាំបាច់ចម្រាញ់ (extraction-free) មិនមែន PCR ទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q01','PI-01','Product Information','What does the MiniDock MTB Test detect?','MiniDock MTB Test រកអ្វី?','Mycobacterium tuberculosis complex (MTBC) DNA.','DNA របស់ Mycobacterium tuberculosis complex (MTBC)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q02','PI-01','Product Information','What are the targets on the card?','គោលដៅលើកាតមានអ្វីខ្លះ?','gyrB and IS6110 (wells 1-3 and 5-7). Well 4 is the internal control.','gyrB និង IS6110 (រន្ធ ១-៣ និង ៥-៧)។ រន្ធទី ៤ ជាការត្រួតពិនិត្យខាងក្នុង (internal control)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q03','PI-01','Product Information','Which well is the internal control?','រន្ធមួយណាជាការត្រួតពិនិត្យខាងក្នុង?','Well 4.','រន្ធទី ៤។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q04','PI-01','Product Information','How many targets can one card detect?','កាតមួយអាចរកគោលដៅបានប៉ុន្មាន?','The card has 7 wells, so it can hold up to 7 targets. The MTB card tests 2 targets (gyrB and IS6110, in wells 1-3 and 5-7) plus an internal control in well 4.','កាតមាន ៧ រន្ធ ដូច្នេះអាចដាក់គោលដៅបានរហូតដល់ ៧។ កាត MTB ធ្វើតេស្ត ២ គោលដៅ (gyrB និង IS6110 ក្នុងរន្ធ ១-៣ និង ៥-៧) បូកការត្រួតពិនិត្យខាងក្នុងក្នុងរន្ធទី ៤។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q05','PI-01','Product Information','Does the test detect IS6110?','តើតេស្តនេះរក IS6110 ទេ?','Yes. IS6110 and gyrB are detected in wells 1-3 and 5-7.','បាទ/ចាស។ IS6110 និង gyrB ត្រូវបានរកឃើញក្នុងរន្ធ ១-៣ និង ៥-៧។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q06','PI-01','Product Information','What gene targets are used?','ប្រើគោលដៅហ្សែនអ្វីខ្លះ?','gyrB and IS6110 (wells 1-3 and 5-7). Well 4 is the internal control.','gyrB និង IS6110 (រន្ធ ១-៣ និង ៥-៧)។ រន្ធទី ៤ ជាការត្រួតពិនិត្យខាងក្នុង (internal control)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q07','PI-01','Product Information','target pathogen','មេរោគគោលដៅ','Mycobacterium tuberculosis complex (MTBC) DNA.','DNA របស់ Mycobacterium tuberculosis complex (MTBC)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q08','PI-01','Product Information','Does the card have an internal control?','តើកាតមានការត្រួតពិនិត្យខាងក្នុងទេ?','Yes. Well 4 is the internal control.','បាទ/ចាស។ រន្ធទី ៤ ជាការត្រួតពិនិត្យខាងក្នុង (internal control)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q09','PI-01','Product Information','What technology does the test use?','តេស្តនេះប្រើបច្ចេកវិទ្យាអ្វី?','RHAM (RNase Hybridization-Assisted aMplification), Pluslife''s one-step isothermal amplification.','RHAM (RNase Hybridization-Assisted aMplification) ជាវិធីពង្រីកសីតុណ្ហភាពថេរ (isothermal) មួយជំហាន របស់ Pluslife។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q10','PI-01','Product Information','What is RHAM?','RHAM ជាអ្វី?','RNase Hybridization-Assisted aMplification: Pluslife''s one-step isothermal amplification. It allows extraction-free testing and uses enzyme-cleavable probes for sensitivity and specificity.','RNase Hybridization-Assisted aMplification៖ ជាវិធីពង្រីកសីតុណ្ហភាពថេរ (isothermal) មួយជំហាន របស់ Pluslife។ វាអនុញ្ញាតឱ្យធ្វើតេស្តដោយមិនចាំបាច់ចម្រាញ់ ហើយប្រើ Probe ដែលអង់ស៊ីមអាចកាត់បាន ដើម្បីភាពរសើប និងភាពជាក់លាក់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q11','PI-01','Product Information','Is this a PCR test?','តើនេះជាតេស្ត PCR ទេ?','No. It uses RHAM, an isothermal amplification method, not PCR.','មិនមែនទេ។ វាប្រើ RHAM ដែលជាវិធីពង្រីកសីតុណ្ហភាពថេរ (isothermal) មិនមែន PCR ទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q12','PI-01','Product Information','Does the test need nucleic acid extraction?','តើតេស្តនេះត្រូវការចម្រាញ់អាស៊ីតនុយក្លេអ៊ីកទេ?','No. Enhanced enzymes allow extraction-free testing.','មិនចាំបាច់ទេ។ អង់ស៊ីមដែលបានពង្រឹង អនុញ្ញាតឱ្យធ្វើតេស្តដោយមិនចាំបាច់ចម្រាញ់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q13','PI-01','Product Information','isothermal amplification','តើការបង្កើនចំនួន DNA នៅសីតុណ្ហភាពថេរ (isothermal amplification) មានន័យថាម៉េច?','The test uses RHAM, a one-step isothermal amplification method.','តេស្តនេះប្រើ RHAM ដែលជាវិធីពង្រីកសីតុណ្ហភាពថេរ (isothermal) មួយជំហាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-01-Q14','PI-01','Product Information','Is it a one-step reaction?','តើវាជាប្រតិកម្មមួយជំហានទេ?','Yes. RHAM is a one-step reaction.','បាទ/ចាស។ RHAM ជាប្រតិកម្មមួយជំហាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-02','PI-02','Product Information','Worker asks about kit size, shelf life or card storage','មួយប្រអប់មានប៉ុន្មានតេស្ត? កាតផុតកំណត់ពេលណា ហើយត្រូវរក្សាទុកដូចម្តេច?','10 tests per kit. Shelf life 13 months. Store cards at 0-40°C; no cold chain needed','១០ តេស្ត ក្នុងមួយកញ្ចប់។ អាយុកាលប្រើប្រាស់ ១៣ ខែ។ រក្សាទុកកាតនៅ 0-40°C។ មិនត្រូវការខ្សែសង្វាក់ត្រជាក់ (cold chain) ទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-02-Q01','PI-02','Product Information','How many tests are in a kit?','ក្នុងកញ្ចប់មួយមានតេស្តប៉ុន្មាន?','10 tests per kit.','១០ តេស្ត ក្នុងមួយកញ្ចប់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-02-Q02','PI-02','Product Information','What is the shelf life of the test card?','អាយុកាលប្រើប្រាស់របស់កាតតេស្តប៉ុន្មាន?','13 months, stored at 0-40°C.','១៣ ខែ ដោយរក្សាទុកនៅ 0-40°C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-02-Q03','PI-02','Product Information','How should the test cards be stored?','គួររក្សាទុកកាតតេស្តយ៉ាងម៉េច?','At 0-40°C. Shelf life is 13 months.','នៅ 0-40°C។ អាយុកាលប្រើប្រាស់ ១៣ ខែ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-02-Q04','PI-02','Product Information','Do the test cards need a cold chain?','តើកាតតេស្តត្រូវការខ្សែសង្វាក់ត្រជាក់ (cold chain) ទេ?','No. Cards are stored at 0-40°C, so no cold chain is needed.','មិនត្រូវការទេ។ កាតរក្សាទុកនៅ 0-40°C ដូច្នេះមិនត្រូវការខ្សែសង្វាក់ត្រជាក់ (cold chain) ទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-02-Q05','PI-02','Product Information','Can test cards be stored at room temperature?','តើអាចរក្សាទុកកាតតេស្តនៅសីតុណ្ហភាពបន្ទប់បានទេ?','Yes. Store at 0-40°C.','បាទ/ចាស។ រក្សាទុកនៅ 0-40°C (ជៀសវាងកន្លែងក្តៅខ្លាំង ឬពន្លឺថ្ងៃផ្ទាល់)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-02-Q06','PI-02','Product Information','storage temperature for test cards','សីតុណ្ហភាពរក្សាទុកកាតតេស្ត','At 0-40°C. Shelf life is 13 months.','នៅ 0-40°C។ អាយុកាលប្រើប្រាស់ ១៣ ខែ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-02-Q07','PI-02','Product Information','kit size','ទំហំកញ្ចប់','10 tests per kit.','១០ តេស្ត ក្នុងមួយកញ្ចប់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03','PI-03','Product Information','Worker asks about test time, workflow or equipment needed','មួយតេស្តចំណាយពេលប៉ុន្មាន មានជំហានអ្វីខ្លះ ហើយត្រូវការឧបករណ៍អ្វីខ្លះ?','Run time 5-25 min; total turnaround ≤30 min; hands-on time within 2 min. Workflow: collect sample → mix → one-step pretreatment in the Thermolyse (3000 rpm, 75°C, 5 min) → run on the MiniDock. Set up three areas: Collection (sputum cup or tongue swab, timer); Processing (Pluslife Thermolyse, Releasing Agent 02 Pro tube and cap, swab); Detection (MiniDock Ultra, test card, PC or mobile)','រយៈពេលដំណើរការ ៥-២៥ នាទី។ រយៈពេលសរុប មិនលើស ៣០ នាទី។ ពេលធ្វើដោយដៃ ក្នុងរយៈពេល ២ នាទី។ លំដាប់ការងារ៖ យកសំណាក → លាយ → pretreatment មួយជំហានក្នុង Thermolyse (3000 rpm, 75°C, ៥ នាទី) → ដំណើរការលើ MiniDock។ រៀបចំ ៣ តំបន់៖ យកសំណាក (កែវកំហាក ឬដងសំឡីអណ្តាត នាឡិកាកំណត់ម៉ោង)។ ដំណើរការសំណាក (Pluslife Thermolyse, បំពង់ និងគម្រប Releasing Agent 02 Pro, ដងសំឡី)។ ធ្វើតេស្ត (MiniDock Ultra, កាតតេស្ត, កុំព្យូទ័រ ឬទូរស័ព្ទ)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q01','PI-03','Product Information','What do I need to run a test?','ត្រូវការអ្វីខ្លះ ដើម្បីធ្វើតេស្ត?','Sample collection: sputum cup or tongue swab, timer.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q02','PI-03','Product Information','What equipment is needed for the MiniDock MTB Test?','ត្រូវការឧបករណ៍អ្វីខ្លះ សម្រាប់ MiniDock MTB Test?','Sample collection: sputum cup or tongue swab, timer.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q03','PI-03','Product Information','What consumables do I need for one test?','តេស្តមួយត្រូវការសម្ភារៈប្រើប្រាស់អ្វីខ្លះ?','Sputum cup or tongue swab, swab, Releasing Agent 02 Pro tube and cap, and a test card.','កែវកំហាក ឬដងសំឡីអណ្តាត ដងសំឡី បំពង់ និងគម្រប Releasing Agent 02 Pro និងកាតតេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q04','PI-03','Product Information','How should I set up the testing areas?','គួររៀបចំតំបន់ធ្វើតេស្តយ៉ាងម៉េច?','Set up three areas:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q05','PI-03','Product Information','What goes in the sample processing area?','តំបន់ដំណើរការសំណាក ត្រូវមានអ្វីខ្លះ?','Pluslife Thermolyse, Releasing Agent 02 Pro tube and cap, swab, and the processing guidance.','Pluslife Thermolyse, បំពង់ និងគម្រប Releasing Agent 02 Pro, ដងសំឡី និងការណែនាំអំពីការដំណើរការសំណាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q06','PI-03','Product Information','test setup checklist','បញ្ជីត្រួតពិនិត្យការរៀបចំតេស្ត','Sample collection: sputum cup or tongue swab, timer.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q07','PI-03','Product Information','Do I need a Thermolyse?','តើត្រូវការ Thermolyse ទេ?','Yes. The Thermolyse is used for the pretreatment step (3000 rpm, 75°C, 5 min).','បាទ/ចាស។ Thermolyse ត្រូវបានប្រើសម្រាប់ជំហាន pretreatment (3000 rpm, 75°C, ៥ នាទី)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q08','PI-03','Product Information','What items are needed for sample collection?','ត្រូវការរបស់អ្វីខ្លះ សម្រាប់យកសំណាក?','A sputum cup or tongue swab, a timer, and the sampling guidance.','កែវកំហាក ឬដងសំឡីអណ្តាត នាឡិកាកំណត់ម៉ោង និងការណែនាំអំពីការស្រង់សំណាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q09','PI-03','Product Information','How long does the test take?','តេស្តចំណាយពេលប៉ុន្មាន?','The run takes 5-25 minutes; total turnaround from sample to result is 30 minutes or less.','ការដំណើរការចំណាយ ៥-២៥ នាទី។ រយៈពេលសរុបពីសំណាកដល់លទ្ធផល មិនលើស ៣០ នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q10','PI-03','Product Information','What is the turnaround time?','រយៈពេលសរុបពីសំណាកដល់លទ្ធផលប៉ុន្មាន?','30 minutes or less.','មិនលើស ៣០ នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q11','PI-03','Product Information','How fast can I get a result?','អាចទទួលលទ្ធផលលឿនប៉ុណ្ណា?','The run takes as little as 5 minutes (5-25 min); total turnaround is 30 minutes or less.','ការដំណើរការចំណាយយ៉ាងលឿន ៥ នាទី (៥-២៥ នាទី)។ រយៈពេលសរុប មិនលើស ៣០ នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q12','PI-03','Product Information','What are the main steps of the test?','ជំហានសំខាន់ៗនៃតេស្តមានអ្វីខ្លះ?','Collect sample → mix sample → one-step pretreatment in the Thermolyse (3000 rpm, 75°C, 5 min) → run the test on the MiniDock.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q13','PI-03','Product Information','How much hands-on time is needed?','ត្រូវចំណាយពេលធ្វើដោយដៃប៉ុន្មាន?','Within 2 minutes.','ក្នុងរយៈពេល ២ នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q14','PI-03','Product Information','How long is the run on the MiniDock?','ការដំណើរការលើ MiniDock ចំណាយពេលប៉ុន្មាន?','5-25 minutes.','៥-២៥ នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q15','PI-03','Product Information','test time','រយៈពេលតេស្ត','The run takes 5-25 minutes; total turnaround from sample to result is 30 minutes or less.','ការដំណើរការចំណាយ ៥-២៥ នាទី។ រយៈពេលសរុបពីសំណាកដល់លទ្ធផល មិនលើស ៣០ នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q16','PI-03','Product Information','Can I get results within 30 minutes?','តើអាចទទួលលទ្ធផលក្នុង ៣០ នាទីបានទេ?','Yes. Total turnaround is 30 minutes or less.','បាទ/ចាស។ រយៈពេលសរុប មិនលើស ៣០ នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-03-Q17','PI-03','Product Information','What''s the overall workflow from sample to result?','លំដាប់ការងារទាំងមូល ពីសំណាកដល់លទ្ធផល យ៉ាងម៉េច?','Collect sample → mix sample → one-step pretreatment in the Thermolyse (3000 rpm, 75°C, 5 min) → run the test on the MiniDock.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04','PI-04','Product Information','Worker asks about device size or specifications','MiniDock មានទំហំប៉ុន្មាន ហើយមានលក្ខណៈបច្ចេកទេសអ្វីខ្លះ?','MiniDock Ultra: 101 x 91 x 65 mm, 240 g, palm-sized; Type-C, Wi-Fi and Bluetooth','MiniDock Ultra៖ 101 x 91 x 65 mm, 240 g, ទំហំប៉ុនបាតដៃ។ Type-C, Wi-Fi និង Bluetooth។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04-Q01','PI-04','Product Information','How big is the MiniDock Ultra?','MiniDock Ultra ធំប៉ុនណា?','101 x 91 x 65 mm.','101 x 91 x 65 mm។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04-Q02','PI-04','Product Information','How much does the device weigh?','ម៉ាស៊ីនទម្ងន់ប៉ុន្មាន?','240 g.','240 g។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04-Q03','PI-04','Product Information','device dimensions','ទំហំម៉ាស៊ីន','101 x 91 x 65 mm.','101 x 91 x 65 mm។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04-Q04','PI-04','Product Information','Is the device portable?','តើម៉ាស៊ីនងាយយកតាមខ្លួនទេ?','Yes. It''s palm-sized: 101 x 91 x 65 mm, 240 g.','បាទ/ចាស។ វាមានទំហំប៉ុនបាតដៃ៖ 101 x 91 x 65 mm, 240 g។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-04-Q05','PI-04','Product Information','What are the MiniDock Ultra specifications?','លក្ខណៈបច្ចេកទេស MiniDock Ultra មានអ្វីខ្លះ?','101 x 91 x 65 mm, 240 g, Type-C and Wi-Fi connectivity.','101 x 91 x 65 mm, 240 g, ភ្ជាប់តាម Type-C និង Wi-Fi។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05','PI-05','Product Information','Worker asks about UPS specifications','ត្រូវប្រើ UPS ប្រភេទណាសម្រាប់ MiniDock?','600W (UPS-PL-600W): 270 x 210 x 185 mm, 6.5 kg, LiFePO4 576 Wh. 1200W (UPS-PL-1200W): 280 x 245 x 250 mm, 11.22 kg, LiFePO4 1152 Wh. Both: 220 V AC ±5% pure sine wave; DC 12 V/10 A; 2 × USB QC 3.0 (max 12 V/1.5 A); Type-C1 PD/QC 3.0 (max 30 W); Type-C2 PD (max 100 W)','600W (UPS-PL-600W)៖ 270 x 210 x 185 mm, 6.5 kg, ថ្ម LiFePO4 576 Wh។ 1200W (UPS-PL-1200W)៖ 280 x 245 x 250 mm, 11.22 kg, ថ្ម LiFePO4 1152 Wh។ ទាំងពីរ៖ 220 V AC ±5% pure sine wave; DC 12 V/10 A; USB QC 3.0 ចំនួន ២ (អតិបរមា 12 V/1.5 A); Type-C1 PD/QC 3.0 (អតិបរមា 30 W); Type-C2 PD (អតិបរមា 100 W)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q01','PI-05','Product Information','What are the UPS specifications?','លក្ខណៈបច្ចេកទេស UPS មានអ្វីខ្លះ?','600W (UPS-PL-600W): 270 x 210 x 185 mm, 6.5 kg, LiFePO4 576 Wh.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q02','PI-05','Product Information','How heavy is the 600W UPS?','UPS 600W ធ្ងន់ប៉ុន្មាន?','6.5 kg.','6.5 kg។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q03','PI-05','Product Information','What outputs does the UPS have?','UPS មានរន្ធចេញភ្លើងអ្វីខ្លះ?','AC 220 V ±5% (pure sine wave), DC 12 V/10 A, 2 × USB QC 3.0 (max 12 V/1.5 A), Type-C1 PD/QC 3.0 (max 30 W), Type-C2 PD (max 100 W).','AC 220 V ±5% (pure sine wave), DC 12 V/10 A, USB QC 3.0 ចំនួន ២ (អតិបរមា 12 V/1.5 A), Type-C1 PD/QC 3.0 (អតិបរមា 30 W), Type-C2 PD (អតិបរមា 100 W)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q04','PI-05','Product Information','What battery does the UPS use?','UPS ប្រើថ្មប្រភេទអ្វី?','LiFePO4: 576 Wh (600W) or 1152 Wh (1200W).','LiFePO4៖ 576 Wh (600W) ឬ 1152 Wh (1200W)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q05','PI-05','Product Information','What is the UPS AC output voltage?','តង់ស្យុង AC ចេញពី UPS ប៉ុន្មាន?','220 V AC ±5%, pure sine wave.','220 V AC ±5%, pure sine wave។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q06','PI-05','Product Information','UPS model numbers','លេខម៉ូដែល UPS','UPS-PL-600W and UPS-PL-1200W.','UPS-PL-600W និង UPS-PL-1200W។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-05-Q07','PI-05','Product Information','How big is the 1200W UPS?','UPS 1200W ធំប៉ុនណា?','280 x 245 x 250 mm (11.22 kg).','280 x 245 x 250 mm (11.22 kg)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06','PI-06','Product Information','Worker asks how accurate the test is','តេស្ត Pluslife មានភាពត្រឹមត្រូវកម្រិតណា?','Against the microbiological reference standard (N=1,266): sputum swab sensitivity 86.7%, specificity 98.0%; tongue swab 80.7% / 99.6%. Xpert Ultra 89.4% / 99.0% (sensitivity difference p=0.11). Smear microscopy sensitivity 62.4% vs 80.7% for tongue swab (p<0.001). Source: R2D2 TB Network stage analysis report, 14 Jul 2025','ធៀបនឹងស្តង់ដារយោងមីក្រូជីវសាស្ត្រ (N=1,266)៖ សំណាកកំហាក ភាពរសើប (sensitivity) 86.7% ភាពជាក់លាក់ (specificity) 98.0%។ សំណាកអណ្តាត 80.7% / 99.6%។ Xpert Ultra 89.4% / 99.0% (ភាពខុសគ្នានៃភាពរសើប p=0.11)។ ការពិនិត្យកំហាកតាមមីក្រូទស្សន៍ (smear) ភាពរសើប 62.4% ធៀបនឹង 80.7% សម្រាប់សំណាកអណ្តាត (p<0.001)។ ប្រភព៖ របាយការណ៍វិភាគដំណាក់កាល R2D2 TB Network ថ្ងៃទី ១៤ ខែកក្កដា ឆ្នាំ ២០២៥។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q01','PI-06','Product Information','How accurate is the MiniDock MTB Test?','MiniDock MTB Test ត្រឹមត្រូវប៉ុណ្ណា?','Against the microbiological reference standard (N=1,266):
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q02','PI-06','Product Information','What is the sensitivity of the sputum test?','ភាពរសើប (sensitivity) នៃតេស្តកំហាកប៉ុន្មាន?','86.7% (sputum swab, against the microbiological reference standard).','86.7% (សំណាកកំហាក ធៀបនឹងស្តង់ដារយោងមីក្រូជីវសាស្ត្រ)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q03','PI-06','Product Information','What is the specificity of the tongue swab test?','ភាពជាក់លាក់ (specificity) នៃតេស្តសំណាកអណ្តាតប៉ុន្មាន?','99.6% (tongue swab, against the microbiological reference standard).','99.6% (សំណាកអណ្តាត ធៀបនឹងស្តង់ដារយោងមីក្រូជីវសាស្ត្រ)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q04','PI-06','Product Information','How does it compare with Xpert Ultra?','ប្រៀបធៀបជាមួយ Xpert Ultra យ៉ាងម៉េច?','Comparable. Sputum swab: 86.7% sensitivity / 98.0% specificity; Xpert Ultra: 89.4% / 99.0%. The sensitivity difference wasn''t significant (p=0.11).','ប្រហាក់ប្រហែលគ្នា។ សំណាកកំហាក៖ ភាពរសើប 86.7% / ភាពជាក់លាក់ 98.0%។ Xpert Ultra៖ 89.4% / 99.0%។ ភាពខុសគ្នានៃភាពរសើប មិនមានសារៈសំខាន់ស្ថិតិទេ (p=0.11)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q05','PI-06','Product Information','How does the tongue swab test compare with smear microscopy?','តេស្តសំណាកអណ្តាត ប្រៀបធៀបជាមួយការពិនិត្យកំហាកតាមមីក្រូទស្សន៍យ៉ាងម៉េច?','Tongue swab sensitivity 80.7% vs 62.4% for smear microscopy (p<0.001). Specificity 99.6% vs 99.8%.','ភាពរសើបនៃសំណាកអណ្តាត 80.7% ធៀបនឹង 62.4% សម្រាប់ការពិនិត្យកំហាកតាមមីក្រូទស្សន៍ (p<0.001)។ ភាពជាក់លាក់ 99.6% ធៀបនឹង 99.8%។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q06','PI-06','Product Information','clinical performance data','ទិន្នន័យប្រសិទ្ធភាពគ្លីនិក','Against the microbiological reference standard (N=1,266):
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q07','PI-06','Product Information','Which study does the performance data come from?','ទិន្នន័យប្រសិទ្ធភាពនេះ មកពីការសិក្សាណា?','R2D2 TB Network, Clinical Performance Study of MiniDock MTB Test in High TB Burden Settings: stage analysis report, 14 Jul 2025 (N=1,266).','R2D2 TB Network, Clinical Performance Study of MiniDock MTB Test in High TB Burden Settings៖ របាយការណ៍វិភាគដំណាក់កាល ថ្ងៃទី ១៤ ខែកក្កដា ឆ្នាំ ២០២៥ (N=1,266)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-06-Q08','PI-06','Product Information','Is the tongue swab as sensitive as sputum?','តើសំណាកអណ្តាតរសើបដូចកំហាកទេ?','No. In the same study, tongue swab sensitivity was 80.7% vs 86.7% for sputum swab.','មិនស្មើទេ។ ក្នុងការសិក្សាដដែល ភាពរសើបនៃសំណាកអណ្តាតគឺ 80.7% ធៀបនឹង 86.7% សម្រាប់សំណាកកំហាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01','RG-01','Regulatory & Guidelines','Worker asks whether the test is covered by WHO guidance','តេស្ត Pluslife ស្ថិតក្នុងគោលការណ៍ណែនាំរបស់ WHO ស្តីពីការធ្វើរោគវិនិច្ឆ័យរបេងទេ?','The MiniDock MTB Test is an NPOC-NAAT (near point-of-care nucleic acid amplification test), a class added to the WHO TB guidelines (Module 3: Diagnosis) as an initial test for people with TB symptoms or who screen positive. Sputum preferred; tongue swab if no sputum. Positive → drug-susceptibility testing and care; negative → clinical assessment / follow-up','MiniDock MTB Test ជា NPOC-NAAT (តេស្តពង្រីកអាស៊ីតនុយក្លេអ៊ីក នៅជិតកន្លែងផ្តល់សេវា) ជាប្រភេទតេស្តដែលត្រូវបានបន្ថែមក្នុងគោលការណ៍ណែនាំជំងឺរបេងរបស់អង្គការសុខភាពពិភពលោក (WHO) (Module 3: Diagnosis) ជាតេស្តដំបូងសម្រាប់អ្នកមានរោគសញ្ញាជំងឺរបេង ឬអ្នកដែលការពិនិត្យស្រាវជ្រាវវិជ្ជមាន។ កំហាកត្រូវបានគេពេញចិត្តជាង។ សំណាកអណ្តាត បើគ្មានកំហាក។ វិជ្ជមាន → ការធ្វើតេស្តរកភាពស៊ាំនឹងថ្នាំ និងការថែទាំ។ អវិជ្ជមាន → ការវាយតម្លៃគ្លីនិក / ការតាមដាន។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q01','RG-01','Regulatory & Guidelines','Is the MiniDock MTB Test covered by WHO guidance?','តើ MiniDock MTB Test មាននៅក្នុងគោលការណ៍ណែនាំរបស់ WHO ទេ?','Yes. The MiniDock MTB Test is an NPOC-NAAT, a test class added to the WHO TB guidelines (Module 3: Diagnosis).','បាទ/ចាស។ MiniDock MTB Test ជា NPOC-NAAT ដែលជាប្រភេទតេស្តដែលត្រូវបានបន្ថែមក្នុងគោលការណ៍ណែនាំជំងឺរបេងរបស់ WHO (Module 3: Diagnosis)។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q02','RG-01','Regulatory & Guidelines','What is an NPOC-NAAT?','NPOC-NAAT ជាអ្វី?','Near point-of-care nucleic acid amplification test: a new WHO test class for near-patient TB testing in decentralised settings.','តេស្តពង្រីកអាស៊ីតនុយក្លេអ៊ីក នៅជិតកន្លែងផ្តល់សេវា (Near point-of-care NAAT)៖ ជាប្រភេទតេស្តថ្មីរបស់ WHO សម្រាប់ធ្វើតេស្តជំងឺរបេងនៅជិតអ្នកជំងឺ ក្នុងមូលដ្ឋានសុខាភិបាលថ្នាក់ក្រោម។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q03','RG-01','Regulatory & Guidelines','What does WHO say about tongue swabs?','WHO និយាយយ៉ាងម៉េចពីសំណាកអណ្តាត?','Sputum is preferred; use a tongue swab when sputum can''t be obtained.','កំហាកត្រូវបានគេពេញចិត្តជាង។ ប្រើសំណាកអណ្តាត ពេលមិនអាចយកកំហាកបាន។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q04','RG-01','Regulatory & Guidelines','Where does the test fit in the TB diagnostic algorithm?','តេស្តនេះស្ថិតនៅត្រង់ណាក្នុងក្បួនដោះស្រាយរោគវិនិច្ឆ័យជំងឺរបេង?','As the initial test for people with TB symptoms or who screen positive. Positive → drug-susceptibility testing and care; negative → clinical assessment / follow-up.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q05','RG-01','Regulatory & Guidelines','WHO guideline','គោលការណ៍ណែនាំ WHO','WHO added NPOC-NAATs (including the MiniDock MTB Test) as an initial test for people with TB symptoms or who screen positive. Sputum is preferred; tongue swab if no sputum. Positive → drug-susceptibility testing and care; negative → clinical assessment / follow-up.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-01-Q06','RG-01','Regulatory & Guidelines','Can it be used as the initial test?','តើអាចប្រើវាជាតេស្តដំបូងបានទេ?','Yes. WHO guidance supports NPOC-NAATs as the initial test for people with symptoms or who screen positive.','បាទ/ចាស។ គោលការណ៍ណែនាំរបស់ WHO គាំទ្រ NPOC-NAATs ជាតេស្តដំបូងសម្រាប់អ្នកមានរោគសញ្ញា ឬអ្នកដែលការពិនិត្យស្រាវជ្រាវវិជ្ជមាន។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02','RG-02','Regulatory & Guidelines','Worker asks about ERPD, Global Fund procurement or WHO PQ status','តេស្តនេះមានស្ថានភាពយ៉ាងណា ពាក់ព័ន្ធនឹង ERPD ការទិញតាម Global Fund ឬ WHO PQ?','Global Fund letter, 11 Jul 2025: ERPD Category 2, procurement allowed for 12 months (until 10 Jul 2026). Pluslife''s March 2026 brief lists an ERPD listing (sputum + tongue swab) in Feb 2026 and expected WHO PQ listing in Dec 2026. Confirm the current status before quoting','លិខិតរបស់ Global Fund ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥៖ ERPD ប្រភេទទី ២ អនុញ្ញាតឱ្យលទ្ធកម្មរយៈពេល ១២ ខែ (រហូតដល់ ១០ កក្កដា ២០២៦)។ សេចក្តីសង្ខេបរបស់ Pluslife ខែមីនា ឆ្នាំ ២០២៦ បង្ហាញការចុះបញ្ជី ERPD (កំហាក + សំណាកអណ្តាត) នៅខែកុម្ភៈ ២០២៦ និងរំពឹងថានឹងចុះបញ្ជី WHO PQ នៅខែធ្នូ ២០២៦។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្នមុននឹងលើកឡើង។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q01','RG-02','Regulatory & Guidelines','What is the ERPD status of the MiniDock MTB Test?','ស្ថានភាព ERPD របស់ MiniDock MTB Test យ៉ាងម៉េច?','Global Fund letter, 11 Jul 2025: ERPD Category 2, procurement allowed for a time-limited 12 months (until 10 July 2026). Pluslife''s March 2026 brief lists an ERPD listing (sputum + tongue swab) in Feb 2026. Please confirm the current status before quoting.','លិខិតរបស់ Global Fund ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥៖ ERPD ប្រភេទទី ២ អនុញ្ញាតឱ្យលទ្ធកម្មក្នុងរយៈពេលកំណត់ ១២ ខែ (រហូតដល់ ១០ កក្កដា ២០២៦)។ សេចក្តីសង្ខេបរបស់ Pluslife ខែមីនា ឆ្នាំ ២០២៦ បង្ហាញការចុះបញ្ជី ERPD (កំហាក + សំណាកអណ្តាត) នៅខែកុម្ភៈ ២០២៦។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្នមុននឹងលើកឡើង។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q02','RG-02','Regulatory & Guidelines','Can the test be procured with Global Fund money?','តើអាចទិញតេស្តនេះដោយថវិកា Global Fund បានទេ?','Unclear. The 11 Jul 2025 ERPD Category 2 approval allowed Global Fund/Unitaid procurement until 10 July 2026, after ad hoc review and a no-objection letter. The current status needs to be confirmed.','មិនច្បាស់ទេ។ ការអនុម័ត ERPD ប្រភេទទី ២ ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥ អនុញ្ញាតឱ្យ Global Fund/Unitaid ធ្វើលទ្ធកម្មរហូតដល់ ១០ កក្កដា ២០២៦ ក្រោយការពិនិត្យពិសេស និងលិខិតគ្មានការជំទាស់។ ស្ថានភាពបច្ចុប្បន្នត្រូវការផ្ទៀងផ្ទាត់។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q03','RG-02','Regulatory & Guidelines','What ERPD category is the product in?','ផលិតផលនេះស្ថិតក្នុង ERPD ប្រភេទណា?','Category 2 (Global Fund letter, 11 Jul 2025). Please confirm the current status.','ប្រភេទទី ២ (លិខិតរបស់ Global Fund ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥)។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្ន។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q04','RG-02','Regulatory & Guidelines','Is the product WHO prequalified?','តើផលិតផលនេះមាន WHO prequalification ហើយឬនៅ?','Unclear. As of the March 2026 brief, WHO PQ listing was expected in December 2026. Please confirm the current status.','មិនច្បាស់ទេ។ យោងតាមសេចក្តីសង្ខេបខែមីនា ឆ្នាំ ២០២៦ ការចុះបញ្ជី WHO PQ ត្រូវបានរំពឹងនៅខែធ្នូ ឆ្នាំ ២០២៦។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្ន។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q05','RG-02','Regulatory & Guidelines','ERPD','ERPD មានន័យថាអ្វីសម្រាប់តេស្តនេះ?','Global Fund letter, 11 Jul 2025: ERPD Category 2, procurement allowed for a time-limited 12 months (until 10 July 2026). Pluslife''s March 2026 brief lists an ERPD listing (sputum + tongue swab) in Feb 2026. Please confirm the current status before quoting.','លិខិតរបស់ Global Fund ថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥៖ ERPD ប្រភេទទី ២ អនុញ្ញាតឱ្យលទ្ធកម្មក្នុងរយៈពេលកំណត់ ១២ ខែ (រហូតដល់ ១០ កក្កដា ២០២៦)។ សេចក្តីសង្ខេបរបស់ Pluslife ខែមីនា ឆ្នាំ ២០២៦ បង្ហាញការចុះបញ្ជី ERPD (កំហាក + សំណាកអណ្តាត) នៅខែកុម្ភៈ ២០២៦។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្នមុននឹងលើកឡើង។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RG-02-Q06','RG-02','Regulatory & Guidelines','When does the ERPD period end?','រយៈពេល ERPD ផុតកំណត់ពេលណា?','The 11 Jul 2025 approval ran until 10 July 2026. Pluslife''s March 2026 brief lists a new ERPD listing (sputum + tongue swab) in Feb 2026, with no end date given. Please confirm the current status.','ការអនុម័តថ្ងៃទី ១១ ខែកក្កដា ឆ្នាំ ២០២៥ មានសុពលភាពរហូតដល់ ១០ កក្កដា ២០២៦។ សេចក្តីសង្ខេបរបស់ Pluslife ខែមីនា ឆ្នាំ ២០២៦ បង្ហាញការចុះបញ្ជី ERPD ថ្មី (កំហាក + សំណាកអណ្តាត) នៅខែកុម្ភៈ ២០២៦ ដោយមិនបញ្ជាក់ថ្ងៃផុតកំណត់។ សូមផ្ទៀងផ្ទាត់ស្ថានភាពបច្ចុប្បន្ន។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-01','TR-01','Training Resources','Worker asks for training videos or documents','មានវីដេអូ ឬឯកសារណែនាំរបៀបប្រើ Pluslife ទេ?','Video (1 min): https://www.youtube.com/watch?v=q4P0pGz8hhM. Full video: https://www.youtube.com/watch?v=BT2BGlf3H8M&t=42s. Daily maintenance video: https://www.youtube.com/watch?v=aiZtZ1tIBig. Clinical procedure: https://docs.google.com/document/d/1d9w2ffsIa9-XLKiivnDRyfWvPhNWLOBp/edit. Operation procedure: [Operation Procedure Document - Pending]. Result decision guide: [Result Decision Guide - Pending]','វីដេអូខ្លី (១ នាទី)៖ https://www.youtube.com/watch?v=q4P0pGz8hhM។ វីដេអូពេញ៖ https://www.youtube.com/watch?v=BT2BGlf3H8M&t=42s។ វីដេអូថែទាំប្រចាំថ្ងៃ៖ https://www.youtube.com/watch?v=aiZtZ1tIBig។ នីតិវិធីគ្លីនិក (Clinical procedure)៖ https://docs.google.com/document/d/1d9w2ffsIa9-XLKiivnDRyfWvPhNWLOBp/edit។ នីតិវិធីប្រតិបត្តិការ (Operation procedure)៖ [ឯកសារកំពុងរៀបចំ - Pending]។ សៀវភៅណែនាំការសម្រេចលទ្ធផល (Result decision guide)៖ [ឯកសារកំពុងរៀបចំ - Pending]','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-01-Q01','TR-01','Training Resources','Is there a video showing how to run the test?','តើមានវីដេអូបង្ហាញពីរបៀបធ្វើតេស្តទេ?','Yes.
