INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-10-Q02','DA-10','Device Alarm','red light + beep','ភ្លើងក្រហម + សំឡេងប៊ីប','Possible causes and solutions:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-10-Q03','DA-10','Device Alarm','It beeps with red light right after I put the card in.','វារោទិ៍ និងភ្លើងក្រហម ភ្លាមៗក្រោយខ្ញុំដាក់កាតចូល។ ត្រូវធ្វើម៉េច?','Possible causes: the card is expired, the card was already tested/scanned (reused), the device cannot recognize the QR code, or the lid was not closed promptly. Use a card within its expiry date, open a new card, or close the lid in time.','មូលហេតុដែលអាចកើតមាន៖ កាតផុតកំណត់ កាតត្រូវបានធ្វើតេស្ត/ស្កេនរួចហើយ (ប្រើម្តងទៀត) ម៉ាស៊ីនមិនអាចអានកូដ QR បាន ឬមិនបានបិទគម្របទាន់ពេល។ សូមប្រើកាតដែលនៅក្នុងកាលកំណត់ បើកកាតថ្មី ឬបិទគម្របឱ្យទាន់ពេល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-10-Q04','DA-10','Device Alarm','Can an old adapter make the device beep with a red light?','តើអាដាប់ទ័រចាស់ អាចធ្វើឱ្យម៉ាស៊ីនរោទិ៍ និងភ្លើងក្រហមបានទេ?','Yes. Non-standard power supply or adapter aging can cause it. Use a wall plug power supply or replace the adapter.','បាទ/ចាស។ ប្រភពភ្លើងមិនត្រឹមត្រូវតាមស្តង់ដារ ឬអាដាប់ទ័រចាស់ អាចបង្កបញ្ហានេះ។ សូមប្រើភ្លើងពីព្រីជញ្ជាំង ឬប្តូរអាដាប់ទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-10-Q05','DA-10','Device Alarm','device keep beeping red, what to check','ម៉ាស៊ីនរោទិ៍ និងភ្លើងក្រហមមិនឈប់ ត្រូវពិនិត្យអ្វី?','Possible causes and solutions:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-10-Q06','DA-10','Device Alarm','Do I need a new card when it beeps?','តើខ្ញុំត្រូវការកាតថ្មីទេ ពេលវារោទិ៍?','Not sure — it depends on the cause. Open a new card if the card was expired, already used, or its QR code cannot be read. If the cause is power, use a wall plug or replace the adapter; if the lid was not closed, close it in time.','មិនប្រាកដទេ — វាអាស្រ័យលើមូលហេតុ។ បើកកាតថ្មី បើកាតផុតកំណត់ ប្រើរួចហើយ ឬកូដ QR របស់វាមិនអាចអានបាន។ បើមូលហេតុមកពីភ្លើង សូមប្រើភ្លើងពីព្រីជញ្ជាំង ឬប្តូរអាដាប់ទ័រ។ បើមិនបានបិទគម្រប សូមបិទវាឱ្យទាន់ពេល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-11','DA-11','Device Alarm','MiniDock Ultra beeping alarm','MiniDock Ultra រោទិ៍។ ត្រូវពិនិត្យអ្វីមុន?','The Ultra instrument beeps in the following situations:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-11-Q01','DA-11','Device Alarm','Why is my Ultra beeping?','ហេតុអ្វីបានជា Ultra របស់ខ្ញុំរោទិ៍?','The Ultra instrument beeps in the following situations:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-11-Q02','DA-11','Device Alarm','ultra beep alarm reasons','មូលហេតុដែល Ultra រោទិ៍រោទិ៍។ ត្រូវធ្វើម៉េច?','The Ultra instrument beeps in the following situations:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-11-Q03','DA-11','Device Alarm','Does the Ultra beep if the card is expired?','តើ Ultra រោទិ៍ទេ បើកាតផុតកំណត់?','Yes. The Ultra beeps when the test card has expired.','បាទ/ចាស។ Ultra រោទិ៍ ពេលកាតតេស្តផុតកំណត់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-11-Q04','DA-11','Device Alarm','Will it beep if I put in a used card?','តើវានឹងរោទិ៍ទេ បើខ្ញុំដាក់កាតដែលប្រើរួច?','Yes. The Ultra beeps when the test card is a duplicate (already used).','បាទ/ចាស។ Ultra រោទិ៍ ពេលកាតតេស្តស្ទួន (ប្រើរួចហើយ)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-11-Q05','DA-11','Device Alarm','I put the card in and left the lid open, now it beeps.','ខ្ញុំដាក់កាតចូល ហើយទុកគម្របចំហ ឥឡូវវារោទិ៍។ ត្រូវធ្វើម៉េច?','The Ultra beeps when the lid is not closed in time after the card is inserted. Close the lid.','Ultra រោទិ៍ ពេលមិនបានបិទគម្របទាន់ពេល ក្រោយដាក់កាតចូល។ សូមបិទគម្រប។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-12','DA-12','Device Alarm','Device alarms some time after power-on, during warm-up','បើកម៉ាស៊ីនបានបន្តិច ស្រាប់តែវារោទិ៍ពេលកំពុងកម្តៅ។ ត្រូវធ្វើម៉េច?','An alarm during warm-up means the instrument''s power supply is too low to reach the set temperature within the specified time. Check whether the adapter in use meets the 5V 3A output requirement, and try replacing the adapter.','ការរោទិ៍ពេលកំពុងកម្តៅ មានន័យថាភ្លើងចូលម៉ាស៊ីនខ្សោយពេក មិនអាចឡើងដល់សីតុណ្ហភាពកំណត់ក្នុងរយៈពេលកំណត់បាន។ សូមពិនិត្យថាអាដាប់ទ័រដែលកំពុងប្រើ បញ្ចេញភ្លើងបានតាមតម្រូវការ 5V 3A ឬអត់ ហើយសាកល្បងប្តូរអាដាប់ទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-12-Q01','DA-12','Device Alarm','The device alarms a few minutes after I switch it on. Why?','ម៉ាស៊ីនរោទិ៍ពីរបីនាទី ក្រោយខ្ញុំបើកវា។ ហេតុអ្វី?','An alarm during warm-up means the instrument''s power supply is too low to reach the set temperature within the specified time. Check whether the adapter in use meets the 5V 3A output requirement, and try replacing the adapter.','ការរោទិ៍ពេលកំពុងកម្តៅ មានន័យថាភ្លើងចូលម៉ាស៊ីនខ្សោយពេក មិនអាចឡើងដល់សីតុណ្ហភាពកំណត់ក្នុងរយៈពេលកំណត់បាន។ សូមពិនិត្យថាអាដាប់ទ័រដែលកំពុងប្រើ បញ្ចេញភ្លើងបានតាមតម្រូវការ 5V 3A ឬអត់ ហើយសាកល្បងប្តូរអាដាប់ទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-12-Q02','DA-12','Device Alarm','alarm during warm up','រោទិ៍ពេលកំពុងកម្តៅ','An alarm during warm-up means the instrument''s power supply is too low to reach the set temperature within the specified time. Check whether the adapter in use meets the 5V 3A output requirement, and try replacing the adapter.','ការរោទិ៍ពេលកំពុងកម្តៅ មានន័យថាភ្លើងចូលម៉ាស៊ីនខ្សោយពេក មិនអាចឡើងដល់សីតុណ្ហភាពកំណត់ក្នុងរយៈពេលកំណត់បាន។ សូមពិនិត្យថាអាដាប់ទ័រដែលកំពុងប្រើ បញ្ចេញភ្លើងបានតាមតម្រូវការ 5V 3A ឬអត់ ហើយសាកល្បងប្តូរអាដាប់ទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-12-Q03','DA-12','Device Alarm','What adapter output does the device need?','តើម៉ាស៊ីនត្រូវការអាដាប់ទ័របញ្ចេញភ្លើងប៉ុន្មាន?','The adapter must meet the 5V 3A output requirement.','អាដាប់ទ័រត្រូវតែបញ្ចេញភ្លើងបានតាមតម្រូវការ 5V 3A។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-12-Q04','DA-12','Device Alarm','Should I change the adapter if it alarms while warming up?','តើខ្ញុំគួរប្តូរអាដាប់ទ័រទេ បើវារោទិ៍ពេលកំពុងកម្តៅ?','Yes. Check whether the adapter meets the 5V 3A output requirement, and try replacing the adapter.','បាទ/ចាស។ សូមពិនិត្យថាអាដាប់ទ័របញ្ចេញភ្លើងបានតាមតម្រូវការ 5V 3A ឬអត់ ហើយសាកល្បងប្តូរអាដាប់ទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-12-Q05','DA-12','Device Alarm','Beep beep before the blue light comes','ប៊ីបៗ មុនពេលភ្លើងខៀវឡើង','An alarm during warm-up means the instrument''s power supply is too low to reach the set temperature within the specified time. Check whether the adapter in use meets the 5V 3A output requirement, and try replacing the adapter.','ការរោទិ៍ពេលកំពុងកម្តៅ មានន័យថាភ្លើងចូលម៉ាស៊ីនខ្សោយពេក មិនអាចឡើងដល់សីតុណ្ហភាពកំណត់ក្នុងរយៈពេលកំណត់បាន។ សូមពិនិត្យថាអាដាប់ទ័រដែលកំពុងប្រើ បញ្ចេញភ្លើងបានតាមតម្រូវការ 5V 3A ឬអត់ ហើយសាកល្បងប្តូរអាដាប់ទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-13','DA-13','Device Alarm','Red light flashes for a long time, blue light never comes on, sometimes with beeping','ភ្លើងក្រហមលោតយូរ ភ្លើងខៀវមិនឡើងសោះ ហើយពេលខ្លះម៉ាស៊ីនរោទិ៍។ ត្រូវធ្វើម៉េច?','"Long-flashing red light, no blue light, cannot start testing" means the device has not reached the preset temperature for a long time (over 5 minutes), so testing cannot proceed. This involves one or more of: external power supply, temperature sensor, heating module, temperature control module, or fuse.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-13-Q01','DA-13','Device Alarm','Red light has been flashing for 10 minutes and it never turns blue. What do I do?','ភ្លើងក្រហមលោតអស់ 10 នាទីហើយ មិនប្តូរជាពណ៌ខៀវសោះ។ តើខ្ញុំត្រូវធ្វើអ្វី?','1. Check that the power and data cables are not swapped — the original adapter connects to the round power cable;
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-13-Q02','DA-13','Device Alarm','never ready, red light only','មិនរួចរាល់សោះ មានតែភ្លើងក្រហម','"Long-flashing red light, no blue light, cannot start testing" means the device has not reached the preset temperature for a long time (over 5 minutes), so testing cannot proceed. This involves one or more of: external power supply, temperature sensor, heating module, temperature control module, or fuse.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-13-Q03','DA-13','Device Alarm','It happened the first time I switched on after delivery, but now it''s fine after restarting. Is that OK?','វាកើតឡើងលើកដំបូងដែលខ្ញុំបើកម៉ាស៊ីនក្រោយទទួលបាន តែឥឡូវល្អវិញក្រោយបិទបើកឡើងវិញ។ តើមិនអីទេ?','Yes. If it happens at the first power-on but returns to normal after powering off and restarting, it is usually a parasitic capacitance effect related to environmental changes after long-distance transport.','បាទ/ចាស។ បើវាកើតឡើងពេលបើកលើកដំបូង តែត្រឡប់មកធម្មតាវិញក្រោយបិទ និងបើកឡើងវិញ ជាធម្មតាវាជាឥទ្ធិពលនៃកាប៉ាស៊ីតង់ប៉ារ៉ាស៊ីត (parasitic capacitance) ដែលទាក់ទងនឹងការប្រែប្រួលបរិស្ថាន ក្រោយការដឹកជញ្ជូនចម្ងាយឆ្ងាយ។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-13-Q04','DA-13','Device Alarm','Can I use my phone charger instead of the Pluslife adapter?','អាចប្រើឆ្នាំងសាកទូរស័ព្ទ ជំនួសអាដាប់ទ័រ Pluslife បានទេ?','No. Pluslife adapters are dedicated adapters and should not be replaced casually. To rule out a problem with the original adapter, you can test with a 5V-output adapter of more than 20W.','មិនបានទេ។ អាដាប់ទ័រ Pluslife ជាអាដាប់ទ័រសម្រាប់ប្រើជាមួយម៉ាស៊ីននេះដោយឡែក ហើយមិនគួរប្តូរដោយធ្វេសប្រហែសទេ។ ដើម្បីពិនិត្យថាអាដាប់ទ័រដើមមានបញ្ហាឬអត់ អ្នកអាចសាកល្បងជាមួយអាដាប់ទ័រដែលបញ្ចេញ 5V លើសពី 20W។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-13-Q05','DA-13','Device Alarm','Could I have plugged the cables the wrong way?','អាចដោតខ្សែខុសទេ?','Yes, that is possible. Check that the data cable and power cable are not swapped — the original adapter connects to the round power cable.','បាទ/ចាស អាចទៅរួច។ សូមពិនិត្យថាខ្សែទិន្នន័យ និងខ្សែភ្លើងមិនបានដោតច្រឡំគ្នា — អាដាប់ទ័រដើមត្រូវភ្ជាប់ទៅខ្សែភ្លើងក្បាលមូល។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-13-Q06','DA-13','Device Alarm','Can I use a multi-port charger?','អាចប្រើឆ្នាំងសាកដែលមានរន្ធច្រើនបានទេ?','Not sure. If a multi-port adapter is used as a substitute, note that when other appliances are drawing power, each port''s output may be insufficient, which can also cause power problems for the instrument.','មិនប្រាកដទេ។ បើប្រើអាដាប់ទ័រច្រើនរន្ធជំនួស សូមចំណាំថា ពេលឧបករណ៍ផ្សេងទៀតកំពុងប្រើភ្លើង ភ្លើងចេញពីរន្ធនីមួយៗអាចមិនគ្រប់គ្រាន់ ដែលក៏អាចបង្កបញ្ហាភ្លើងដល់ម៉ាស៊ីនដែរ។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-13-Q07','DA-13','Device Alarm','Nothing works, still red flashing. Does it need repair?','ធ្វើអ្វីក៏មិនបាន នៅតែភ្លើងក្រហមលោត។ តើវាត្រូវជួសជុលទេ?','Yes. If all of the above have been ruled out, at least one of the temperature sensor, heating module, temperature control module or fuse has likely failed, and the device must be returned to the factory for repair. For devices under warranty, Pluslife will replace the device with one of the same model instead of repairing it.','បាទ/ចាស។ បើបានពិនិត្យអស់ចំណុចខាងលើរួចហើយ ទំនងជាយ៉ាងហោចណាស់ផ្នែកមួយក្នុងចំណោម ឧបករណ៍ចាប់សីតុណ្ហភាព (temperature sensor) ម៉ូឌុលកម្តៅ ម៉ូឌុលគ្រប់គ្រងសីតុណ្ហភាព ឬហ្វុយស៊ីប (fuse) បានខូច ហើយម៉ាស៊ីនត្រូវតែបញ្ជូនត្រឡប់ទៅរោងចក្រដើម្បីជួសជុល។ សម្រាប់ម៉ាស៊ីនដែលនៅក្នុងរយៈពេលធានា Pluslife នឹងប្តូរម៉ាស៊ីនម៉ូដែលដូចគ្នាឱ្យ ជំនួសការជួសជុល។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-14','DA-14','Device Alarm','Device beeps and power light flashes red during a test','ពេលកំពុងធ្វើតេស្ត ម៉ាស៊ីនរោទិ៍ ហើយភ្លើងប៊ូតុងបើកបិទលោតពណ៌ក្រហម។ ត្រូវធ្វើម៉េច?','A flashing red light during testing indicates unstable voltage or that the device temperature has exceeded the set range. Possible causes include using a non-standard power supply, device overheating, or a damaged power adapter.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-14-Q01','DA-14','Device Alarm','The device started beeping in the middle of the test. What does it mean?','ម៉ាស៊ីនចាប់ផ្តើមរោទិ៍ ពាក់កណ្តាលតេស្ត។ តើវាមានន័យថាម៉េច?','A flashing red light during testing indicates unstable voltage or that the device temperature has exceeded the set range. Possible causes include using a non-standard power supply, device overheating, or a damaged power adapter.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-14-Q02','DA-14','Device Alarm','Can the test continue if it recovers by itself?','តើតេស្តអាចបន្តបានទេ បើវាត្រឡប់មកធម្មតាវិញដោយខ្លួនឯង?','Yes. If the instrument automatically recovers within 2 minutes, testing can continue.','បាទ/ចាស។ បើម៉ាស៊ីនត្រឡប់មកធម្មតាវិញដោយស្វ័យប្រវត្តិក្នុងរយៈពេល 2 នាទី អាចបន្តធ្វើតេស្តបាន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-14-Q03','DA-14','Device Alarm','red flash during test','ភ្លើងក្រហមលោត ពេលកំពុងធ្វើតេស្ត','A flashing red light during testing indicates unstable voltage or that the device temperature has exceeded the set range. Possible causes include using a non-standard power supply, device overheating, or a damaged power adapter.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-14-Q04','DA-14','Device Alarm','It has been beeping for 3 minutes during the test.','វារោទិ៍អស់ 3 នាទីហើយ ពេលកំពុងធ្វើតេស្ត។ ត្រូវធ្វើម៉េច?','If it does not recover within 2 minutes, stop testing and identify the cause. Possible causes include using a non-standard power supply, device overheating, or a damaged power adapter.','បើវាមិនត្រឡប់មកធម្មតាវិញក្នុងរយៈពេល 2 នាទីទេ សូមបញ្ឈប់ការធ្វើតេស្ត ហើយរកមូលហេតុ។ មូលហេតុដែលអាចកើតមានរួមមាន៖ ប្រើប្រភពភ្លើងមិនត្រឹមត្រូវតាមស្តង់ដារ ម៉ាស៊ីនក្តៅពេក ឬអាដាប់ទ័រភ្លើងខូច។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-14-Q05','DA-14','Device Alarm','Should I stop the test when the red light flashes?','តើខ្ញុំគួរបញ្ឈប់តេស្តទេ ពេលភ្លើងក្រហមលោត?','Not right away. If the instrument automatically recovers within 2 minutes, testing can continue. If it does not recover, stop testing and identify the cause.','មិនទាន់ភ្លាមៗទេ។ បើម៉ាស៊ីនត្រឡប់មកធម្មតាវិញដោយស្វ័យប្រវត្តិក្នុងរយៈពេល 2 នាទី អាចបន្តធ្វើតេស្តបាន។ បើវាមិនត្រឡប់មកធម្មតាវិញទេ សូមបញ្ឈប់ការធ្វើតេស្ត ហើយរកមូលហេតុ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-15','DA-15','Device Alarm','Card inserted into the Ultra, test does not start and the device beeps','ដាក់កាតក្នុង MiniDock Ultra ហើយ តេស្តមិនចាប់ផ្តើម ថែមទាំងរោទិ៍។ ត្រូវធ្វើម៉េច?','1. Check whether the QR code on the card is damaged or offset, and reinsert it for the test;
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-15-Q01','DA-15','Device Alarm','I put the card in the Ultra, it beeped and the test didn''t start.','ខ្ញុំដាក់កាតចូល Ultra វារោទិ៍ ហើយតេស្តមិនចាប់ផ្តើម។ ត្រូវធ្វើម៉េច?','1. Check whether the QR code on the card is damaged or offset, and reinsert it for the test;
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-15-Q02','DA-15','Device Alarm','card inside but no start, beep','កាតនៅខាងក្នុង តែមិនចាប់ផ្តើម មានសំឡេងប៊ីប','1. Check whether the QR code on the card is damaged or offset, and reinsert it for the test;
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-15-Q03','DA-15','Device Alarm','I put the card in the Ultra, it beeped and the test didn''t start. Should I take the card out and put it in again?','ខ្ញុំដាក់កាតចូល Ultra វារោទិ៍ ហើយតេស្តមិនចាប់ផ្តើម។ តើខ្ញុំគួរដកកាតចេញ ហើយដាក់ចូលវិញទេ?','Yes. Check whether the QR code on the card is damaged or offset, and reinsert it for the test.','បាទ/ចាស។ ពិនិត្យថាកូដ QR លើកាតខូច ឬបិទលៀនឬអត់ ហើយដាក់កាតចូលម្តងទៀតដើម្បីធ្វើតេស្ត។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-15-Q04','DA-15','Device Alarm','How do I know if the scanner is broken?','តើខ្ញុំដឹងយ៉ាងម៉េចថាឧបករណ៍ស្កេនខូច?','Use another card to test whether the scanner can read the code, and record a video. If it still fails, contact the vendor with the video and instrument serial number and request a replacement.','ប្រើកាតមួយផ្សេងទៀត ដើម្បីសាកថាឧបករណ៍ស្កេនអាចអានកូដបានឬអត់ ហើយថតវីដេអូទុក។ បើនៅតែមិនបាន សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅអ្នកផ្គត់ផ្គង់ (vendor) ដោយភ្ជាប់វីដេអូ និងលេខសម្គាល់ម៉ាស៊ីន (serial number) ហើយស្នើសុំប្តូរ។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-15-Q05','DA-15','Device Alarm','What info do I send to the vendor?','តើខ្ញុំត្រូវផ្ញើព័ត៌មានអ្វីខ្លះទៅអ្នកផ្គត់ផ្គង់?','Attach the problem video and the instrument serial number, and request a replacement.','ភ្ជាប់វីដេអូបញ្ហា និងលេខសម្គាល់ម៉ាស៊ីន (serial number) ហើយស្នើសុំប្តូរ។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-16','DA-16','Device Alarm','Device beeps at power-on (RTC / real-time clock error)','ទើបបើកម៉ាស៊ីន វាក៏រោទិ៍ ហើយបង្ហាញបញ្ហា RTC។ ត្រូវធ្វើម៉េច?','The device mainboard has a built-in rechargeable battery. After long-term storage, this battery may lose charge, causing an RTC (real-time clock) error and beeping at power-on.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-16-Q01','DA-16','Device Alarm','The device beeps as soon as I turn it on. Why?','ម៉ាស៊ីនរោទិ៍ ភ្លាមៗពេលខ្ញុំបើកវា។ ហេតុអ្វី?','One possible cause: The device mainboard has a built-in rechargeable battery. After long-term storage, this battery may lose charge, causing an RTC (real-time clock) error and beeping at power-on.','មូលហេតុមួយដែលអាចកើតមាន៖ បន្ទះមេ (mainboard) របស់ម៉ាស៊ីន មានថ្មសាកបានមួយនៅខាងក្នុង។ ក្រោយទុកចោលយូរ ថ្មនេះអាចអស់ ធ្វើឱ្យមានកំហុស RTC (នាឡិកាពេលវេលាពិត) ហើយរោទិ៍ពេលបើកម៉ាស៊ីន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-16-Q02','DA-16','Device Alarm','We stored the device for months and now it beeps at start-up.','យើងទុកម៉ាស៊ីនចោលច្រើនខែ ហើយឥឡូវវារោទិ៍ពេលបើក។ ត្រូវធ្វើម៉េច?','The device mainboard has a built-in rechargeable battery. After long-term storage, this battery may lose charge, causing an RTC (real-time clock) error and beeping at power-on. Connect the power adapter and turn the device on so the built-in battery charges automatically; while charging, sync the time via the computer software or mobile app. If it keeps beeping, keep the power and software/app connected and restart the instrument once.','បន្ទះមេ (mainboard) របស់ម៉ាស៊ីន មានថ្មសាកបានមួយនៅខាងក្នុង។ ក្រោយទុកចោលយូរ ថ្មនេះអាចអស់ ធ្វើឱ្យមានកំហុស RTC (នាឡិកាពេលវេលាពិត) ហើយរោទិ៍ពេលបើកម៉ាស៊ីន។ ភ្ជាប់អាដាប់ទ័រភ្លើង ហើយបើកម៉ាស៊ីន ដើម្បីឱ្យថ្មខាងក្នុងសាកដោយស្វ័យប្រវត្តិ។ ពេលកំពុងសាក សូមធ្វើសមកាលកម្មម៉ោង (sync time) តាមកម្មវិធីកុំព្យូទ័រ ឬ App ទូរស័ព្ទ។ បើនៅតែរោទិ៍ សូមទុកភ្លើង និងកម្មវិធី/App ឱ្យនៅភ្ជាប់ ហើយបិទបើកម៉ាស៊ីនឡើងវិញម្តង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-16-Q03','DA-16','Device Alarm','How do I fix an RTC error?','តើខ្ញុំដោះស្រាយកំហុស RTC យ៉ាងម៉េច?','Connect the power adapter and turn the device on so the built-in battery charges automatically; while charging, sync the time via the computer software or mobile app. If it keeps beeping, keep the power and software/app connected and restart the instrument once.','ភ្ជាប់អាដាប់ទ័រភ្លើង ហើយបើកម៉ាស៊ីន ដើម្បីឱ្យថ្មខាងក្នុងសាកដោយស្វ័យប្រវត្តិ។ ពេលកំពុងសាក សូមធ្វើសមកាលកម្មម៉ោង (sync time) តាមកម្មវិធីកុំព្យូទ័រ ឬ App ទូរស័ព្ទ។ បើនៅតែរោទិ៍ សូមទុកភ្លើង និងកម្មវិធី/App ឱ្យនៅភ្ជាប់ ហើយបិទបើកម៉ាស៊ីនឡើងវិញម្តង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-16-Q04','DA-16','Device Alarm','RTC error','អេក្រង់ឡើង កំហុស RTC។ មានន័យថាម៉េច?','Connect the power adapter and turn the device on so the built-in battery charges automatically; while charging, sync the time via the computer software or mobile app. If it keeps beeping, keep the power and software/app connected and restart the instrument once.','ភ្ជាប់អាដាប់ទ័រភ្លើង ហើយបើកម៉ាស៊ីន ដើម្បីឱ្យថ្មខាងក្នុងសាកដោយស្វ័យប្រវត្តិ។ ពេលកំពុងសាក សូមធ្វើសមកាលកម្មម៉ោង (sync time) តាមកម្មវិធីកុំព្យូទ័រ ឬ App ទូរស័ព្ទ។ បើនៅតែរោទិ៍ សូមទុកភ្លើង និងកម្មវិធី/App ឱ្យនៅភ្ជាប់ ហើយបិទបើកម៉ាស៊ីនឡើងវិញម្តង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-16-Q05','DA-16','Device Alarm','Still beeping after I synced the time.','នៅតែរោទិ៍ ក្រោយខ្ញុំធ្វើសមកាលកម្មម៉ោងរួច។ ត្រូវធ្វើម៉េច?','Keep the power and software/app connected and restart the instrument once.','ទុកភ្លើង និងកម្មវិធី/App ឱ្យនៅភ្ជាប់ ហើយបិទបើកម៉ាស៊ីនឡើងវិញម្តង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-16-Q06','DA-16','Device Alarm','Do I need to connect the app to fix the clock error?','តើខ្ញុំត្រូវភ្ជាប់ កម្មវិធី ដើម្បីដោះស្រាយកំហុសម៉ោងទេ?','Yes. While the battery charges, sync the time via the computer software or mobile app.','បាទ/ចាស។ ពេលថ្មកំពុងសាក សូមធ្វើសមកាលកម្មម៉ោង (sync time) តាមកម្មវិធីកុំព្យូទ័រ ឬ App ទូរស័ព្ទ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-17','DA-17','Device Alarm','MiniDock Ultra shows error code 1 (Temperature abnormality)','MiniDock Ultra ចេញកូដ 1។ តើមានបញ្ហាអ្វីជាមួយសីតុណ្ហភាព?','Error code 1 on the MiniDock Ultra means: Temperature abnormality. Possible cause(s): over temperature; low temperature; loose sensor wiring.','លេខកូដកំហុស 1 លើ MiniDock Ultra មានន័យថា៖ សីតុណ្ហភាពមិនប្រក្រតី (Temperature abnormality)។ មូលហេតុដែលអាចកើតមាន៖ សីតុណ្ហភាពខ្ពស់ពេក សីតុណ្ហភាពទាបពេក ខ្សែឧបករណ៍ចាប់សីតុណ្ហភាព (sensor) រលុង។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-17-Q01','DA-17','Device Alarm','What does error code 1 mean?','តើលេខកូដកំហុស 1 មានន័យថាម៉េច?','Error code 1 on the MiniDock Ultra means: Temperature abnormality. Possible cause(s): over temperature; low temperature; loose sensor wiring.','លេខកូដកំហុស 1 លើ MiniDock Ultra មានន័យថា៖ សីតុណ្ហភាពមិនប្រក្រតី (Temperature abnormality)។ មូលហេតុដែលអាចកើតមាន៖ សីតុណ្ហភាពខ្ពស់ពេក សីតុណ្ហភាពទាបពេក ខ្សែឧបករណ៍ចាប់សីតុណ្ហភាព (sensor) រលុង។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-17-Q02','DA-17','Device Alarm','error 1','អេក្រង់ឡើង កំហុស 1។ មានន័យថាម៉េច?','Error code 1 on the MiniDock Ultra means: Temperature abnormality. Possible cause(s): over temperature; low temperature; loose sensor wiring.','លេខកូដកំហុស 1 លើ MiniDock Ultra មានន័យថា៖ សីតុណ្ហភាពមិនប្រក្រតី (Temperature abnormality)។ មូលហេតុដែលអាចកើតមាន៖ សីតុណ្ហភាពខ្ពស់ពេក សីតុណ្ហភាពទាបពេក ខ្សែឧបករណ៍ចាប់សីតុណ្ហភាព (sensor) រលុង។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-17-Q03','DA-17','Device Alarm','The device shows error 1. What''s the cause?','ម៉ាស៊ីនបង្ហាញកំហុស 1។ តើមូលហេតុអ្វី?','Error code 1 on the MiniDock Ultra means: Temperature abnormality. Possible cause(s): over temperature; low temperature; loose sensor wiring.','លេខកូដកំហុស 1 លើ MiniDock Ultra មានន័យថា៖ សីតុណ្ហភាពមិនប្រក្រតី (Temperature abnormality)។ មូលហេតុដែលអាចកើតមាន៖ សីតុណ្ហភាពខ្ពស់ពេក សីតុណ្ហភាពទាបពេក ខ្សែឧបករណ៍ចាប់សីតុណ្ហភាព (sensor) រលុង។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-17-Q04','DA-17','Device Alarm','Error 1 — what should I do?','កំហុស 1 — តើខ្ញុំត្រូវធ្វើអ្វី?','Not sure. Error code 1 means: Temperature abnormality. Possible cause(s): over temperature; low temperature; loose sensor wiring. No action is stated for this code; contact the study focal point.','មិនប្រាកដទេ។ លេខកូដកំហុស 1 មានន័យថា៖ សីតុណ្ហភាពមិនប្រក្រតី (Temperature abnormality)។ មូលហេតុដែលអាចកើតមាន៖ សីតុណ្ហភាពខ្ពស់ពេក សីតុណ្ហភាពទាបពេក ខ្សែឧបករណ៍ចាប់សីតុណ្ហភាព (sensor) រលុង។ មិនមានការណែនាំអំពីវិធីដោះស្រាយសម្រាប់កូដនេះទេ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-18','DA-18','Device Alarm','MiniDock Ultra shows error code 2 (DC power 5V under-voltage)','MiniDock Ultra ចេញកូដ 2។ តើមានន័យថាវ៉ុល DC 5V ទាបពេកមែនទេ?','Error code 2 on the MiniDock Ultra means: DC power 5V under-voltage. Possible cause(s): oxidized power supply wires, low voltage due to high voltage drop; power supply out of specification.','លេខកូដកំហុស 2 លើ MiniDock Ultra មានន័យថា៖ ភ្លើង DC 5V ខ្សោយពេក (DC power 5V under-voltage)។ មូលហេតុដែលអាចកើតមាន៖ ខ្សែភ្លើងច្រេះ (oxidized) ភ្លើងធ្លាក់ចុះខ្លាំង ធ្វើឱ្យវ៉ុលទាប ប្រភពភ្លើងមិនត្រឹមត្រូវតាមលក្ខណៈបច្ចេកទេស។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-18-Q01','DA-18','Device Alarm','What does error code 2 mean?','តើលេខកូដកំហុស 2 មានន័យថាម៉េច?','Error code 2 on the MiniDock Ultra means: DC power 5V under-voltage. Possible cause(s): oxidized power supply wires, low voltage due to high voltage drop; power supply out of specification.','លេខកូដកំហុស 2 លើ MiniDock Ultra មានន័យថា៖ ភ្លើង DC 5V ខ្សោយពេក (DC power 5V under-voltage)។ មូលហេតុដែលអាចកើតមាន៖ ខ្សែភ្លើងច្រេះ (oxidized) ភ្លើងធ្លាក់ចុះខ្លាំង ធ្វើឱ្យវ៉ុលទាប ប្រភពភ្លើងមិនត្រឹមត្រូវតាមលក្ខណៈបច្ចេកទេស។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-18-Q02','DA-18','Device Alarm','error 2','អេក្រង់ឡើង កំហុស 2។ មានន័យថាម៉េច?','Error code 2 on the MiniDock Ultra means: DC power 5V under-voltage. Possible cause(s): oxidized power supply wires, low voltage due to high voltage drop; power supply out of specification.','លេខកូដកំហុស 2 លើ MiniDock Ultra មានន័យថា៖ ភ្លើង DC 5V ខ្សោយពេក (DC power 5V under-voltage)។ មូលហេតុដែលអាចកើតមាន៖ ខ្សែភ្លើងច្រេះ (oxidized) ភ្លើងធ្លាក់ចុះខ្លាំង ធ្វើឱ្យវ៉ុលទាប ប្រភពភ្លើងមិនត្រឹមត្រូវតាមលក្ខណៈបច្ចេកទេស។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-18-Q03','DA-18','Device Alarm','The device shows error 2. What''s the cause?','ម៉ាស៊ីនបង្ហាញកំហុស 2។ តើមូលហេតុអ្វី?','Error code 2 on the MiniDock Ultra means: DC power 5V under-voltage. Possible cause(s): oxidized power supply wires, low voltage due to high voltage drop; power supply out of specification.','លេខកូដកំហុស 2 លើ MiniDock Ultra មានន័យថា៖ ភ្លើង DC 5V ខ្សោយពេក (DC power 5V under-voltage)។ មូលហេតុដែលអាចកើតមាន៖ ខ្សែភ្លើងច្រេះ (oxidized) ភ្លើងធ្លាក់ចុះខ្លាំង ធ្វើឱ្យវ៉ុលទាប ប្រភពភ្លើងមិនត្រឹមត្រូវតាមលក្ខណៈបច្ចេកទេស។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-18-Q04','DA-18','Device Alarm','Error 2 — what should I do?','កំហុស 2 — តើខ្ញុំត្រូវធ្វើអ្វី?','Not sure. Error code 2 means: DC power 5V under-voltage. Possible cause(s): oxidized power supply wires, low voltage due to high voltage drop; power supply out of specification. No action is stated for this code; contact the study focal point.','មិនប្រាកដទេ។ លេខកូដកំហុស 2 មានន័យថា៖ ភ្លើង DC 5V ខ្សោយពេក (DC power 5V under-voltage)។ មូលហេតុដែលអាចកើតមាន៖ ខ្សែភ្លើងច្រេះ (oxidized) ភ្លើងធ្លាក់ចុះខ្លាំង ធ្វើឱ្យវ៉ុលទាប ប្រភពភ្លើងមិនត្រឹមត្រូវតាមលក្ខណៈបច្ចេកទេស។ មិនមានការណែនាំអំពីវិធីដោះស្រាយសម្រាប់កូដនេះទេ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-18-Q05','DA-18','Device Alarm','Can a bad adapter cause error 2?','តើអាដាប់ទ័រខូច អាចបង្កកំហុស 2 បានទេ?','Yes. A power supply out of specification is one cause of error 2 (DC power 5V under-voltage).','បាទ/ចាស។ ប្រភពភ្លើងមិនត្រឹមត្រូវតាមលក្ខណៈបច្ចេកទេស គឺជាមូលហេតុមួយនៃកំហុស 2 (ភ្លើង DC 5V ខ្សោយពេក)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-19','DA-19','Device Alarm','MiniDock Ultra shows error code 3 (DC power 5V over-voltage)','MiniDock Ultra ចេញកូដ 3។ តើមានន័យថាវ៉ុល DC 5V ខ្ពស់ពេកមែនទេ?','Error code 3 on the MiniDock Ultra means: DC power 5V over-voltage. Possible cause(s): damaged power adapter.','លេខកូដកំហុស 3 លើ MiniDock Ultra មានន័យថា៖ ភ្លើង DC 5V ខ្លាំងពេក (DC power 5V over-voltage)។ មូលហេតុដែលអាចកើតមាន៖ អាដាប់ទ័រភ្លើងខូច។','Routine','Study focal point → Pluslife');
