INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-20','DA-20','Device Alarm','MiniDock Ultra shows error code 7 (Heating timeout)','MiniDock Ultra ចេញកូដ 7 ពេលកំពុងកម្តៅ។ ត្រូវធ្វើម៉េច?','Error code 7 on the MiniDock Ultra means: Heating timeout. Possible cause(s): heating module damaged; power adapter out of specification.','លេខកូដកំហុស 7 លើ MiniDock Ultra មានន័យថា៖ កម្តៅហួសពេល (Heating timeout)។ មូលហេតុដែលអាចកើតមាន៖ ម៉ូឌុលកម្តៅខូច អាដាប់ទ័រភ្លើងមិនត្រឹមត្រូវតាមលក្ខណៈបច្ចេកទេស។','Routine','Study focal point → Pluslife');
