INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-25-Q01','DA-25','Device Alarm','What does error code ER01 mean?','តើលេខកូដកំហុស ER01 មានន័យថាម៉េច?','Error code ER01 on the Thermolyse WD002 means: Temperature sensor abnormal. Possible cause(s): temperature sensor malfunction.','លេខកូដកំហុស ER01 លើ Thermolyse WD002 មានន័យថា៖ ឧបករណ៍ចាប់សីតុណ្ហភាពមិនប្រក្រតី (Temperature sensor abnormal)។ មូលហេតុដែលអាចកើតមាន៖ ឧបករណ៍ចាប់សីតុណ្ហភាព (temperature sensor) ខូច។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-25-Q02','DA-25','Device Alarm','error ER01','អេក្រង់ឡើង កំហុស ER01។ មានន័យថាម៉េច?','Error code ER01 on the Thermolyse WD002 means: Temperature sensor abnormal. Possible cause(s): temperature sensor malfunction.','លេខកូដកំហុស ER01 លើ Thermolyse WD002 មានន័យថា៖ ឧបករណ៍ចាប់សីតុណ្ហភាពមិនប្រក្រតី (Temperature sensor abnormal)។ មូលហេតុដែលអាចកើតមាន៖ ឧបករណ៍ចាប់សីតុណ្ហភាព (temperature sensor) ខូច។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-25-Q03','DA-25','Device Alarm','The device shows error ER01. What''s the cause?','ម៉ាស៊ីនបង្ហាញកំហុស ER01។ តើមូលហេតុអ្វី?','Error code ER01 on the Thermolyse WD002 means: Temperature sensor abnormal. Possible cause(s): temperature sensor malfunction.','លេខកូដកំហុស ER01 លើ Thermolyse WD002 មានន័យថា៖ ឧបករណ៍ចាប់សីតុណ្ហភាពមិនប្រក្រតី (Temperature sensor abnormal)។ មូលហេតុដែលអាចកើតមាន៖ ឧបករណ៍ចាប់សីតុណ្ហភាព (temperature sensor) ខូច។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DA-25-Q04','DA-25','Device Alarm','Error ER01 — what should I do?','កំហុស ER01 — តើខ្ញុំត្រូវធ្វើអ្វី?','Not sure. Error code ER01 means: Temperature sensor abnormal. Possible cause(s): temperature sensor malfunction. No action is stated for this code; contact the study focal point.','មិនប្រាកដទេ។ លេខកូដកំហុស ER01 មានន័យថា៖ ឧបករណ៍ចាប់សីតុណ្ហភាពមិនប្រក្រតី (Temperature sensor abnormal)។ មូលហេតុដែលអាចកើតមាន៖ ឧបករណ៍ចាប់សីតុណ្ហភាព (temperature sensor) ខូច។ មិនមានការណែនាំអំពីវិធីដោះស្រាយសម្រាប់កូដនេះទេ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-10','MO-10','Mis-operation','Worker wants to retest the same card (immediately or after an invalid result)','បើតេស្តចេញ Invalid ឬចង់តេស្តម្តងទៀតភ្លាមៗ អាចប្រើកាតដដែលទេ?','After testing, a card should be disposed of as medical waste; the same card cannot be tested again.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-10-Q01','MO-10','Mis-operation','Can I test the same card again straight away?','អាចធ្វើតេស្តកាតដដែលម្តងទៀតភ្លាមៗបានទេ?','No. After testing, a card should be disposed of as medical waste; the same card cannot be tested again.','មិនបានទេ។ ក្រោយធ្វើតេស្ត កាតត្រូវបោះចោលជាកាកសំណល់វេជ្ជសាស្ត្រ។ មិនអាចធ្វើតេស្តកាតដដែលម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-10-Q02','MO-10','Mis-operation','The result was invalid. Can I reload the same card?','លទ្ធផលចេញ Invalid ។ អាចដាក់កាតដដែលចូលវិញបានទេ?','No. Do not reload a used card for retesting. If you reload the same card after an invalid result, the result will most likely still be invalid.','មិនបានទេ។ កុំដាក់កាតដែលប្រើរួចចូលវិញដើម្បីធ្វើតេស្តម្តងទៀត។ បើដាក់កាតដដែលចូលវិញ ក្រោយលទ្ធផលគ្មានសុពលភាព លទ្ធផលទំនងជានៅតែគ្មានសុពលភាពដដែល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-10-Q03','MO-10','Mis-operation','Why can''t I reuse the card if it was invalid?','ហេតុអ្វីបានជាខ្ញុំមិនអាចប្រើកាតម្តងទៀត បើវាចេញ Invalid?','In a used card, the beads have been consumed and have already undergone isothermal amplification in the instrument, so reuse is meaningless.','ក្នុងកាតដែលប្រើរួច គ្រាប់សារធាតុ (beads) ត្រូវបានប្រើអស់ ហើយបានឆ្លងកាត់ការពង្រីកសីតុណ្ហភាពថេរ (isothermal amplification) ក្នុងម៉ាស៊ីនរួចហើយ ដូច្នេះការប្រើម្តងទៀតគ្មានប្រយោជន៍ទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-10-Q04','MO-10','Mis-operation','How do I dispose of a tested card?','តើខ្ញុំបោះចោលកាតដែលធ្វើតេស្តរួចយ៉ាងម៉េច?','Dispose of it as medical waste.','បោះចោលវាជាកាកសំណល់វេជ្ជសាស្ត្រ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-10-Q05','MO-10','Mis-operation','invalid card use again','កាតចេញ Invalid ប្រើម្តងទៀត','No. Every test card, whether the result was invalid or not, should be discarded.','មិនបានទេ។ កាតតេស្តគ្រប់សន្លឹក មិនថាលទ្ធផលគ្មានសុពលភាព ឬអត់ ត្រូវតែបោះចោល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-11','MO-11','Mis-operation','Tested card left inside the instrument','ខ្ញុំភ្លេចដកកាតដែលប្រើរួចចេញពីម៉ាស៊ីន។ ត្រូវធ្វើម៉េច?','We recommend not leaving the test card in the instrument. Although the cards are well sealed and pose no leak risk when undamaged, the instrument remains at a relatively high temperature in standby, and leaving the card inside for a long time may cause amplification products to leak.','យើងណែនាំកុំទុកកាតតេស្តនៅក្នុងម៉ាស៊ីន។ ទោះបីកាតត្រូវបានបិទជិតល្អ ហើយគ្មានហានិភ័យលេចធ្លាយពេលមិនខូចក៏ដោយ ម៉ាស៊ីននៅតែមានសីតុណ្ហភាពខ្ពស់ល្មមពេលរង់ចាំ (standby) ហើយការទុកកាតក្នុងម៉ាស៊ីនយូរ អាចធ្វើឱ្យផលិតផលនៃការពង្រីក (amplification products) លេចធ្លាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-11-Q01','MO-11','Mis-operation','Can I leave the card in the device after the test?','អាចទុកកាតក្នុងម៉ាស៊ីន ក្រោយធ្វើតេស្តរួចបានទេ?','No, it is not recommended. Although the cards are well sealed and pose no leak risk when undamaged, the instrument remains at a relatively high temperature in standby, and leaving the card inside for a long time may cause amplification products to leak.','មិនបានទេ មិនណែនាំទេ។ ទោះបីកាតត្រូវបានបិទជិតល្អ ហើយគ្មានហានិភ័យលេចធ្លាយពេលមិនខូចក៏ដោយ ម៉ាស៊ីននៅតែមានសីតុណ្ហភាពខ្ពស់ល្មមពេលរង់ចាំ (standby) ហើយការទុកកាតក្នុងម៉ាស៊ីនយូរ អាចធ្វើឱ្យផលិតផលនៃការពង្រីក (amplification products) លេចធ្លាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-11-Q02','MO-11','Mis-operation','I forgot the card in the device overnight.','ខ្ញុំភ្លេចកាតក្នុងម៉ាស៊ីនពេញមួយយប់។ ត្រូវធ្វើម៉េច?','We recommend not leaving the test card in the instrument. Although the cards are well sealed and pose no leak risk when undamaged, the instrument remains at a relatively high temperature in standby, and leaving the card inside for a long time may cause amplification products to leak.','យើងណែនាំកុំទុកកាតតេស្តនៅក្នុងម៉ាស៊ីន។ ទោះបីកាតត្រូវបានបិទជិតល្អ ហើយគ្មានហានិភ័យលេចធ្លាយពេលមិនខូចក៏ដោយ ម៉ាស៊ីននៅតែមានសីតុណ្ហភាពខ្ពស់ល្មមពេលរង់ចាំ (standby) ហើយការទុកកាតក្នុងម៉ាស៊ីនយូរ អាចធ្វើឱ្យផលិតផលនៃការពង្រីក (amplification products) លេចធ្លាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-11-Q03','MO-11','Mis-operation','card stay in machine ok?','ទុកកាតក្នុងម៉ាស៊ីន បានទេ?','No. Leaving the card inside for a long time may cause amplification products to leak.','មិនបានទេ។ ការទុកកាតក្នុងម៉ាស៊ីនយូរ អាចធ្វើឱ្យផលិតផលនៃការពង្រីក (amplification products) លេចធ្លាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-12','MO-12','Mis-operation','Lid opened during a test','ខ្ញុំបើកគម្របម៉ាស៊ីនពេលតេស្តកំពុងដំណើរការ។ ត្រូវធ្វើម៉េច?','Opening the lid during a test is strictly prohibited. With MiniDock Ultra, the instrument stops the test and reports an invalid result when the lid is opened.','ហាមដាច់ខាតមិនឱ្យបើកគម្របពេលកំពុងធ្វើតេស្ត។ ចំពោះ MiniDock Ultra ពេលបើកគម្រប ម៉ាស៊ីននឹងបញ្ឈប់តេស្ត ហើយរាយការណ៍លទ្ធផលគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-12-Q01','MO-12','Mis-operation','What happens if I open the lid during the test?','តើមានអ្វីកើតឡើង បើខ្ញុំបើកគម្របពេលកំពុងធ្វើតេស្ត?','With MiniDock Ultra, the instrument stops the test and reports an invalid result when the lid is opened. Opening the lid during a test is strictly prohibited.','ចំពោះ MiniDock Ultra ពេលបើកគម្រប ម៉ាស៊ីននឹងបញ្ឈប់តេស្ត ហើយរាយការណ៍លទ្ធផលគ្មានសុពលភាព។ ហាមដាច់ខាតមិនឱ្យបើកគម្របពេលកំពុងធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-12-Q02','MO-12','Mis-operation','I opened the lid by mistake. Will it continue if I close it?','ខ្ញុំបើកគម្របដោយច្រឡំ។ តើវានឹងបន្តទេ បើខ្ញុំបិទវាវិញ?','No. With MiniDock Ultra, the instrument stops the test and reports an invalid result when the lid is opened.','ទេ។ ចំពោះ MiniDock Ultra ពេលបើកគម្រប ម៉ាស៊ីននឹងបញ្ឈប់តេស្ត ហើយរាយការណ៍លទ្ធផលគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-12-Q03','MO-12','Mis-operation','open lid mid test','បើកគម្របពាក់កណ្តាលតេស្ត','Opening the lid during a test is strictly prohibited. With MiniDock Ultra, the instrument stops the test and reports an invalid result when the lid is opened.','ហាមដាច់ខាតមិនឱ្យបើកគម្របពេលកំពុងធ្វើតេស្ត។ ចំពោះ MiniDock Ultra ពេលបើកគម្រប ម៉ាស៊ីននឹងបញ្ឈប់តេស្ត ហើយរាយការណ៍លទ្ធផលគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MO-12-Q04','MO-12','Mis-operation','Can I check the card during the test?','អាចពិនិត្យមើលកាតពេលកំពុងធ្វើតេស្តបានទេ?','No. Opening the lid during a test is strictly prohibited.','មិនបានទេ។ ហាមដាច់ខាតមិនឱ្យបើកគម្របពេលកំពុងធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-05','PC-05','Power & Connectivity','Software shows the device as ''offline'' instead of ''online''','ហេតុអ្វីកម្មវិធីបង្ហាញថាម៉ាស៊ីន «offline» ជំនួសឱ្យ «online»?','Offline will not affect the result; just reconnect when you need to check the result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-05-Q01','PC-05','Power & Connectivity','PluslifePad says my device is offline. Will my result be lost?','PluslifePad បង្ហាញថាម៉ាស៊ីនរបស់ខ្ញុំ offline។ តើលទ្ធផលរបស់ខ្ញុំនឹងបាត់ទេ?','No. Offline will not affect the result; just reconnect when you need to check the result.','ទេ។ ស្ថានភាព Offline មិនប៉ះពាល់ដល់លទ្ធផលទេ។ គ្រាន់តែភ្ជាប់ឡើងវិញ ពេលអ្នកត្រូវការមើលលទ្ធផល។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-05-Q02','PC-05','Power & Connectivity','device show offline','ម៉ាស៊ីនបង្ហាញ offline','Offline will not affect the result; just reconnect when you need to check the result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-05-Q03','PC-05','Power & Connectivity','It goes offline when I use the cable.','វា offline ពេលខ្ញុំប្រើខ្សែ។ ត្រូវធ្វើម៉េច?','Port failures, loose connections, damaged data cables and aging adapters can all cause disconnections — check each part one by one.','រន្ធដោតខូច ការតភ្ជាប់រលុង ខ្សែទិន្នន័យខូច និងអាដាប់ទ័រចាស់ សុទ្ធតែអាចធ្វើឱ្យដាច់ការតភ្ជាប់ — សូមពិនិត្យផ្នែកនីមួយៗម្តងមួយៗ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-05-Q04','PC-05','Power & Connectivity','It keeps going offline on WiFi.','វា offline ជាញឹកញាប់ពេលប្រើ Wi‑Fi។ ត្រូវធ្វើម៉េច?','Possible causes: unstable network; the network configured for the instrument is different from the PC''s WiFi; firewalls or antivirus software block the software from the network. Check each part one by one or contact your agent or service@pluslife.com.','មូលហេតុដែលអាចកើតមាន៖ បណ្តាញមិនស្ថិរ បណ្តាញដែលកំណត់សម្រាប់ម៉ាស៊ីន ខុសពី WiFi របស់កុំព្យូទ័រ កម្មវិធីការពារ (firewall) ឬកម្មវិធីកម្ចាត់មេរោគ (antivirus) រារាំងកម្មវិធីមិនឱ្យចូលបណ្តាញ។ សូមពិនិត្យផ្នែកនីមួយៗម្តងមួយៗ ឬទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅភ្នាក់ងារ (agent) ឬ service@pluslife.com។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-05-Q05','PC-05','Power & Connectivity','Can antivirus cause the device to show offline?','តើកម្មវិធីកម្ចាត់មេរោគ (antivirus) អាចធ្វើឱ្យម៉ាស៊ីនបង្ហាញ offline បានទេ?','Yes, when connected by WiFi. Firewalls or antivirus software can prohibit the software from accessing the network.','បាទ/ចាស ពេលភ្ជាប់តាម WiFi។ កម្មវិធីការពារ (firewall) ឬកម្មវិធីកម្ចាត់មេរោគ (antivirus) អាចហាមមិនឱ្យកម្មវិធីចូលប្រើបណ្តាញ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-06','PC-06','Power & Connectivity','Worried the Ultra on WiFi will connect to another computer','បើ MiniDock Ultra ភ្ជាប់តាម Wi‑Fi តើធ្វើម៉េចកុំឱ្យវាភ្ជាប់ទៅកុំព្យូទ័រផ្សេងដោយច្រឡំ?','When configuring WiFi for the instrument, tick the "Bind device" option to bind the instrument to the computer and prevent it from connecting to other computers by mistake.','ពេលកំណត់ WiFi សម្រាប់ម៉ាស៊ីន សូមធីកជម្រើស "Bind device" ដើម្បីចងម៉ាស៊ីនជាប់នឹងកុំព្យូទ័រ ហើយការពារកុំឱ្យវាភ្ជាប់ទៅកុំព្យូទ័រផ្សេងដោយច្រឡំ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-06-Q01','PC-06','Power & Connectivity','Will the Ultra connect to other computers when using WiFi?','តើ Ultra នឹងភ្ជាប់ទៅកុំព្យូទ័រផ្សេង ពេលប្រើ Wi‑Fi ទេ?','Not if you bind it. When configuring WiFi for the instrument, tick the "Bind device" option to bind the instrument to the computer and prevent it from connecting to other computers by mistake.','មិនភ្ជាប់ទេ បើអ្នកចងវា។ ពេលកំណត់ WiFi សម្រាប់ម៉ាស៊ីន សូមធីកជម្រើស "Bind device" ដើម្បីចងម៉ាស៊ីនជាប់នឹងកុំព្យូទ័រ ហើយការពារកុំឱ្យវាភ្ជាប់ទៅកុំព្យូទ័រផ្សេងដោយច្រឡំ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-06-Q02','PC-06','Power & Connectivity','How do I stop the device from connecting to the other lab computer?','តើខ្ញុំធ្វើម៉េច ដើម្បីកុំឱ្យម៉ាស៊ីនភ្ជាប់ទៅកុំព្យូទ័រមួយទៀតក្នុងមន្ទីរពិសោធន៍?','When configuring WiFi for the instrument, tick the "Bind device" option to bind the instrument to the computer and prevent it from connecting to other computers by mistake.','ពេលកំណត់ WiFi សម្រាប់ម៉ាស៊ីន សូមធីកជម្រើស "Bind device" ដើម្បីចងម៉ាស៊ីនជាប់នឹងកុំព្យូទ័រ ហើយការពារកុំឱ្យវាភ្ជាប់ទៅកុំព្យូទ័រផ្សេងដោយច្រឡំ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-06-Q03','PC-06','Power & Connectivity','bind device wifi','ចងម៉ាស៊ីន (bind device) Wi‑Fi','When configuring WiFi for the instrument, tick the "Bind device" option to bind the instrument to the computer and prevent it from connecting to other computers by mistake.','ពេលកំណត់ WiFi សម្រាប់ម៉ាស៊ីន សូមធីកជម្រើស "Bind device" ដើម្បីចងម៉ាស៊ីនជាប់នឹងកុំព្យូទ័រ ហើយការពារកុំឱ្យវាភ្ជាប់ទៅកុំព្យូទ័រផ្សេងដោយច្រឡំ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-06-Q04','PC-06','Power & Connectivity','Is there a way to lock the device to one PC?','តើមានវិធីចាក់សោម៉ាស៊ីនឱ្យភ្ជាប់តែកុំព្យូទ័រមួយទេ?','Yes. When configuring WiFi for the instrument, tick the "Bind device" option to bind the instrument to the computer and prevent it from connecting to other computers by mistake.','បាទ/ចាស មាន។ ពេលកំណត់ WiFi សម្រាប់ម៉ាស៊ីន សូមធីកជម្រើស "Bind device" ដើម្បីចងម៉ាស៊ីនជាប់នឹងកុំព្យូទ័រ ហើយការពារកុំឱ្យវាភ្ជាប់ទៅកុំព្យូទ័រផ្សេងដោយច្រឡំ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-07','PC-07','Power & Connectivity','Worker asks how the MiniDock Ultra can connect','MiniDock Ultra អាចភ្ជាប់តាមវិធីណាខ្លះ?','MiniDock Ultra supports wired connection and WiFi connection to PC, and Bluetooth and WiFi connection to a mobile phone.','MiniDock Ultra អាចភ្ជាប់កុំព្យូទ័រតាមខ្សែ និងតាម WiFi ហើយភ្ជាប់ទូរស័ព្ទតាម Bluetooth និង WiFi។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-07-Q01','PC-07','Power & Connectivity','What connections does the MiniDock Ultra support?','តើ MiniDock Ultra គាំទ្រការភ្ជាប់តាមរបៀបណាខ្លះ?','MiniDock Ultra supports wired connection and WiFi connection to PC, and Bluetooth and WiFi connection to a mobile phone.','MiniDock Ultra អាចភ្ជាប់កុំព្យូទ័រតាមខ្សែ និងតាម WiFi ហើយភ្ជាប់ទូរស័ព្ទតាម Bluetooth និង WiFi។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-07-Q02','PC-07','Power & Connectivity','Can I connect the Ultra to my phone by Bluetooth?','អាចភ្ជាប់ Ultra ទៅទូរស័ព្ទតាម Bluetooth បានទេ?','Yes. MiniDock Ultra supports Bluetooth and WiFi connection to a mobile phone.','បាទ/ចាស។ MiniDock Ultra គាំទ្រការភ្ជាប់ទូរស័ព្ទតាម Bluetooth និង WiFi។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-07-Q03','PC-07','Power & Connectivity','Can the Ultra connect to the computer without a cable?','តើ Ultra អាចភ្ជាប់កុំព្យូទ័រដោយគ្មានខ្សែបានទេ?','Yes. MiniDock Ultra supports WiFi connection to a PC.','បាទ/ចាស។ MiniDock Ultra គាំទ្រការភ្ជាប់កុំព្យូទ័រតាម WiFi។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-07-Q04','PC-07','Power & Connectivity','connect way?','ភ្ជាប់តាមរបៀបណា?','MiniDock Ultra supports wired connection and WiFi connection to PC, and Bluetooth and WiFi connection to a mobile phone.','MiniDock Ultra អាចភ្ជាប់កុំព្យូទ័រតាមខ្សែ និងតាម WiFi ហើយភ្ជាប់ទូរស័ព្ទតាម Bluetooth និង WiFi។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-07-Q05','PC-07','Power & Connectivity','Does the computer connect by Bluetooth?','តើកុំព្យូទ័រភ្ជាប់តាម Bluetooth បានទេ?','No. For the PC, MiniDock Ultra supports wired connection and WiFi connection.','មិនបានទេ។ សម្រាប់កុំព្យូទ័រ MiniDock Ultra គាំទ្រការភ្ជាប់តាមខ្សែ និងតាម WiFi។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-08','PC-08','Power & Connectivity','Device often disconnects or goes offline','ម៉ាស៊ីនដាច់ការតភ្ជាប់ញឹកញាប់ ហើយឡើង «offline»។ ត្រូវពិនិត្យអ្វីខ្លះ?','This could be: 1. PC port issue; 2. Type-C cable malfunction; 3. Adapter issue; 4. Device failure.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-08-Q01','PC-08','Power & Connectivity','My device keeps disconnecting from the computer.','ម៉ាស៊ីនរបស់ខ្ញុំដាច់ពីកុំព្យូទ័រញឹកញាប់។ ត្រូវធ្វើម៉េច?','This could be: 1. PC port issue; 2. Type-C cable malfunction; 3. Adapter issue; 4. Device failure.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-08-Q02','PC-08','Power & Connectivity','disconnect again and again','ដាច់ម្តងហើយម្តងទៀត','This could be: 1. PC port issue; 2. Type-C cable malfunction; 3. Adapter issue; 4. Device failure.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-08-Q03','PC-08','Power & Connectivity','Could the cable be the problem?','តើខ្សែអាចជាបញ្ហាទេ?','Yes. A Type-C cable malfunction can cause it. Try another Type-C cable.','បាទ/ចាស។ ខ្សែ Type-C ខូច អាចបង្កបញ្ហានេះ។ សូមសាកប្រើខ្សែ Type-C ផ្សេង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-08-Q04','PC-08','Power & Connectivity','Should I try another USB port?','តើខ្ញុំគួរសាកដោតរន្ធ USB ផ្សេងទេ?','Yes. Try another USB port on your PC.','បាទ/ចាស។ សូមសាកដោតរន្ធ USB ផ្សេងលើកុំព្យូទ័ររបស់អ្នក។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-08-Q05','PC-08','Power & Connectivity','I tried everything and it still disconnects.','ខ្ញុំសាកអស់ហើយ តែវានៅតែដាច់។ ត្រូវធ្វើម៉េច?','Contact the vendor for help.','សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅអ្នកផ្គត់ផ្គង់ (vendor) សុំជំនួយ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-09','PC-09','Power & Connectivity','Device powered from a computer USB port','អាចយកភ្លើងពីរន្ធ USB របស់កុំព្យូទ័រមកបើក MiniDock បានទេ?','No, because the power output of a computer is not stable and sufficient, and may lead to an abnormal result.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-09-Q01','PC-09','Power & Connectivity','Can the MiniDock Ultra be powered by a computer?','តើ MiniDock Ultra អាចប្រើភ្លើងពីកុំព្យូទ័របានទេ?','No, because the power output of a computer is not stable and sufficient, and may lead to an abnormal result.','មិនបានទេ ព្រោះភ្លើងពីកុំព្យូទ័រមិនស្ថិរ និងមិនគ្រប់គ្រាន់ ហើយអាចធ្វើឱ្យលទ្ធផលមិនប្រក្រតី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-09-Q02','PC-09','Power & Connectivity','Can I plug the power into the laptop USB?','អាចដោតភ្លើងចូលរន្ធ USB កុំព្យូទ័រយួរដៃបានទេ?','No, because the power output of a computer is not stable and sufficient, and may lead to an abnormal result.','មិនបានទេ ព្រោះភ្លើងពីកុំព្យូទ័រមិនស្ថិរ និងមិនគ្រប់គ្រាន់ ហើយអាចធ្វើឱ្យលទ្ធផលមិនប្រក្រតី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-09-Q03','PC-09','Power & Connectivity','How should I power the device?','តើខ្ញុំគួរផ្គត់ផ្គង់ភ្លើងដល់ម៉ាស៊ីនយ៉ាងម៉េច?','Use the original power adapter and cable, and plug it into a power outlet. Do not use a computer as a power source.','ប្រើអាដាប់ទ័រភ្លើង និងខ្សែដើម ហើយដោតចូលព្រីភ្លើង។ កុំប្រើកុំព្យូទ័រជាប្រភពភ្លើង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-09-Q04','PC-09','Power & Connectivity','no socket, use laptop power ok?','គ្មានព្រីភ្លើង ប្រើភ្លើងកុំព្យូទ័រយួរដៃ បានទេ?','No, because the power output of a computer is not stable and sufficient, and may lead to an abnormal result.','មិនបានទេ ព្រោះភ្លើងពីកុំព្យូទ័រមិនស្ថិរ និងមិនគ្រប់គ្រាន់ ហើយអាចធ្វើឱ្យលទ្ធផលមិនប្រក្រតី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-09-Q05','PC-09','Power & Connectivity','Is it OK to use my own adapter?','អាចប្រើអាដាប់ទ័រផ្ទាល់ខ្លួនបានទេ?','No. Use the original power adapter and cable, and plug it into a power outlet.','មិនបានទេ។ សូមប្រើអាដាប់ទ័រភ្លើង និងខ្សែដើម ហើយដោតចូលព្រីភ្លើង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-10','PC-10','Power & Connectivity','Worker confused by the separate power port / power and data cables','តើរន្ធដោតភ្លើងនៅឯណា ហើយមួយណាជាខ្សែភ្លើង មួយណាជាខ្សែទិន្នន័យ?','The power cable has a DC connector (round), which powers the device; the data cable has a Type-C connector (flat), which is for data transfer only and does not power the device.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-10-Q01','PC-10','Power & Connectivity','Which cable is power and which is data?','តើខ្សែណាជាខ្សែភ្លើង ហើយខ្សែណាជាខ្សែទិន្នន័យ?','The power cable has a DC connector (round), which powers the device; the data cable has a Type-C connector (flat), which is for data transfer only and does not power the device.','ខ្សែភ្លើងមានក្បាល DC (មូល) សម្រាប់ផ្គត់ផ្គង់ភ្លើងដល់ម៉ាស៊ីន។ ខ្សែទិន្នន័យមានក្បាល Type-C (សំប៉ែត) សម្រាប់បញ្ជូនទិន្នន័យតែប៉ុណ្ណោះ ហើយមិនផ្គត់ផ្គង់ភ្លើងដល់ម៉ាស៊ីនទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-10-Q02','PC-10','Power & Connectivity','Can the device be powered only by the Type-C cable?','តើម៉ាស៊ីនអាចប្រើភ្លើងតែពីខ្សែ Type-C បានទេ?','No. The Type-C port is designed mainly for data connection and does not power the device. The device uses isothermal amplification, and its internal temperature module needs a larger power supply.','មិនបានទេ។ រន្ធ Type-C ត្រូវបានរចនាជាចម្បងសម្រាប់ការតភ្ជាប់ទិន្នន័យ ហើយមិនផ្គត់ផ្គង់ភ្លើងដល់ម៉ាស៊ីនទេ។ ម៉ាស៊ីនប្រើការពង្រីកសីតុណ្ហភាពថេរ (isothermal amplification) ហើយម៉ូឌុលសីតុណ្ហភាពខាងក្នុងត្រូវការភ្លើងច្រើន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-10-Q03','PC-10','Power & Connectivity','round plug or flat plug for power?','ក្បាលមូល ឬក្បាលសំប៉ែត សម្រាប់ភ្លើង?','The round DC connector is for power; the flat Type-C connector is for data only.','ក្បាល DC មូល សម្រាប់ភ្លើង។ ក្បាល Type-C សំប៉ែត សម្រាប់ទិន្នន័យតែប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-10-Q04','PC-10','Power & Connectivity','Why does the device need two cables?','ហេតុអ្វីបានជាម៉ាស៊ីនត្រូវការខ្សែពីរ?','The device uses isothermal amplification, and its internal temperature module needs a larger power supply. The Type-C port is designed mainly for data connection. To ensure connection stability and temperature stability, the power port and data port are designed independently.','ម៉ាស៊ីនប្រើការពង្រីកសីតុណ្ហភាពថេរ (isothermal amplification) ហើយម៉ូឌុលសីតុណ្ហភាពខាងក្នុងត្រូវការភ្លើងច្រើន។ រន្ធ Type-C ត្រូវបានរចនាជាចម្បងសម្រាប់ការតភ្ជាប់ទិន្នន័យ។ ដើម្បីធានាស្ថិរភាពនៃការតភ្ជាប់ និងស្ថិរភាពសីតុណ្ហភាព រន្ធភ្លើង និងរន្ធទិន្នន័យត្រូវបានរចនាដាច់ដោយឡែកពីគ្នា។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-10-Q05','PC-10','Power & Connectivity','I only plugged in the Type-C cable and nothing happens.','ខ្ញុំដោតតែខ្សែ Type-C ហើយគ្មានអ្វីកើតឡើងទេ?','The Type-C cable is for data transfer only and does not power the device. Connect the power cable (round DC connector).','ខ្សែ Type-C សម្រាប់បញ្ជូនទិន្នន័យតែប៉ុណ្ណោះ ហើយមិនផ្គត់ផ្គង់ភ្លើងដល់ម៉ាស៊ីនទេ។ សូមភ្ជាប់ខ្សែភ្លើង (ក្បាល DC មូល)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-11','PC-11','Power & Connectivity','Forgot the instrument connection password; cannot connect from the app','ខ្ញុំភ្លេចពាក្យសម្ងាត់សម្រាប់ភ្ជាប់ម៉ាស៊ីន ហើយភ្ជាប់ពីកម្មវិធីមិនបាន។ ត្រូវធ្វើម៉េច?','Method 1: Connect the instrument to the computer with a USB cable, right-click the instrument icon in the computer software, and select "WiFi Configuration" to view it.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-11-Q01','PC-11','Power & Connectivity','I forgot the password to connect to the device from the app.','ខ្ញុំភ្លេចពាក្យសម្ងាត់ សម្រាប់ភ្ជាប់ម៉ាស៊ីនពី App។ ត្រូវធ្វើម៉េច?','Method 1: Connect the instrument to the computer with a USB cable, right-click the instrument icon in the computer software, and select "WiFi Configuration" to view it.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-11-Q02','PC-11','Power & Connectivity','where to find device password','រកពាក្យសម្ងាត់ម៉ាស៊ីននៅឯណា?','Method 1: Connect the instrument to the computer with a USB cable, right-click the instrument icon in the computer software, and select "WiFi Configuration" to view it.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-11-Q03','PC-11','Power & Connectivity','Is the device password the same as my app login password?','តើពាក្យសម្ងាត់ម៉ាស៊ីន ដូចគ្នានឹងពាក្យសម្ងាត់ចូល កម្មវិធី របស់ខ្ញុំទេ?','No. The instrument connection password is different from the software or app account login password.','ទេ។ ពាក្យសម្ងាត់ភ្ជាប់ម៉ាស៊ីន ខុសពីពាក្យសម្ងាត់ចូលគណនីកម្មវិធី ឬ App។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-11-Q04','PC-11','Power & Connectivity','Can I see the device password on the computer?','អាចមើលពាក្យសម្ងាត់ម៉ាស៊ីននៅលើកុំព្យូទ័របានទេ?','Yes. Connect the instrument to the computer with a USB cable, right-click the instrument icon in the software, and select "WiFi Configuration" to view it.','បាទ/ចាស។ ភ្ជាប់ម៉ាស៊ីនទៅកុំព្យូទ័រដោយខ្សែ USB ចុចកណ្តុរខាងស្តាំលើរូបម៉ាស៊ីនក្នុងកម្មវិធី ហើយជ្រើសរើស "WiFi Configuration" ដើម្បីមើល។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-11-Q05','PC-11','Power & Connectivity','My colleague''s phone connected before. Can I find the password there?','ទូរស័ព្ទរបស់មិត្តរួមការងារខ្ញុំធ្លាប់ភ្ជាប់ពីមុន។ អាចរកពាក្យសម្ងាត់នៅទីនោះបានទេ?','Yes. You can view it in the app on a phone that has previously connected to the instrument.','បាទ/ចាស។ អ្នកអាចមើលវាក្នុង App លើទូរស័ព្ទដែលធ្លាប់ភ្ជាប់ជាមួយម៉ាស៊ីនពីមុន។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-12','PC-12','Power & Connectivity','Worker asks how to connect the device to a computer','ត្រូវភ្ជាប់ម៉ាស៊ីនទៅកុំព្យូទ័រដោយរបៀបណា?','1. Use the original Type-C cable to connect directly to the computer.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-12-Q01','PC-12','Power & Connectivity','How do I connect the device to the computer?','តើខ្ញុំភ្ជាប់ម៉ាស៊ីនទៅកុំព្យូទ័រយ៉ាងម៉េច?','1. Use the original Type-C cable to connect directly to the computer.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-12-Q02','PC-12','Power & Connectivity','Can I connect by WiFi the first time?','អាចភ្ជាប់តាម Wi‑Fi នៅលើកដំបូងបានទេ?','No. WiFi must be configured using the data cable during the first connection.','មិនបានទេ។ ត្រូវកំណត់ WiFi ដោយប្រើខ្សែទិន្នន័យ នៅពេលភ្ជាប់លើកដំបូង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-12-Q03','PC-12','Power & Connectivity','connect pc how','ភ្ជាប់កុំព្យូទ័រ យ៉ាងម៉េច?','1. Use the original Type-C cable to connect directly to the computer.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-12-Q04','PC-12','Power & Connectivity','Which cable connects to the laptop?','តើខ្សែណាសម្រាប់ភ្ជាប់កុំព្យូទ័រយួរដៃ?','Use the original Type-C cable to connect directly to the computer.','ប្រើខ្សែ Type-C ដើម ភ្ជាប់ផ្ទាល់ទៅកុំព្យូទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-13','PC-13','Power & Connectivity','Worker asks how to set up WiFi on the device','ត្រូវកំណត់ Wi‑Fi លើម៉ាស៊ីនដោយរបៀបណា?','Installation video: https://youtu.be/xpNLK8t3II8
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-13-Q01','PC-13','Power & Connectivity','How do I set up WiFi on the device?','តើខ្ញុំកំណត់ Wi‑Fi លើម៉ាស៊ីនយ៉ាងម៉េច?','Installation video: https://youtu.be/xpNLK8t3II8
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-13-Q02','PC-13','Power & Connectivity','Can I use 5 GHz WiFi?','អាចប្រើ Wi‑Fi 5 GHz បានទេ?','No. The WiFi must be 2.4 GHz and must be the same as the WiFi network used by the computer.','មិនបានទេ។ WiFi ត្រូវតែជា 2.4 GHz ហើយត្រូវតែជាបណ្តាញ WiFi តែមួយជាមួយកុំព្យូទ័រ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-13-Q03','PC-13','Power & Connectivity','wifi setting video','មានវីដេអូកំណត់ Wi‑Fiទេ?','Installation video: https://youtu.be/xpNLK8t3II8','វីដេអូដំឡើង៖ https://youtu.be/xpNLK8t3II8','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-13-Q04','PC-13','Power & Connectivity','Device details says "No Signal" after WiFi setup.','"Device details" បង្ហាញ "No Signal" ក្រោយកំណត់ Wi‑Fi។ ត្រូវធ្វើម៉េច?','Please contact service@pluslife.com.','សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅ service@pluslife.com។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-13-Q05','PC-13','Power & Connectivity','Our PC uses a LAN cable, not WiFi. What IP should the device have?','កុំព្យូទ័ររបស់យើងប្រើខ្សែ LAN មិនមែន Wi‑Fi ទេ។ តើម៉ាស៊ីនគួរមាន IP អ្វី?','If the computer is using a wired network, the first three segments of the IP address configured on the device must match those of the wired network.','បើកុំព្យូទ័រប្រើបណ្តាញតាមខ្សែ លេខបីផ្នែកដំបូងនៃអាសយដ្ឋាន IP ដែលកំណត់លើម៉ាស៊ីន ត្រូវតែដូចគ្នានឹងបណ្តាញតាមខ្សែនោះ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-13-Q06','PC-13','Power & Connectivity','Does the device need to be on the same WiFi as the computer?','តើម៉ាស៊ីនត្រូវនៅលើ Wi‑Fi តែមួយជាមួយកុំព្យូទ័រទេ?','Yes. The WiFi must be 2.4 GHz and the same as the WiFi network used by the computer.','បាទ/ចាស។ WiFi ត្រូវតែជា 2.4 GHz ហើយជាបណ្តាញ WiFi តែមួយជាមួយកុំព្យូទ័រ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-14','PC-14','Power & Connectivity','App cannot find the instrument when searching','ខ្ញុំចុចស្វែងរកក្នុងកម្មវិធីទូរស័ព្ទ តែរកម៉ាស៊ីនមិនឃើញ។ ត្រូវធ្វើម៉េច?','Please ensure that the following conditions are met:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-14-Q01','PC-14','Power & Connectivity','The app can''t find my device.','កម្មវិធី រកម៉ាស៊ីនរបស់ខ្ញុំមិនឃើញ?','Please ensure that the following conditions are met:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-14-Q02','PC-14','Power & Connectivity','search device not found','ស្វែងរកម៉ាស៊ីន រកមិនឃើញ។ ត្រូវធ្វើម៉េច?','Please ensure that the following conditions are met:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-14-Q03','PC-14','Power & Connectivity','Do I need to turn on location for the app to find the device?','តើខ្ញុំត្រូវបើកទីតាំង (location) ដើម្បីឱ្យ កម្មវិធី រកឃើញម៉ាស៊ីនទេ?','Yes. Location services must be enabled on your phone or tablet, and the Pluslife app must have permission to access your location.','បាទ/ចាស។ សេវាទីតាំង (Location) ត្រូវតែបើកលើទូរស័ព្ទ ឬថេប្លេតរបស់អ្នក ហើយ App Pluslife ត្រូវតែមានសិទ្ធិចូលប្រើទីតាំងរបស់អ្នក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-14-Q04','PC-14','Power & Connectivity','The device is plugged into the laptop. Can my phone still find it?','ម៉ាស៊ីនកំពុងដោតជាមួយកុំព្យូទ័រយួរដៃ។ តើទូរស័ព្ទខ្ញុំនៅតែអាចរកវាឃើញទេ?','No. The device must not be connected to a computer via a data cable or to another phone or tablet via Bluetooth.','មិនបានទេ។ ម៉ាស៊ីនមិនត្រូវភ្ជាប់ទៅកុំព្យូទ័រតាមខ្សែទិន្នន័យ ឬទៅទូរស័ព្ទ ឬថេប្លេតផ្សេងតាម Bluetooth ទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-14-Q05','PC-14','Power & Connectivity','bluetooth on but cannot see device','បើក Bluetooth ហើយ តែមើលមិនឃើញម៉ាស៊ីន','Also check: the device is on and not connected to a computer by cable or to another phone/tablet by Bluetooth; location services are on; the Pluslife app has location permission.','សូមពិនិត្យបន្ថែម៖ ម៉ាស៊ីនបានបើក ហើយមិនបានភ្ជាប់ទៅកុំព្យូទ័រតាមខ្សែ ឬទៅទូរស័ព្ទ/ថេប្លេតផ្សេងតាម Bluetooth សេវាទីតាំង (Location) បានបើក ហើយ App Pluslife មានសិទ្ធិចូលប្រើទីតាំង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-15','PC-15','Power & Connectivity','Worker tries to connect the device to a phone/tablet with a cable','អាចភ្ជាប់ម៉ាស៊ីនទៅទូរស័ព្ទ ឬថេប្លេតដោយខ្សែបានទេ?','No, for mobile devices, we only support wireless connections, including Bluetooth and Wi-Fi. Cable connections are only supported for connecting the device to a computer.','មិនបានទេ។ សម្រាប់ទូរស័ព្ទ និងថេប្លេត យើងគាំទ្រតែការភ្ជាប់ឥតខ្សែប៉ុណ្ណោះ គឺ Bluetooth និង Wi-Fi។ ការភ្ជាប់តាមខ្សែ គាំទ្រតែសម្រាប់ភ្ជាប់ម៉ាស៊ីនទៅកុំព្យូទ័រប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-15-Q01','PC-15','Power & Connectivity','Can I connect the device to my phone with a cable?','អាចភ្ជាប់ម៉ាស៊ីនទៅទូរស័ព្ទដោយខ្សែបានទេ?','No, for mobile devices, we only support wireless connections, including Bluetooth and Wi-Fi. Cable connections are only supported for connecting the device to a computer.','មិនបានទេ។ សម្រាប់ទូរស័ព្ទ និងថេប្លេត យើងគាំទ្រតែការភ្ជាប់ឥតខ្សែប៉ុណ្ណោះ គឺ Bluetooth និង Wi-Fi។ ការភ្ជាប់តាមខ្សែ គាំទ្រតែសម្រាប់ភ្ជាប់ម៉ាស៊ីនទៅកុំព្យូទ័រប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-15-Q02','PC-15','Power & Connectivity','Type-C to phone ok?','ខ្សែ Type-C ទៅទូរស័ព្ទ បានទេ?','No, for mobile devices, we only support wireless connections, including Bluetooth and Wi-Fi. Cable connections are only supported for connecting the device to a computer.','មិនបានទេ។ សម្រាប់ទូរស័ព្ទ និងថេប្លេត យើងគាំទ្រតែការភ្ជាប់ឥតខ្សែប៉ុណ្ណោះ គឺ Bluetooth និង Wi-Fi។ ការភ្ជាប់តាមខ្សែ គាំទ្រតែសម្រាប់ភ្ជាប់ម៉ាស៊ីនទៅកុំព្យូទ័រប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-15-Q03','PC-15','Power & Connectivity','How do I connect the device to a tablet?','តើខ្ញុំភ្ជាប់ម៉ាស៊ីនទៅថេប្លេតយ៉ាងម៉េច?','For mobile devices, only wireless connections are supported: Bluetooth and Wi-Fi.','សម្រាប់ទូរស័ព្ទ និងថេប្លេត គាំទ្រតែការភ្ជាប់ឥតខ្សែប៉ុណ្ណោះ គឺ Bluetooth និង Wi-Fi។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PC-15-Q04','PC-15','Power & Connectivity','cable to tablet not working','ខ្សែទៅថេប្លេត មិនដំណើរការ។ ត្រូវធ្វើម៉េច?','No, for mobile devices, we only support wireless connections, including Bluetooth and Wi-Fi. Cable connections are only supported for connecting the device to a computer.','មិនបានទេ។ សម្រាប់ទូរស័ព្ទ និងថេប្លេត យើងគាំទ្រតែការភ្ជាប់ឥតខ្សែប៉ុណ្ណោះ គឺ Bluetooth និង Wi-Fi។ ការភ្ជាប់តាមខ្សែ គាំទ្រតែសម្រាប់ភ្ជាប់ម៉ាស៊ីនទៅកុំព្យូទ័រប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-09','SC-09','Sample Collection','Worker wants to pool several samples in one test','អាចលាយសំណាកច្រើន ហើយធ្វើតេស្តក្នុងកាតតែមួយបានទេ?','Pooled testing is not recommended.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-09-Q01','SC-09','Sample Collection','Can I pool 10 samples in one test?','អាចបញ្ចូលសំណាក 10 រួមគ្នាក្នុងតេស្តតែមួយបានទេ?','No. Pooled testing is not recommended.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-09-Q02','SC-09','Sample Collection','Can I mix samples from two patients in one tube?','អាចលាយសំណាកពីអ្នកជំងឺពីរនាក់ក្នុងបំពង់តែមួយបានទេ?','No. Pooled testing is not recommended. If the pool contains an improperly sampled positive sample, it is easily missed.','មិនបានទេ។ មិនណែនាំឱ្យធ្វើតេស្តសំណាករួមគ្នា (pooled testing) ទេ។ បើក្នុងក្រុមសំណាកនោះ មានសំណាកវិជ្ជមានដែលយកមិនបានត្រឹមត្រូវ វាងាយនឹងរកមិនឃើញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-09-Q03','SC-09','Sample Collection','pooling ok to save cards?','បញ្ចូលសំណាករួមគ្នា ដើម្បីសន្សំកាត បានទេ?','No. Pooled testing is not recommended. The diluent volume in the kit is designed for single testing; pooling can easily throw off the sample-to-diluent ratio.','មិនបានទេ។ មិនណែនាំឱ្យធ្វើតេស្តសំណាករួមគ្នា (pooled testing) ទេ។ បរិមាណទឹករំលាយ (diluent) ក្នុងកញ្ចប់តេស្ត ត្រូវបានរចនាសម្រាប់ធ្វើតេស្តម្តងមួយសំណាក។ ការបញ្ចូលសំណាករួមគ្នា ងាយធ្វើឱ្យខុសសមាមាត្ររវាងសំណាក និងទឹករំលាយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-09-Q04','SC-09','Sample Collection','Why is pooled testing not recommended?','ហេតុអ្វីបានជាមិនណែនាំឱ្យធ្វើតេស្តសំណាករួមគ្នា?','First: Pluslife products use an endogenous internal control. In single testing it effectively monitors sampling, extraction and amplification, but in pooled testing it can only monitor extraction and amplification. If the pool contains an improperly sampled positive sample, it is easily missed.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-12','SC-12','Sample Collection','Worker wants to use swabs from another manufacturer or polyester swabs','អាចប្រើដងសំឡីពីក្រុមហ៊ុនផ្សេង ឬសំឡីប្រភេទ polyester បានទេ?','No. Please use the swabs supplied with the kit.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-12-Q01','SC-12','Sample Collection','Can I use swabs from another company?','អាចប្រើដងសំឡីរបស់ក្រុមហ៊ុនផ្សេងបានទេ?','No. Please use the swabs supplied with the kit.','មិនបានទេ។ សូមប្រើដងសំឡីដែលភ្ជាប់មកជាមួយកញ្ចប់តេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-12-Q02','SC-12','Sample Collection','We ran out of kit swabs. Can I use the hospital''s swabs?','ដងសំឡីក្នុងកញ្ចប់តេស្តអស់ហើយ។ អាចប្រើដងសំឡីរបស់មន្ទីរពេទ្យបានទេ?','No. Please use the swabs supplied with the kit.','មិនបានទេ។ សូមប្រើដងសំឡីដែលភ្ជាប់មកជាមួយកញ្ចប់តេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-12-Q03','SC-12','Sample Collection','Can polyester swabs be used?','តើអាចប្រើដងសំឡីប៉ូលីអេស្ទ័រ (polyester) បានទេ?','No, polyester swabs are not recommended. Please use the swabs provided by Pluslife.','មិនបានទេ មិនណែនាំឱ្យប្រើដងសំឡីប៉ូលីអេស្ទ័រ (polyester) ទេ។ សូមប្រើដងសំឡីដែល Pluslife ផ្តល់ឱ្យ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-12-Q04','SC-12','Sample Collection','other brand swab ok?','ដងសំឡីម៉ាកផ្សេង បានទេ?','No. Please use the swabs supplied with the kit.','មិនបានទេ។ សូមប្រើដងសំឡីដែលភ្ជាប់មកជាមួយកញ្ចប់តេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-13','SC-13','Sample Collection','Worker asks which sample types the MTB test accepts','តេស្ត MTB របស់ Pluslife អាចប្រើសំណាកប្រភេទណាខ្លះ?','Tongue swab and sputum.','សំណាកអណ្តាត (tongue swab) និងកំហាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-13-Q01','SC-13','Sample Collection','What sample type does the MTB test use?','តើតេស្ត MTB ប្រើសំណាកប្រភេទណា?','Tongue swab and sputum.','សំណាកអណ្តាត (tongue swab) និងកំហាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-13-Q02','SC-13','Sample Collection','Can I use a tongue swab for the TB test?','អាចប្រើសំណាកអណ្តាតសម្រាប់តេស្តជំងឺរបេងបានទេ?','Yes. The MTB test sample types are tongue swab and sputum.','បាទ/ចាស។ ប្រភេទសំណាកសម្រាប់តេស្ត MTB គឺសំណាកអណ្តាត (tongue swab) និងកំហាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-13-Q03','SC-13','Sample Collection','Can I test blood for TB with Pluslife?','អាចធ្វើតេស្តឈាមរកជំងឺរបេងជាមួយ Pluslife បានទេ?','No. The MTB test sample types are tongue swab and sputum.','មិនបានទេ។ ប្រភេទសំណាកសម្រាប់តេស្ត MTB គឺសំណាកអណ្តាត (tongue swab) និងកំហាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-13-Q04','SC-13','Sample Collection','sample type tb','ប្រភេទសំណាក ជំងឺរបេង','Tongue swab and sputum.','សំណាកអណ្តាត (tongue swab) និងកំហាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-14','SC-14','Sample Collection','Worker asks how to collect a sputum sample','ត្រូវណែនាំអ្នកជំងឺឱ្យស្រង់កំហាកដោយរបៀបណា?','1. Rinse mouth.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-14-Q01','SC-14','Sample Collection','How do I collect sputum for the test?','តើខ្ញុំយកកំហាកសម្រាប់ធ្វើតេស្តយ៉ាងម៉េច?','1. Rinse mouth.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-14-Q02','SC-14','Sample Collection','How much sputum do I need?','តើខ្ញុំត្រូវការកំហាកប៉ុន្មាន?','More than 1 mL.','លើសពី 1 mL។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-14-Q03','SC-14','Sample Collection','Does the patient need to rinse first?','តើអ្នកជំងឺត្រូវខ្ពុរមាត់ជាមុនសិនទេ?','Yes. Rinse mouth first.','បាទ/ចាស។ ខ្ពុរមាត់ជាមុនសិន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-14-Q04','SC-14','Sample Collection','Can I liquefy the sputum first?','អាចធ្វើឱ្យកំហាករាវជាមុនសិនបានទេ?','No. Use a fresh sample without VTM or liquefying.','មិនបានទេ។ ប្រើសំណាកថ្មី ដែលគ្មាន VTM និងមិនទាន់បានធ្វើឱ្យរាវ (liquefying)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-14-Q05','SC-14','Sample Collection','sputum steps','ជំហានស្រង់កំហាក','1. Rinse mouth.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-15','SC-15','Sample Collection','Worker asks how to collect a tongue swab','ត្រូវស្រង់សំណាកអណ្តាតដោយរបៀបណា?','1. Ensure no eating or drinking within 30 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-15-Q01','SC-15','Sample Collection','How do I take a tongue swab?','តើខ្ញុំស្រង់សំណាកអណ្តាតយ៉ាងម៉េច?','1. Ensure no eating or drinking within 30 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-15-Q02','SC-15','Sample Collection','Patient just drank water. Can I swab now?','អ្នកជំងឺទើបតែផឹកទឹក។ អាចយកសំណាកឥឡូវនេះបានទេ?','No. Ensure no eating or drinking within 30 minutes before the tongue swab.','មិនបានទេ។ ធ្វើឱ្យប្រាកដថាអ្នកជំងឺមិនបានញ៉ាំ ឬផឹកអ្វីក្នុងរយៈពេល 30 នាទី មុនស្រង់សំណាកអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-15-Q03','SC-15','Sample Collection','How long do I swab the tongue?','តើខ្ញុំជូតអណ្តាតរយៈពេលប៉ុន្មាន?','Swab the tongue with pressure and rotate the swab for 30 s.','ជូតអណ្តាតដោយសង្កត់ ហើយបង្វិលដងសំឡីរយៈពេល 30 វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-15-Q04','SC-15','Sample Collection','Which part of the tongue?','ផ្នែកណានៃអណ្តាត?','The back of the tongue.','ផ្នែកខាងក្រោយនៃអណ្តាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-15-Q05','SC-15','Sample Collection','tongue swab how','ស្រង់សំណាកអណ្តាត យ៉ាងម៉េច?','1. Ensure no eating or drinking within 30 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-16','SC-16','Sample Collection','Sputum already treated with Xpert liquefaction reagent','កំហាកនេះលាយជាមួយសារធាតុរបស់ Xpert រួចហើយ។ នៅអាចយកមកតេស្ត Pluslife បានទេ?','No, please use the original (untreated) sputum sample for testing.','មិនបានទេ សូមប្រើសំណាកកំហាកដើម (មិនទាន់ដាក់សារធាតុអ្វី) ដើម្បីធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-16-Q01','SC-16','Sample Collection','Can I use sputum that already had the Xpert reagent added?','អាចប្រើកំហាកដែលបានដាក់សារធាតុ Xpert រួចហើយបានទេ?','No, please use the original (untreated) sputum sample for testing.','មិនបានទេ សូមប្រើសំណាកកំហាកដើម (មិនទាន់ដាក់សារធាតុអ្វី) ដើម្បីធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-16-Q02','SC-16','Sample Collection','Xpert sample left over, use for Pluslife?','សំណាក Xpert នៅសល់ ប្រើសម្រាប់ Pluslife បានទេ?','No, not if it was treated with Xpert''s liquefaction reagent. Use the original (untreated) sputum sample.','មិនបានទេ បើវាត្រូវបានដាក់សារធាតុធ្វើឱ្យរាវរបស់ Xpert (Xpert liquefaction reagent) រួចហើយ។ សូមប្រើសំណាកកំហាកដើម (មិនទាន់ដាក់សារធាតុអ្វី)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-16-Q03','SC-16','Sample Collection','Can I split one sputum for Xpert and Pluslife?','អាចចែកកំហាកមួយ សម្រាប់ Xpert និង Pluslife បានទេ?','Not sure — that is not stated. What is stated: use the original (untreated) sputum sample for Pluslife, not sputum treated with Xpert''s liquefaction reagent.','មិនប្រាកដទេ — រឿងនេះមិនមានបញ្ជាក់ទេ។ អ្វីដែលបានបញ្ជាក់គឺ៖ សូមប្រើសំណាកកំហាកដើម (មិនទាន់ដាក់សារធាតុអ្វី) សម្រាប់ Pluslife មិនមែនកំហាកដែលបានដាក់សារធាតុធ្វើឱ្យរាវរបស់ Xpert ទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-17','SC-17','Sample Collection','Sputum sample contains a lot of saliva','ក្នុងកែវកំហាកមានទឹកមាត់ច្រើន។ អាចយកទៅធ្វើតេស្តបានទេ?','Yes, it can. However, we recommend ensuring the quality of the sample as much as possible during collection.','បាទ/ចាស អាចប្រើបាន។ ប៉ុន្តែ យើងណែនាំឱ្យធានាគុណភាពសំណាកឱ្យបានល្អបំផុតតាមដែលអាចធ្វើបាន ពេលយកសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-17-Q01','SC-17','Sample Collection','There''s a lot of saliva in the sputum. Can I still test it?','មានទឹកមាត់ច្រើនក្នុងកំហាក។ តើខ្ញុំនៅតែអាចធ្វើតេស្តវាបានទេ?','Yes, it can. However, we recommend ensuring the quality of the sample as much as possible during collection.','បាទ/ចាស អាចប្រើបាន។ ប៉ុន្តែ យើងណែនាំឱ្យធានាគុណភាពសំណាកឱ្យបានល្អបំផុតតាមដែលអាចធ្វើបាន ពេលយកសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-17-Q02','SC-17','Sample Collection','sputum watery, ok?','កំហាករាវដូចទឹក បានទេ?','Yes, it can. However, we recommend ensuring the quality of the sample as much as possible during collection.','បាទ/ចាស អាចប្រើបាន។ ប៉ុន្តែ យើងណែនាំឱ្យធានាគុណភាពសំណាកឱ្យបានល្អបំផុតតាមដែលអាចធ្វើបាន ពេលយកសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SC-17-Q03','SC-17','Sample Collection','Should I reject a sputum sample with saliva?','តើខ្ញុំគួរបដិសេធសំណាកកំហាកដែលមានទឹកមាត់ទេ?','No, it can still be tested. However, ensure the quality of the sample as much as possible during collection.','ទេ វានៅតែអាចធ្វើតេស្តបាន។ ប៉ុន្តែ សូមធានាគុណភាពសំណាកឱ្យបានល្អបំផុតតាមដែលអាចធ្វើបាន ពេលយកសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-02','SS-02','Sample Storage','Sample cannot be tested right after collection','ស្រង់សំណាករួច តែធ្វើតេស្តភ្លាមៗមិនបាន។ អាចទុកបានយូរប៉ុន្មាន?','Test samples immediately after collection. If immediate testing is not possible, store DNA samples at room temperature (10–30 °C) for 24 hours, 2–8 °C for up to 5 days, or -20 °C for up to 6 months. The specimen should be transported with ice in a foam box.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-02-Q01','SS-02','Sample Storage','How soon must I test the sample after collection?','តើខ្ញុំត្រូវធ្វើតេស្តសំណាកក្នុងរយៈពេលប៉ុន្មាន ក្រោយយករួច?','Test samples immediately after collection.','ធ្វើតេស្តសំណាកភ្លាមៗក្រោយយករួច។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-02-Q02','SS-02','Sample Storage','I can''t test today. How long can I keep the TB sample?','ខ្ញុំមិនអាចធ្វើតេស្តថ្ងៃនេះបានទេ។ អាចទុកសំណាកជំងឺរបេងបានយូរប៉ុណ្ណា?','If immediate testing is not possible, store DNA samples at room temperature (10–30 °C) for 24 hours, 2–8 °C for up to 5 days, or -20 °C for up to 6 months.','បើមិនអាចធ្វើតេស្តភ្លាមៗបាន សូមរក្សាទុកសំណាក DNA នៅសីតុណ្ហភាពបន្ទប់ (10–30 °C) រយៈពេល 24 ម៉ោង នៅ 2–8 °C រហូតដល់ 5 ថ្ងៃ ឬនៅ -20 °C រហូតដល់ 6 ខែ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-02-Q03','SS-02','Sample Storage','Can I keep the sample in the fridge until tomorrow?','អាចទុកសំណាកក្នុងទូទឹកកករហូតដល់ថ្ងៃស្អែកបានទេ?','Yes. DNA samples can be stored at 2–8 °C for up to 5 days. Testing immediately after collection is best.','បាទ/ចាស។ សំណាក DNA អាចរក្សាទុកនៅ 2–8 °C រហូតដល់ 5 ថ្ងៃ។ ការធ្វើតេស្តភ្លាមៗក្រោយយករួច គឺល្អបំផុត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-02-Q04','SS-02','Sample Storage','How should samples be transported to another site?','តើគួរដឹកជញ្ជូនសំណាកទៅកន្លែងផ្សេងយ៉ាងម៉េច?','The specimen should be transported with ice in a foam box.','សំណាកគួរដឹកជញ្ជូនជាមួយទឹកកកក្នុងប្រអប់ស្នោ (foam box)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-02-Q05','SS-02','Sample Storage','sample store room temp how long','ទុកសំណាកនៅសីតុណ្ហភាពបន្ទប់បានយូរប៉ុណ្ណា?','DNA samples: room temperature (10–30 °C) for 24 hours.','សំណាក DNA៖ នៅសីតុណ្ហភាពបន្ទប់ (10–30 °C) រយៈពេល 24 ម៉ោង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-02-Q06','SS-02','Sample Storage','Our room is 33 °C. Can the sample stay out for 24 hours?','បន្ទប់របស់យើងមានសីតុណ្ហភាព 33 °C។ តើសំណាកអាចទុកនៅខាងក្រៅ 24 ម៉ោងបានទេ?','Not sure. The room-temperature limit given is 10–30 °C for 24 hours; 33 °C is outside that range. Test immediately or store at 2–8 °C.','មិនប្រាកដទេ។ កម្រិតសីតុណ្ហភាពបន្ទប់ដែលបានផ្តល់ឱ្យគឺ 10–30 °C រយៈពេល 24 ម៉ោង។ 33 °C គឺនៅក្រៅកម្រិតនោះ។ សូមធ្វើតេស្តភ្លាមៗ ឬរក្សាទុកនៅ 2–8 °C។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-03','SS-03','Sample Storage','Worker wants to store samples in VTM/UTM','អាចរក្សាទុកសំណាកក្នុងសារធាតុដឹកជញ្ជូន VTM ឬ UTM បានទេ?','Samples prepared according to the instructions should be tested on-site immediately after collection. Inactivating VTM/UTM is known not to work. Some manufacturers'' non-inactivating VTM can be used to store samples, with an added volume of about 500 µL; validated VTM manufacturers include Savyon and Copan.','សំណាកដែលរៀបចំតាមការណែនាំ គួរធ្វើតេស្តនៅនឹងកន្លែងភ្លាមៗក្រោយយករួច។ VTM/UTM ប្រភេទធ្វើឱ្យមេរោគអសកម្ម (inactivating) ត្រូវបានដឹងថាមិនដំណើរការទេ។ VTM ប្រភេទមិនធ្វើឱ្យមេរោគអសកម្ម (non-inactivating) របស់ក្រុមហ៊ុនផលិតខ្លះ អាចប្រើរក្សាទុកសំណាកបាន ដោយបន្ថែមបរិមាណប្រហែល 500 µL។ ក្រុមហ៊ុនផលិត VTM ដែលបានផ្ទៀងផ្ទាត់រួមមាន Savyon និង Copan។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-03-Q01','SS-03','Sample Storage','Can I store the swab in VTM?','អាចរក្សាទុកដងសំឡីក្នុង VTM បានទេ?','Not sure — it depends on the type. Inactivating VTM/UTM is known not to work. Some manufacturers'' non-inactivating VTM (e.g. Savyon, Copan) can be used, with an added volume of about 500 µL.','មិនប្រាកដទេ — វាអាស្រ័យលើប្រភេទ។ VTM/UTM ប្រភេទធ្វើឱ្យមេរោគអសកម្ម (inactivating) ត្រូវបានដឹងថាមិនដំណើរការទេ។ VTM ប្រភេទមិនធ្វើឱ្យមេរោគអសកម្ម (non-inactivating) របស់ក្រុមហ៊ុនផលិតខ្លះ (ឧទាហរណ៍ Savyon, Copan) អាចប្រើបាន ដោយបន្ថែមបរិមាណប្រហែល 500 µL។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-03-Q02','SS-03','Sample Storage','Does inactivating UTM work with Pluslife?','តើ UTM ប្រភេទធ្វើឱ្យមេរោគអសកម្ម (inactivating) ដំណើរការជាមួយ Pluslife ទេ?','No. Inactivating VTM/UTM is known not to work.','មិនដំណើរការទេ។ VTM/UTM ប្រភេទធ្វើឱ្យមេរោគអសកម្ម (inactivating) ត្រូវបានដឹងថាមិនដំណើរការទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-03-Q03','SS-03','Sample Storage','Which VTM brands are validated?','តើម៉ាក VTM ណាខ្លះដែលបានផ្ទៀងផ្ទាត់?','Validated VTM manufacturers include Savyon and Copan (non-inactivating VTM).','ក្រុមហ៊ុនផលិត VTM ដែលបានផ្ទៀងផ្ទាត់រួមមាន Savyon និង Copan (VTM ប្រភេទមិនធ្វើឱ្យមេរោគអសកម្ម - non-inactivating)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-03-Q04','SS-03','Sample Storage','How much VTM sample do I add?','តើខ្ញុំត្រូវបន្ថែមសំណាក VTM ប៉ុន្មាន?','An added volume of about 500 µL.','បន្ថែមបរិមាណប្រហែល 500 µL។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-03-Q05','SS-03','Sample Storage','vtm ok?','VTM បានទេ?','Samples prepared according to the instructions should be tested on-site immediately after collection. Inactivating VTM/UTM is known not to work. Some manufacturers'' non-inactivating VTM can be used to store samples, with an added volume of about 500 µL; validated VTM manufacturers include Savyon and Copan.','សំណាកដែលរៀបចំតាមការណែនាំ គួរធ្វើតេស្តនៅនឹងកន្លែងភ្លាមៗក្រោយយករួច។ VTM/UTM ប្រភេទធ្វើឱ្យមេរោគអសកម្ម (inactivating) ត្រូវបានដឹងថាមិនដំណើរការទេ។ VTM ប្រភេទមិនធ្វើឱ្យមេរោគអសកម្ម (non-inactivating) របស់ក្រុមហ៊ុនផលិតខ្លះ អាចប្រើរក្សាទុកសំណាកបាន ដោយបន្ថែមបរិមាណប្រហែល 500 µL។ ក្រុមហ៊ុនផលិត VTM ដែលបានផ្ទៀងផ្ទាត់រួមមាន Savyon និង Copan។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-04','SS-04','Sample Storage','Sample left in the lysis buffer before testing','ខ្ញុំទុកសំណាកក្នុងសូលុយស្យុងបំបែក (lysis buffer) មុនធ្វើតេស្ត។ តើអាចទុកបានយូរប៉ុន្មាន?','With immediate sampling and testing, sample loading is usually completed within 10 minutes and no refrigeration is needed. To ensure reliability, testing must be completed within 1 hour after sampling.','បើយកសំណាក ហើយធ្វើតេស្តភ្លាមៗ ការដាក់សំណាកជាធម្មតាត្រូវបានបញ្ចប់ក្នុងរយៈពេល 10 នាទី ហើយមិនចាំបាច់ដាក់ទូទឹកកកទេ។ ដើម្បីធានាភាពជឿទុកចិត្តបាន ត្រូវតែធ្វើតេស្តឱ្យរួចក្នុងរយៈពេល 1 ម៉ោង ក្រោយយកសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-04-Q01','SS-04','Sample Storage','How long can the sample stay in the lysis buffer?','តើសំណាកអាចទុកក្នុងសារធាតុបំបែក (lysis buffer) បានយូរប៉ុណ្ណា?','Testing must be completed within 1 hour after sampling.','ត្រូវតែធ្វើតេស្តឱ្យរួចក្នុងរយៈពេល 1 ម៉ោង ក្រោយយកសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-04-Q02','SS-04','Sample Storage','Does the tube need to go in the fridge?','តើបំពង់ត្រូវដាក់ក្នុងទូទឹកកកទេ?','No. With immediate sampling and testing, sample loading is usually completed within 10 minutes and no refrigeration is needed.','ទេ។ បើយកសំណាក ហើយធ្វើតេស្តភ្លាមៗ ការដាក់សំណាកជាធម្មតាត្រូវបានបញ្ចប់ក្នុងរយៈពេល 10 នាទី ហើយមិនចាំបាច់ដាក់ទូទឹកកកទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-04-Q03','SS-04','Sample Storage','sample in buffer 2 hours still ok?','សំណាកក្នុងសារធាតុបំបែក (buffer) 2 ម៉ោង នៅតែប្រើបានទេ?','No. To ensure reliability, testing must be completed within 1 hour after sampling.','មិនបានទេ។ ដើម្បីធានាភាពជឿទុកចិត្តបាន ត្រូវតែធ្វើតេស្តឱ្យរួចក្នុងរយៈពេល 1 ម៉ោង ក្រោយយកសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-04-Q04','SS-04','Sample Storage','lysis buffer time limit','រយៈពេលកំណត់ក្នុងសារធាតុបំបែក (lysis buffer)','With immediate sampling and testing, sample loading is usually completed within 10 minutes and no refrigeration is needed. To ensure reliability, testing must be completed within 1 hour after sampling.','បើយកសំណាក ហើយធ្វើតេស្តភ្លាមៗ ការដាក់សំណាកជាធម្មតាត្រូវបានបញ្ចប់ក្នុងរយៈពេល 10 នាទី ហើយមិនចាំបាច់ដាក់ទូទឹកកកទេ។ ដើម្បីធានាភាពជឿទុកចិត្តបាន ត្រូវតែធ្វើតេស្តឱ្យរួចក្នុងរយៈពេល 1 ម៉ោង ក្រោយយកសំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-05','SS-05','Sample Storage','Sample already in Releasing Agent cannot be tested right away','ខ្ញុំដាក់សំណាកក្នុង Releasing Agent រួច តែមិនអាចធ្វើតេស្តភ្លាមៗ។ ត្រូវធ្វើម៉េច?','For MTB, a sample processed with Releasing Agent can be stored at room temperature for no more than 5 hours, or at 2–8 °C for no more than 3 days.','សម្រាប់ MTB សំណាកដែលបានដាក់ក្នុង Releasing Agent អាចរក្សាទុកនៅសីតុណ្ហភាពបន្ទប់ មិនលើស 5 ម៉ោង ឬនៅ 2–8 °C មិនលើស 3 ថ្ងៃ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-05-Q01','SS-05','Sample Storage','How long can I keep the sample after adding the releasing agent?','អាចទុកសំណាកបានយូរប៉ុណ្ណា ក្រោយដាក់ Releasing agent រួច?','For MTB, a sample processed with Releasing Agent can be stored at room temperature for no more than 5 hours, or at 2–8 °C for no more than 3 days.','សម្រាប់ MTB សំណាកដែលបានដាក់ក្នុង Releasing Agent អាចរក្សាទុកនៅសីតុណ្ហភាពបន្ទប់ មិនលើស 5 ម៉ោង ឬនៅ 2–8 °C មិនលើស 3 ថ្ងៃ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-05-Q02','SS-05','Sample Storage','Can I put the releasing agent tube in the fridge?','អាចដាក់បំពង់ Releasing agent ក្នុងទូទឹកកកបានទេ?','Yes. For MTB, it can be stored at 2–8 °C for no more than 3 days.','បាទ/ចាស។ សម្រាប់ MTB វាអាចរក្សាទុកនៅ 2–8 °C មិនលើស 3 ថ្ងៃ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-05-Q03','SS-05','Sample Storage','releasing agent sample room temp max','សំណាកក្នុង Releasing agent ទុកនៅសីតុណ្ហភាពបន្ទប់បានយូរបំផុតប៉ុណ្ណា?','No more than 5 hours at room temperature (MTB).','មិនលើស 5 ម៉ោង នៅសីតុណ្ហភាពបន្ទប់ (MTB)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-05-Q04','SS-05','Sample Storage','I processed the sample this morning, can I test it tomorrow?','ខ្ញុំបានរៀបចំសំណាកព្រឹកនេះ អាចធ្វើតេស្តវានៅថ្ងៃស្អែកបានទេ?','Yes, if it was kept at 2–8 °C: for MTB, no more than 3 days. At room temperature the limit is 5 hours.','បាទ/ចាស បើវាត្រូវបានរក្សាទុកនៅ 2–8 °C៖ សម្រាប់ MTB មិនលើស 3 ថ្ងៃ។ នៅសីតុណ្ហភាពបន្ទប់ កម្រិតគឺ 5 ម៉ោង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SS-05-Q05','SS-05','Sample Storage','Is 6 hours at room temperature OK?','តើ 6 ម៉ោងនៅសីតុណ្ហភាពបន្ទប់ មិនអីទេឬ?','No. At room temperature the limit is no more than 5 hours.','មិនបានទេ។ នៅសីតុណ្ហភាពបន្ទប់ កម្រិតគឺមិនលើស 5 ម៉ោង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-03','SP-03','Sample Pretreatment','Worker wants to use nucleic acid extracted by a conventional extractor','អាចយកអាស៊ីតនុយក្លេអ៊ិកដែលស្រង់ពីម៉ាស៊ីនស្រង់ធម្មតា មកធ្វើតេស្ត Pluslife បានទេ?','Yes. Prepare a 1.5 mL EP tube, pipette 50 µL of the extracted nucleic acid sample, then add 350 µL of diluent, mix thoroughly in the EP tube, and add all of it to the test card for testing.','បាទ/ចាស អាចប្រើបាន។ រៀបចំបំពង់ EP ទំហំ 1.5 mL ស្រូប (pipette) សំណាកអាស៊ីតនុយក្លេអ៊ីកដែលចម្រាញ់រួច 50 µL រួចបន្ថែមទឹករំលាយ (diluent) 350 µL លាយឱ្យសព្វក្នុងបំពង់ EP ហើយចាក់ទាំងអស់ចូលកាតតេស្ត ដើម្បីធ្វើតេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-03-Q01','SP-03','Sample Pretreatment','Can I use DNA extracted by our extraction machine?','អាចប្រើ DNA ដែលចម្រាញ់ដោយម៉ាស៊ីនចម្រាញ់របស់យើងបានទេ?','Yes. Prepare a 1.5 mL EP tube, pipette 50 µL of the extracted nucleic acid sample, then add 350 µL of diluent, mix thoroughly in the EP tube, and add all of it to the test card for testing.','បាទ/ចាស អាចប្រើបាន។ រៀបចំបំពង់ EP ទំហំ 1.5 mL ស្រូប (pipette) សំណាកអាស៊ីតនុយក្លេអ៊ីកដែលចម្រាញ់រួច 50 µL រួចបន្ថែមទឹករំលាយ (diluent) 350 µL លាយឱ្យសព្វក្នុងបំពង់ EP ហើយចាក់ទាំងអស់ចូលកាតតេស្ត ដើម្បីធ្វើតេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-03-Q02','SP-03','Sample Pretreatment','extracted sample how much','សំណាកដែលចម្រាញ់រួច ដាក់ប៉ុន្មាន?','50 µL of extracted nucleic acid sample plus 350 µL of diluent in a 1.5 mL EP tube; mix and add all of it to the test card.','សំណាកអាស៊ីតនុយក្លេអ៊ីកដែលចម្រាញ់រួច 50 µL បូកទឹករំលាយ (diluent) 350 µL ក្នុងបំពង់ EP ទំហំ 1.5 mL។ លាយ ហើយចាក់ទាំងអស់ចូលកាតតេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-03-Q03','SP-03','Sample Pretreatment','How do I dilute an extracted sample?','តើខ្ញុំពនរ (dilute) សំណាកដែលចម្រាញ់រួចយ៉ាងម៉េច?','Pipette 50 µL of the extracted nucleic acid sample into a 1.5 mL EP tube, add 350 µL of diluent, and mix thoroughly.','ស្រូប (pipette) សំណាកអាស៊ីតនុយក្លេអ៊ីកដែលចម្រាញ់រួច 50 µL ចូលក្នុងបំពង់ EP ទំហំ 1.5 mL បន្ថែមទឹករំលាយ (diluent) 350 µL ហើយលាយឱ្យសព្វ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-04','SP-04','Sample Pretreatment','Releasing agent / lysis buffer splashed on skin or eyes, or swallowed','បើ Releasing Agent ឬ lysis buffer ខ្ទាតចូលភ្នែក ប៉ះស្បែក ឬលេបចូលដោយចៃដន្យ ត្រូវធ្វើម៉េច?','If releasing agent gets on your skin, rinse it immediately with clean water — there is no need to worry too much, as the reagent does not burn the skin. If it gets into your eyes, rinse immediately with plenty of water and seek medical attention promptly. We recommend wearing gloves during testing.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-04-Q01','SP-04','Sample Pretreatment','Releasing agent got on my hand. What do I do?','Releasing agent ប៉ះដៃខ្ញុំ។ តើខ្ញុំត្រូវធ្វើអ្វី?','Rinse it immediately with clean water — there is no need to worry too much, as the reagent does not burn the skin.','លាងវាភ្លាមៗដោយទឹកស្អាត — មិនចាំបាច់បារម្ភខ្លាំងទេ ព្រោះសារធាតុនេះមិនរលាកស្បែកទេ។','Safety-critical','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-04-Q02','SP-04','Sample Pretreatment','Liquid splashed in my eye!','សូលុយស្យុងខ្ទាតចូលភ្នែកខ្ញុំ។ ត្រូវធ្វើអ្វីភ្លាមៗ?','Rinse immediately with plenty of water and seek medical attention promptly.','លាងភ្លាមៗដោយទឹកច្រើន ហើយទៅជួបគ្រូពេទ្យឱ្យបានឆាប់។','Safety-critical','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-04-Q03','SP-04','Sample Pretreatment','Is the lysis buffer dangerous?','តើសារធាតុបំបែក (lysis buffer) មានគ្រោះថ្នាក់ទេ?','Brief skin contact will not cause harm, but it is slightly alkaline and must not be ingested; avoid direct contact with the body.','ការប៉ះស្បែកមួយភ្លែតមិនបង្កគ្រោះថ្នាក់ទេ ប៉ុន្តែវាមានជាតិបាសបន្តិច ហើយហាមលេបចូលដាច់ខាត។ ជៀសវាងការប៉ះផ្ទាល់នឹងរាងកាយ។','Safety-critical','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-04-Q04','SP-04','Sample Pretreatment','Is it OK to drink / swallow the buffer by accident?','តើផឹក / លេបសារធាតុបំបែកដោយចៃដន្យ មិនអីទេឬ?','No. The lysis buffer must not be ingested.','មិនបានទេ។ ហាមលេបសារធាតុបំបែក (lysis buffer) ចូលដាច់ខាត។','Safety-critical','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-04-Q05','SP-04','Sample Pretreatment','Do I need gloves?','តើខ្ញុំត្រូវពាក់ស្រោមដៃទេ?','Yes. We recommend wearing gloves during testing.','បាទ/ចាស។ យើងណែនាំឱ្យពាក់ស្រោមដៃពេលធ្វើតេស្ត។','Safety-critical','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-04-Q06','SP-04','Sample Pretreatment','reagent on skin burn?','សារធាតុប៉ះស្បែក រលាកទេ?','No. The reagent does not burn the skin. Rinse it immediately with clean water.','ទេ។ សារធាតុនេះមិនរលាកស្បែកទេ។ សូមលាងវាភ្លាមៗដោយទឹកស្អាត។','Safety-critical','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-05','SP-05','Sample Pretreatment','Worker asks what the lysis buffer does / how to dispose of it','សូលុយស្យុងបំបែក (lysis buffer) ប្រើសម្រាប់អ្វី ហើយប្រើរួចត្រូវបោះចោលដោយរបៀបណា?','The lysis buffer inactivates viruses and releases nucleic acids. During the experiment and disposal, it should be treated as infectious medical waste in accordance with regulations.','សារធាតុបំបែក (lysis buffer) ធ្វើឱ្យមេរោគអសកម្ម និងបញ្ចេញអាស៊ីតនុយក្លេអ៊ីក។ ពេលធ្វើតេស្ត និងពេលបោះចោល វាត្រូវចាត់ទុកជាកាកសំណល់វេជ្ជសាស្ត្រឆ្លងរោគ ស្របតាមបទប្បញ្ញត្តិ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-05-Q01','SP-05','Sample Pretreatment','What does the lysis buffer do?','តើសារធាតុបំបែក (lysis buffer) មានតួនាទីអ្វី?','The lysis buffer inactivates viruses and releases nucleic acids.','សារធាតុបំបែក (lysis buffer) ធ្វើឱ្យមេរោគអសកម្ម និងបញ្ចេញអាស៊ីតនុយក្លេអ៊ីក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-05-Q02','SP-05','Sample Pretreatment','How do I throw away the used buffer tube?','តើខ្ញុំបោះចោលបំពង់សារធាតុបំបែកដែលប្រើរួចយ៉ាងម៉េច?','Treat it as infectious medical waste in accordance with regulations.','ចាត់ទុកវាជាកាកសំណល់វេជ្ជសាស្ត្រឆ្លងរោគ ស្របតាមបទប្បញ្ញត្តិ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-05-Q03','SP-05','Sample Pretreatment','Can I throw the tube in normal trash?','អាចបោះបំពង់ចូលធុងសំរាមធម្មតាបានទេ?','No. During the experiment and disposal, it should be treated as infectious medical waste in accordance with regulations.','មិនបានទេ។ ពេលធ្វើតេស្ត និងពេលបោះចោល វាត្រូវចាត់ទុកជាកាកសំណល់វេជ្ជសាស្ត្រឆ្លងរោគ ស្របតាមបទប្បញ្ញត្តិ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-06','SP-06','Sample Pretreatment','Worker wants to test PCR amplification products on Pluslife','អាចយកផលិតផលដែលបានពីការបង្កើនចំនួន DNA ដោយ PCR មកធ្វើតេស្ត Pluslife បានទេ?','No. PCR amplification regions do not necessarily overlap with Pluslife''s amplification regions, so PCR products may not test properly on the Pluslife platform. In addition, handling amplification products directly easily causes contamination and carries risk.','មិនបានទេ។ តំបន់ពង្រីករបស់ PCR មិនប្រាកដថាត្រួតគ្នានឹងតំបន់ពង្រីករបស់ Pluslife ទេ ដូច្នេះផលិតផល PCR អាចធ្វើតេស្តលើ Pluslife មិនបានត្រឹមត្រូវ។ លើសពីនេះ ការប៉ះពាល់ផ្ទាល់នឹងផលិតផលពង្រីក ងាយបង្កការចម្លងរោគ (contamination) និងមានហានិភ័យ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-06-Q01','SP-06','Sample Pretreatment','Can I test PCR products on Pluslife?','អាចធ្វើតេស្តផលិតផល PCR លើ Pluslife បានទេ?','No. PCR amplification regions do not necessarily overlap with Pluslife''s amplification regions, so PCR products may not test properly on the Pluslife platform. In addition, handling amplification products directly easily causes contamination and carries risk.','មិនបានទេ។ តំបន់ពង្រីករបស់ PCR មិនប្រាកដថាត្រួតគ្នានឹងតំបន់ពង្រីករបស់ Pluslife ទេ ដូច្នេះផលិតផល PCR អាចធ្វើតេស្តលើ Pluslife មិនបានត្រឹមត្រូវ។ លើសពីនេះ ការប៉ះពាល់ផ្ទាល់នឹងផលិតផលពង្រីក ងាយបង្កការចម្លងរោគ (contamination) និងមានហានិភ័យ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-06-Q02','SP-06','Sample Pretreatment','use leftover PCR product to test','ប្រើផលិតផល PCR ដែលនៅសល់ ដើម្បីធ្វើតេស្ត','No. PCR amplification regions do not necessarily overlap with Pluslife''s amplification regions, so PCR products may not test properly on the Pluslife platform. In addition, handling amplification products directly easily causes contamination and carries risk.','មិនបានទេ។ តំបន់ពង្រីករបស់ PCR មិនប្រាកដថាត្រួតគ្នានឹងតំបន់ពង្រីករបស់ Pluslife ទេ ដូច្នេះផលិតផល PCR អាចធ្វើតេស្តលើ Pluslife មិនបានត្រឹមត្រូវ។ លើសពីនេះ ការប៉ះពាល់ផ្ទាល់នឹងផលិតផលពង្រីក ងាយបង្កការចម្លងរោគ (contamination) និងមានហានិភ័យ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-06-Q03','SP-06','Sample Pretreatment','Is it risky to open PCR tubes in the lab?','តើការបើកបំពង់ PCR ក្នុងមន្ទីរពិសោធន៍ មានហានិភ័យទេ?','Yes. Handling amplification products directly easily causes contamination and carries risk.','បាទ/ចាស។ ការប៉ះពាល់ផ្ទាល់នឹងផលិតផលពង្រីក (amplification products) ងាយបង្កការចម្លងរោគ (contamination) និងមានហានិភ័យ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-07','SP-07','Sample Pretreatment','Worker unsure how much sputum to add to the release reagent','ត្រូវដាក់កំហាកប៉ុន្មានចូលក្នុង Releasing Agent?','When collecting the sputum sample, immerse the swab into the sputum and mix/rotate it thoroughly to ensure the swab is well coated with the sputum, then transfer the swab into the release reagent.','ពេលយកសំណាកកំហាក សូមជ្រលក់ដងសំឡីចូលក្នុងកំហាក ហើយកូរ/បង្វិលឱ្យសព្វ ដើម្បីធានាថាដងសំឡីជាប់កំហាកបានល្អ រួចផ្ទេរដងសំឡីចូលក្នុង release reagent។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-07-Q01','SP-07','Sample Pretreatment','How much sputum do I add to the release reagent?','តើខ្ញុំដាក់កំហាកប៉ុន្មានចូលក្នុង release reagent?','When collecting the sputum sample, immerse the swab into the sputum and mix/rotate it thoroughly to ensure the swab is well coated with the sputum, then transfer the swab into the release reagent.','ពេលយកសំណាកកំហាក សូមជ្រលក់ដងសំឡីចូលក្នុងកំហាក ហើយកូរ/បង្វិលឱ្យសព្វ ដើម្បីធានាថាដងសំឡីជាប់កំហាកបានល្អ រួចផ្ទេរដងសំឡីចូលក្នុង release reagent។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-07-Q02','SP-07','Sample Pretreatment','Do I pour the sputum into the tube?','តើខ្ញុំចាក់កំហាកចូលក្នុងបំពង់ទេ?','No. Immerse the swab into the sputum and mix/rotate it thoroughly so the swab is well coated, then transfer the swab into the release reagent.','ទេ។ ជ្រលក់ដងសំឡីចូលក្នុងកំហាក ហើយកូរ/បង្វិលឱ្យសព្វ ដើម្បីឱ្យដងសំឡីជាប់កំហាកបានល្អ រួចផ្ទេរដងសំឡីចូលក្នុង release reagent។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-07-Q03','SP-07','Sample Pretreatment','sputum amount into tube','បរិមាណកំហាកដាក់ចូលបំពង់','When collecting the sputum sample, immerse the swab into the sputum and mix/rotate it thoroughly to ensure the swab is well coated with the sputum, then transfer the swab into the release reagent.','ពេលយកសំណាកកំហាក សូមជ្រលក់ដងសំឡីចូលក្នុងកំហាក ហើយកូរ/បង្វិលឱ្យសព្វ ដើម្បីធានាថាដងសំឡីជាប់កំហាកបានល្អ រួចផ្ទេរដងសំឡីចូលក្នុង release reagent។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-08','SP-08','Sample Pretreatment','Worker unsure how to elute the swab, or left the swab in the tube','ត្រូវកូរដងសំឡីក្នុងសូលុយស្យុងដូចម្តេច ដើម្បីឱ្យសំណាកចេញពីចុងសំឡី? អាចទុកដងសំឡីក្នុងបំពង់បានទេ?','Immerse the swab into the releasing agent, rotate and stir the swab while squeezing the tube wall 10 times to ensure the sample is fully eluted into the releasing agent.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-08-Q01','SP-08','Sample Pretreatment','How do I elute the swab in the releasing agent?','តើខ្ញុំលាងសំណាកចេញពីដងសំឡី (elute) ក្នុង Releasing agent យ៉ាងម៉េច?','Immerse the swab into the releasing agent, rotate and stir the swab while squeezing the tube wall 10 times to ensure the sample is fully eluted into the releasing agent.','ជ្រលក់ដងសំឡីចូលក្នុង Releasing agent បង្វិល និងកូរដងសំឡី ពេលច្របាច់ជញ្ជាំងបំពង់ 10 ដង ដើម្បីធានាថាសំណាកត្រូវបានលាងចេញចូលក្នុង Releasing agent ទាំងស្រុង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-08-Q02','SP-08','Sample Pretreatment','How many times do I squeeze the tube?','តើខ្ញុំច្របាច់បំពង់ប៉ុន្មានដង?','Rotate and stir the swab while squeezing the tube wall 10 times.','បង្វិល និងកូរដងសំឡី ពេលច្របាច់ជញ្ជាំងបំពង់ 10 ដង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-08-Q03','SP-08','Sample Pretreatment','Can I leave the swab in the tube?','អាចទុកដងសំឡីក្នុងបំពង់បានទេ?','No. Do not leave the swab in the releasing agent, as it may lead to an invalid result.','មិនបានទេ។ កុំទុកដងសំឡីក្នុង Releasing agent ព្រោះវាអាចធ្វើឱ្យលទ្ធផលគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-08-Q04','SP-08','Sample Pretreatment','swab stay inside tube ok?','ទុកដងសំឡីក្នុងបំពង់ បានទេ?','No. Do not leave the swab in the releasing agent, as it may lead to an invalid result.','មិនបានទេ។ កុំទុកដងសំឡីក្នុង Releasing agent ព្រោះវាអាចធ្វើឱ្យលទ្ធផលគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-08-Q05','SP-08','Sample Pretreatment','I forgot the swab in the tube and heated it.','ខ្ញុំភ្លេចដងសំឡីក្នុងបំពង់ ហើយបានកម្តៅវា។ ត្រូវធ្វើម៉េច?','Not sure what to do with this sample — that is not stated. Leaving the swab in the releasing agent may lead to an invalid result.','មិនប្រាកដថាត្រូវធ្វើអ្វីជាមួយសំណាកនេះទេ — រឿងនេះមិនមានបញ្ជាក់ទេ។ ការទុកដងសំឡីក្នុង Releasing agent អាចធ្វើឱ្យលទ្ធផលគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-09','SP-09','Sample Pretreatment','Thermolyse not available, or worker asks how many samples it holds','បើគ្មាន Thermolyse ត្រូវធ្វើម៉េច? បើមាន អាចដាក់បានប៉ុន្មានសំណាកក្នុងមួយលើក?','We recommend using the Thermolyse to heat and vortex for 5 minutes. You may also use the laboratory''s mixer — in that case, heat the sample at 75 °C for 10 minutes, then vortex for 5 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-09-Q01','SP-09','Sample Pretreatment','Is the Thermolyse necessary?','តើ Thermolyse ចាំបាច់ទេ?','No, but it is recommended. We recommend using the Thermolyse to heat and vortex for 5 minutes. You may also use the laboratory''s mixer instead.','មិនចាំបាច់ទេ ប៉ុន្តែត្រូវបានណែនាំ។ យើងណែនាំឱ្យប្រើ Thermolyse ដើម្បីកម្តៅ និងកូរ (vortex) រយៈពេល 5 នាទី។ អ្នកក៏អាចប្រើម៉ាស៊ីនកូររបស់មន្ទីរពិសោធន៍ជំនួសបានដែរ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-09-Q02','SP-09','Sample Pretreatment','Can I use the lab vortex mixer instead of the Thermolyse?','អាចប្រើម៉ាស៊ីនកូរ (vortex mixer) របស់មន្ទីរពិសោធន៍ ជំនួស Thermolyse បានទេ?','Yes. In that case, heat the sample at 75 °C for 10 minutes, then vortex for 5 minutes.','បាទ/ចាស។ ក្នុងករណីនោះ សូមកម្តៅសំណាកនៅ 75 °C រយៈពេល 10 នាទី រួចកូរ (vortex) រយៈពេល 5 នាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-09-Q03','SP-09','Sample Pretreatment','Thermolyse broken, what now?','Thermolyse ខូច ត្រូវធ្វើអ្វី?','You may use the laboratory''s mixer: heat the sample at 75 °C for 10 minutes, then vortex for 5 minutes.','អ្នកអាចប្រើម៉ាស៊ីនកូររបស់មន្ទីរពិសោធន៍៖ កម្តៅសំណាកនៅ 75 °C រយៈពេល 10 នាទី រួចកូរ (vortex) រយៈពេល 5 នាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-09-Q04','SP-09','Sample Pretreatment','How many samples can the Thermolyse run at once?','តើ Thermolyse អាចដំណើរការសំណាកបានប៉ុន្មានក្នុងពេលតែមួយ?','1 to 3 samples at the same time.','សំណាកពី 1 ដល់ 3 ក្នុងពេលតែមួយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-09-Q05','SP-09','Sample Pretreatment','Can I put 4 tubes in the Thermolyse?','អាចដាក់បំពង់ 4 ក្នុង Thermolyse បានទេ?','No. It can process 1 to 3 samples at the same time.','មិនបានទេ។ វាអាចដំណើរការសំណាកពី 1 ដល់ 3 ក្នុងពេលតែមួយ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-10','SP-10','Sample Pretreatment','Worker waits for the heated sample to cool before adding it to the card','កម្តៅសំណាករួច ត្រូវរង់ចាំឱ្យត្រជាក់សិន មុនដាក់ចូលកាតទេ?','No, it''s not necessary. You can proceed to add the sample directly.','មិនចាំបាច់ទេ។ អ្នកអាចបន្តដាក់សំណាកបានភ្លាម។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-10-Q01','SP-10','Sample Pretreatment','Do I need to let the tube cool down before adding to the card?','តើខ្ញុំត្រូវទុកបំពង់ឱ្យត្រជាក់ មុនដាក់ចូលកាតទេ?','No, it''s not necessary. You can proceed to add the sample directly.','មិនចាំបាច់ទេ។ អ្នកអាចបន្តដាក់សំណាកបានភ្លាម។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-10-Q02','SP-10','Sample Pretreatment','tube still hot, wait?','បំពង់នៅក្តៅ ត្រូវរង់ចាំទេ?','No, it''s not necessary. You can proceed to add the sample directly.','មិនចាំបាច់ទេ។ អ្នកអាចបន្តដាក់សំណាកបានភ្លាម។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-10-Q03','SP-10','Sample Pretreatment','After heating, can I add the sample straight away?','ក្រោយកម្តៅរួច អាចដាក់សំណាកភ្លាមៗបានទេ?','Yes. You can proceed to add the sample directly.','បាទ/ចាស។ អ្នកអាចបន្តដាក់សំណាកបានភ្លាម។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-11','SP-11','Sample Pretreatment','Thermolyse keeps beeping','Thermolyse រោទិ៍មិនឈប់។ ត្រូវធ្វើម៉េច?','Press "Run/Stop" once.','ចុច "Run/Stop" ម្តង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-11-Q01','SP-11','Sample Pretreatment','How do I stop the Thermolyse beeping?','តើខ្ញុំធ្វើម៉េច ដើម្បីឱ្យ Thermolyse ឈប់រោទិ៍?','Press "Run/Stop" once.','ចុច "Run/Stop" ម្តង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-11-Q02','SP-11','Sample Pretreatment','thermolyse beep','Thermolyse រោទិ៍។ ត្រូវធ្វើម៉េច?','Press "Run/Stop" once.','ចុច "Run/Stop" ម្តង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-11-Q03','SP-11','Sample Pretreatment','The heater won''t stop beeping after 5 minutes.','ម៉ាស៊ីនកម្តៅមិនឈប់រោទិ៍ ក្រោយ 5 នាទី។ ត្រូវធ្វើម៉េច?','Press "Run/Stop" once.','ចុច "Run/Stop" ម្តង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-12','SP-12','Sample Pretreatment','Sample leaked/splashed, or reagent sprays out of the tube cap after heating','សំណាកលេច ឬខ្ទាត ឬសូលុយស្យុងខ្ទាតចេញពីគម្របបំពង់ក្រោយកម្តៅ។ ត្រូវធ្វើម៉េច?','Spray 75% alcohol onto a tissue to wipe off the reagent, and change gloves before proceeding with the test.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-12-Q01','SP-12','Sample Pretreatment','The sample leaked on the bench.','សំណាកលេចធ្លាយលើតុ។ ត្រូវធ្វើម៉េច?','Spray 75% alcohol onto a tissue to wipe off the reagent, and change gloves before proceeding with the test.','បាញ់អាល់កុល 75% លើក្រដាសជូតមាត់ ដើម្បីជូតសារធាតុចេញ ហើយប្តូរស្រោមដៃ មុនបន្តធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-12-Q02','SP-12','Sample Pretreatment','What do I clean a spill with?','តើខ្ញុំសម្អាតទឹកដែលកំពប់ដោយប្រើអ្វី?','Spray 75% alcohol onto a tissue to wipe off the reagent.','បាញ់អាល់កុល 75% លើក្រដាសជូតមាត់ ដើម្បីជូតសារធាតុចេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-12-Q03','SP-12','Sample Pretreatment','Reagent sprayed out when I opened the cap after heating.','សារធាតុបាញ់ចេញ ពេលខ្ញុំបើកគម្របក្រោយកម្តៅ។ ត្រូវធ្វើម៉េច?','To prevent this: do not invert the releasing agent before or after heating.','ដើម្បីការពារបញ្ហានេះ៖ កុំបញ្ច្រាស (ផ្កាប់) បំពង់ Releasing agent មុន ឬក្រោយកម្តៅ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-12-Q04','SP-12','Sample Pretreatment','Can I turn the tube upside down to mix?','អាចផ្កាប់បំពង់ ដើម្បីលាយបានទេ?','No. Do not invert the releasing agent before or after heating.','មិនបានទេ។ កុំបញ្ច្រាស (ផ្កាប់) បំពង់ Releasing agent មុន ឬក្រោយកម្តៅ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('SP-12-Q05','SP-12','Sample Pretreatment','Do I need new gloves after a spill?','តើខ្ញុំត្រូវប្តូរស្រោមដៃថ្មី ក្រោយទឹកកំពប់ទេ?','Yes. Change gloves before proceeding with the test.','បាទ/ចាស។ ប្តូរស្រោមដៃ មុនបន្តធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-06','CP-06','Card Preparation','Worker unsure how much releasing agent to load, or loaded too much/too little','ត្រូវបញ្ចូលសូលុយស្យុងពីបំពង់ Releasing Agent ប៉ុន្មានទៅក្នុងកាត? បើដាក់លើស ឬខ្វះ ត្រូវធ្វើម៉េច?','The releasing agent tube contains 2 mL (2000 µL). The amount added to the test card should be 0.4–0.5 mL (corresponding to the upper and lower marks on the card), with a nominal loading volume of 450 µL.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-06-Q01','CP-06','Card Preparation','How much liquid do I add to the card?','តើខ្ញុំដាក់ទឹកប៉ុន្មានចូលកាត?','0.4–0.5 mL (between the upper and lower marks on the card), with a nominal loading volume of 450 µL. It is recommended to add the liquid up to the middle of the scale lines.','0.4–0.5 mL (នៅចន្លោះសញ្ញាខាងលើ និងខាងក្រោមលើកាត) ដោយបរិមាណស្តង់ដារគឺ 450 µL។ ណែនាំឱ្យដាក់ទឹករហូតដល់ពាក់កណ្តាលបន្ទាត់សញ្ញា។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-06-Q02','CP-06','Card Preparation','How much is in the releasing agent tube?','តើក្នុងបំពង់ Releasing agent មានប៉ុន្មាន?','2 mL (2000 µL).','2 mL (2000 µL)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-06-Q03','CP-06','Card Preparation','I added above the top line. Is that a problem?','ខ្ញុំដាក់លើសបន្ទាត់ខាងលើ។ តើវាជាបញ្ហាទេ?','Yes. If the releasing agent is excessive, the liquid may not be able to flow into each chamber due to pressure imbalance, which can cause large air bubbles and affect the result.','បាទ/ចាស។ បើដាក់ Releasing agent ច្រើនពេក ទឹកអាចមិនហូរចូលរន្ធនីមួយៗបាន ដោយសារសម្ពាធមិនស្មើគ្នា ដែលអាចបង្កពពុះខ្យល់ធំ ហើយប៉ះពាល់ដល់លទ្ធផល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-06-Q04','CP-06','Card Preparation','Liquid is below the lower mark.','ទឹកនៅក្រោមសញ្ញាខាងក្រោម។ ត្រូវធ្វើម៉េច?','If too little is added, the liquid may fail to fill the chambers properly, which can cause large air bubbles and affect the result.','បើដាក់តិចពេក ទឹកអាចមិនពេញរន្ធបានត្រឹមត្រូវ ដែលអាចបង្កពពុះខ្យល់ធំ ហើយប៉ះពាល់ដល់លទ្ធផល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-06-Q05','CP-06','Card Preparation','Do I add the whole tube?','តើខ្ញុំដាក់ទាំងបំពង់ទេ?','No. The tube contains 2 mL; add 0.4–0.5 mL to the card (between the two marks).','ទេ។ បំពង់មាន 2 mL សូមដាក់ 0.4–0.5 mL ចូលកាត (នៅចន្លោះសញ្ញាទាំងពីរ)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-06-Q06','CP-06','Card Preparation','loading volume','បរិមាណដាក់ចូលកាត','The releasing agent tube contains 2 mL (2000 µL). The amount added to the test card should be 0.4–0.5 mL (corresponding to the upper and lower marks on the card), with a nominal loading volume of 450 µL.','បំពង់ Releasing agent មាន 2 mL (2000 µL)។ បរិមាណដែលដាក់ចូលកាតតេស្ត គួរមាន 0.4–0.5 mL (ត្រូវនឹងសញ្ញាខាងលើ និងខាងក្រោមលើកាត) ដោយបរិមាណស្តង់ដារគឺ 450 µL។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-07','CP-07','Card Preparation','Bubbles visible in chambers after loading','បញ្ចូលសំណាកហើយ ឃើញពពុះខ្យល់ក្នុងបន្ទប់តូចៗលើកាត។ ត្រូវធ្វើម៉េច?','Before placing the card in the instrument, check again for obvious bubbles; flick the card gently with a finger to move bubbles to the top.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-07-Q01','CP-07','Card Preparation','I see small bubbles in some chambers. Can I still run it?','ខ្ញុំឃើញពពុះតូចៗក្នុងរន្ធខ្លះ។ តើខ្ញុំនៅតែអាចដំណើរការវាបានទេ?','Yes. Tiny bubbles in the chambers do not affect the test. Flick the card gently with a finger to move bubbles to the top.','បាទ/ចាស។ ពពុះតូចៗក្នុងរន្ធ មិនប៉ះពាល់ដល់តេស្តទេ។ ប៉ោកកាតថ្នមៗដោយម្រាមដៃ ដើម្បីឱ្យពពុះរំកិលទៅខាងលើ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-07-Q02','CP-07','Card Preparation','There''s a big bubble in the middle of one chamber.','មានពពុះធំមួយនៅកណ្តាលរន្ធមួយ។ ត្រូវធ្វើម៉េច?','Large bubbles in the center of a chamber will affect the result; a new test card must be prepared.','ពពុះធំនៅកណ្តាលរន្ធ នឹងប៉ះពាល់ដល់លទ្ធផល។ ត្រូវតែរៀបចំកាតតេស្តថ្មី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-07-Q03','CP-07','Card Preparation','How do I get bubbles out?','តើខ្ញុំយកពពុះចេញយ៉ាងម៉េច?','Flick the card gently with a finger to move bubbles to the top.','ប៉ោកកាតថ្នមៗដោយម្រាមដៃ ដើម្បីឱ្យពពុះរំកិលទៅខាងលើ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-07-Q04','CP-07','Card Preparation','What problems do bubbles cause?','តើពពុះបង្កបញ្ហាអ្វីខ្លះ?','Bubbles affect the fluorescence signal and can lead to invalid or false-positive results.','ពពុះប៉ះពាល់ដល់សញ្ញាពន្លឺ (fluorescence signal) ហើយអាចធ្វើឱ្យលទ្ធផលគ្មានសុពលភាព ឬវិជ្ជមានក្លែងក្លាយ (false-positive)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-07-Q05','CP-07','Card Preparation','bubbles 1/3 chamber','ពពុះ 1/3 នៃរន្ធ','Do not run the test; use a new card and reload the sample.','កុំដំណើរការតេស្ត។ សូមប្រើកាតថ្មី ហើយដាក់សំណាកម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-07-Q06','CP-07','Card Preparation','Can bubbles give a false positive?','តើពពុះអាចធ្វើឱ្យលទ្ធផលវិជ្ជមានក្លែងក្លាយបានទេ?','Yes. Bubbles can lead to invalid or false-positive results.','បាទ/ចាស។ ពពុះអាចធ្វើឱ្យលទ្ធផលគ្មានសុពលភាព ឬវិជ្ជមានក្លែងក្លាយ (false-positive)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-08','CP-08','Card Preparation','Lyophilized beads don''t dissolve after adding releasing agent','ដាក់សូលុយស្យុងពីបំពង់ Releasing Agent ហើយ តែគ្រាប់សារធាតុស្ងួតមិនរលាយ។ ត្រូវធ្វើម៉េច?','Normally they dissolve after shaking. If they never dissolve, the card may be expired or there may be a product quality issue; do not use it.','ជាធម្មតា វារលាយក្រោយអង្រួន។ បើវាមិនរលាយសោះ កាតអាចផុតកំណត់ ឬផលិតផលអាចមានបញ្ហាគុណភាព។ កុំប្រើវា។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-08-Q01','CP-08','Card Preparation','The beads in the card did not dissolve.','គ្រាប់សារធាតុក្នុងកាតមិនរលាយ។ ត្រូវធ្វើម៉េច?','Normally they dissolve after shaking. If they never dissolve, the card may be expired or there may be a product quality issue; do not use it.','ជាធម្មតា វារលាយក្រោយអង្រួន។ បើវាមិនរលាយសោះ កាតអាចផុតកំណត់ ឬផលិតផលអាចមានបញ្ហាគុណភាព។ កុំប្រើវា។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-08-Q02','CP-08','Card Preparation','bead not melt','គ្រាប់សារធាតុមិនរលាយ។ ត្រូវធ្វើម៉េច?','Normally they dissolve after shaking. If they never dissolve, the card may be expired or there may be a product quality issue; do not use it.','ជាធម្មតា វារលាយក្រោយអង្រួន។ បើវាមិនរលាយសោះ កាតអាចផុតកំណត់ ឬផលិតផលអាចមានបញ្ហាគុណភាព។ កុំប្រើវា។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-08-Q03','CP-08','Card Preparation','Can I still use a card if the beads won''t dissolve after shaking?','តើខ្ញុំនៅតែអាចប្រើកាតបានទេ បើគ្រាប់សារធាតុមិនរលាយក្រោយអង្រួន?','No. If they never dissolve, the card may be expired or there may be a product quality issue; do not use it.','មិនបានទេ។ បើវាមិនរលាយសោះ កាតអាចផុតកំណត់ ឬផលិតផលអាចមានបញ្ហាគុណភាព។ កុំប្រើវា។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-09','CP-09','Card Preparation','Worker asks what to watch out for when preparing the card','ពេលរៀបចំកាតតេស្ត ត្រូវប្រយ័ត្នអ្វីខ្លះ?','1. Add the Releasing Agent until the liquid level is between the 2 marks.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-09-Q01','CP-09','Card Preparation','What should I check when preparing the test card?','តើខ្ញុំគួរពិនិត្យអ្វីខ្លះ ពេលរៀបចំកាតតេស្ត?','1. Add the Releasing Agent until the liquid level is between the 2 marks.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-09-Q02','CP-09','Card Preparation','How many times do I shake the card?','តើខ្ញុំអង្រួនកាតប៉ុន្មានដង?','Shake the test card quickly 10 times; do not turn the card upside down.','អង្រួនកាតតេស្តលឿនៗ 10 ដង។ កុំបញ្ច្រាស (ផ្កាប់) កាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-09-Q03','CP-09','Card Preparation','Can I turn the card upside down?','អាចផ្កាប់កាតបានទេ?','No. Do not turn the card upside down.','មិនបានទេ។ កុំបញ្ច្រាស (ផ្កាប់) កាត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-09-Q04','CP-09','Card Preparation','card prep tips','គន្លឹះរៀបចំកាត','1. Add the Releasing Agent until the liquid level is between the 2 marks.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-10','CP-10','Card Preparation','Lyophilized beads in the card look broken','ឃើញគ្រាប់សារធាតុស្ងួតក្នុងកាតបែក។ នៅប្រើកាតនេះបានទេ?','Broken lyophilized beads do not affect the result. As long as the test card is within its expiry date and its appearance is undamaged, it can be used.','គ្រាប់សារធាតុស្ងួតដែលបែក មិនប៉ះពាល់ដល់លទ្ធផលទេ។ ដរាបណាកាតតេស្តនៅក្នុងកាលកំណត់ ហើយរូបរាងខាងក្រៅមិនខូច អាចប្រើបាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-10-Q01','CP-10','Card Preparation','The beads in the card are broken. Can I use it?','គ្រាប់សារធាតុក្នុងកាតបែក។ អាចប្រើវាបានទេ?','Yes. Broken lyophilized beads do not affect the result. As long as the test card is within its expiry date and its appearance is undamaged, it can be used.','បាទ/ចាស។ គ្រាប់សារធាតុស្ងួត (lyophilized beads) ដែលបែក មិនប៉ះពាល់ដល់លទ្ធផលទេ។ ដរាបណាកាតតេស្តនៅក្នុងកាលកំណត់ ហើយរូបរាងខាងក្រៅមិនខូច អាចប្រើបាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-10-Q02','CP-10','Card Preparation','bead crack','គ្រាប់សារធាតុប្រេះ','Broken lyophilized beads do not affect the result. As long as the test card is within its expiry date and its appearance is undamaged, it can be used.','គ្រាប់សារធាតុស្ងួតដែលបែក មិនប៉ះពាល់ដល់លទ្ធផលទេ។ ដរាបណាកាតតេស្តនៅក្នុងកាលកំណត់ ហើយរូបរាងខាងក្រៅមិនខូច អាចប្រើបាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-10-Q03','CP-10','Card Preparation','Will broken beads affect the result?','តើគ្រាប់សារធាតុដែលបែក នឹងប៉ះពាល់ដល់លទ្ធផលទេ?','No. Broken lyophilized beads do not affect the result. As long as the test card is within its expiry date and its appearance is undamaged, it can be used.','ទេ។ គ្រាប់សារធាតុស្ងួត (lyophilized beads) ដែលបែក មិនប៉ះពាល់ដល់លទ្ធផលទេ។ ដរាបណាកាតតេស្តនៅក្នុងកាលកំណត់ ហើយរូបរាងខាងក្រៅមិនខូច អាចប្រើបាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-11','CP-11','Card Preparation','The 7 chambers are not full after loading','បញ្ចូលសំណាកហើយ តែបន្ទប់ទាំង ៧ លើកាតមិនពេញ។ ត្រូវធ្វើម៉េច?','If the 7 chambers are not full after loading correctly according to the instructions, wait a few minutes; the liquid will gradually fill the chambers.','បើរន្ធទាំង 7 មិនពេញ ក្រោយដាក់សំណាកត្រឹមត្រូវតាមការណែនាំ សូមរង់ចាំពីរបីនាទី។ ទឹកនឹងហូរពេញរន្ធបន្តិចម្តងៗ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-11-Q01','CP-11','Card Preparation','The chambers are not full after I loaded the sample.','រន្ធមិនពេញ ក្រោយខ្ញុំដាក់សំណាក។ ត្រូវធ្វើម៉េច?','If the 7 chambers are not full after loading correctly according to the instructions, wait a few minutes; the liquid will gradually fill the chambers.','បើរន្ធទាំង 7 មិនពេញ ក្រោយដាក់សំណាកត្រឹមត្រូវតាមការណែនាំ សូមរង់ចាំពីរបីនាទី។ ទឹកនឹងហូរពេញរន្ធបន្តិចម្តងៗ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-11-Q02','CP-11','Card Preparation','chamber not full','រន្ធមិនពេញ។ ត្រូវធ្វើម៉េច?','Wait a few minutes; the liquid will gradually fill the chambers.','រង់ចាំពីរបីនាទី។ ទឹកនឹងហូរពេញរន្ធបន្តិចម្តងៗ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-11-Q03','CP-11','Card Preparation','Should I throw away the card if the chambers aren''t full?','តើខ្ញុំគួរបោះចោលកាតទេ បើរន្ធមិនពេញ?','Not straight away. If you loaded correctly according to the instructions, wait a few minutes; the liquid will gradually fill the chambers.','មិនទាន់ភ្លាមៗទេ។ បើអ្នកបានដាក់សំណាកត្រឹមត្រូវតាមការណែនាំ សូមរង់ចាំពីរបីនាទី។ ទឹកនឹងហូរពេញរន្ធបន្តិចម្តងៗ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-12','CP-12','Card Preparation','Beads dissolved after screwing on the cap but before pressing','បិទគម្របកាតហើយ គ្រាប់សារធាតុស្ងួតរលាយមុនខ្ញុំចុចថង់ខ្យល់។ ត្រូវធ្វើម៉េច?','This is normal and does not affect the result.','នេះជារឿងធម្មតា ហើយមិនប៉ះពាល់ដល់លទ្ធផលទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-12-Q01','CP-12','Card Preparation','The beads dissolved before I pressed the airbag. Is that a problem?','គ្រាប់សារធាតុរលាយ មុនពេលខ្ញុំសង្កត់ថង់ខ្យល់ (airbag)។ តើវាជាបញ្ហាទេ?','No. This is normal and does not affect the result.','ទេ។ នេះជារឿងធម្មតា ហើយមិនប៉ះពាល់ដល់លទ្ធផលទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-12-Q02','CP-12','Card Preparation','bead dissolve early','គ្រាប់សារធាតុរលាយមុនពេល','This is normal and does not affect the result.','នេះជារឿងធម្មតា ហើយមិនប៉ះពាល់ដល់លទ្ធផលទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-12-Q03','CP-12','Card Preparation','Is it normal that beads dissolve right after I screw on the cap?','តើជារឿងធម្មតាទេ ដែលគ្រាប់សារធាតុរលាយភ្លាមៗក្រោយខ្ញុំមួលគម្រប?','Yes. This is normal and does not affect the result.','បាទ/ចាស។ នេះជារឿងធម្មតា ហើយមិនប៉ះពាល់ដល់លទ្ធផលទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-13','CP-13','Card Preparation','Worker wants to use an expired test card','កាតតេស្តផុតកំណត់ហើយ។ នៅប្រើបានទេ?','Always check the test card''s expiry date before testing. Test cards have a shelf life of 13 months; expired cards must not be used, and the MiniDock will alarm and refuse to start the test.','ត្រូវពិនិត្យកាលកំណត់នៃកាតតេស្តជានិច្ច មុនធ្វើតេស្ត។ កាតតេស្តមានអាយុកាលប្រើប្រាស់ 13 ខែ។ ហាមប្រើកាតដែលផុតកំណត់ ហើយ MiniDock នឹងរោទិ៍ ហើយមិនព្រមចាប់ផ្តើមតេស្តទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-13-Q01','CP-13','Card Preparation','Can I use expired test cards?','អាចប្រើកាតតេស្តដែលផុតកំណត់បានទេ?','No. Expired cards must not be used, and the MiniDock will alarm and refuse to start the test.','មិនបានទេ។ ហាមប្រើកាតដែលផុតកំណត់ ហើយ MiniDock នឹងរោទិ៍ ហើយមិនព្រមចាប់ផ្តើមតេស្តទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-13-Q02','CP-13','Card Preparation','What is the shelf life of the cards?','តើកាតមានអាយុកាលប្រើប្រាស់ប៉ុន្មាន?','Test cards have a shelf life of 13 months.','កាតតេស្តមានអាយុកាលប្រើប្រាស់ 13 ខែ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-13-Q03','CP-13','Card Preparation','card expire last month, still ok?','កាតផុតកំណត់ខែមុន នៅប្រើបានទេ?','No. Always check the test card''s expiry date before testing. Test cards have a shelf life of 13 months; expired cards must not be used, and the MiniDock will alarm and refuse to start the test.','មិនបានទេ។ ត្រូវពិនិត្យកាលកំណត់នៃកាតតេស្តជានិច្ច មុនធ្វើតេស្ត។ កាតតេស្តមានអាយុកាលប្រើប្រាស់ 13 ខែ។ ហាមប្រើកាតដែលផុតកំណត់ ហើយ MiniDock នឹងរោទិ៍ ហើយមិនព្រមចាប់ផ្តើមតេស្តទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-13-Q04','CP-13','Card Preparation','When do I check the expiry date?','តើខ្ញុំពិនិត្យកាលកំណត់នៅពេលណា?','Always check the test card''s expiry date before testing.','ត្រូវពិនិត្យកាលកំណត់នៃកាតតេស្តជានិច្ច មុនធ្វើតេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-14','CP-14','Card Preparation','Large air bubbles remain after following the standard procedure','ខ្ញុំធ្វើតាមជំហានណែនាំរួច តែនៅឃើញពពុះខ្យល់ធំៗក្នុងកាត។ ត្រូវធ្វើម៉េច?','If there are large air bubbles in the chamber, we recommend loosening and re-tightening the cap. If the liquid still does not fill the chamber, seal and discard the card, and open a new one for sample loading.','បើមានពពុះខ្យល់ធំក្នុងរន្ធ យើងណែនាំឱ្យបន្ធូរគម្របបន្តិច រួចមួលឱ្យជិតវិញ។ បើទឹកនៅតែមិនពេញរន្ធ សូមបិទកាតឱ្យជិត ហើយបោះចោល រួចបើកកាតថ្មីដើម្បីដាក់សំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-14-Q01','CP-14','Card Preparation','Still big bubbles after doing everything right.','នៅតែមានពពុះធំ ក្រោយធ្វើត្រឹមត្រូវគ្រប់យ៉ាង។ ត្រូវធ្វើម៉េច?','If there are large air bubbles in the chamber, we recommend loosening and re-tightening the cap. If the liquid still does not fill the chamber, seal and discard the card, and open a new one for sample loading.','បើមានពពុះខ្យល់ធំក្នុងរន្ធ យើងណែនាំឱ្យបន្ធូរគម្របបន្តិច រួចមួលឱ្យជិតវិញ។ បើទឹកនៅតែមិនពេញរន្ធ សូមបិទកាតឱ្យជិត ហើយបោះចោល រួចបើកកាតថ្មីដើម្បីដាក់សំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-14-Q02','CP-14','Card Preparation','Should I loosen the cap to get rid of bubbles?','តើខ្ញុំគួរបន្ធូរគម្រប ដើម្បីបំបាត់ពពុះទេ?','Yes. We recommend loosening and re-tightening the cap. If the liquid still does not fill the chamber, seal and discard the card and open a new one.','បាទ/ចាស។ យើងណែនាំឱ្យបន្ធូរគម្របបន្តិច រួចមួលឱ្យជិតវិញ។ បើទឹកនៅតែមិនពេញរន្ធ សូមបិទកាតឱ្យជិត ហើយបោះចោល រួចបើកកាតថ្មី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-14-Q03','CP-14','Card Preparation','big bubble not go away','ពពុះធំមិនបាត់។ ត្រូវធ្វើម៉េច?','If there are large air bubbles in the chamber, we recommend loosening and re-tightening the cap. If the liquid still does not fill the chamber, seal and discard the card, and open a new one for sample loading.','បើមានពពុះខ្យល់ធំក្នុងរន្ធ យើងណែនាំឱ្យបន្ធូរគម្របបន្តិច រួចមួលឱ្យជិតវិញ។ បើទឹកនៅតែមិនពេញរន្ធ សូមបិទកាតឱ្យជិត ហើយបោះចោល រួចបើកកាតថ្មីដើម្បីដាក់សំណាក។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-15','CP-15','Card Preparation','Card leaks during sample loading','កាតលេចទឹកពេលកំពុងបញ្ចូលសំណាក។ ត្រូវធ្វើម៉េច?','Immediately seal the card and wipe off the leaked liquid. Disinfect the area with 75% alcohol. After changing gloves, open a new card and perform the test again.','បិទកាតឱ្យជិតភ្លាមៗ ហើយជូតទឹកដែលលេចធ្លាយចេញ។ សម្លាប់មេរោគលើកន្លែងនោះដោយអាល់កុល 75%។ ក្រោយប្តូរស្រោមដៃរួច សូមបើកកាតថ្មី ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-15-Q01','CP-15','Card Preparation','The card leaked while I was loading the sample.','កាតលេចធ្លាយ ពេលខ្ញុំកំពុងដាក់សំណាក។ ត្រូវធ្វើម៉េច?','Immediately seal the card and wipe off the leaked liquid. Disinfect the area with 75% alcohol. After changing gloves, open a new card and perform the test again.','បិទកាតឱ្យជិតភ្លាមៗ ហើយជូតទឹកដែលលេចធ្លាយចេញ។ សម្លាប់មេរោគលើកន្លែងនោះដោយអាល់កុល 75%។ ក្រោយប្តូរស្រោមដៃរួច សូមបើកកាតថ្មី ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-15-Q02','CP-15','Card Preparation','card leak loading','កាតលេចធ្លាយពេលដាក់សំណាក','Immediately seal the card and wipe off the leaked liquid. Disinfect the area with 75% alcohol. After changing gloves, open a new card and perform the test again.','បិទកាតឱ្យជិតភ្លាមៗ ហើយជូតទឹកដែលលេចធ្លាយចេញ។ សម្លាប់មេរោគលើកន្លែងនោះដោយអាល់កុល 75%។ ក្រោយប្តូរស្រោមដៃរួច សូមបើកកាតថ្មី ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-15-Q03','CP-15','Card Preparation','Can I continue with a card that leaked?','អាចបន្តប្រើកាតដែលលេចធ្លាយបានទេ?','No. Seal the card, wipe off and disinfect the area with 75% alcohol, change gloves, and open a new card.','មិនបានទេ។ បិទកាតឱ្យជិត ជូត និងសម្លាប់មេរោគលើកន្លែងនោះដោយអាល់កុល 75% ប្តូរស្រោមដៃ ហើយបើកកាតថ្មី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-16','CP-16','Card Preparation','Worker unsure whether to invert the card after pressing the air bladder','ចុចថង់ខ្យល់រួច ត្រូវផ្ងារកាតទេ?','Mixing only requires shaking up and down; no inversion is needed. Inverting introduces extra bubbles and the card would need to stand again.','ការលាយ គ្រាន់តែត្រូវអង្រួនឡើងចុះប៉ុណ្ណោះ មិនចាំបាច់បញ្ច្រាស (ផ្កាប់) កាតទេ។ ការបញ្ច្រាសកាត បង្កើតពពុះបន្ថែម ហើយកាតត្រូវទុកឱ្យនឹងម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-16-Q01','CP-16','Card Preparation','Do I need to turn the card upside down 3–4 times after shaking?','តើខ្ញុំត្រូវផ្កាប់កាត 3–4 ដង ក្រោយអង្រួនទេ?','No. Mixing only requires shaking up and down; no inversion is needed. Inverting introduces extra bubbles and the card would need to stand again.','ទេ។ ការលាយ គ្រាន់តែត្រូវអង្រួនឡើងចុះប៉ុណ្ណោះ មិនចាំបាច់បញ្ច្រាស (ផ្កាប់) កាតទេ។ ការបញ្ច្រាសកាត បង្កើតពពុះបន្ថែម ហើយកាតត្រូវទុកឱ្យនឹងម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-16-Q02','CP-16','Card Preparation','shake or invert card?','អង្រួន ឬផ្កាប់កាត?','Only shake up and down; no inversion is needed. Inverting introduces extra bubbles and the card would need to stand again.','គ្រាន់តែអង្រួនឡើងចុះប៉ុណ្ណោះ មិនចាំបាច់បញ្ច្រាស (ផ្កាប់) កាតទេ។ ការបញ្ច្រាសកាត បង្កើតពពុះបន្ថែម ហើយកាតត្រូវទុកឱ្យនឹងម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-16-Q03','CP-16','Card Preparation','Is it wrong to invert the card?','តើការផ្កាប់កាតខុសទេ?','Yes, no inversion is needed. Inverting introduces extra bubbles and the card would need to stand again.','បាទ/ចាស មិនចាំបាច់បញ្ច្រាស (ផ្កាប់) កាតទេ។ ការបញ្ច្រាសកាត បង្កើតពពុះបន្ថែម ហើយកាតត្រូវទុកឱ្យនឹងម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-17','CP-17','Card Preparation','Prepared card left waiting before the test','រៀបចំកាតរួច តែទុកមួយសន្ទុះមុនចាប់ផ្តើមតេស្ត។ នៅប្រើបានទេ?','Once the sample enters the card, amplification may start early and affect the result, causing false negatives or non-specific amplification. We recommend loading the card onto the instrument within 1 minute after preparation.','ពេលសំណាកចូលក្នុងកាតហើយ ការពង្រីក (amplification) អាចចាប់ផ្តើមមុនពេល ហើយប៉ះពាល់ដល់លទ្ធផល បង្កឱ្យមានលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative) ឬការពង្រីកមិនជាក់លាក់ (non-specific amplification)។ យើងណែនាំឱ្យដាក់កាតចូលម៉ាស៊ីនក្នុងរយៈពេល 1 នាទី ក្រោយរៀបចំរួច។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-17-Q01','CP-17','Card Preparation','How soon after adding the sample must I start the test?','ក្រោយដាក់សំណាក តើខ្ញុំត្រូវចាប់ផ្តើមតេស្តក្នុងរយៈពេលប៉ុន្មាន?','We recommend loading the card onto the instrument within 1 minute after preparation.','យើងណែនាំឱ្យដាក់កាតចូលម៉ាស៊ីនក្នុងរយៈពេល 1 នាទី ក្រោយរៀបចំរួច។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-17-Q02','CP-17','Card Preparation','Can I prepare the card and wait 10 minutes?','អាចរៀបចំកាត ហើយរង់ចាំ 10 នាទីបានទេ?','No. Amplification may start early and affect the result, causing false negatives or non-specific amplification. Load the card within 1 minute.','មិនបានទេ។ ការពង្រីក (amplification) អាចចាប់ផ្តើមមុនពេល ហើយប៉ះពាល់ដល់លទ្ធផល បង្កឱ្យមានលទ្ធផលអវិជ្ជមានក្លែងក្លាយ ឬការពង្រីកមិនជាក់លាក់។ សូមដាក់កាតចូលម៉ាស៊ីនក្នុងរយៈពេល 1 នាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-17-Q03','CP-17','Card Preparation','card ready but device busy','កាតរួចរាល់ តែម៉ាស៊ីនកំពុងជាប់រវល់','Not sure what to do with that card — that is not stated. We recommend loading the card onto the instrument within 1 minute after preparation, so prepare it only when the device is ready.','មិនប្រាកដថាត្រូវធ្វើអ្វីជាមួយកាតនោះទេ — រឿងនេះមិនមានបញ្ជាក់ទេ។ យើងណែនាំឱ្យដាក់កាតចូលម៉ាស៊ីនក្នុងរយៈពេល 1 នាទី ក្រោយរៀបចំរួច ដូច្នេះសូមរៀបចំកាត តែពេលម៉ាស៊ីនរួចរាល់ប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('CP-17-Q04','CP-17','Card Preparation','time limit card to device','រយៈពេលកំណត់ពីកាតទៅម៉ាស៊ីន','Within 1 minute after preparation.','ក្នុងរយៈពេល 1 នាទី ក្រោយរៀបចំរួច។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-06','DO-06','Device Operation','Power button pressed by accident while a test is running','ខ្ញុំចុចប៊ូតុងបើកបិទដោយចៃដន្យ ពេលតេស្តកំពុងដំណើរការ។ តើប៉ះពាល់ដល់តេស្តទេ?','Once the device has started testing a sample, pressing the power button does not affect the test. However, we recommend avoiding touching the power button while the device is working.','ពេលម៉ាស៊ីនបានចាប់ផ្តើមធ្វើតេស្តសំណាករួចហើយ ការចុចប៊ូតុងបើក/បិទ មិនប៉ះពាល់ដល់តេស្តទេ។ ប៉ុន្តែ យើងណែនាំឱ្យជៀសវាងការប៉ះប៊ូតុងបើក/បិទ ពេលម៉ាស៊ីនកំពុងដំណើរការ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-06-Q01','DO-06','Device Operation','I pressed the power button by mistake during the test. Is the test ruined?','ខ្ញុំចុចប៊ូតុងបើក/បិទដោយច្រឡំ ពេលកំពុងធ្វើតេស្ត។ តើតេស្តខូចទេ?','No. Once the device has started testing a sample, pressing the power button does not affect the test. However, avoid touching the power button while the device is working.','ទេ។ ពេលម៉ាស៊ីនបានចាប់ផ្តើមធ្វើតេស្តសំណាករួចហើយ ការចុចប៊ូតុងបើក/បិទ មិនប៉ះពាល់ដល់តេស្តទេ។ ប៉ុន្តែ សូមជៀសវាងការប៉ះប៊ូតុងបើក/បិទ ពេលម៉ាស៊ីនកំពុងដំណើរការ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-06-Q02','DO-06','Device Operation','Can I press the power button while the device is running?','អាចចុចប៊ូតុងបើក/បិទ ពេលម៉ាស៊ីនកំពុងដំណើរការបានទេ?','Yes, it does not affect a test that has started. However, we recommend avoiding touching the power button while the device is working.','បាទ/ចាស វាមិនប៉ះពាល់ដល់តេស្តដែលបានចាប់ផ្តើមរួចទេ។ ប៉ុន្តែ យើងណែនាំឱ្យជៀសវាងការប៉ះប៊ូតុងបើក/បិទ ពេលម៉ាស៊ីនកំពុងដំណើរការ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-06-Q03','DO-06','Device Operation','touch button by accident when testing','ប៉ះប៊ូតុងដោយចៃដន្យ ពេលកំពុងធ្វើតេស្ត','Once the device has started testing a sample, pressing the power button does not affect the test. However, we recommend avoiding touching the power button while the device is working.','ពេលម៉ាស៊ីនបានចាប់ផ្តើមធ្វើតេស្តសំណាករួចហើយ ការចុចប៊ូតុងបើក/បិទ មិនប៉ះពាល់ដល់តេស្តទេ។ ប៉ុន្តែ យើងណែនាំឱ្យជៀសវាងការប៉ះប៊ូតុងបើក/បិទ ពេលម៉ាស៊ីនកំពុងដំណើរការ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-06-Q04','DO-06','Device Operation','Will pressing the button stop my running test?','តើការចុចប៊ូតុង នឹងបញ្ឈប់តេស្តដែលកំពុងដំណើរការទេ?','No. Once the device has started testing a sample, pressing the power button does not affect the test.','ទេ។ ពេលម៉ាស៊ីនបានចាប់ផ្តើមធ្វើតេស្តសំណាករួចហើយ ការចុចប៊ូតុងបើក/បិទ មិនប៉ះពាល់ដល់តេស្តទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-06-Q05','DO-06','Device Operation','My colleague hit the power button mid-test, what now?','មិត្តរួមការងារខ្ញុំចុចប៊ូតុងបើក/បិទ ពាក់កណ្តាលតេស្ត ត្រូវធ្វើអ្វីឥឡូវ?','Once the device has started testing a sample, pressing the power button does not affect the test. However, we recommend avoiding touching the power button while the device is working.','ពេលម៉ាស៊ីនបានចាប់ផ្តើមធ្វើតេស្តសំណាករួចហើយ ការចុចប៊ូតុងបើក/បិទ មិនប៉ះពាល់ដល់តេស្តទេ។ ប៉ុន្តែ យើងណែនាំឱ្យជៀសវាងការប៉ះប៊ូតុងបើក/បិទ ពេលម៉ាស៊ីនកំពុងដំណើរការ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-07','DO-07','Device Operation','Worker asks how long the device takes to warm up','បើកម៉ាស៊ីនហើយ ត្រូវទុកឱ្យវាកម្តៅប៉ុន្មាននាទី?','Warm-up brings the device to its preset temperature (about 60 °C). The time depends on the ambient temperature when the device is turned on; at an ambient temperature of 25 °C, warm-up takes 1–2 minutes from power-on. If warm-up has not completed after more than 5 minutes and the red light keeps flashing, or the power indicator goes off, please contact your distributor promptly.','ការកម្តៅធ្វើឱ្យម៉ាស៊ីនឡើងដល់សីតុណ្ហភាពកំណត់ (ប្រហែល 60 °C)។ រយៈពេលអាស្រ័យលើសីតុណ្ហភាពជុំវិញ ពេលបើកម៉ាស៊ីន។ នៅសីតុណ្ហភាពជុំវិញ 25 °C ការកម្តៅចំណាយពេល 1–2 នាទី ចាប់ពីពេលបើក។ បើការកម្តៅមិនទាន់ចប់ក្រោយលើសពី 5 នាទី ហើយភ្លើងក្រហមនៅតែភ្លឹបភ្លែត ឬភ្លើងសញ្ញាថាមពលរលត់ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ឱ្យបានឆាប់ ដើម្បីបញ្ជូនទៅអ្នកចែកចាយ (distributor)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-07-Q01','DO-07','Device Operation','How long does the device take to warm up?','តើម៉ាស៊ីនត្រូវកម្តៅរយៈពេលប៉ុន្មាន?','At an ambient temperature of 25 °C, warm-up takes 1–2 minutes from power-on. The time depends on the ambient temperature when the device is turned on.','នៅសីតុណ្ហភាពជុំវិញ 25 °C ការកម្តៅចំណាយពេល 1–2 នាទី ចាប់ពីពេលបើក។ រយៈពេលអាស្រ័យលើសីតុណ្ហភាពជុំវិញ ពេលបើកម៉ាស៊ីន។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-07-Q02','DO-07','Device Operation','warm up time?','រយៈពេលកម្តៅ?','About 1–2 minutes from power-on at an ambient temperature of 25 °C.','ប្រហែល 1–2 នាទី ចាប់ពីពេលបើក នៅសីតុណ្ហភាពជុំវិញ 25 °C។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-07-Q03','DO-07','Device Operation','It has been warming up for 6 minutes and the red light is still flashing.','វាកម្តៅអស់ 6 នាទីហើយ ហើយភ្លើងក្រហមនៅតែលោត។ ត្រូវធ្វើម៉េច?','If warm-up has not completed after more than 5 minutes and the red light keeps flashing, please contact your distributor promptly.','បើការកម្តៅមិនទាន់ចប់ក្រោយលើសពី 5 នាទី ហើយភ្លើងក្រហមនៅតែភ្លឹបភ្លែត សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ឱ្យបានឆាប់ ដើម្បីបញ្ជូនទៅអ្នកចែកចាយ (distributor)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-07-Q04','DO-07','Device Operation','Why does warm-up take longer in the morning?','ហេតុអ្វីបានជាការកម្តៅយូរជាងនៅពេលព្រឹក?','The warm-up time depends on the ambient temperature when the device is turned on. Warm-up brings the device to its preset temperature (about 60 °C). The time depends on the ambient temperature when the device is turned on; at an ambient temperature of 25 °C, warm-up takes 1–2 minutes from power-on. If warm-up has not completed after more than 5 minutes and the red light keeps flashing, or the power indicator goes off, please contact your distributor promptly.','រយៈពេលកម្តៅអាស្រ័យលើសីតុណ្ហភាពជុំវិញ ពេលបើកម៉ាស៊ីន។ ការកម្តៅធ្វើឱ្យម៉ាស៊ីនឡើងដល់សីតុណ្ហភាពកំណត់ (ប្រហែល 60 °C)។ រយៈពេលអាស្រ័យលើសីតុណ្ហភាពជុំវិញ ពេលបើកម៉ាស៊ីន។ នៅសីតុណ្ហភាពជុំវិញ 25 °C ការកម្តៅចំណាយពេល 1–2 នាទី ចាប់ពីពេលបើក។ បើការកម្តៅមិនទាន់ចប់ក្រោយលើសពី 5 នាទី ហើយភ្លើងក្រហមនៅតែភ្លឹបភ្លែត ឬភ្លើងសញ្ញាថាមពលរលត់ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ឱ្យបានឆាប់ ដើម្បីបញ្ជូនទៅអ្នកចែកចាយ (distributor)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-07-Q05','DO-07','Device Operation','What temperature does the device heat to?','តើម៉ាស៊ីនកម្តៅដល់សីតុណ្ហភាពប៉ុន្មាន?','Warm-up brings the device to its preset temperature (about 60 °C).','ការកម្តៅធ្វើឱ្យម៉ាស៊ីនឡើងដល់សីតុណ្ហភាពកំណត់ (ប្រហែល 60 °C)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-07-Q06','DO-07','Device Operation','The power light went off during warm-up.','ភ្លើងសញ្ញាថាមពលរលត់ ពេលកំពុងកម្តៅ។ ត្រូវធ្វើម៉េច?','If the power indicator goes off during warm-up, please contact your distributor promptly.','បើភ្លើងសញ្ញាថាមពលរលត់ពេលកំពុងកម្តៅ សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ឱ្យបានឆាប់ ដើម្បីបញ្ជូនទៅអ្នកចែកចាយ (distributor)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-08','DO-08','Device Operation','Device left switched on overnight / for long periods','ខ្ញុំភ្លេចបិទម៉ាស៊ីនពេញមួយយប់។ តើមានបញ្ហាអ្វីទេ?','We recommend shutting it down every day after testing is finished. If left on for long periods, the instrument stays at its set temperature, which may accelerate aging and wastes electricity.','យើងណែនាំឱ្យបិទម៉ាស៊ីនរាល់ថ្ងៃ ក្រោយធ្វើតេស្តរួច។ បើទុកបើកយូរ ម៉ាស៊ីននៅតែរក្សាសីតុណ្ហភាពកំណត់ ដែលអាចធ្វើឱ្យម៉ាស៊ីនឆាប់ចាស់ និងខ្ជះខ្ជាយភ្លើង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-08-Q01','DO-08','Device Operation','Should I turn off the device every day?','តើខ្ញុំគួរបិទម៉ាស៊ីនរាល់ថ្ងៃទេ?','Yes. We recommend shutting it down every day after testing is finished.','បាទ/ចាស។ យើងណែនាំឱ្យបិទម៉ាស៊ីនរាល់ថ្ងៃ ក្រោយធ្វើតេស្តរួច។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-08-Q02','DO-08','Device Operation','Can I leave the MiniDock on overnight?','អាចទុក MiniDock បើកពេញមួយយប់បានទេ?','No, it is not recommended. We recommend shutting it down every day after testing is finished. If left on for long periods, the instrument stays at its set temperature, which may accelerate aging and wastes electricity.','មិនបានទេ មិនណែនាំទេ។ យើងណែនាំឱ្យបិទម៉ាស៊ីនរាល់ថ្ងៃ ក្រោយធ្វើតេស្តរួច។ បើទុកបើកយូរ ម៉ាស៊ីននៅតែរក្សាសីតុណ្ហភាពកំណត់ ដែលអាចធ្វើឱ្យម៉ាស៊ីនឆាប់ចាស់ និងខ្ជះខ្ជាយភ្លើង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-08-Q03','DO-08','Device Operation','how often shut down device','បិទម៉ាស៊ីនញឹកញាប់ប៉ុណ្ណា?','We recommend shutting it down every day after testing is finished. If left on for long periods, the instrument stays at its set temperature, which may accelerate aging and wastes electricity.','យើងណែនាំឱ្យបិទម៉ាស៊ីនរាល់ថ្ងៃ ក្រោយធ្វើតេស្តរួច។ បើទុកបើកយូរ ម៉ាស៊ីននៅតែរក្សាសីតុណ្ហភាពកំណត់ ដែលអាចធ្វើឱ្យម៉ាស៊ីនឆាប់ចាស់ និងខ្ជះខ្ជាយភ្លើង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-08-Q04','DO-08','Device Operation','Is it bad to leave the device on all the time?','តើការទុកម៉ាស៊ីនបើករហូត មិនល្អទេឬ?','Yes. If left on for long periods, the instrument stays at its set temperature, which may accelerate aging and wastes electricity.','បាទ/ចាស។ បើទុកបើកយូរ ម៉ាស៊ីននៅតែរក្សាសីតុណ្ហភាពកំណត់ ដែលអាចធ្វើឱ្យម៉ាស៊ីនឆាប់ចាស់ និងខ្ជះខ្ជាយភ្លើង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-08-Q05','DO-08','Device Operation','We forgot to switch off the device last night.','យើងភ្លេចបិទម៉ាស៊ីនកាលពីយប់មិញ។ ត្រូវធ្វើម៉េច?','We recommend shutting it down every day after testing is finished; leaving it on for long periods may accelerate aging and wastes electricity.','យើងណែនាំឱ្យបិទម៉ាស៊ីនរាល់ថ្ងៃ ក្រោយធ្វើតេស្តរួច។ ការទុកវាបើកយូរ អាចធ្វើឱ្យម៉ាស៊ីនឆាប់ចាស់ និងខ្ជះខ្ជាយភ្លើង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-09','DO-09','Device Operation','Worker unsure how to turn the device on or off','ត្រូវបើក និងបិទ MiniDock ដោយរបៀបណា?','Short-press the power button to turn on; press and hold for 3 seconds to turn off.','ចុចប៊ូតុងបើក/បិទខ្លីៗ ដើម្បីបើក។ ចុចឱ្យជាប់ 3 វិនាទី ដើម្បីបិទ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-09-Q01','DO-09','Device Operation','How do I turn on the device?','តើខ្ញុំបើកម៉ាស៊ីនយ៉ាងម៉េច?','Short-press the power button to turn on.','ចុចប៊ូតុងបើក/បិទខ្លីៗ ដើម្បីបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-09-Q02','DO-09','Device Operation','How do I switch off the MiniDock?','តើខ្ញុំបិទ MiniDock យ៉ាងម៉េច?','Press and hold the power button for 3 seconds to turn off.','ចុចប៊ូតុងបើក/បិទឱ្យជាប់ 3 វិនាទី ដើម្បីបិទ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-09-Q03','DO-09','Device Operation','press button but not turn off','ចុចប៊ូតុង តែមិនបិទ','To turn off, press and hold the power button for 3 seconds.','ដើម្បីបិទ សូមចុចប៊ូតុងបើក/បិទឱ្យជាប់ 3 វិនាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-09-Q04','DO-09','Device Operation','power on off how','បើក បិទ យ៉ាងម៉េច?','Short-press the power button to turn on; press and hold for 3 seconds to turn off.','ចុចប៊ូតុងបើក/បិទខ្លីៗ ដើម្បីបើក។ ចុចឱ្យជាប់ 3 វិនាទី ដើម្បីបិទ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-09-Q05','DO-09','Device Operation','Do I need to hold the button to turn it on?','តើខ្ញុំត្រូវចុចប៊ូតុងឱ្យជាប់ ដើម្បីបើកវាទេ?','No. Short-press the power button to turn on; press and hold for 3 seconds to turn off.','ទេ។ ចុចប៊ូតុងបើក/បិទខ្លីៗ ដើម្បីបើក។ ចុចឱ្យជាប់ 3 វិនាទី ដើម្បីបិទ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-10','DO-10','Device Operation','Worker asks what the single front button does','ប៊ូតុងតែមួយនៅខាងមុខម៉ាស៊ីន ប្រើធ្វើអ្វីខ្លះ?','The button on the front of the instrument has four functions:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-10-Q01','DO-10','Device Operation','The device only has one button. What does it do?','ម៉ាស៊ីនមានប៊ូតុងតែមួយ។ តើវាមានមុខងារអ្វី?','The button on the front of the instrument has four functions:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-10-Q02','DO-10','Device Operation','How do I reset the device before the next test?','តើខ្ញុំកំណត់ម៉ាស៊ីនឡើងវិញ (reset) មុនតេស្តបន្ទាប់យ៉ាងម៉េច?','After finishing one test and before starting the next, short-press the power button.','ក្រោយធ្វើតេស្តមួយចប់ និងមុនចាប់ផ្តើមតេស្តបន្ទាប់ ចុចប៊ូតុងបើក/បិទខ្លីៗ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-10-Q03','DO-10','Device Operation','button function?','មុខងារប៊ូតុង?','The button on the front of the instrument has four functions:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-10-Q04','DO-10','Device Operation','Do I need to press the button again before the next patient?','តើខ្ញុំត្រូវចុចប៊ូតុងម្តងទៀត មុនអ្នកជំងឺបន្ទាប់ទេ?','Yes. Reset: after finishing one test and before starting the next, short-press the power button.','បាទ/ចាស។ កំណត់ឡើងវិញ (Reset)៖ ក្រោយធ្វើតេស្តមួយចប់ និងមុនចាប់ផ្តើមតេស្តបន្ទាប់ ចុចប៊ូតុងបើក/បិទខ្លីៗ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-10-Q05','DO-10','Device Operation','How long do I hold the button to switch off?','តើខ្ញុំត្រូវចុចប៊ូតុងឱ្យជាប់រយៈពេលប៉ុន្មាន ដើម្បីបិទ?','Press and hold the power button for more than three seconds, at any time.','ចុចប៊ូតុងបើក/បិទឱ្យជាប់លើសពីបីវិនាទី នៅពេលណាក៏បាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-11','DO-11','Device Operation','Worker asks what room conditions the device needs','ត្រូវដាក់ម៉ាស៊ីនក្នុងបន្ទប់ដែលមានលក្ខខណ្ឌបែបណា?','The recommended operating temperature is 15 °C–30 °C with humidity ≤70%. At low temperatures, changes in liquid viscosity can easily cause ineffective liquid loading, so the entire test should be performed above 15 °C.','សីតុណ្ហភាពប្រើប្រាស់ដែលណែនាំគឺ 15 °C–30 °C និងសំណើម ≤70%។ នៅសីតុណ្ហភាពទាប ការប្រែប្រួលភាពខាប់របស់ទឹក ងាយធ្វើឱ្យការដាក់ទឹកចូលកាតមិនមានប្រសិទ្ធភាព ដូច្នេះតេស្តទាំងមូលគួរធ្វើនៅសីតុណ្ហភាពលើស 15 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-11-Q01','DO-11','Device Operation','What room temperature is needed to run the device?','តើត្រូវការសីតុណ្ហភាពបន្ទប់ប៉ុន្មាន ដើម្បីដំណើរការម៉ាស៊ីន?','The recommended operating temperature is 15 °C–30 °C with humidity ≤70%.','សីតុណ្ហភាពប្រើប្រាស់ដែលណែនាំគឺ 15 °C–30 °C និងសំណើម ≤70%។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-11-Q02','DO-11','Device Operation','Can I test in an air-conditioned room at 14 °C?','អាចធ្វើតេស្តក្នុងបន្ទប់ម៉ាស៊ីនត្រជាក់ 14 °C បានទេ?','No. The entire test should be performed above 15 °C. At low temperatures, changes in liquid viscosity can easily cause ineffective liquid loading.','មិនបានទេ។ តេស្តទាំងមូលគួរធ្វើនៅសីតុណ្ហភាពលើស 15 °C។ នៅសីតុណ្ហភាពទាប ការប្រែប្រួលភាពខាប់របស់ទឹក ងាយធ្វើឱ្យការដាក់ទឹកចូលកាតមិនមានប្រសិទ្ធភាព។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-11-Q03','DO-11','Device Operation','humidity requirement','តម្រូវការសំណើម','Humidity ≤70% (recommended operating temperature 15 °C–30 °C).','សំណើម ≤70% (សីតុណ្ហភាពប្រើប្រាស់ដែលណែនាំ 15 °C–30 °C)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-11-Q04','DO-11','Device Operation','Why can''t I test when the room is cold?','ហេតុអ្វីបានជាខ្ញុំមិនអាចធ្វើតេស្ត ពេលបន្ទប់ត្រជាក់?','At low temperatures, changes in liquid viscosity can easily cause ineffective liquid loading, so the entire test should be performed above 15 °C.','នៅសីតុណ្ហភាពទាប ការប្រែប្រួលភាពខាប់របស់ទឹក ងាយធ្វើឱ្យការដាក់ទឹកចូលកាតមិនមានប្រសិទ្ធភាព ដូច្នេះតេស្តទាំងមូលគួរធ្វើនៅសីតុណ្ហភាពលើស 15 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-11-Q05','DO-11','Device Operation','operating environment?','បរិស្ថានប្រើប្រាស់?','The recommended operating temperature is 15 °C–30 °C with humidity ≤70%. At low temperatures, changes in liquid viscosity can easily cause ineffective liquid loading, so the entire test should be performed above 15 °C.','សីតុណ្ហភាពប្រើប្រាស់ដែលណែនាំគឺ 15 °C–30 °C និងសំណើម ≤70%។ នៅសីតុណ្ហភាពទាប ការប្រែប្រួលភាពខាប់របស់ទឹក ងាយធ្វើឱ្យការដាក់ទឹកចូលកាតមិនមានប្រសិទ្ធភាព ដូច្នេះតេស្តទាំងមូលគួរធ្វើនៅសីតុណ្ហភាពលើស 15 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-12','DO-12','Device Operation','Red light flashing right after power-on','ទើបបើកម៉ាស៊ីន ភ្លើងក្រហមក៏លោត។ តើធម្មតាទេ?','Yes, it is normal. After pressing the power button, the device flashing red indicates that it is heating up. After about 1–2 minutes, the indicator will turn blue, indicating that the device is ready.','បាទ/ចាស វាជារឿងធម្មតា។ ក្រោយចុចប៊ូតុងបើក/បិទ ម៉ាស៊ីនភ្លឹបភ្លែតពណ៌ក្រហម បង្ហាញថាវាកំពុងកម្តៅ។ ប្រហែល 1–2 នាទីក្រោយ ភ្លើងសញ្ញានឹងប្តូរជាពណ៌ខៀវ បង្ហាញថាម៉ាស៊ីនរួចរាល់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-12-Q01','DO-12','Device Operation','Is it normal for the light to flash red after I turn the device on?','តើជារឿងធម្មតាទេ ដែលភ្លើងលោតពណ៌ក្រហម ក្រោយខ្ញុំបើកម៉ាស៊ីន?','Yes, it is normal. After pressing the power button, the device flashing red indicates that it is heating up. After about 1–2 minutes, the indicator will turn blue, indicating that the device is ready.','បាទ/ចាស វាជារឿងធម្មតា។ ក្រោយចុចប៊ូតុងបើក/បិទ ម៉ាស៊ីនភ្លឹបភ្លែតពណ៌ក្រហម បង្ហាញថាវាកំពុងកម្តៅ។ ប្រហែល 1–2 នាទីក្រោយ ភ្លើងសញ្ញានឹងប្តូរជាពណ៌ខៀវ បង្ហាញថាម៉ាស៊ីនរួចរាល់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-12-Q02','DO-12','Device Operation','red light blinking after power on, broken?','ភ្លើងក្រហមលោតក្រោយបើក ខូចទេ?','No, it is normal. The flashing red light means the device is heating up. After about 1–2 minutes it turns blue, meaning the device is ready.','ទេ វាជារឿងធម្មតា។ ភ្លើងក្រហមភ្លឹបភ្លែត មានន័យថាម៉ាស៊ីនកំពុងកម្តៅ។ ប្រហែល 1–2 នាទីក្រោយ វាប្តូរជាពណ៌ខៀវ មានន័យថាម៉ាស៊ីនរួចរាល់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-12-Q03','DO-12','Device Operation','When will the light turn blue?','តើភ្លើងនឹងប្តូរជាពណ៌ខៀវនៅពេលណា?','After about 1–2 minutes of heating, the indicator will turn blue, indicating that the device is ready.','ក្រោយកម្តៅប្រហែល 1–2 នាទី ភ្លើងសញ្ញានឹងប្តូរជាពណ៌ខៀវ បង្ហាញថាម៉ាស៊ីនរួចរាល់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-12-Q04','DO-12','Device Operation','What does the blue light mean?','តើភ្លើងពណ៌ខៀវមានន័យថាម៉េច?','Blue means the device is ready.','ពណ៌ខៀវមានន័យថាម៉ាស៊ីនរួចរាល់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-12-Q05','DO-12','Device Operation','Just switched on, red flashing','ទើបតែបើក ភ្លើងក្រហមលោត','Yes, it is normal. After pressing the power button, the device flashing red indicates that it is heating up. After about 1–2 minutes, the indicator will turn blue, indicating that the device is ready.','បាទ/ចាស វាជារឿងធម្មតា។ ក្រោយចុចប៊ូតុងបើក/បិទ ម៉ាស៊ីនភ្លឹបភ្លែតពណ៌ក្រហម បង្ហាញថាវាកំពុងកម្តៅ។ ប្រហែល 1–2 នាទីក្រោយ ភ្លើងសញ្ញានឹងប្តូរជាពណ៌ខៀវ បង្ហាញថាម៉ាស៊ីនរួចរាល់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-13','DO-13','Device Operation','Worker asks what to watch out for while running a test','ពេលតេស្តកំពុងដំណើរការ ត្រូវប្រយ័ត្នអ្វីខ្លះ?','1. After putting the test card in the device, close the lid within 30 seconds.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-13-Q01','DO-13','Device Operation','What should I pay attention to during testing?','តើខ្ញុំគួរយកចិត្តទុកដាក់អ្វីខ្លះ ពេលកំពុងធ្វើតេស្ត?','1. After putting the test card in the device, close the lid within 30 seconds.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-13-Q02','DO-13','Device Operation','How fast must I close the lid after putting in the card?','តើខ្ញុំត្រូវបិទគម្របលឿនប៉ុណ្ណា ក្រោយដាក់កាតចូល?','Close the lid within 30 seconds after putting the test card in the device.','បិទគម្របក្នុងរយៈពេល 30 វិនាទី ក្រោយដាក់កាតតេស្តចូលម៉ាស៊ីន។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-13-Q03','DO-13','Device Operation','Can I open the lid to check during the test?','អាចបើកគម្របដើម្បីពិនិត្យ ពេលកំពុងធ្វើតេស្តបានទេ?','No. Do not open the device lid during testing.','មិនបានទេ។ កុំបើកគម្របម៉ាស៊ីនពេលកំពុងធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-13-Q04','DO-13','Device Operation','testing notes','ចំណាំពេលធ្វើតេស្ត','1. After putting the test card in the device, close the lid within 30 seconds.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-13-Q05','DO-13','Device Operation','Is it OK to close the lid after one minute?','តើបិទគម្របក្រោយមួយនាទី មិនអីទេឬ?','No. After putting the test card in the device, close the lid within 30 seconds.','មិនបានទេ។ ក្រោយដាក់កាតតេស្តចូលម៉ាស៊ីន សូមបិទគម្របក្នុងរយៈពេល 30 វិនាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-14','DO-14','Device Operation','PC software or mobile app closed during a test','ខ្ញុំបិទកម្មវិធីលើកុំព្យូទ័រ ឬទូរស័ព្ទ ពេលម៉ាស៊ីនកំពុងធ្វើតេស្ត។ តើប៉ះពាល់ដល់តេស្តទេ?','It will not affect the result. However, we recommend reconnecting to the software or app after the test ends and before removing the reaction card, so the entered sample information is saved correctly with the result.','វាមិនប៉ះពាល់ដល់លទ្ធផលទេ។ ប៉ុន្តែ យើងណែនាំឱ្យភ្ជាប់កម្មវិធី ឬ App ឡើងវិញ ក្រោយតេស្តចប់ និងមុនដកកាតប្រតិកម្មចេញ ដើម្បីឱ្យព័ត៌មានសំណាកដែលបានបញ្ចូល ត្រូវបានរក្សាទុកត្រឹមត្រូវជាមួយលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-14-Q01','DO-14','Device Operation','I closed the software during the test. Will the result be affected?','ខ្ញុំបានបិទកម្មវិធីពេលកំពុងធ្វើតេស្ត។ តើលទ្ធផលនឹងត្រូវប៉ះពាល់ទេ?','No. It will not affect the result. However, we recommend reconnecting to the software or app after the test ends and before removing the reaction card, so the entered sample information is saved correctly with the result.','ទេ។ វាមិនប៉ះពាល់ដល់លទ្ធផលទេ។ ប៉ុន្តែ យើងណែនាំឱ្យភ្ជាប់កម្មវិធី ឬ App ឡើងវិញ ក្រោយតេស្តចប់ និងមុនដកកាតប្រតិកម្មចេញ ដើម្បីឱ្យព័ត៌មានសំណាកដែលបានបញ្ចូល ត្រូវបានរក្សាទុកត្រឹមត្រូវជាមួយលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-14-Q02','DO-14','Device Operation','The app shut down while the device was testing. Is my result lost?','កម្មវិធី បានបិទ ពេលម៉ាស៊ីនកំពុងធ្វើតេស្ត។ តើលទ្ធផលរបស់ខ្ញុំបាត់ទេ?','No, it will not affect the result. We recommend reconnecting to the app after the test ends and before removing the reaction card, so the entered sample information is saved correctly with the result.','ទេ វាមិនប៉ះពាល់ដល់លទ្ធផលទេ។ យើងណែនាំឱ្យភ្ជាប់ App ឡើងវិញ ក្រោយតេស្តចប់ និងមុនដកកាតប្រតិកម្មចេញ ដើម្បីឱ្យព័ត៌មានសំណាកដែលបានបញ្ចូល ត្រូវបានរក្សាទុកត្រឹមត្រូវជាមួយលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-14-Q03','DO-14','Device Operation','Do I need to reconnect before taking out the card?','តើខ្ញុំត្រូវភ្ជាប់ឡើងវិញ មុនដកកាតចេញទេ?','Yes. We recommend reconnecting to the software or app after the test ends and before removing the reaction card, so the entered sample information is saved correctly with the result.','បាទ/ចាស។ យើងណែនាំឱ្យភ្ជាប់កម្មវិធី ឬ App ឡើងវិញ ក្រោយតេស្តចប់ និងមុនដកកាតប្រតិកម្មចេញ ដើម្បីឱ្យព័ត៌មានសំណាកដែលបានបញ្ចូល ត្រូវបានរក្សាទុកត្រឹមត្រូវជាមួយលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-14-Q04','DO-14','Device Operation','laptop turned off in middle of test','កុំព្យូទ័រយួរដៃរលត់ ពាក់កណ្តាលតេស្ត','It will not affect the result. However, we recommend reconnecting to the software or app after the test ends and before removing the reaction card, so the entered sample information is saved correctly with the result.','វាមិនប៉ះពាល់ដល់លទ្ធផលទេ។ ប៉ុន្តែ យើងណែនាំឱ្យភ្ជាប់កម្មវិធី ឬ App ឡើងវិញ ក្រោយតេស្តចប់ និងមុនដកកាតប្រតិកម្មចេញ ដើម្បីឱ្យព័ត៌មានសំណាកដែលបានបញ្ចូល ត្រូវបានរក្សាទុកត្រឹមត្រូវជាមួយលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DO-14-Q05','DO-14','Device Operation','Can I close the app while the test runs?','អាចបិទ កម្មវិធី ពេលតេស្តកំពុងដំណើរការបានទេ?','Yes, it will not affect the result. But reconnect after the test ends and before removing the card so the sample information is saved with the result.','បាទ/ចាស វាមិនប៉ះពាល់ដល់លទ្ធផលទេ។ ប៉ុន្តែ សូមភ្ជាប់ឡើងវិញក្រោយតេស្តចប់ និងមុនដកកាតចេញ ដើម្បីឱ្យព័ត៌មានសំណាកត្រូវបានរក្សាទុកជាមួយលទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-05','RS-05','Results & Clinical Decision','Worker asks what IC means or sees "IC not detected"','IC មានន័យថាអ្វី? បើអេក្រង់បង្ហាញ «IC not detected» ត្រូវធ្វើម៉េច?','IC (Internal Control) is usually a housekeeping gene that monitors the entire process of sampling, transport, extraction and amplification, avoiding false-negative results.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-05-Q01','RS-05','Results & Clinical Decision','What is IC?','តើ IC ជាអ្វី?','IC (Internal Control) is usually a housekeeping gene that monitors the entire process of sampling, transport, extraction and amplification, avoiding false-negative results.','IC (Internal Control - ការត្រួតពិនិត្យខាងក្នុង) ជាធម្មតាគឺជាហ្សែនមូលដ្ឋាន (housekeeping gene) ដែលតាមដានដំណើរការទាំងមូល ចាប់ពីការស្រង់សំណាក ការដឹកជញ្ជូន ការចម្រាញ់ និងការពង្រីក ដើម្បីជៀសវាងលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false-negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-05-Q02','RS-05','Results & Clinical Decision','The result says IC not detected. What does that mean?','លទ្ធផលបង្ហាញ "IC not detected"។ តើវាមានន័យថាម៉េច?','IC not detected means this test result is invalid. If an invalid result occurs, analyze the cause, eliminate it, and then retest.','IC not detected (រកមិនឃើញ IC) មានន័យថាលទ្ធផលតេស្តនេះគ្មានសុពលភាព។ បើមានលទ្ធផលគ្មានសុពលភាព សូមវិភាគរកមូលហេតុ ដោះស្រាយវា រួចធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-05-Q03','RS-05','Results & Clinical Decision','IC not detect','IC រកមិនឃើញ។ ត្រូវធ្វើម៉េច?','IC not detected means this test result is invalid. If an invalid result occurs, analyze the cause, eliminate it, and then retest.','IC not detected (រកមិនឃើញ IC) មានន័យថាលទ្ធផលតេស្តនេះគ្មានសុពលភាព។ បើមានលទ្ធផលគ្មានសុពលភាព សូមវិភាគរកមូលហេតុ ដោះស្រាយវា រួចធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-05-Q04','RS-05','Results & Clinical Decision','Is IC not detected the same as negative?','តើ "IC not detected" ដូចគ្នានឹងអវិជ្ជមានទេ?','No. IC not detected means this test result is invalid.','ទេ។ IC not detected (រកមិនឃើញ IC) មានន័យថាលទ្ធផលតេស្តនេះគ្មានសុពលភាព។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-05-Q05','RS-05','Results & Clinical Decision','Why does the test need an internal control?','ហេតុអ្វីបានជាតេស្តត្រូវការការត្រួតពិនិត្យខាងក្នុង (internal control)?','It monitors the entire process of sampling, transport, extraction and amplification, avoiding false-negative results.','វាតាមដានដំណើរការទាំងមូល ចាប់ពីការស្រង់សំណាក ការដឹកជញ្ជូន ការចម្រាញ់ និងការពង្រីក ដើម្បីជៀសវាងលទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false-negative)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-06','RS-06','Results & Clinical Decision','Worker unsure how to read the result shown in the software/app','ត្រូវអានលទ្ធផលដែលបង្ហាញក្នុងកម្មវិធីដោយរបៀបណា?','Results consist of two parts: Internal Control (IC) and the pathogen target (e.g., MTB). The overall result is Positive, Negative or Invalid.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-06-Q01','RS-06','Results & Clinical Decision','How does the software show test results?','តើកម្មវិធីបង្ហាញលទ្ធផលតេស្តយ៉ាងម៉េច?','Results consist of two parts: Internal Control (IC) and the pathogen target (e.g., MTB). The overall result is Positive, Negative or Invalid.','លទ្ធផលមានពីរផ្នែក៖ ការត្រួតពិនិត្យខាងក្នុង (Internal Control - IC) និងគោលដៅមេរោគ (ឧទាហរណ៍ MTB)។ លទ្ធផលរួមគឺ Positive (វិជ្ជមាន) Negative (អវិជ្ជមាន) ឬ Invalid (គ្មានសុពលភាព)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-06-Q02','RS-06','Results & Clinical Decision','How do I read the result?','តើខ្ញុំអានលទ្ធផលយ៉ាងម៉េច?','Always check whether IC is Valid first, then check the pathogen target result. IC Valid + target Positive = overall Positive; IC Valid + target Negative = overall Negative; IC Invalid = overall Invalid.','ត្រូវពិនិត្យជានិច្ចថា IC មានសុពលភាព (Valid) ជាមុនសិន រួចទើបពិនិត្យលទ្ធផលគោលដៅមេរោគ។ IC Valid + គោលដៅ Positive = លទ្ធផលរួម Positive (វិជ្ជមាន)។ IC Valid + គោលដៅ Negative = លទ្ធផលរួម Negative (អវិជ្ជមាន)។ IC Invalid = លទ្ធផលរួម Invalid (គ្មានសុពលភាព)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-06-Q03','RS-06','Results & Clinical Decision','IC valid and MTB positive means?','IC valid និង MTB positive មានន័យថា?','Overall Positive.','លទ្ធផលរួម Positive (វិជ្ជមាន)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-06-Q04','RS-06','Results & Clinical Decision','IC valid, target negative = ?','IC valid, គោលដៅ negative = ?','Overall Negative.','លទ្ធផលរួម Negative (អវិជ្ជមាន)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-06-Q05','RS-06','Results & Clinical Decision','Which do I check first, IC or MTB?','តើខ្ញុំពិនិត្យអ្វីមុន IC ឬ MTB?','Always check whether IC is Valid first, then check the pathogen target result.','ត្រូវពិនិត្យជានិច្ចថា IC មានសុពលភាព (Valid) ជាមុនសិន រួចទើបពិនិត្យលទ្ធផលគោលដៅមេរោគ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-06-Q06','RS-06','Results & Clinical Decision','result meaning','តើលទ្ធផលនីមួយៗក្នុងកម្មវិធីមានន័យថាម៉េច?','Results consist of two parts: Internal Control (IC) and the pathogen target (e.g., MTB). The overall result is Positive, Negative or Invalid. Always check whether IC is Valid first, then check the pathogen target result. IC Valid + target Positive = overall Positive; IC Valid + target Negative = overall Negative; IC Invalid = overall Invalid.','លទ្ធផលមានពីរផ្នែក៖ ការត្រួតពិនិត្យខាងក្នុង (Internal Control - IC) និងគោលដៅមេរោគ (ឧទាហរណ៍ MTB)។ លទ្ធផលរួមគឺ Positive (វិជ្ជមាន) Negative (អវិជ្ជមាន) ឬ Invalid (គ្មានសុពលភាព)។ ត្រូវពិនិត្យជានិច្ចថា IC មានសុពលភាព (Valid) ជាមុនសិន រួចទើបពិនិត្យលទ្ធផលគោលដៅមេរោគ។ IC Valid + គោលដៅ Positive = លទ្ធផលរួម Positive (វិជ្ជមាន)។ IC Valid + គោលដៅ Negative = លទ្ធផលរួម Negative (អវិជ្ជមាន)។ IC Invalid = លទ្ធផលរួម Invalid (គ្មានសុពលភាព)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-07','RS-07','Results & Clinical Decision','Result shows "IC invalid, pathogen target negative"','អេក្រង់បង្ហាញ «IC invalid, pathogen target negative»។ តើត្រូវអានលទ្ធផលនេះយ៉ាងម៉េច?','No. This is the normal itemized display, but the overall result of the test should be judged Invalid; it must not be judged Negative based on the target being Negative.','ទេ។ នេះជាការបង្ហាញលម្អិតតាមធាតុធម្មតា ប៉ុន្តែលទ្ធផលរួមនៃតេស្តនេះ ត្រូវវិនិច្ឆ័យថា Invalid (គ្មានសុពលភាព)។ ហាមវិនិច្ឆ័យថា Negative (អវិជ្ជមាន) ដោយផ្អែកលើគោលដៅមេរោគអវិជ្ជមាននោះទេ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-07-Q01','RS-07','Results & Clinical Decision','It shows IC invalid and target negative. Is that a display error?','វាបង្ហាញ IC invalid និងគោលដៅ negative។ តើវាជាកំហុសនៃការបង្ហាញទេ?','No. This is the normal itemized display, but the overall result of the test should be judged Invalid; it must not be judged Negative based on the target being Negative.','ទេ។ នេះជាការបង្ហាញលម្អិតតាមធាតុធម្មតា ប៉ុន្តែលទ្ធផលរួមនៃតេស្តនេះ ត្រូវវិនិច្ឆ័យថា Invalid (គ្មានសុពលភាព)។ ហាមវិនិច្ឆ័យថា Negative (អវិជ្ជមាន) ដោយផ្អែកលើគោលដៅមេរោគអវិជ្ជមាននោះទេ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-07-Q02','RS-07','Results & Clinical Decision','Can I record IC invalid + MTB negative as negative?','អាចកត់ត្រា IC invalid + MTB negative ថាអវិជ្ជមានបានទេ?','No. The overall result should be judged Invalid; it must not be judged Negative based on the target being Negative.','មិនបានទេ។ លទ្ធផលរួមត្រូវវិនិច្ឆ័យថា Invalid (គ្មានសុពលភាព)។ ហាមវិនិច្ឆ័យថា Negative (អវិជ្ជមាន) ដោយផ្អែកលើគោលដៅមេរោគអវិជ្ជមាននោះទេ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-07-Q03','RS-07','Results & Clinical Decision','ic invalid mtb negative','អេក្រង់បង្ហាញ IC Invalid និង MTB Negative។ តើអានលទ្ធផលនេះយ៉ាងម៉េច?','The overall result is Invalid, not Negative.','លទ្ធផលរួមគឺ Invalid (គ្មានសុពលភាព) មិនមែន Negative (អវិជ្ជមាន) ទេ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-07-Q04','RS-07','Results & Clinical Decision','Is this patient TB negative if IC is invalid?','តើអ្នកជំងឺនេះអវិជ្ជមានជំងឺរបេងទេ បើ IC invalid?','No. The overall result of the test should be judged Invalid.','ទេ។ លទ្ធផលរួមនៃតេស្តនេះ ត្រូវវិនិច្ឆ័យថា Invalid (គ្មានសុពលភាព)។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-08','RS-08','Results & Clinical Decision','Blank (unused) swab test gave Negative instead of Invalid','ខ្ញុំយកដងសំឡីថ្មីដែលមិនបានស្រង់សំណាកមកតេស្ត។ ហេតុអ្វីចេញ Negative ជំនួសឱ្យ Invalid?','Using a blank swab as the sample should normally give an invalid result. A negative result may mean human genomic material was introduced, e.g., operating without gloves, the swab brushing against skin, or environmental contamination. You can check for environmental contamination with these tests: a. test card + diluent; b. test card + diluent + blank swab; c. test card + diluent + swab + sample. They should give a. invalid, b. invalid, c. negative or positive, respectively.','ការប្រើដងសំឡីទទេជាសំណាក ជាធម្មតាគួរចេញលទ្ធផលគ្មានសុពលភាព (invalid)។ លទ្ធផលអវិជ្ជមាន (negative) អាចមានន័យថាមានសារធាតុហ្សែនមនុស្សចូល ឧទាហរណ៍ ធ្វើការដោយមិនពាក់ស្រោមដៃ ដងសំឡីប៉ះស្បែក ឬការចម្លងរោគពីបរិស្ថាន។ អ្នកអាចពិនិត្យរកការចម្លងរោគពីបរិស្ថាន ដោយធ្វើតេស្តទាំងនេះ៖ a. កាតតេស្ត + ទឹករំលាយ (diluent); b. កាតតេស្ត + ទឹករំលាយ + ដងសំឡីទទេ; c. កាតតេស្ត + ទឹករំលាយ + ដងសំឡី + សំណាក។ លទ្ធផលគួរតែជា a. invalid, b. invalid, c. negative ឬ positive រៀងៗខ្លួន។','Safety-critical','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-08-Q01','RS-08','Results & Clinical Decision','I tested a blank swab and got negative, not invalid. Why?','ខ្ញុំធ្វើតេស្តដងសំឡីទទេ ហើយបានលទ្ធផលអវិជ្ជមាន មិនមែនចេញ Invalid ទេ។ ហេតុអ្វី?','Using a blank swab as the sample should normally give an invalid result. A negative result may mean human genomic material was introduced, e.g., operating without gloves, the swab brushing against skin, or environmental contamination. You can check for environmental contamination with these tests: a. test card + diluent; b. test card + diluent + blank swab; c. test card + diluent + swab + sample. They should give a. invalid, b. invalid, c. negative or positive, respectively.','ការប្រើដងសំឡីទទេជាសំណាក ជាធម្មតាគួរចេញលទ្ធផលគ្មានសុពលភាព (invalid)។ លទ្ធផលអវិជ្ជមាន (negative) អាចមានន័យថាមានសារធាតុហ្សែនមនុស្សចូល ឧទាហរណ៍ ធ្វើការដោយមិនពាក់ស្រោមដៃ ដងសំឡីប៉ះស្បែក ឬការចម្លងរោគពីបរិស្ថាន។ អ្នកអាចពិនិត្យរកការចម្លងរោគពីបរិស្ថាន ដោយធ្វើតេស្តទាំងនេះ៖ a. កាតតេស្ត + ទឹករំលាយ (diluent); b. កាតតេស្ត + ទឹករំលាយ + ដងសំឡីទទេ; c. កាតតេស្ត + ទឹករំលាយ + ដងសំឡី + សំណាក។ លទ្ធផលគួរតែជា a. invalid, b. invalid, c. negative ឬ positive រៀងៗខ្លួន។','Safety-critical','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-08-Q02','RS-08','Results & Clinical Decision','How can I check for environmental contamination?','អាចពិនិត្យរកការចម្លងរោគពីបរិស្ថានយ៉ាងម៉េច?','Run these tests: a. test card + diluent; b. test card + diluent + blank swab; c. test card + diluent + swab + sample. They should give a. invalid, b. invalid, c. negative or positive, respectively.','ធ្វើតេស្តទាំងនេះ៖ a. កាតតេស្ត + ទឹករំលាយ (diluent); b. កាតតេស្ត + ទឹករំលាយ + ដងសំឡីទទេ; c. កាតតេស្ត + ទឹករំលាយ + ដងសំឡី + សំណាក។ លទ្ធផលគួរតែជា a. invalid, b. invalid, c. negative ឬ positive រៀងៗខ្លួន។','Safety-critical','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-08-Q03','RS-08','Results & Clinical Decision','Should a blank swab give invalid?','តើដងសំឡីទទេ គួរចេញលទ្ធផលចេញ Invalid (invalid) ទេ?','Yes. Using a blank swab as the sample should normally give an invalid result.','បាទ/ចាស។ ការប្រើដងសំឡីទទេជាសំណាក ជាធម្មតាគួរចេញលទ្ធផលគ្មានសុពលភាព (invalid)។','Safety-critical','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-08-Q04','RS-08','Results & Clinical Decision','empty swab negative?','ដងសំឡីទទេ អវិជ្ជមាន?','Using a blank swab as the sample should normally give an invalid result. A negative result may mean human genomic material was introduced, e.g., operating without gloves, the swab brushing against skin, or environmental contamination. You can check for environmental contamination with these tests: a. test card + diluent; b. test card + diluent + blank swab; c. test card + diluent + swab + sample. They should give a. invalid, b. invalid, c. negative or positive, respectively.','ការប្រើដងសំឡីទទេជាសំណាក ជាធម្មតាគួរចេញលទ្ធផលគ្មានសុពលភាព (invalid)។ លទ្ធផលអវិជ្ជមាន (negative) អាចមានន័យថាមានសារធាតុហ្សែនមនុស្សចូល ឧទាហរណ៍ ធ្វើការដោយមិនពាក់ស្រោមដៃ ដងសំឡីប៉ះស្បែក ឬការចម្លងរោគពីបរិស្ថាន។ អ្នកអាចពិនិត្យរកការចម្លងរោគពីបរិស្ថាន ដោយធ្វើតេស្តទាំងនេះ៖ a. កាតតេស្ត + ទឹករំលាយ (diluent); b. កាតតេស្ត + ទឹករំលាយ + ដងសំឡីទទេ; c. កាតតេស្ត + ទឹករំលាយ + ដងសំឡី + សំណាក។ លទ្ធផលគួរតែជា a. invalid, b. invalid, c. negative ឬ positive រៀងៗខ្លួន។','Safety-critical','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-09','RS-09','Results & Clinical Decision','Result is Invalid','តេស្តចេញ Invalid។ ត្រូវធ្វើម៉េច?','Invalid results may be caused by insufficient sample, sample contamination, incorrect sampling, operating errors, interrupted reaction, etc. If the result is invalid, reread the instructions or operating guide and start a new test; if it is still invalid, contact your sales representative promptly.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-09-Q01','RS-09','Results & Clinical Decision','Why did I get an invalid result?','ហេតុអ្វីបានជាខ្ញុំបានលទ្ធផលចេញ Invalid?','Invalid results may be caused by insufficient sample, sample contamination, incorrect sampling, operating errors, interrupted reaction, etc. If the result is invalid, reread the instructions or operating guide and start a new test; if it is still invalid, contact your sales representative promptly.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-09-Q02','RS-09','Results & Clinical Decision','invalid result what to do','លទ្ធផលចេញ Invalid ត្រូវធ្វើអ្វី?','Reread the instructions or operating guide and start a new test; if it is still invalid, contact your sales representative promptly.','អានការណែនាំ ឬមគ្គុទ្ទេសក៍ប្រតិបត្តិម្តងទៀត ហើយចាប់ផ្តើមតេស្តថ្មី។ បើនៅតែគ្មានសុពលភាព សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ឱ្យបានឆាប់ ដើម្បីបញ្ជូនទៅតំណាងលក់ (sales representative)។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-09-Q03','RS-09','Results & Clinical Decision','Can too much mucus cause invalid?','តើស្លេស្មច្រើនពេក អាចធ្វើឱ្យលទ្ធផលចេញ Invalid ទេ?','Yes. Large amounts of mucus, dust or feces exceeding the reagent''s anti-inhibition capacity inhibit amplification, resulting in an invalid result.','បាទ/ចាស។ ស្លេស្ម ធូលី ឬលាមកច្រើន លើសសមត្ថភាពប្រឆាំងការរារាំងរបស់សារធាតុ ធ្វើឱ្យរារាំងការពង្រីក ហើយបណ្តាលឱ្យលទ្ធផលគ្មានសុពលភាព។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-09-Q04','RS-09','Results & Clinical Decision','Second test also invalid.','តេស្តលើកទីពីរក៏ចេញ Invalid ដែរ។ តើត្រូវធ្វើអ្វីបន្ទាប់?','If it is still invalid, contact your sales representative promptly.','បើនៅតែគ្មានសុពលភាព សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ឱ្យបានឆាប់ ដើម្បីបញ្ជូនទៅតំណាងលក់ (sales representative)។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-09-Q05','RS-09','Results & Clinical Decision','Can a loose cap make the result invalid?','តើគម្របរលុង អាចធ្វើឱ្យលទ្ធផលចេញ Invalid ទេ?','Yes. The card''s air bladder cap not tightened is one cause of invalid results.','បាទ/ចាស។ ការមិនបានមួលគម្របថង់ខ្យល់ (air bladder) របស់កាតឱ្យជិត គឺជាមូលហេតុមួយនៃលទ្ធផលគ្មានសុពលភាព។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-09-Q06','RS-09','Results & Clinical Decision','What operation mistakes cause invalid?','តើកំហុសប្រតិបត្តិអ្វីខ្លះ ដែលធ្វើឱ្យលទ្ធផលចេញ Invalid?','Incorrect sampling, liquid volume not between the two marks on the card, the air bladder cap not tightened, the seven chambers not filled, or insufficient mixing.','ការស្រង់សំណាកមិនត្រឹមត្រូវ បរិមាណទឹកមិននៅចន្លោះសញ្ញាទាំងពីរលើកាត មិនបានមួលគម្របថង់ខ្យល់ (air bladder) ឱ្យជិត រន្ធទាំងប្រាំពីរមិនពេញ ឬលាយមិនបានសព្វ។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-10','RS-10','Results & Clinical Decision','Worker asks for a Ct value','តើអាចមើលតម្លៃ Ct របស់តេស្ត Pluslife បានទេ?','Pluslife POCT products work on a different principle from PCR and have no Ct value concept, so Ct values are not displayed; results are shown via indicator lights or the software. The detection time of a positive result is for reference only — generally, a shorter time indicates higher viral load, but there is no linear relationship between detection time and viral load.','ផលិតផល POCT របស់ Pluslife ដំណើរការលើគោលការណ៍ខុសពី PCR ហើយគ្មានគំនិតតម្លៃ Ct ទេ ដូច្នេះតម្លៃ Ct មិនត្រូវបានបង្ហាញទេ។ លទ្ធផលត្រូវបានបង្ហាញតាមភ្លើងសញ្ញា ឬកម្មវិធី។ រយៈពេលរកឃើញនៃលទ្ធផលវិជ្ជមាន គឺសម្រាប់ជាឯកសារយោងតែប៉ុណ្ណោះ — ជាទូទៅ រយៈពេលខ្លីជាង បង្ហាញពីបរិមាណមេរោគខ្ពស់ជាង ប៉ុន្តែគ្មានទំនាក់ទំនងបន្ទាត់ត្រង់ (linear) រវាងរយៈពេលរកឃើញ និងបរិមាណមេរោគទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-10-Q01','RS-10','Results & Clinical Decision','Can the software show Ct values?','តើកម្មវិធីអាចបង្ហាញតម្លៃ Ct បានទេ?','No. Pluslife has no Ct value concept, so Ct values are not displayed; results are shown via indicator lights or the software.','មិនបានទេ។ Pluslife គ្មានគំនិតតម្លៃ Ct ទេ ដូច្នេះតម្លៃ Ct មិនត្រូវបានបង្ហាញទេ។ លទ្ធផលត្រូវបានបង្ហាញតាមភ្លើងសញ្ញា ឬកម្មវិធី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-10-Q02','RS-10','Results & Clinical Decision','Ct value where?','តម្លៃ Ct នៅឯណា?','Pluslife POCT products work on a different principle from PCR and have no Ct value concept, so Ct values are not displayed; results are shown via indicator lights or the software. The detection time of a positive result is for reference only — generally, a shorter time indicates higher viral load, but there is no linear relationship between detection time and viral load.','ផលិតផល POCT របស់ Pluslife ដំណើរការលើគោលការណ៍ខុសពី PCR ហើយគ្មានគំនិតតម្លៃ Ct ទេ ដូច្នេះតម្លៃ Ct មិនត្រូវបានបង្ហាញទេ។ លទ្ធផលត្រូវបានបង្ហាញតាមភ្លើងសញ្ញា ឬកម្មវិធី។ រយៈពេលរកឃើញនៃលទ្ធផលវិជ្ជមាន គឺសម្រាប់ជាឯកសារយោងតែប៉ុណ្ណោះ — ជាទូទៅ រយៈពេលខ្លីជាង បង្ហាញពីបរិមាណមេរោគខ្ពស់ជាង ប៉ុន្តែគ្មានទំនាក់ទំនងបន្ទាត់ត្រង់ (linear) រវាងរយៈពេលរកឃើញ និងបរិមាណមេរោគទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-10-Q03','RS-10','Results & Clinical Decision','Does a faster positive mean a higher load?','តើលទ្ធផលវិជ្ជមានលឿនជាង មានន័យថាបរិមាណមេរោគខ្ពស់ជាងទេ?','Yes, generally: a shorter time indicates higher load, but there is no linear relationship between detection time and viral load. The detection time is for reference only.','បាទ/ចាស ជាទូទៅ៖ រយៈពេលខ្លីជាង បង្ហាញពីបរិមាណមេរោគខ្ពស់ជាង ប៉ុន្តែគ្មានទំនាក់ទំនងបន្ទាត់ត្រង់ (linear) រវាងរយៈពេលរកឃើញ និងបរិមាណមេរោគទេ។ រយៈពេលរកឃើញ គឺសម្រាប់ជាឯកសារយោងតែប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-10-Q04','RS-10','Results & Clinical Decision','Can I use the positive time like a Ct value?','អាចប្រើរយៈពេលវិជ្ជមាន ដូចតម្លៃ Ct បានទេ?','No. The detection time of a positive result is for reference only; there is no linear relationship between detection time and viral load.','មិនបានទេ។ រយៈពេលរកឃើញនៃលទ្ធផលវិជ្ជមាន គឺសម្រាប់ជាឯកសារយោងតែប៉ុណ្ណោះ។ គ្មានទំនាក់ទំនងបន្ទាត់ត្រង់ (linear) រវាងរយៈពេលរកឃើញ និងបរិមាណមេរោគទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-11','RS-11','Results & Clinical Decision','Result came out sooner than the stated test time','លទ្ធផលចេញលឿនជាងពេលដែលបានកំណត់។ តើធម្មតាទេ?','1. The system stops the test and reports a positive result as soon as a positive is detected, usually within 10–20 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-11-Q01','RS-11','Results & Clinical Decision','Why did my result come out early?','ហេតុអ្វីបានជាលទ្ធផលរបស់ខ្ញុំចេញមុនពេល?','1. The system stops the test and reports a positive result as soon as a positive is detected, usually within 10–20 minutes.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-11-Q02','RS-11','Results & Clinical Decision','Positive after 12 minutes — is that normal?','វិជ្ជមានក្រោយ 12 នាទី — តើជារឿងធម្មតាទេ?','Yes. The system stops the test and reports a positive result as soon as a positive is detected, usually within 10–20 minutes.','បាទ/ចាស។ ប្រព័ន្ធបញ្ឈប់តេស្ត ហើយរាយការណ៍លទ្ធផលវិជ្ជមានភ្លាម ពេលរកឃើញវិជ្ជមាន ជាធម្មតាក្នុងរយៈពេល 10–20 នាទី។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-11-Q03','RS-11','Results & Clinical Decision','Test stopped at 7 minutes and said negative.','តេស្តឈប់នៅនាទីទី 7 ហើយបង្ហាញថាអវិជ្ជមាន។ តើត្រូវធ្វើអ្វីបន្ទាប់?','The fluorescence signal increased abnormally during the first 5 minutes. This points to an operational error or an abnormal result. Repeat the test, following the correct procedure.','សញ្ញាពន្លឺ (fluorescence signal) កើនឡើងមិនប្រក្រតី ក្នុងរយៈពេល 5 នាទីដំបូង។ នេះបង្ហាញពីកំហុសក្នុងការប្រតិបត្តិ ឬលទ្ធផលមិនប្រក្រតី។ សូមធ្វើតេស្តម្តងទៀត ដោយអនុវត្តតាមនីតិវិធីត្រឹមត្រូវ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-11-Q04','RS-11','Results & Clinical Decision','Invalid after only 6 minutes.','ចេញ Invalid ក្រោយតែ 6 នាទី។ តើត្រូវធ្វើអ្វីបន្ទាប់?','The instrument kept detecting a fluorescence signal that was too low, so it stopped and reported invalid. The usual cause is that no test card was inserted.','ម៉ាស៊ីនបានរកឃើញសញ្ញាពន្លឺទាបពេកជាប់ៗគ្នា ដូច្នេះវាបានបញ្ឈប់ ហើយរាយការណ៍ថាគ្មានសុពលភាព។ មូលហេតុធម្មតាគឺមិនបានដាក់កាតតេស្តចូល។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-11-Q05','RS-11','Results & Clinical Decision','Is an early negative result reliable?','តើលទ្ធផលអវិជ្ជមានដែលចេញមុនពេល គួរឱ្យទុកចិត្តទេ?','No. A negative reported after 5–10 minutes points to an operational error or an abnormal result. Repeat the test, following the correct procedure.','ទេ។ លទ្ធផលអវិជ្ជមានដែលរាយការណ៍ក្រោយ 5–10 នាទី បង្ហាញពីកំហុសក្នុងការប្រតិបត្តិ ឬលទ្ធផលមិនប្រក្រតី។ សូមធ្វើតេស្តម្តងទៀត ដោយអនុវត្តតាមនីតិវិធីត្រឹមត្រូវ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-12','RS-12','Results & Clinical Decision','Worker asks whether Pluslife can give a false negative','តើ Pluslife អាចចេញអវិជ្ជមាន ទោះមានមេរោគក៏ដោយទេ?','Any testing method can produce false negatives. This relates to the reagent''s sensitivity and specificity, as well as sample condition and operation. False negatives should be analyzed case by case.','វិធីធ្វើតេស្តណាក៏ដោយ អាចផ្តល់លទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative) បាន។ រឿងនេះពាក់ព័ន្ធនឹងភាពរសើប (sensitivity) និងភាពជាក់លាក់ (specificity) របស់សារធាតុ ក៏ដូចជាស្ថានភាពសំណាក និងការប្រតិបត្តិ។ លទ្ធផលអវិជ្ជមានក្លែងក្លាយ គួរវិភាគតាមករណីនីមួយៗ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-12-Q01','RS-12','Results & Clinical Decision','Can Pluslife give a false negative?','តើ Pluslife អាចផ្តល់លទ្ធផលអវិជ្ជមានក្លែងក្លាយបានទេ?','Yes. Any testing method can produce false negatives. This relates to the reagent''s sensitivity and specificity, as well as sample condition and operation. False negatives should be analyzed case by case.','បាទ/ចាស។ វិធីធ្វើតេស្តណាក៏ដោយ អាចផ្តល់លទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative) បាន។ រឿងនេះពាក់ព័ន្ធនឹងភាពរសើប (sensitivity) និងភាពជាក់លាក់ (specificity) របស់សារធាតុ ក៏ដូចជាស្ថានភាពសំណាក និងការប្រតិបត្តិ។ លទ្ធផលអវិជ្ជមានក្លែងក្លាយ គួរវិភាគតាមករណីនីមួយៗ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-12-Q02','RS-12','Results & Clinical Decision','Is a negative result 100% sure?','តើលទ្ធផលអវិជ្ជមាន ប្រាកដ 100% ទេ?','No. Any testing method can produce false negatives. This relates to the reagent''s sensitivity and specificity, as well as sample condition and operation.','ទេ។ វិធីធ្វើតេស្តណាក៏ដោយ អាចផ្តល់លទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative) បាន។ រឿងនេះពាក់ព័ន្ធនឹងភាពរសើប (sensitivity) និងភាពជាក់លាក់ (specificity) របស់សារធាតុ ក៏ដូចជាស្ថានភាពសំណាក និងការប្រតិបត្តិ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-12-Q03','RS-12','Results & Clinical Decision','false negative possible?','អវិជ្ជមានក្លែងក្លាយ អាចកើតមានទេ?','Yes. Any testing method can produce false negatives. This relates to the reagent''s sensitivity and specificity, as well as sample condition and operation. False negatives should be analyzed case by case.','បាទ/ចាស។ វិធីធ្វើតេស្តណាក៏ដោយ អាចផ្តល់លទ្ធផលអវិជ្ជមានក្លែងក្លាយ (false negative) បាន។ រឿងនេះពាក់ព័ន្ធនឹងភាពរសើប (sensitivity) និងភាពជាក់លាក់ (specificity) របស់សារធាតុ ក៏ដូចជាស្ថានភាពសំណាក និងការប្រតិបត្តិ។ លទ្ធផលអវិជ្ជមានក្លែងក្លាយ គួរវិភាគតាមករណីនីមួយៗ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-13','RS-13','Results & Clinical Decision','GeneXpert/PCR positive but Pluslife negative','GeneXpert ឬ PCR ចេញវិជ្ជមាន តែ Pluslife ចេញអវិជ្ជមាន។ ហេតុអ្វីលទ្ធផលខុសគ្នា?','Possible reasons for a positive PCR result but a negative Pluslife result:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-13-Q01','RS-13','Results & Clinical Decision','Xpert is positive but Pluslife is negative. Why?','Xpert វិជ្ជមាន តែ Pluslife អវិជ្ជមាន។ ហេតុអ្វី?','Possible reasons for a positive PCR result but a negative Pluslife result:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-13-Q02','RS-13','Results & Clinical Decision','PCR pos pluslife neg','PCR វិជ្ជមាន Pluslife អវិជ្ជមាន','Possible reasons for a positive PCR result but a negative Pluslife result:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-13-Q03','RS-13','Results & Clinical Decision','We did Pluslife and Xpert on different days and got different results.','យើងធ្វើ Pluslife និង Xpert នៅថ្ងៃខុសគ្នា ហើយបានលទ្ធផលខុសគ្នា។ តើត្រូវធ្វើអ្វីបន្ទាប់?','If both tests were not performed on the same day, the comparison may not be meaningful due to potential sample degradation or changes. We recommend retesting under controlled conditions.','បើតេស្តទាំងពីរមិនបានធ្វើនៅថ្ងៃតែមួយទេ ការប្រៀបធៀបអាចគ្មានន័យ ដោយសារសំណាកអាចខូច ឬប្រែប្រួល។ យើងណែនាំឱ្យធ្វើតេស្តម្តងទៀតក្រោមលក្ខខណ្ឌដែលគ្រប់គ្រងបាន។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-13-Q04','RS-13','Results & Clinical Decision','Could mucus cause the Pluslife negative?','តើស្លេស្មអាចធ្វើឱ្យ Pluslife អវិជ្ជមានទេ?','Yes. Mucus, debris or other inhibitors in the sample may interfere with amplification and cause false-negative results.','បាទ/ចាស។ ស្លេស្ម កំទេច ឬសារធាតុរារាំងផ្សេងទៀតក្នុងសំណាក អាចរំខានដល់ការពង្រីក ហើយបង្កលទ្ធផលអវិជ្ជមានក្លែងក្លាយ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-13-Q05','RS-13','Results & Clinical Decision','Can a low bacterial load be missed by Pluslife but found by PCR?','តើបរិមាណបាក់តេរីទាប អាចត្រូវ Pluslife រកមិនឃើញ តែ PCR រកឃើញបានទេ?','Yes. The pathogen concentration may be below the limit of detection for the Pluslife system, even if detectable by more sensitive PCR methods.','បាទ/ចាស។ កំហាប់មេរោគអាចទាបជាងកម្រិតរកឃើញ (limit of detection) របស់ប្រព័ន្ធ Pluslife ទោះបីវិធី PCR ដែលរសើបជាងអាចរកឃើញក៏ដោយ។','Safety-critical','TB focal person / OD');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-14','RS-14','Results & Clinical Decision','Worker asks for Pluslife sensitivity in terms of PCR Ct value','បើធៀបនឹងតម្លៃ Ct របស់ PCR តើ Pluslife អាចរកឃើញមេរោគដល់កម្រិតណា?','The sensitivity varies between different products; please refer to the IFU for details. There is no fixed correlation between sensitivity and Ct value — it depends on the detection limit and cut-off value of the PCR brand used. For example: Brand 1 has a LoD of 50 copies/mL with a cut-off of 40, so a Ct of 40 is about 50 copies/mL; for Pluslife, 400 copies correspond to a Ct of around 37, so any Ct below 37 can be reliably detected. Brand 2 has a LoD of 200 copies/mL with a cut-off of 35; for Pluslife, 400 copies correspond to a Ct of around 35–36, so any Ct below 36 can be reliably detected.','ភាពរសើបខុសគ្នាតាមផលិតផលនីមួយៗ សូមមើលព័ត៌មានលម្អិតក្នុង IFU (ឯកសារណែនាំការប្រើប្រាស់)។ គ្មានទំនាក់ទំនងថេររវាងភាពរសើប និងតម្លៃ Ct ទេ — វាអាស្រ័យលើកម្រិតរកឃើញ និងតម្លៃកាត់ (cut-off) របស់ម៉ាក PCR ដែលប្រើ។ ឧទាហរណ៍៖ ម៉ាកទី 1 មាន LoD 50 copies/mL ជាមួយ cut-off 40 ដូច្នេះ Ct 40 ស្មើប្រហែល 50 copies/mL។ សម្រាប់ Pluslife 400 copies ត្រូវនឹង Ct ប្រហែល 37 ដូច្នេះ Ct ណាដែលទាបជាង 37 អាចរកឃើញបានយ៉ាងជឿទុកចិត្ត។ ម៉ាកទី 2 មាន LoD 200 copies/mL ជាមួយ cut-off 35។ សម្រាប់ Pluslife 400 copies ត្រូវនឹង Ct ប្រហែល 35–36 ដូច្នេះ Ct ណាដែលទាបជាង 36 អាចរកឃើញបានយ៉ាងជឿទុកចិត្ត។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-14-Q01','RS-14','Results & Clinical Decision','What is the lowest Ct value Pluslife can detect?','តើតម្លៃ Ct ទាបបំផុតដែល Pluslife អាចរកឃើញ គឺប៉ុន្មាន?','The sensitivity varies between different products; please refer to the IFU for details. There is no fixed correlation between sensitivity and Ct value — it depends on the detection limit and cut-off value of the PCR brand used. For example: Brand 1 has a LoD of 50 copies/mL with a cut-off of 40, so a Ct of 40 is about 50 copies/mL; for Pluslife, 400 copies correspond to a Ct of around 37, so any Ct below 37 can be reliably detected. Brand 2 has a LoD of 200 copies/mL with a cut-off of 35; for Pluslife, 400 copies correspond to a Ct of around 35–36, so any Ct below 36 can be reliably detected.','ភាពរសើបខុសគ្នាតាមផលិតផលនីមួយៗ សូមមើលព័ត៌មានលម្អិតក្នុង IFU (ឯកសារណែនាំការប្រើប្រាស់)។ គ្មានទំនាក់ទំនងថេររវាងភាពរសើប និងតម្លៃ Ct ទេ — វាអាស្រ័យលើកម្រិតរកឃើញ និងតម្លៃកាត់ (cut-off) របស់ម៉ាក PCR ដែលប្រើ។ ឧទាហរណ៍៖ ម៉ាកទី 1 មាន LoD 50 copies/mL ជាមួយ cut-off 40 ដូច្នេះ Ct 40 ស្មើប្រហែល 50 copies/mL។ សម្រាប់ Pluslife 400 copies ត្រូវនឹង Ct ប្រហែល 37 ដូច្នេះ Ct ណាដែលទាបជាង 37 អាចរកឃើញបានយ៉ាងជឿទុកចិត្ត។ ម៉ាកទី 2 មាន LoD 200 copies/mL ជាមួយ cut-off 35។ សម្រាប់ Pluslife 400 copies ត្រូវនឹង Ct ប្រហែល 35–36 ដូច្នេះ Ct ណាដែលទាបជាង 36 អាចរកឃើញបានយ៉ាងជឿទុកចិត្ត។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-14-Q02','RS-14','Results & Clinical Decision','Is there a fixed Ct cut-off for Pluslife?','តើ Pluslife មានតម្លៃកាត់ (cut-off) Ct ថេរទេ?','No. There is no fixed correlation between sensitivity and Ct value — it depends on the detection limit and cut-off value of the PCR brand used.','ទេ។ គ្មានទំនាក់ទំនងថេររវាងភាពរសើប និងតម្លៃ Ct ទេ — វាអាស្រ័យលើកម្រិតរកឃើញ និងតម្លៃកាត់ (cut-off) របស់ម៉ាក PCR ដែលប្រើ។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-14-Q03','RS-14','Results & Clinical Decision','sensitivity of kit?','ភាពរសើបរបស់កញ្ចប់តេស្ត?','The sensitivity varies between different products; please refer to the IFU for details.','ភាពរសើបខុសគ្នាតាមផលិតផលនីមួយៗ សូមមើលព័ត៌មានលម្អិតក្នុង IFU (ឯកសារណែនាំការប្រើប្រាស់)។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-15','RS-15','Results & Clinical Decision','Lab validation: positive detection times not linear with concentration (400/800/1600 copies/mL)','ពេលផ្ទៀងផ្ទាត់ក្នុងមន្ទីរពិសោធន៍ ហេតុអ្វីពេលចេញវិជ្ជមានមិនប្រែប្រួលតាមកំហាប់ 400, 800 និង 1600 copies/mL?','1) Some customers may have used pseudovirus for validation without considering the storage stability of low-concentration pseudovirus.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-15-Q01','RS-15','Results & Clinical Decision','Why aren''t positive times linear across 400, 800 and 1600 copies/mL?','ហេតុអ្វីបានជារយៈពេលវិជ្ជមាន មិនស៊ីសង្វាក់ (linear) រវាង 400, 800 និង 1600 copies/mL?','1) Some customers may have used pseudovirus for validation without considering the storage stability of low-concentration pseudovirus.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-15-Q02','RS-15','Results & Clinical Decision','Is the MiniDock quantitative?','តើ MiniDock វាស់បរិមាណ (quantitative) ទេ?','No. The instrument gives qualitative results and is not a quantitative device.','ទេ។ ម៉ាស៊ីនផ្តល់លទ្ធផលគុណវិស័យ (qualitative) មិនមែនជាឧបករណ៍វាស់បរិមាណ (quantitative) ទេ។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-15-Q03','RS-15','Results & Clinical Decision','How much does the positive time vary for the same sample?','តើរយៈពេលវិជ្ជមាន ប្រែប្រួលប៉ុណ្ណា សម្រាប់សំណាកដូចគ្នា?','For the same concentration across multiple tests, positive detection time has an RSD of 21.6%.','សម្រាប់កំហាប់ដូចគ្នាក្នុងតេស្តច្រើនដង រយៈពេលរកឃើញវិជ្ជមានមាន RSD 21.6%។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-15-Q04','RS-15','Results & Clinical Decision','linearity test fail','តេស្តភាពស៊ីសង្វាក់ (linearity) បរាជ័យ','1) Some customers may have used pseudovirus for validation without considering the storage stability of low-concentration pseudovirus.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-16','RS-16','Results & Clinical Decision','Invalid result — Sample contains no human gene, e.g. commercial controls, cultured MTB strain','ហេតុអ្វីសំណាកដែលគ្មានហ្សែនមនុស្ស ដូចជាសំណាកត្រួតពិនិត្យពាណិជ្ជកម្ម ឬមេរោគ MTB ដែលបានបណ្តុះ អាចចេញ Invalid?','Add human sample in this kind of samples before testing if possible.','បើអាចធ្វើបាន សូមបន្ថែមសំណាកមនុស្សទៅក្នុងសំណាកប្រភេទនេះ មុនធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-16-Q01','RS-16','Results & Clinical Decision','I tested a cultured MTB strain and got invalid.','ខ្ញុំធ្វើតេស្តមេរោគ MTB ដែលបណ្តុះ ហើយបានលទ្ធផលចេញ Invalid ។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Invalid can happen when the sample contains no human gene, e.g. commercial controls or a cultured MTB strain. Add human sample in this kind of samples before testing if possible.','លទ្ធផលគ្មានសុពលភាព អាចកើតឡើងពេលសំណាកគ្មានហ្សែនមនុស្ស ឧទាហរណ៍ សំណាកត្រួតពិនិត្យពាណិជ្ជកម្ម (commercial controls) ឬមេរោគ MTB ដែលបណ្តុះ។ បើអាចធ្វើបាន សូមបន្ថែមសំណាកមនុស្សទៅក្នុងសំណាកប្រភេទនេះ មុនធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-16-Q02','RS-16','Results & Clinical Decision','Why is a commercial control invalid?','ហេតុអ្វីបានជាសំណាកត្រួតពិនិត្យពាណិជ្ជកម្ម (commercial control) ចេញ Invalid?','The sample contains no human gene. Add human sample before testing if possible.','សំណាកគ្មានហ្សែនមនុស្ស។ បើអាចធ្វើបាន សូមបន្ថែមសំណាកមនុស្ស មុនធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-16-Q03','RS-16','Results & Clinical Decision','invalid with culture sample','ចេញ Invalid ជាមួយសំណាកបណ្តុះ','Add human sample in this kind of samples before testing if possible.','បើអាចធ្វើបាន សូមបន្ថែមសំណាកមនុស្សទៅក្នុងសំណាកប្រភេទនេះ មុនធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-17','RS-17','Results & Clinical Decision','Invalid result — Tongue swab collected too shallowly, not reaching tissue with enough human cells','ខ្ញុំជូតអណ្តាតស្រាលពេក ហើយលទ្ធផលចេញ Invalid។ តើអាចមកពីសំណាកមានកោសិកាមនុស្សមិនគ្រប់ទេ?','Recollect the tongue swab correctly following the instruction.','ស្រង់សំណាកអណ្តាតម្តងទៀតឱ្យបានត្រឹមត្រូវ តាមការណែនាំ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-17-Q01','RS-17','Results & Clinical Decision','Tongue swab gave invalid. Did I swab too lightly?','សំណាកអណ្តាតចេញលទ្ធផលចេញ Invalid ។ តើខ្ញុំជូតស្រាលពេកទេ?','Possibly. If the tongue swab is collected too shallowly, it fails to reach the tissue layer that contains sufficient human cells. Recollect the tongue swab correctly following the instruction.','អាចទៅរួច។ បើស្រង់សំណាកអណ្តាតរាក់ពេក វាមិនដល់ស្រទាប់ជាលិកាដែលមានកោសិកាមនុស្សគ្រប់គ្រាន់ទេ។ សូមស្រង់សំណាកអណ្តាតម្តងទៀតឱ្យបានត្រឹមត្រូវ តាមការណែនាំ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-17-Q02','RS-17','Results & Clinical Decision','invalid tongue swab','សំណាកអណ្តាតចេញ Invalid','Recollect the tongue swab correctly following the instruction. A swab collected too shallowly fails to reach the tissue layer with sufficient human cells.','ស្រង់សំណាកអណ្តាតម្តងទៀតឱ្យបានត្រឹមត្រូវ តាមការណែនាំ។ ដងសំឡីដែលយករាក់ពេក មិនដល់ស្រទាប់ជាលិកាដែលមានកោសិកាមនុស្សគ្រប់គ្រាន់ទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-17-Q03','RS-17','Results & Clinical Decision','Should I recollect after an invalid tongue swab?','តើខ្ញុំគួរយកសំណាកម្តងទៀត ក្រោយសំណាកអណ្តាតចេញ Invalid ទេ?','Yes. Recollect the tongue swab correctly following the instruction.','បាទ/ចាស។ ស្រង់សំណាកអណ្តាតម្តងទៀតឱ្យបានត្រឹមត្រូវ តាមការណែនាំ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-18','RS-18','Results & Clinical Decision','Invalid / False Negative result — Sample contains inhibitors','តើសារធាតុរារាំងប្រតិកម្មក្នុងសំណាកអាចធ្វើឱ្យចេញ Invalid ឬអវិជ្ជមានក្លែងក្លាយទេ?','Collect the qualified sample correctly following the instruction. Avoid or remove the inhibitors. Inhibitors include flocked swabs left in the releasing agent, high protein content, blood, thick mucus, haemoglobin, proteolytic enzymes, or residual chemicals from sample collection or processing (e.g., disinfectants or extraction reagents) that have not been completely removed.','យកសំណាកដែលមានគុណភាពឱ្យបានត្រឹមត្រូវ តាមការណែនាំ។ ជៀសវាង ឬដកសារធាតុរារាំងចេញ។ សារធាតុរារាំងរួមមាន៖ ដងសំឡីប្រភេទ flocked ដែលទុកចោលក្នុង Releasing agent ប្រូតេអ៊ីនច្រើន ឈាម ស្លេស្មខាប់ អេម៉ូក្លូប៊ីន (haemoglobin) អង់ស៊ីមបំបែកប្រូតេអ៊ីន ឬសារធាតុគីមីសល់ពីការយក ឬការរៀបចំសំណាក (ឧទាហរណ៍ ថ្នាំសម្លាប់មេរោគ ឬសារធាតុចម្រាញ់) ដែលមិនទាន់ដកចេញអស់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-18-Q01','RS-18','Results & Clinical Decision','What inhibitors can make the result invalid or falsely negative?','តើសារធាតុរារាំងអ្វីខ្លះ អាចធ្វើឱ្យលទ្ធផលចេញ Invalid ឬអវិជ្ជមានក្លែងក្លាយ?','Inhibitors include flocked swabs left in the releasing agent, high protein content, blood, thick mucus, haemoglobin, proteolytic enzymes, or residual chemicals from sample collection or processing (e.g., disinfectants or extraction reagents) that have not been completely removed.','សារធាតុរារាំងរួមមាន៖ ដងសំឡីប្រភេទ flocked ដែលទុកចោលក្នុង Releasing agent ប្រូតេអ៊ីនច្រើន ឈាម ស្លេស្មខាប់ អេម៉ូក្លូប៊ីន (haemoglobin) អង់ស៊ីមបំបែកប្រូតេអ៊ីន ឬសារធាតុគីមីសល់ពីការយក ឬការរៀបចំសំណាក (ឧទាហរណ៍ ថ្នាំសម្លាប់មេរោគ ឬសារធាតុចម្រាញ់) ដែលមិនទាន់ដកចេញអស់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-18-Q02','RS-18','Results & Clinical Decision','Bloody sputum gave invalid. Why?','កំហាកមានឈាម ចេញលទ្ធផលចេញ Invalid ។ ហេតុអ្វី?','Blood is an inhibitor. Collect the qualified sample correctly following the instruction and avoid or remove the inhibitors.','ឈាមជាសារធាតុរារាំង។ សូមយកសំណាកដែលមានគុណភាពឱ្យបានត្រឹមត្រូវ តាមការណែនាំ ហើយជៀសវាង ឬដកសារធាតុរារាំងចេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-18-Q03','RS-18','Results & Clinical Decision','Can disinfectant on the bench affect the test?','តើថ្នាំសម្លាប់មេរោគលើតុ អាចប៉ះពាល់ដល់តេស្តទេ?','Yes. Residual chemicals from sample collection or processing (e.g. disinfectants) that have not been completely removed are inhibitors.','បាទ/ចាស។ សារធាតុគីមីសល់ពីការយក ឬការរៀបចំសំណាក (ឧទាហរណ៍ ថ្នាំសម្លាប់មេរោគ) ដែលមិនទាន់ដកចេញអស់ គឺជាសារធាតុរារាំង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-18-Q04','RS-18','Results & Clinical Decision','inhibitor','សារធាតុរារាំង','Collect the qualified sample correctly following the instruction. Avoid or remove the inhibitors.','យកសំណាកដែលមានគុណភាពឱ្យបានត្រឹមត្រូវ តាមការណែនាំ។ ជៀសវាង ឬដកសារធាតុរារាំងចេញ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-19','RS-19','Results & Clinical Decision','Invalid / False Positive result — Too many or too big bubbles','បើក្នុងកាតមានពពុះខ្យល់ច្រើន ឬធំពេក តើអាចចេញ Invalid ឬវិជ្ជមានក្លែងក្លាយទេ?','Prepare the test card correctly according to the instruction and avoid bubbles in the reaction card. Do not use cards with big bubbles.','រៀបចំកាតតេស្តឱ្យបានត្រឹមត្រូវតាមការណែនាំ ហើយជៀសវាងពពុះក្នុងកាតប្រតិកម្ម។ កុំប្រើកាតដែលមានពពុះធំ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-19-Q01','RS-19','Results & Clinical Decision','Can bubbles cause an invalid result?','តើពពុះអាចធ្វើឱ្យលទ្ធផលចេញ Invalid ទេ?','Yes. Too many or too big bubbles can cause invalid or false-positive results. Do not use cards with big bubbles.','បាទ/ចាស។ ពពុះច្រើនពេក ឬធំពេក អាចធ្វើឱ្យលទ្ធផលគ្មានសុពលភាព ឬវិជ្ជមានក្លែងក្លាយ។ កុំប្រើកាតដែលមានពពុះធំ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-19-Q02','RS-19','Results & Clinical Decision','false positive bubble','វិជ្ជមានក្លែងក្លាយ ដោយសារពពុះ','Prepare the test card correctly according to the instruction and avoid bubbles. Do not use cards with big bubbles.','រៀបចំកាតតេស្តឱ្យបានត្រឹមត្រូវតាមការណែនាំ ហើយជៀសវាងពពុះ។ កុំប្រើកាតដែលមានពពុះធំ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-20','RS-20','Results & Clinical Decision','Invalid result — Device lid opened during testing','តេស្តចេញ Invalid ក្រោយខ្ញុំបើកគម្របពេលម៉ាស៊ីនកំពុងដំណើរការ។ ត្រូវធ្វើម៉េច?','Do not open the lid during the test. If it was opened, prepare a new reaction card for a retest.','កុំបើកគម្របពេលកំពុងធ្វើតេស្ត។ បើបានបើករួចហើយ សូមរៀបចំកាតប្រតិកម្មថ្មី ដើម្បីធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-20-Q01','RS-20','Results & Clinical Decision','I opened the lid and got invalid. What now?','ខ្ញុំបានបើកគម្រប ហើយបានលទ្ធផលចេញ Invalid ។ ត្រូវធ្វើអ្វីឥឡូវ?','Prepare a new reaction card for a retest. Do not open the lid during the test.','រៀបចំកាតប្រតិកម្មថ្មី ដើម្បីធ្វើតេស្តម្តងទៀត។ កុំបើកគម្របពេលកំពុងធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-20-Q02','RS-20','Results & Clinical Decision','lid open invalid retest?','បើកគម្របចេញ Invalid ធ្វើតេស្តម្តងទៀត?','Yes. Prepare a new reaction card for the retest.','បាទ/ចាស។ រៀបចំកាតប្រតិកម្មថ្មី ដើម្បីធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-21','RS-21','Results & Clinical Decision','Invalid / False Negative result — Detection module failure','តើបញ្ហានៅផ្នែកចាប់សញ្ញារបស់ម៉ាស៊ីនអាចធ្វើឱ្យចេញ Invalid ឬអវិជ្ជមានក្លែងក្លាយទេ?','Repeat the test using another device to confirm. Check the device''s function. Contact the manufacturer.','ធ្វើតេស្តម្តងទៀតដោយប្រើម៉ាស៊ីនផ្សេង ដើម្បីបញ្ជាក់។ ពិនិត្យមុខងាររបស់ម៉ាស៊ីន។ ទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅក្រុមហ៊ុនផលិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-21-Q01','RS-21','Results & Clinical Decision','Could the device itself cause invalid results?','តើម៉ាស៊ីនខ្លួនឯង អាចធ្វើឱ្យលទ្ធផលចេញ Invalid ទេ?','Yes. A detection module failure can cause invalid or false-negative results. Repeat the test using another device to confirm, check the device''s function, and contact the manufacturer.','បាទ/ចាស។ ម៉ូឌុលរកឃើញ (detection module) ខូច អាចធ្វើឱ្យលទ្ធផលគ្មានសុពលភាព ឬអវិជ្ជមានក្លែងក្លាយ។ ធ្វើតេស្តម្តងទៀតដោយប្រើម៉ាស៊ីនផ្សេង ដើម្បីបញ្ជាក់ ពិនិត្យមុខងាររបស់ម៉ាស៊ីន ហើយទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅក្រុមហ៊ុនផលិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-21-Q02','RS-21','Results & Clinical Decision','Many invalids on one device only.','មានលទ្ធផលចេញ Invalid ច្រើន តែលើម៉ាស៊ីនមួយប៉ុណ្ណោះ។ តើត្រូវធ្វើអ្វីបន្ទាប់?','Repeat the test using another device to confirm. Check the device''s function. Contact the manufacturer.','ធ្វើតេស្តម្តងទៀតដោយប្រើម៉ាស៊ីនផ្សេង ដើម្បីបញ្ជាក់។ ពិនិត្យមុខងាររបស់ម៉ាស៊ីន។ ទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅក្រុមហ៊ុនផលិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-21-Q03','RS-21','Results & Clinical Decision','device module broken?','ម៉ូឌុលម៉ាស៊ីនខូច?','Not sure. To confirm, repeat the test using another device, check the device''s function, and contact the manufacturer.','មិនប្រាកដទេ។ ដើម្បីបញ្ជាក់ សូមធ្វើតេស្តម្តងទៀតដោយប្រើម៉ាស៊ីនផ្សេង ពិនិត្យមុខងាររបស់ម៉ាស៊ីន ហើយទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅក្រុមហ៊ុនផលិត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-22','RS-22','Results & Clinical Decision','False Positive result — Sample contaminated by positive samples during collection or pretreatment','តើការចម្លងរោគពីសំណាកវិជ្ជមាន ពេលស្រង់ ឬរៀបចំសំណាក អាចធ្វើឱ្យចេញវិជ្ជមានក្លែងក្លាយទេ?','Standardize the sample collection and pretreatment process. Store the samples in different containers, seal the processed samples and discard them in hypochlorous acid solution.','ស្រង់សំណាកតាមជំហានស្តង់ដារ និង pretreatment។ រក្សាទុកសំណាកក្នុងប្រអប់ដាច់ដោយឡែកពីគ្នា បិទសំណាកដែលរៀបចំរួចឱ្យជិត ហើយបោះចោលក្នុងសូលុយស្យុងអាស៊ីតអ៊ីប៉ូក្លរូស (hypochlorous acid)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-22-Q01','RS-22','Results & Clinical Decision','How can a negative patient become positive by contamination?','តើអ្នកជំងឺអវិជ្ជមាន អាចក្លាយជាវិជ្ជមានដោយសារការចម្លងរោគយ៉ាងដូចម្តេច?','The sample can be contaminated by positive samples during collection or pretreatment. Standardize the sample collection and pretreatment process.','សំណាកអាចឆ្លងមេរោគពីសំណាកវិជ្ជមាន ពេលយកសំណាក ឬពេល pretreatment។ សូមស្រង់សំណាកតាមជំហានស្តង់ដារ និង pretreatment។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-22-Q02','RS-22','Results & Clinical Decision','How do I dispose of processed samples to avoid contamination?','តើខ្ញុំបោះចោលសំណាកដែលរៀបចំរួចយ៉ាងម៉េច ដើម្បីជៀសវាងការចម្លងរោគ?','Seal the processed samples and discard them in hypochlorous acid solution.','បិទសំណាកដែលរៀបចំរួចឱ្យជិត ហើយបោះចោលក្នុងសូលុយស្យុងអាស៊ីតអ៊ីប៉ូក្លរូស (hypochlorous acid)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-22-Q03','RS-22','Results & Clinical Decision','Can I keep all patients'' samples in one box?','អាចទុកសំណាករបស់អ្នកជំងឺទាំងអស់ក្នុងប្រអប់តែមួយបានទេ?','No. Store the samples in different containers.','មិនបានទេ។ រក្សាទុកសំណាកក្នុងប្រអប់ដាច់ដោយឡែកពីគ្នា។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-23','RS-23','Results & Clinical Decision','False Positive result — Transport medium used to store the sample','ខ្ញុំទុកសំណាកក្នុងសារធាតុដឹកជញ្ជូនសំណាក។ តើវាអាចធ្វើឱ្យចេញវិជ្ជមានក្លែងក្លាយទេ?','Do not use transport medium to store the sample; store it with a dry swab.','កុំប្រើមជ្ឈដ្ឋានដឹកជញ្ជូន (transport medium) ដើម្បីរក្សាទុកសំណាក។ សូមរក្សាទុកជាមួយដងសំឡីស្ងួត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-23-Q01','RS-23','Results & Clinical Decision','Can transport medium cause a false positive?','តើមជ្ឈដ្ឋានដឹកជញ្ជូន (transport medium) អាចធ្វើឱ្យលទ្ធផលវិជ្ជមានក្លែងក្លាយទេ?','Yes. Do not use transport medium to store the sample; store it with a dry swab.','បាទ/ចាស។ កុំប្រើមជ្ឈដ្ឋានដឹកជញ្ជូន (transport medium) ដើម្បីរក្សាទុកសំណាក។ សូមរក្សាទុកជាមួយដងសំឡីស្ងួត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-23-Q02','RS-23','Results & Clinical Decision','How should I store the swab if I can''t test now?','តើខ្ញុំគួររក្សាទុកដងសំឡីយ៉ាងម៉េច បើមិនអាចធ្វើតេស្តឥឡូវ?','Store it with a dry swab; do not use transport medium.','រក្សាទុកជាមួយដងសំឡីស្ងួត។ កុំប្រើមជ្ឈដ្ឋានដឹកជញ្ជូន (transport medium)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-24','RS-24','Results & Clinical Decision','False Positive result — Device or its power supply moved during testing','ខ្ញុំរើម៉ាស៊ីន ឬប្រភពភ្លើងពេលតេស្តកំពុងដំណើរការ។ តើវាអាចប៉ះពាល់ដល់លទ្ធផលវិជ្ជមានទេ?','Place the device on a stable platform; do not move the device or its power supply during testing.','ដាក់ម៉ាស៊ីនលើកន្លែងនឹង។ កុំរើម៉ាស៊ីន ឬប្រភពភ្លើងរបស់វា ពេលកំពុងធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-24-Q01','RS-24','Results & Clinical Decision','Can moving the device during a test cause a false positive?','តើការរើម៉ាស៊ីនពេលកំពុងធ្វើតេស្ត អាចធ្វើឱ្យលទ្ធផលវិជ្ជមានក្លែងក្លាយទេ?','Yes. Do not move the device or its power supply during testing.','បាទ/ចាស។ កុំរើម៉ាស៊ីន ឬប្រភពភ្លើងរបស់វា ពេលកំពុងធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-24-Q02','RS-24','Results & Clinical Decision','bumped the device during test','ប៉ះទង្គិចម៉ាស៊ីន ពេលកំពុងធ្វើតេស្ត','Moving the device or its power supply during testing can cause a false positive. Place the device on a stable platform.','ការរើម៉ាស៊ីន ឬប្រភពភ្លើងរបស់វា ពេលកំពុងធ្វើតេស្ត អាចធ្វើឱ្យលទ្ធផលវិជ្ជមានក្លែងក្លាយ។ សូមដាក់ម៉ាស៊ីនលើកន្លែងនឹង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-24-Q03','RS-24','Results & Clinical Decision','Is it OK to move the cable during the test?','តើរើខ្សែពេលកំពុងធ្វើតេស្ត មិនអីទេឬ?','No. Do not move the device or its power supply during testing.','មិនបានទេ។ កុំរើម៉ាស៊ីន ឬប្រភពភ្លើងរបស់វា ពេលកំពុងធ្វើតេស្ត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-25','RS-25','Results & Clinical Decision','False Positive result — False negative from the other detection method','Pluslife ចេញវិជ្ជមាន តែវិធីតេស្តផ្សេងចេញអវិជ្ជមាន។ តើលទ្ធផលអវិជ្ជមាននោះអាចខុសទេ?','Use a sensitive detection platform and repeat the test.','ប្រើប្រព័ន្ធរកមេរោគដែលមានភាពរសើបខ្ពស់ ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-25-Q01','RS-25','Results & Clinical Decision','Pluslife positive but the other test negative. Which is wrong?','Pluslife វិជ្ជមាន តែតេស្តផ្សេងអវិជ្ជមាន។ មួយណាខុស?','Not sure. One possible reason is a false negative from the other detection method. Use a sensitive detection platform and repeat the test.','មិនប្រាកដទេ។ មូលហេតុមួយដែលអាចកើតមាន គឺលទ្ធផលអវិជ្ជមានក្លែងក្លាយពីវិធីរកមេរោគមួយទៀត។ សូមប្រើប្រព័ន្ធរកមេរោគដែលមានភាពរសើបខ្ពស់ ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-25-Q02','RS-25','Results & Clinical Decision','pluslife pos other neg','Pluslife វិជ្ជមាន តេស្តផ្សេងអវិជ្ជមាន','Use a sensitive detection platform and repeat the test.','ប្រើប្រព័ន្ធរកមេរោគដែលមានភាពរសើបខ្ពស់ ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-26','RS-26','Results & Clinical Decision','False Positive result — Nucleic acid residues at the end of treatment','អ្នកជំងឺជិតបញ្ចប់ការព្យាបាល តែតេស្តនៅតែចេញវិជ្ជមាន។ តើអាចមកពីអាស៊ីតនុយក្លេអ៊ិកនៅសល់ទេ?','Nucleic acid testing is not recommended in the short term for patients who have completed a standard course of treatment; it is recommended in conjunction with clinical symptoms/smears/cultures.','មិនណែនាំឱ្យធ្វើតេស្តអាស៊ីតនុយក្លេអ៊ីកក្នុងរយៈពេលខ្លី សម្រាប់អ្នកជំងឺដែលបានបញ្ចប់វគ្គព្យាបាលស្តង់ដាររួច។ ណែនាំឱ្យធ្វើរួមជាមួយរោគសញ្ញាគ្លីនិក/ការពិនិត្យកំហាកតាមមីក្រូទស្សន៍ (smear)/ការបណ្តុះមេរោគ (culture)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-26-Q01','RS-26','Results & Clinical Decision','Can I use Pluslife to check if a patient is cured after treatment?','អាចប្រើ Pluslife ដើម្បីពិនិត្យថាអ្នកជំងឺជាសះស្បើយក្រោយព្យាបាលបានទេ?','No, not in the short term. Nucleic acid testing is not recommended in the short term for patients who have completed a standard course of treatment; use it in conjunction with clinical symptoms/smears/cultures.','មិនបានទេ មិនមែនក្នុងរយៈពេលខ្លីទេ។ មិនណែនាំឱ្យធ្វើតេស្តអាស៊ីតនុយក្លេអ៊ីកក្នុងរយៈពេលខ្លី សម្រាប់អ្នកជំងឺដែលបានបញ្ចប់វគ្គព្យាបាលស្តង់ដាររួច។ សូមប្រើរួមជាមួយរោគសញ្ញាគ្លីនិក/ការពិនិត្យកំហាកតាមមីក្រូទស្សន៍ (smear)/ការបណ្តុះមេរោគ (culture)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-26-Q02','RS-26','Results & Clinical Decision','Patient finished treatment but still positive.','អ្នកជំងឺបានបញ្ចប់ការព្យាបាល តែនៅតែវិជ្ជមាន។ តើត្រូវធ្វើអ្វីបន្ទាប់?','This may be nucleic acid residues at the end of treatment. Nucleic acid testing is not recommended in the short term after a standard course of treatment; combine with clinical symptoms/smears/cultures.','នេះអាចជាសំណល់អាស៊ីតនុយក្លេអ៊ីក នៅចុងបញ្ចប់នៃការព្យាបាល។ មិនណែនាំឱ្យធ្វើតេស្តអាស៊ីតនុយក្លេអ៊ីកក្នុងរយៈពេលខ្លី ក្រោយវគ្គព្យាបាលស្តង់ដារ។ សូមប្រើរួមជាមួយរោគសញ្ញាគ្លីនិក/ការពិនិត្យកំហាកតាមមីក្រូទស្សន៍ (smear)/ការបណ្តុះមេរោគ (culture)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-26-Q03','RS-26','Results & Clinical Decision','test after treatment','ធ្វើតេស្តក្រោយព្យាបាល','Not recommended in the short term after a standard course of treatment.','មិនណែនាំក្នុងរយៈពេលខ្លី ក្រោយវគ្គព្យាបាលស្តង់ដារទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-27','RS-27','Results & Clinical Decision','False Positive result — Environmental contamination','តើការចម្លងរោគពីកន្លែងធ្វើតេស្តអាចធ្វើឱ្យលទ្ធផលចេញវិជ្ជមានក្លែងក្លាយទេ?','Perform daily cleaning, do not open tested cards, and discard tested cards promptly. If positive cases are found constantly, perform the contamination elimination process (please refer to 5.4).','សម្អាតជារៀងរាល់ថ្ងៃ កុំបើកកាតដែលធ្វើតេស្តរួច ហើយបោះចោលកាតដែលធ្វើតេស្តរួចឱ្យបានឆាប់។ បើរកឃើញករណីវិជ្ជមានជាប់ៗគ្នា សូមអនុវត្តដំណើរការលុបបំបាត់ការចម្លងរោគ (សូមមើលផ្នែក 5.4)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-27-Q01','RS-27','Results & Clinical Decision','We are getting many positives in a row. Could it be contamination?','យើងកំពុងបានលទ្ធផលវិជ្ជមានជាច្រើនជាប់ៗគ្នា។ តើវាអាចជាការចម្លងរោគទេ?','Possibly environmental contamination. If constant positive cases are found, perform the contamination elimination process (please refer to 5.4).','អាចជាការចម្លងរោគពីបរិស្ថាន។ បើរកឃើញករណីវិជ្ជមានជាប់ៗគ្នា សូមអនុវត្តដំណើរការលុបបំបាត់ការចម្លងរោគ (សូមមើលផ្នែក 5.4)។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-27-Q02','RS-27','Results & Clinical Decision','How do I prevent contamination?','តើខ្ញុំការពារការចម្លងរោគយ៉ាងម៉េច?','Perform daily cleaning, do not open tested cards, and discard tested cards promptly.','សម្អាតជារៀងរាល់ថ្ងៃ កុំបើកកាតដែលធ្វើតេស្តរួច ហើយបោះចោលកាតដែលធ្វើតេស្តរួចឱ្យបានឆាប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-27-Q03','RS-27','Results & Clinical Decision','Can I open a tested card to look inside?','អាចបើកកាតដែលធ្វើតេស្តរួច ដើម្បីមើលខាងក្នុងបានទេ?','No. Do not open tested cards.','មិនបានទេ។ កុំបើកកាតដែលធ្វើតេស្តរួច។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-28','RS-28','Results & Clinical Decision','False Positive result — Nonspecific amplification','តើប្រតិកម្មបង្កើនចំនួន DNA ខុសគោលដៅអាចធ្វើឱ្យចេញវិជ្ជមានក្លែងក្លាយទេ?','Resample and retest.','យកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-28-Q01','RS-28','Results & Clinical Decision','What do I do if I suspect non-specific amplification?','បើសង្ស័យថាប្រតិកម្មបង្កើនចំនួន DNA ខុសគោលដៅ ត្រូវធ្វើម៉េច?','Resample and retest.','យកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-28-Q02','RS-28','Results & Clinical Decision','nonspecific amplification','ការបង្កើនចំនួន DNA ខុសគោលដៅ (nonspecific amplification) មានន័យថាម៉េច?','Resample and retest.','យកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-29','RS-29','Results & Clinical Decision','False Negative result — Few target pathogens; tongue swab collected improperly; sputum not qualified','តើមេរោគតិច សំណាកអណ្តាតស្រង់មិនត្រឹមត្រូវ ឬកំហាកគុណភាពមិនល្អ អាចធ្វើឱ្យចេញអវិជ្ជមានក្លែងក្លាយទេ?','Standardize the sample collection process. Recollect the samples and retest.','ស្រង់សំណាកតាមជំហានស្តង់ដារ។ យកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-29-Q01','RS-29','Results & Clinical Decision','Could poor sampling give a false negative?','តើការស្រង់សំណាកមិនល្អ អាចធ្វើឱ្យលទ្ធផលអវិជ្ជមានក្លែងក្លាយទេ?','Yes. The tongue swab collected improperly or an unqualified sputum sample can fail to obtain sufficient pathogen. Standardize the sample collection process, recollect and retest.','បាទ/ចាស។ សំណាកអណ្តាតដែលយកមិនត្រឹមត្រូវ ឬសំណាកកំហាកដែលមិនមានគុណភាព អាចមិនទទួលបានមេរោគគ្រប់គ្រាន់។ សូមស្រង់សំណាកតាមជំហានស្តង់ដារ យកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-29-Q02','RS-29','Results & Clinical Decision','sample bad false negative','សំណាកមិនល្អ អវិជ្ជមានក្លែងក្លាយ','Recollect the samples and retest.','យកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-30','RS-30','Results & Clinical Decision','False Negative result — Improper sample storage causing degradation','បើទុកសំណាកមិនត្រឹមត្រូវ តើសំណាកអាចខូច ហើយធ្វើឱ្យលទ្ធផលចេញអវិជ្ជមានក្លែងក្លាយទេ?','Recollect the sample and retest.','យកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-30-Q01','RS-30','Results & Clinical Decision','The sample was left out too long. Can I still trust a negative?','សំណាកត្រូវបានទុកនៅខាងក្រៅយូរពេក។ តើខ្ញុំនៅតែអាចទុកចិត្តលទ្ធផលអវិជ្ជមានបានទេ?','No. Improper sample storage can cause sample degradation and a false negative. Recollect the sample and retest.','ទេ។ ការរក្សាទុកសំណាកមិនត្រឹមត្រូវ អាចធ្វើឱ្យសំណាកខូច និងលទ្ធផលអវិជ្ជមានក្លែងក្លាយ។ សូមយកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-30-Q02','RS-30','Results & Clinical Decision','sample degraded','សំណាកខូច','Recollect the sample and retest.','យកសំណាកម្តងទៀត ហើយធ្វើតេស្តម្តងទៀត។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-31','RS-31','Results & Clinical Decision','False Negative result — Sample collected at an early stage of infection (incubation period)','បើស្រង់សំណាកនៅដំណាក់កាលដំបូងនៃការឆ្លង តើតេស្តអាចចេញអវិជ្ជមានក្លែងក្លាយទេ?','Recollect a sample from the patient after symptom onset for 1 week.','យកសំណាកពីអ្នកជំងឺម្តងទៀត ក្រោយចេញរោគសញ្ញាបាន 1 សប្តាហ៍។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-31-Q01','RS-31','Results & Clinical Decision','Patient only had symptoms for 2 days and tested negative.','អ្នកជំងឺទើបតែមានរោគសញ្ញា 2 ថ្ងៃ ហើយលទ្ធផលតេស្តអវិជ្ជមាន។ តើត្រូវធ្វើអ្វីបន្ទាប់?','A sample collected at an early stage of infection can give a false negative. Recollect a sample after symptom onset for 1 week.','សំណាកដែលយកនៅដំណាក់កាលដំបូងនៃការឆ្លង អាចផ្តល់លទ្ធផលអវិជ្ជមានក្លែងក្លាយ។ សូមយកសំណាកម្តងទៀត ក្រោយចេញរោគសញ្ញាបាន 1 សប្តាហ៍។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-31-Q02','RS-31','Results & Clinical Decision','When should I retest an early case?','តើខ្ញុំគួរធ្វើតេស្តម្តងទៀតសម្រាប់ករណីដំបូងនៅពេលណា?','Recollect a sample from the patient after symptom onset for 1 week.','យកសំណាកពីអ្នកជំងឺម្តងទៀត ក្រោយចេញរោគសញ្ញាបាន 1 សប្តាហ៍។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-32','RS-32','Results & Clinical Decision','False Negative result — Pathogen concentration lower than the LOD','បើមេរោគមានតិចជាងកម្រិតដែលម៉ាស៊ីនអាចរកឃើញ (LOD) តើតេស្តអាចចេញអវិជ្ជមានក្លែងក្លាយទេ?','Extract the sample using an extraction & purification kit, or retest with other methods.','ចម្រាញ់សំណាកដោយប្រើកញ្ចប់ចម្រាញ់ និងបន្សុទ្ធ (extraction & purification kit) ឬធ្វើតេស្តម្តងទៀតដោយវិធីផ្សេង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-32-Q01','RS-32','Results & Clinical Decision','What if the bacterial load is below the LOD?','ចុះបើបរិមាណបាក់តេរីទាបជាងកម្រិតរកឃើញ (LOD)?','Extract the sample using an extraction & purification kit, or retest with other methods.','ចម្រាញ់សំណាកដោយប្រើកញ្ចប់ចម្រាញ់ និងបន្សុទ្ធ (extraction & purification kit) ឬធ្វើតេស្តម្តងទៀតដោយវិធីផ្សេង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('RS-32-Q02','RS-32','Results & Clinical Decision','low load negative','បើមេរោគមានតិច តើអាចចេញអវិជ្ជមានទេ?','Extract the sample using an extraction & purification kit, or retest with other methods.','ចម្រាញ់សំណាកដោយប្រើកញ្ចប់ចម្រាញ់ និងបន្សុទ្ធ (extraction & purification kit) ឬធ្វើតេស្តម្តងទៀតដោយវិធីផ្សេង។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-05','IT-05','Installation/Setup','Worker wants to use their own barcode scanner with the computer','អាចប្រើម៉ាស៊ីនស្កេនបាកូដដែលមណ្ឌលសុខភាពមានស្រាប់ ជាមួយកម្មវិធីលើកុំព្យូទ័របានទេ?','Yes. It can be used once its driver is installed.','បាទ/ចាស អាចប្រើបាន ក្រោយដំឡើងកម្មវិធីបញ្ជា (driver) របស់វារួច។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-05-Q01','IT-05','Installation/Setup','Can I connect my own barcode scanner to the computer to scan sample codes?','អាចភ្ជាប់ម៉ាស៊ីនស្កេនបាកូដផ្ទាល់ខ្លួន ទៅកុំព្យូទ័រដើម្បីស្កេនកូដសំណាកបានទេ?','Yes. It can be used once its driver is installed.','បាទ/ចាស អាចប្រើបាន ក្រោយដំឡើងកម្មវិធីបញ្ជា (driver) របស់វារួច។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-05-Q02','IT-05','Installation/Setup','my barcode gun work with software?','កាំភ្លើងស្កេនបាកូដរបស់ខ្ញុំ ដំណើរការជាមួយកម្មវិធីទេ?','Yes. It can be used once its driver is installed.','បាទ/ចាស អាចប្រើបាន ក្រោយដំឡើងកម្មវិធីបញ្ជា (driver) របស់វារួច។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-05-Q03','IT-05','Installation/Setup','Does a barcode scanner need a driver?','តើម៉ាស៊ីនស្កេនបាកូដត្រូវការកម្មវិធីបញ្ជា (driver) ទេ?','Yes. It can be used once its driver is installed.','បាទ/ចាស អាចប្រើបាន ក្រោយដំឡើងកម្មវិធីបញ្ជា (driver) របស់វារួច។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-06','IT-06','Installation/Setup','Driver installation fails on a Windows 7 computer','ដំឡើង Driver លើកុំព្យូទ័រ Windows 7 មិនបាន។ ត្រូវធ្វើម៉េច?','The driver cannot be installed on some 32/64-bit Windows 7 systems until a patch is installed. Download and install the patch matching your system:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-06-Q01','IT-06','Installation/Setup','Driver install fails on our Windows 7 computer.','ដំឡើងកម្មវិធីបញ្ជា (driver) មិនបាន លើកុំព្យូទ័រ Windows 7 របស់យើង។ ត្រូវធ្វើម៉េច?','The driver cannot be installed on some 32/64-bit Windows 7 systems until a patch is installed. Download and install the patch matching your system:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-06-Q02','IT-06','Installation/Setup','win7 driver error','កំហុសកម្មវិធីបញ្ជា (driver) Windows 7','The driver cannot be installed on some 32/64-bit Windows 7 systems until a patch is installed. Download and install the patch matching your system:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-06-Q03','IT-06','Installation/Setup','Can PluslifePad be used on Windows 7?','តើ PluslifePad អាចប្រើលើ Windows 7 បានទេ?','Not sure — that is not stated. On some 32/64-bit Windows 7 systems the driver cannot be installed until a patch is installed. 32-bit: https://download.microsoft.com/download/3/7/4/37473F39-5728-4153-9A25-64C09DE9ED52/Windows6.1-KB3033929-x86.msu
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-06-Q04','IT-06','Installation/Setup','Which patch do I need for Windows 7 64-bit?','តើខ្ញុំត្រូវការបំណះ (patch) មួយណា សម្រាប់ Windows 7 64-bit?','64-bit: https://download.microsoft.com/download/C/8/7/C87AE67E-A228-48FB-8F02-B2A9A1238099/Windows6.1-KB3033929-x64.msu. After installation, run CH341SER.EXE in the PluslifePad software folder to reinstall the driver.','64-bit: https://download.microsoft.com/download/C/8/7/C87AE67E-A228-48FB-8F02-B2A9A1238099/Windows6.1-KB3033929-x64.msu ។ ក្រោយដំឡើងរួច សូមដំណើរការ CH341SER.EXE ក្នុងថតកម្មវិធី PluslifePad ដើម្បីដំឡើងកម្មវិធីបញ្ជា (driver) ម្តងទៀត។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-07','IT-07','Installation/Setup','Worker asks for the software login after installation','ដំឡើងកម្មវិធីរួច ត្រូវប្រើឈ្មោះអ្នកប្រើ និងពាក្យសម្ងាត់អ្វី ដើម្បីចូល?','For the first login, use the default username "admin" and password "admin". After logging in, you can change the password or create new users on the User page.','សម្រាប់ការចូលលើកដំបូង សូមប្រើឈ្មោះអ្នកប្រើលំនាំដើម "admin" និងពាក្យសម្ងាត់ "admin"។ ក្រោយចូលរួច អ្នកអាចប្តូរពាក្យសម្ងាត់ ឬបង្កើតអ្នកប្រើថ្មី នៅទំព័រ User។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-07-Q01','IT-07','Installation/Setup','What is the username and password for the computer software?','តើឈ្មោះអ្នកប្រើ និងពាក្យសម្ងាត់សម្រាប់កម្មវិធីកុំព្យូទ័រ គឺអ្វី?','For the first login, use the default username "admin" and password "admin". After logging in, you can change the password or create new users on the User page.','សម្រាប់ការចូលលើកដំបូង សូមប្រើឈ្មោះអ្នកប្រើលំនាំដើម "admin" និងពាក្យសម្ងាត់ "admin"។ ក្រោយចូលរួច អ្នកអាចប្តូរពាក្យសម្ងាត់ ឬបង្កើតអ្នកប្រើថ្មី នៅទំព័រ User។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-07-Q02','IT-07','Installation/Setup','default password?','ពាក្យសម្ងាត់លំនាំដើម?','Default username "admin" and password "admin" for the first login.','ឈ្មោះអ្នកប្រើលំនាំដើម "admin" និងពាក្យសម្ងាត់ "admin" សម្រាប់ការចូលលើកដំបូង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-07-Q03','IT-07','Installation/Setup','first time login PluslifePad','ចូល PluslifePad លើកដំបូង','For the first login, use the default username "admin" and password "admin". After logging in, you can change the password or create new users on the User page.','សម្រាប់ការចូលលើកដំបូង សូមប្រើឈ្មោះអ្នកប្រើលំនាំដើម "admin" និងពាក្យសម្ងាត់ "admin"។ ក្រោយចូលរួច អ្នកអាចប្តូរពាក្យសម្ងាត់ ឬបង្កើតអ្នកប្រើថ្មី នៅទំព័រ User។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-07-Q04','IT-07','Installation/Setup','Can I change the admin password?','អាចប្តូរពាក្យសម្ងាត់ admin បានទេ?','Yes. After logging in, you can change the password or create new users on the User page.','បាទ/ចាស។ ក្រោយចូលរួច អ្នកអាចប្តូរពាក្យសម្ងាត់ ឬបង្កើតអ្នកប្រើថ្មី នៅទំព័រ User។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-08','IT-08','Installation/Setup','Worker wants separate user accounts for different operators','បុគ្គលិកម្នាក់ៗអាចមានគណនីចូលកម្មវិធីផ្ទាល់ខ្លួនបានទេ?','Yes. After the first login, you can create new users on the User page and grant each user different operating permissions, making it easier for different operators to manage tests.','បាទ/ចាស អាចធ្វើបាន។ ក្រោយការចូលលើកដំបូង អ្នកអាចបង្កើតអ្នកប្រើថ្មីនៅទំព័រ User ហើយផ្តល់សិទ្ធិប្រតិបត្តិខុសៗគ្នាដល់អ្នកប្រើនីមួយៗ ដើម្បីងាយស្រួលឱ្យអ្នកប្រតិបត្តិផ្សេងៗគ្រប់គ្រងតេស្ត។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-08-Q01','IT-08','Installation/Setup','Can I create new users after logging in?','អាចបង្កើតអ្នកប្រើថ្មី ក្រោយចូលរួចបានទេ?','Yes. After the first login, you can create new users on the User page and grant each user different operating permissions, making it easier for different operators to manage tests.','បាទ/ចាស អាចធ្វើបាន។ ក្រោយការចូលលើកដំបូង អ្នកអាចបង្កើតអ្នកប្រើថ្មីនៅទំព័រ User ហើយផ្តល់សិទ្ធិប្រតិបត្តិខុសៗគ្នាដល់អ្នកប្រើនីមួយៗ ដើម្បីងាយស្រួលឱ្យអ្នកប្រតិបត្តិផ្សេងៗគ្រប់គ្រងតេស្ត។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-08-Q02','IT-08','Installation/Setup','Can each staff member have their own login?','តើបុគ្គលិកម្នាក់ៗអាចមានគណនីចូលផ្ទាល់ខ្លួនបានទេ?','Yes. After the first login, you can create new users on the User page and grant each user different operating permissions, making it easier for different operators to manage tests.','បាទ/ចាស អាចធ្វើបាន។ ក្រោយការចូលលើកដំបូង អ្នកអាចបង្កើតអ្នកប្រើថ្មីនៅទំព័រ User ហើយផ្តល់សិទ្ធិប្រតិបត្តិខុសៗគ្នាដល់អ្នកប្រើនីមួយៗ ដើម្បីងាយស្រួលឱ្យអ្នកប្រតិបត្តិផ្សេងៗគ្រប់គ្រងតេស្ត។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-08-Q03','IT-08','Installation/Setup','add user how','បន្ថែមអ្នកប្រើ យ៉ាងម៉េច?','After the first login, create new users on the User page and grant each user different operating permissions.','ក្រោយការចូលលើកដំបូង សូមបង្កើតអ្នកប្រើថ្មីនៅទំព័រ User ហើយផ្តល់សិទ្ធិប្រតិបត្តិខុសៗគ្នាដល់អ្នកប្រើនីមួយៗ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-08-Q04','IT-08','Installation/Setup','Can I give users different permissions?','អាចផ្តល់សិទ្ធិខុសៗគ្នាដល់អ្នកប្រើបានទេ?','Yes. You can grant each user different operating permissions on the User page.','បាទ/ចាស។ អ្នកអាចផ្តល់សិទ្ធិប្រតិបត្តិខុសៗគ្នាដល់អ្នកប្រើនីមួយៗ នៅទំព័រ User។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-09','IT-09','Installation/Setup','Forgot the computer software login password','ខ្ញុំភ្លេចពាក្យសម្ងាត់ចូលកម្មវិធីលើកុំព្យូទ័រ។ ត្រូវធ្វើម៉េច?','We recommend creating a new login account after the first login rather than changing the admin password directly. If you have already changed the admin password and forgotten it, please consult your distributor or email service@pluslife.com with your instrument serial number and software version.','យើងណែនាំឱ្យបង្កើតគណនីចូលថ្មី ក្រោយការចូលលើកដំបូង ជាជាងប្តូរពាក្យសម្ងាត់ admin ផ្ទាល់។ បើអ្នកបានប្តូរពាក្យសម្ងាត់ admin ហើយភ្លេច សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅអ្នកចែកចាយ (distributor) ឬផ្ញើអ៊ីមែលទៅ service@pluslife.com ដោយភ្ជាប់លេខសម្គាល់ម៉ាស៊ីន (serial number) និងកំណែកម្មវិធី (software version)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-09-Q01','IT-09','Installation/Setup','I forgot the PluslifePad password.','ខ្ញុំភ្លេចពាក្យសម្ងាត់ PluslifePad។ ត្រូវធ្វើម៉េច?','We recommend creating a new login account after the first login rather than changing the admin password directly. If you have already changed the admin password and forgotten it, please consult your distributor or email service@pluslife.com with your instrument serial number and software version.','យើងណែនាំឱ្យបង្កើតគណនីចូលថ្មី ក្រោយការចូលលើកដំបូង ជាជាងប្តូរពាក្យសម្ងាត់ admin ផ្ទាល់។ បើអ្នកបានប្តូរពាក្យសម្ងាត់ admin ហើយភ្លេច សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅអ្នកចែកចាយ (distributor) ឬផ្ញើអ៊ីមែលទៅ service@pluslife.com ដោយភ្ជាប់លេខសម្គាល់ម៉ាស៊ីន (serial number) និងកំណែកម្មវិធី (software version)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-09-Q02','IT-09','Installation/Setup','forgot admin password','ភ្លេចពាក្យសម្ងាត់ admin','Please consult your distributor or email service@pluslife.com with your instrument serial number and software version.','សូមទាក់ទងអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅអ្នកចែកចាយ (distributor) ឬផ្ញើអ៊ីមែលទៅ service@pluslife.com ដោយភ្ជាប់លេខសម្គាល់ម៉ាស៊ីន (serial number) និងកំណែកម្មវិធី (software version)។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-09-Q03','IT-09','Installation/Setup','What info do I send to reset the password?','តើខ្ញុំត្រូវផ្ញើព័ត៌មានអ្វីខ្លះ ដើម្បីកំណត់ពាក្យសម្ងាត់ឡើងវិញ?','Your instrument serial number and software version, to your distributor or service@pluslife.com.','លេខសម្គាល់ម៉ាស៊ីន (serial number) និងកំណែកម្មវិធី (software version) របស់អ្នក ទៅអ្នកចែកចាយ (distributor) តាមរយៈអ្នកសម្របសម្រួលគម្រោង (study focal point) ឬទៅ service@pluslife.com។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-09-Q04','IT-09','Installation/Setup','Should I change the admin password?','តើខ្ញុំគួរប្តូរពាក្យសម្ងាត់ admin ទេ?','No, it is better not to. We recommend creating a new login account after the first login rather than changing the admin password directly.','ទេ គួរកុំប្តូរ។ យើងណែនាំឱ្យបង្កើតគណនីចូលថ្មី ក្រោយការចូលលើកដំបូង ជាជាងប្តូរពាក្យសម្ងាត់ admin ផ្ទាល់។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-10','IT-10','Installation/Setup','Computer cannot update the software automatically','កម្មវិធីលើកុំព្យូទ័រអាប់ដេតដោយស្វ័យប្រវត្តិមិនបាន។ ត្រូវធ្វើម៉េច?','1. Confirm that your installed software version is SV4.1.0 or later.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-10-Q01','IT-10','Installation/Setup','The software won''t update automatically.','កម្មវិធីមិនធ្វើបច្ចុប្បន្នភាពដោយស្វ័យប្រវត្តិ។ ត្រូវធ្វើម៉េច?','1. Confirm that your installed software version is SV4.1.0 or later.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-10-Q02','IT-10','Installation/Setup','update fail','ធ្វើបច្ចុប្បន្នភាពមិនបាន។ ត្រូវធ្វើម៉េច?','1. Confirm that your installed software version is SV4.1.0 or later.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-10-Q03','IT-10','Installation/Setup','Does auto-update need internet?','តើការធ្វើបច្ចុប្បន្នភាពដោយស្វ័យប្រវត្តិ ត្រូវការអ៊ីនធឺណិតទេ?','Yes. Automatic updates require an internet connection; make sure your computer is online.','បាទ/ចាស។ ការធ្វើបច្ចុប្បន្នភាពដោយស្វ័យប្រវត្តិ ត្រូវការអ៊ីនធឺណិត ដូច្នេះត្រូវធ្វើឱ្យប្រាកដថាកុំព្យូទ័រភ្ជាប់អ៊ីនធឺណិត។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-10-Q04','IT-10','Installation/Setup','Which software version supports automatic update?','តើកំណែកម្មវិធីណា គាំទ្រការធ្វើបច្ចុប្បន្នភាពដោយស្វ័យប្រវត្តិ?','SV4.1.0 or later.','SV4.1.0 ឬថ្មីជាងនេះ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-10-Q05','IT-10','Installation/Setup','Could antivirus block the update?','តើកម្មវិធីកម្ចាត់មេរោគ (antivirus) អាចរារាំងការធ្វើបច្ចុប្បន្នភាពទេ?','Yes. The update may be blocked by antivirus software; please disable it while downloading and installing.','បាទ/ចាស។ ការធ្វើបច្ចុប្បន្នភាពអាចត្រូវបានរារាំងដោយកម្មវិធីកម្ចាត់មេរោគ (antivirus) សូមបិទវាពេលកំពុងទាញយក និងដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-11','IT-11','Installation/Setup','Driver skipped during installation; instrument not detected','ខ្ញុំរំលងការដំឡើង Driver ហើយឥឡូវកម្មវិធីរកម៉ាស៊ីនមិនឃើញ។ ត្រូវធ្វើម៉េច?','Right-click the software icon, choose "Open file location", find the "CH341SER" folder, open it, and double-click the application with the same name to install.','ចុចកណ្តុរខាងស្តាំលើរូបកម្មវិធី ជ្រើសរើស "Open file location" រកថត "CH341SER" បើកវា ហើយចុចពីរដងលើកម្មវិធីដែលមានឈ្មោះដូចគ្នា ដើម្បីដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-11-Q01','IT-11','Installation/Setup','I skipped the driver when installing and now the device isn''t detected.','ខ្ញុំបានរំលងកម្មវិធីបញ្ជា (driver) ពេលដំឡើង ហើយឥឡូវកុំព្យូទ័ររកមិនឃើញម៉ាស៊ីន។ ត្រូវធ្វើម៉េច?','Right-click the software icon, choose "Open file location", find the "CH341SER" folder, open it, and double-click the application with the same name to install.','ចុចកណ្តុរខាងស្តាំលើរូបកម្មវិធី ជ្រើសរើស "Open file location" រកថត "CH341SER" បើកវា ហើយចុចពីរដងលើកម្មវិធីដែលមានឈ្មោះដូចគ្នា ដើម្បីដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-11-Q02','IT-11','Installation/Setup','how reinstall driver','ដំឡើងកម្មវិធីបញ្ជា (driver) ម្តងទៀត យ៉ាងម៉េច?','Right-click the software icon, choose "Open file location", find the "CH341SER" folder, open it, and double-click the application with the same name to install.','ចុចកណ្តុរខាងស្តាំលើរូបកម្មវិធី ជ្រើសរើស "Open file location" រកថត "CH341SER" បើកវា ហើយចុចពីរដងលើកម្មវិធីដែលមានឈ្មោះដូចគ្នា ដើម្បីដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-11-Q03','IT-11','Installation/Setup','Where is the driver file?','តើឯកសារកម្មវិធីបញ្ជា (driver) នៅឯណា?','Right-click the software icon, choose "Open file location", and find the "CH341SER" folder.','ចុចកណ្តុរខាងស្តាំលើរូបកម្មវិធី ជ្រើសរើស "Open file location" ហើយរកថត "CH341SER"។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-11-Q04','IT-11','Installation/Setup','Do I need to reinstall the whole software to get the driver?','តើខ្ញុំត្រូវដំឡើងកម្មវិធីទាំងមូលម្តងទៀត ដើម្បីបានកម្មវិធីបញ្ជាទេ?','No. Right-click the software icon, choose "Open file location", find the "CH341SER" folder, open it, and double-click the application with the same name to install.','ទេ។ ចុចកណ្តុរខាងស្តាំលើរូបកម្មវិធី ជ្រើសរើស "Open file location" រកថត "CH341SER" បើកវា ហើយចុចពីរដងលើកម្មវិធីដែលមានឈ្មោះដូចគ្នា ដើម្បីដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-12','IT-12','Installation/Setup','Worker asks whether the MiniDock Ultra needs software installed','ប្រើ MiniDock Ultra ត្រូវដំឡើងកម្មវិធីលើកុំព្យូទ័រទេ?','The instrument itself does not require software installation, but we recommend installing the app ''Pluslife'' on your mobile phone or the "PluslifePad" software on your computer to control the instrument and manage the results. MiniDock Ultra may require a firmware update after setup.','ម៉ាស៊ីនខ្លួនឯងមិនត្រូវការដំឡើងកម្មវិធីទេ ប៉ុន្តែយើងណែនាំឱ្យដំឡើង App ''Pluslife'' លើទូរស័ព្ទ ឬកម្មវិធី "PluslifePad" លើកុំព្យូទ័រ ដើម្បីបញ្ជាម៉ាស៊ីន និងគ្រប់គ្រងលទ្ធផល។ MiniDock Ultra អាចត្រូវធ្វើបច្ចុប្បន្នភាព Firmware ក្រោយការដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-12-Q01','IT-12','Installation/Setup','Does the MiniDock Ultra need software installed?','តើ MiniDock Ultra ត្រូវដំឡើងកម្មវិធីទេ?','No, the instrument itself does not require software installation. We recommend installing the ''Pluslife'' app on your phone or "PluslifePad" on your computer to control the instrument and manage the results.','ទេ ម៉ាស៊ីនខ្លួនឯងមិនត្រូវការដំឡើងកម្មវិធីទេ។ យើងណែនាំឱ្យដំឡើង App ''Pluslife'' លើទូរស័ព្ទ ឬ "PluslifePad" លើកុំព្យូទ័រ ដើម្បីបញ្ជាម៉ាស៊ីន និងគ្រប់គ្រងលទ្ធផល។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-12-Q02','IT-12','Installation/Setup','Do I have to install anything on the device?','តើខ្ញុំត្រូវដំឡើងអ្វីលើម៉ាស៊ីនទេ?','No. The instrument itself does not require software installation. MiniDock Ultra may require a firmware update after setup.','ទេ។ ម៉ាស៊ីនខ្លួនឯងមិនត្រូវការដំឡើងកម្មវិធីទេ។ MiniDock Ultra អាចត្រូវធ្វើបច្ចុប្បន្នភាព Firmware ក្រោយការដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-12-Q03','IT-12','Installation/Setup','which app to install','ដំឡើង កម្មវិធី មួយណា','The app ''Pluslife'' on your mobile phone or the "PluslifePad" software on your computer.','App ''Pluslife'' លើទូរស័ព្ទ ឬកម្មវិធី "PluslifePad" លើកុំព្យូទ័រ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-12-Q04','IT-12','Installation/Setup','Does the Ultra need a firmware update after setup?','តើ Ultra ត្រូវធ្វើបច្ចុប្បន្នភាព Firmware ក្រោយការដំឡើងទេ?','Not sure — it may. MiniDock Ultra may require a firmware update after setup.','មិនប្រាកដទេ — វាអាចត្រូវការ។ MiniDock Ultra អាចត្រូវធ្វើបច្ចុប្បន្នភាព Firmware ក្រោយការដំឡើង។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-13','IT-13','Installation/Setup','Language doesn''t change after switching it in the software','ខ្ញុំប្តូរភាសាក្នុងកម្មវិធីហើយ តែភាសានៅដដែល។ ត្រូវធ្វើម៉េច?','After changing the language, restart the computer software for the new setting to take effect. There is no need to restart the instrument or the computer.','ក្រោយប្តូរភាសា សូមបិទបើកកម្មវិធីកុំព្យូទ័រឡើងវិញ ដើម្បីឱ្យការកំណត់ថ្មីមានប្រសិទ្ធភាព។ មិនចាំបាច់បិទបើកម៉ាស៊ីន ឬកុំព្យូទ័រឡើងវិញទេ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-13-Q01','IT-13','Installation/Setup','I changed the language but nothing changed.','ខ្ញុំបានប្តូរភាសា តែគ្មានអ្វីប្រែប្រួលទេ?','After changing the language, restart the computer software for the new setting to take effect. There is no need to restart the instrument or the computer.','ក្រោយប្តូរភាសា សូមបិទបើកកម្មវិធីកុំព្យូទ័រឡើងវិញ ដើម្បីឱ្យការកំណត់ថ្មីមានប្រសិទ្ធភាព។ មិនចាំបាច់បិទបើកម៉ាស៊ីន ឬកុំព្យូទ័រឡើងវិញទេ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-13-Q02','IT-13','Installation/Setup','Do I need to restart the computer after changing the language?','តើខ្ញុំត្រូវបិទបើកកុំព្យូទ័រឡើងវិញ ក្រោយប្តូរភាសាទេ?','No. Just restart the computer software. There is no need to restart the instrument or the computer.','ទេ។ គ្រាន់តែបិទបើកកម្មវិធីកុំព្យូទ័រឡើងវិញ។ មិនចាំបាច់បិទបើកម៉ាស៊ីន ឬកុំព្យូទ័រឡើងវិញទេ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-13-Q03','IT-13','Installation/Setup','language not change','ភាសាមិនប្តូរ','After changing the language, restart the computer software for the new setting to take effect. There is no need to restart the instrument or the computer.','ក្រោយប្តូរភាសា សូមបិទបើកកម្មវិធីកុំព្យូទ័រឡើងវិញ ដើម្បីឱ្យការកំណត់ថ្មីមានប្រសិទ្ធភាព។ មិនចាំបាច់បិទបើកម៉ាស៊ីន ឬកុំព្យូទ័រឡើងវិញទេ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-14','IT-14','Installation/Setup','Worker asks whether PluslifePad runs on a tablet','អាចប្រើ PluslifePad លើថេប្លេតបានទេ?','The software is compatible with Windows 10 and Windows 11; any device running these Windows systems can use it normally. Support for Android and iOS is under development.','កម្មវិធីនេះដំណើរការជាមួយ Windows 10 និង Windows 11។ ឧបករណ៍ណាដែលប្រើប្រព័ន្ធ Windows ទាំងនេះ អាចប្រើវាបានធម្មតា។ ការគាំទ្រ Android និង iOS កំពុងអភិវឌ្ឍ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-14-Q01','IT-14','Installation/Setup','Can PluslifePad run on a tablet?','តើ PluslifePad អាចដំណើរការលើថេប្លេតបានទេ?','Yes, if the tablet runs Windows 10 or Windows 11. Support for Android and iOS is under development.','បាទ/ចាស បើថេប្លេតប្រើ Windows 10 ឬ Windows 11។ ការគាំទ្រ Android និង iOS កំពុងអភិវឌ្ឍ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-14-Q02','IT-14','Installation/Setup','Does the software work on Windows 11?','តើកម្មវិធីដំណើរការលើ Windows 11 ទេ?','Yes. The software is compatible with Windows 10 and Windows 11.','បាទ/ចាស។ កម្មវិធីនេះដំណើរការជាមួយ Windows 10 និង Windows 11។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-14-Q03','IT-14','Installation/Setup','PluslifePad on iPad?','PluslifePad លើ iPad?','No, not yet. Support for Android and iOS is under development.','មិនទាន់បានទេ។ ការគាំទ្រ Android និង iOS កំពុងអភិវឌ្ឍ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-14-Q04','IT-14','Installation/Setup','What Windows version do I need?','តើខ្ញុំត្រូវការ Windows កំណែណា?','The software is compatible with Windows 10 and Windows 11; any device running these Windows systems can use it normally. Support for Android and iOS is under development.','កម្មវិធីនេះដំណើរការជាមួយ Windows 10 និង Windows 11។ ឧបករណ៍ណាដែលប្រើប្រព័ន្ធ Windows ទាំងនេះ អាចប្រើវាបានធម្មតា។ ការគាំទ្រ Android និង iOS កំពុងអភិវឌ្ឍ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-15','IT-15','Installation/Setup','No desktop shortcut after clicking Install','ចុច «Install» ហើយ តែរករូបតំណាងកម្មវិធីលើ Desktop មិនឃើញ។ ត្រូវធ្វើម៉េច?','1. Close the antivirus software.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-15-Q01','IT-15','Installation/Setup','I installed the software but there''s no icon on the desktop.','ខ្ញុំបានដំឡើងកម្មវិធី តែគ្មានរូបតំណាងលើផ្ទៃ desktop ទេ?','1. Close the antivirus software.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-15-Q02','IT-15','Installation/Setup','no shortcut','គ្មានរូបតំណាង (shortcut)','1. Close the antivirus software.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-15-Q03','IT-15','Installation/Setup','Do I need to reinstall to get the shortcut?','តើខ្ញុំត្រូវដំឡើងម្តងទៀត ដើម្បីបានរូបតំណាង (shortcut) ទេ?','Yes. Close the antivirus software, then reinstall and tick "Create a desktop shortcut".','បាទ/ចាស។ បិទកម្មវិធីកម្ចាត់មេរោគ (antivirus) រួចដំឡើងម្តងទៀត ហើយធីក "Create a desktop shortcut"។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-16','IT-16','Installation/Setup','Logo image rejected when editing institution information','ខ្ញុំកែព័ត៌មានស្ថាប័ន តែកម្មវិធីមិនទទួលរូបឡូហ្គោ។ ត្រូវធ្វើម៉េច?','The image must be in PNG format.','រូបភាពត្រូវតែជាទម្រង់ PNG។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-16-Q01','IT-16','Installation/Setup','What format should the logo be?','តើរូបនិមិត្តសញ្ញា (logo) គួរជាទម្រង់អ្វី?','The image must be in PNG format.','រូបភាពត្រូវតែជាទម្រង់ PNG។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-16-Q02','IT-16','Installation/Setup','Can I upload a JPG logo?','អាចផ្ទុករូបនិមិត្តសញ្ញា (logo) ទម្រង់ JPG បានទេ?','No. The image must be in PNG format.','មិនបានទេ។ រូបភាពត្រូវតែជាទម្រង់ PNG។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-16-Q03','IT-16','Installation/Setup','logo not upload','ផ្ទុករូបនិមិត្តសញ្ញា (logo) មិនបាន។ ត្រូវធ្វើម៉េច?','Check the format: the image must be in PNG format.','ពិនិត្យទម្រង់៖ រូបភាពត្រូវតែជាទម្រង់ PNG។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-17','IT-17','Installation/Setup','Worker wants to update the mobile app','ត្រូវអាប់ដេតកម្មវិធី Pluslife លើទូរស័ព្ទដោយរបៀបណា?','Uninstalling the app will result in the loss of result data, which cannot be recovered. When upgrading the app, do not uninstall the original version first; instead, directly update and install the new version so historical data is not deleted.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-17-Q01','IT-17','Installation/Setup','How do I update the Pluslife app?','តើខ្ញុំធ្វើបច្ចុប្បន្នភាព កម្មវិធី Pluslife យ៉ាងម៉េច?','Uninstalling the app will result in the loss of result data, which cannot be recovered. When upgrading the app, do not uninstall the original version first; instead, directly update and install the new version so historical data is not deleted.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-17-Q02','IT-17','Installation/Setup','Can I uninstall and reinstall the app to update it?','អាចលុប ហើយដំឡើង កម្មវិធី ម្តងទៀត ដើម្បីធ្វើបច្ចុប្បន្នភាពបានទេ?','No. Uninstalling the app will result in the loss of result data, which cannot be recovered. Update directly instead.','មិនបានទេ។ ការលុប (uninstall) App នឹងធ្វើឱ្យបាត់ទិន្នន័យលទ្ធផល ហើយមិនអាចយកមកវិញបានទេ។ សូមធ្វើបច្ចុប្បន្នភាពដោយផ្ទាល់ជំនួសវិញ។','Safety-critical','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-17-Q03','IT-17','Installation/Setup','I installed the app from an APK. How do I update?','ខ្ញុំដំឡើង កម្មវិធី ពីកញ្ចប់ APK។ តើខ្ញុំធ្វើបច្ចុប្បន្នភាពយ៉ាងម៉េច?','Update it in the app, under the "Profile" section.','ធ្វើបច្ចុប្បន្នភាពក្នុង App នៅផ្នែក "Profile"។','Safety-critical','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-17-Q04','IT-17','Installation/Setup','app update','ធ្វើបច្ចុប្បន្នភាព កម្មវិធី','Uninstalling the app will result in the loss of result data, which cannot be recovered. When upgrading the app, do not uninstall the original version first; instead, directly update and install the new version so historical data is not deleted.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-17-Q05','IT-17','Installation/Setup','Will I lose my results when I update the app?','តើខ្ញុំនឹងបាត់លទ្ធផល ពេលធ្វើបច្ចុប្បន្នភាព កម្មវិធី ទេ?','No, as long as you do not uninstall the original version first. Directly update and install the new version.','ទេ ដរាបណាអ្នកមិនលុប (uninstall) កំណែចាស់ចេញមុន។ សូមធ្វើបច្ចុប្បន្នភាព និងដំឡើងកំណែថ្មីដោយផ្ទាល់។','Safety-critical','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-18','IT-18','Installation/Setup','Forgot the mobile app login password','ខ្ញុំភ្លេចពាក្យសម្ងាត់ចូលកម្មវិធីលើទូរស័ព្ទ។ ត្រូវធ្វើម៉េច?','After re-registering, history saved on this device will be kept as long as the app has not been uninstalled.','ក្រោយចុះឈ្មោះឡើងវិញ ប្រវត្តិដែលរក្សាទុកលើឧបករណ៍នេះ នឹងនៅដដែល ដរាបណា App មិនត្រូវបានលុប (uninstall)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-18-Q01','IT-18','Installation/Setup','I forgot my app password. If I register again, will I lose history?','ខ្ញុំភ្លេចពាក្យសម្ងាត់ App។ បើខ្ញុំចុះឈ្មោះម្តងទៀត តើខ្ញុំនឹងបាត់ប្រវត្តិទេ?','No. After re-registering, history saved on this device will be kept as long as the app has not been uninstalled.','ទេ។ ក្រោយចុះឈ្មោះឡើងវិញ ប្រវត្តិដែលរក្សាទុកលើឧបករណ៍នេះ នឹងនៅដដែល ដរាបណា App មិនត្រូវបានលុប (uninstall)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-18-Q02','IT-18','Installation/Setup','forgot app login','ភ្លេចការចូល កម្មវិធី','You can re-register. After re-registering, history saved on this device will be kept as long as the app has not been uninstalled.','អ្នកអាចចុះឈ្មោះឡើងវិញបាន។ ក្រោយចុះឈ្មោះឡើងវិញ ប្រវត្តិដែលរក្សាទុកលើឧបករណ៍នេះ នឹងនៅដដែល ដរាបណា App មិនត្រូវបានលុប (uninstall)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-18-Q03','IT-18','Installation/Setup','Will my results still be there after I make a new account?','តើលទ្ធផលរបស់ខ្ញុំនៅដដែលទេ ក្រោយបង្កើតគណនីថ្មី?','Yes, as long as the app has not been uninstalled.','បាទ/ចាស ដរាបណា App មិនត្រូវបានលុប (uninstall)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-19','IT-19','Installation/Setup','Account registration rejected','កម្មវិធីមិនទទួលការចុះឈ្មោះគណនី។ ត្រូវធ្វើម៉េច?','For username, there is no requirement, but "admin" cannot be used. Passwords must consist of a combination of letters, numbers and special characters (case-sensitive) and be at least 6 characters long.','សម្រាប់ឈ្មោះអ្នកប្រើ គ្មានលក្ខខណ្ឌទេ ប៉ុន្តែមិនអាចប្រើ "admin" បានទេ។ ពាក្យសម្ងាត់ត្រូវតែផ្សំពីអក្សរ លេខ និងតួអក្សរពិសេស (ប្រកាន់អក្សរធំ/តូច) ហើយមានយ៉ាងតិច 6 តួអក្សរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-19-Q01','IT-19','Installation/Setup','What are the rules for username and password?','តើមានច្បាប់អ្វីខ្លះ សម្រាប់ឈ្មោះអ្នកប្រើ និងពាក្យសម្ងាត់?','For username, there is no requirement, but "admin" cannot be used. Passwords must consist of a combination of letters, numbers and special characters (case-sensitive) and be at least 6 characters long.','សម្រាប់ឈ្មោះអ្នកប្រើ គ្មានលក្ខខណ្ឌទេ ប៉ុន្តែមិនអាចប្រើ "admin" បានទេ។ ពាក្យសម្ងាត់ត្រូវតែផ្សំពីអក្សរ លេខ និងតួអក្សរពិសេស (ប្រកាន់អក្សរធំ/តូច) ហើយមានយ៉ាងតិច 6 តួអក្សរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-19-Q02','IT-19','Installation/Setup','Can I use admin as my username?','អាចប្រើ admin ជាឈ្មោះអ្នកប្រើបានទេ?','No. "admin" cannot be used as a username.','មិនបានទេ។ មិនអាចប្រើ "admin" ជាឈ្មោះអ្នកប្រើបានទេ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-19-Q03','IT-19','Installation/Setup','password not accept','ពាក្យសម្ងាត់មិនទទួលយក','Passwords must consist of a combination of letters, numbers and special characters (case-sensitive) and be at least 6 characters long.','ពាក្យសម្ងាត់ត្រូវតែផ្សំពីអក្សរ លេខ និងតួអក្សរពិសេស (ប្រកាន់អក្សរធំ/តូច) ហើយមានយ៉ាងតិច 6 តួអក្សរ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-19-Q04','IT-19','Installation/Setup','Is the password case-sensitive?','តើពាក្យសម្ងាត់ប្រកាន់អក្សរធំ/តូចទេ?','Yes.','បាទ/ចាស។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-20','IT-20','Installation/Setup','Mobile app crashed / shut down unexpectedly','កម្មវិធីលើទូរស័ព្ទស្រាប់តែបិទដោយខ្លួនឯង។ ត្រូវធ្វើម៉េច?','Please try reopening the app. If you need help, export the log file and report it to Pluslife''s service provider:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-20-Q01','IT-20','Installation/Setup','The app keeps crashing.','កម្មវិធី គាំងជាញឹកញាប់។ ត្រូវធ្វើម៉េច?','Please try reopening the app. If you need help, export the log file and report it to Pluslife''s service provider:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-20-Q02','IT-20','Installation/Setup','app close by itself','កម្មវិធី បិទដោយខ្លួនឯង','Please try reopening the app. If you need help, export the log file and report it to Pluslife''s service provider:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-20-Q03','IT-20','Installation/Setup','How do I export the app log?','តើខ្ញុំនាំចេញកំណត់ហេតុ (log) របស់ កម្មវិធី យ៉ាងម៉េច?','1. Tap the Profile screen 2. Quickly tap "Current Version" 5 times 3. Enter the password "exportlog@1".','1. ចុចលើអេក្រង់ Profile 2. ចុច "Current Version" លឿនៗ 5 ដង 3. បញ្ចូលពាក្យសម្ងាត់ "exportlog@1"។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('IT-20-Q04','IT-20','Installation/Setup','Should I uninstall the app if it crashes?','តើខ្ញុំគួរលុប កម្មវិធី ទេ បើវាគាំង?','No. Do not uninstall the app. Try reopening it, and export the log file to report it to Pluslife''s service provider.','ទេ។ កុំលុប (uninstall) App។ សូមសាកល្បងបើកវាម្តងទៀត ហើយនាំចេញឯកសារកំណត់ហេតុ (log file) ដើម្បីរាយការណ៍ទៅអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅអ្នកផ្តល់សេវារបស់ Pluslife។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-03','DM-03','Data & Device Management','Worker asks whether the device stores results and how many','ម៉ាស៊ីនរក្សាទុកលទ្ធផលបានទេ? អាចទុកបានប៉ុន្មានលទ្ធផល?','MiniDock Ultra (PM001 Ultra) stores historical results within the instrument itself, with a capacity of up to 6,000 entries. When the instrument is connected to the computer software, it syncs the stored data to the software. The data within the instrument can be cleared using the computer software.','MiniDock Ultra (PM001 Ultra) រក្សាទុកលទ្ធផលចាស់ៗនៅក្នុងម៉ាស៊ីនផ្ទាល់ ដោយមានសមត្ថភាពរហូតដល់ 6,000 លទ្ធផល។ ពេលម៉ាស៊ីនភ្ជាប់ជាមួយកម្មវិធីកុំព្យូទ័រ វាធ្វើសមកាលកម្ម (sync) ទិន្នន័យដែលរក្សាទុកទៅកម្មវិធី។ ទិន្នន័យក្នុងម៉ាស៊ីនអាចលុបបាន ដោយប្រើកម្មវិធីកុំព្យូទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-03-Q01','DM-03','Data & Device Management','Can the device store results?','តើម៉ាស៊ីនអាចរក្សាទុកលទ្ធផលបានទេ?','Yes. MiniDock Ultra stores historical results within the instrument itself, up to 6,000 entries.','បាទ/ចាស។ MiniDock Ultra រក្សាទុកលទ្ធផលចាស់ៗនៅក្នុងម៉ាស៊ីនផ្ទាល់ រហូតដល់ 6,000 លទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-03-Q02','DM-03','Data & Device Management','how many result device can save','ម៉ាស៊ីនអាចរក្សាទុកលទ្ធផលបានប៉ុន្មាន?','Up to 6,000 entries.','រហូតដល់ 6,000 លទ្ធផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-03-Q03','DM-03','Data & Device Management','Will results on the device go to the computer?','តើលទ្ធផលលើម៉ាស៊ីន នឹងទៅកុំព្យូទ័រទេ?','Yes. When the instrument is connected to the computer software, it syncs the stored data to the software.','បាទ/ចាស។ ពេលម៉ាស៊ីនភ្ជាប់ជាមួយកម្មវិធីកុំព្យូទ័រ វាធ្វើសមកាលកម្ម (sync) ទិន្នន័យដែលរក្សាទុកទៅកម្មវិធី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-03-Q04','DM-03','Data & Device Management','How do I clear the data on the device?','តើខ្ញុំលុបទិន្នន័យលើម៉ាស៊ីនយ៉ាងម៉េច?','The data within the instrument can be cleared using the computer software.','ទិន្នន័យក្នុងម៉ាស៊ីនអាចលុបបាន ដោយប្រើកម្មវិធីកុំព្យូទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-03-Q05','DM-03','Data & Device Management','I tested without the laptop. Are the results saved?','ខ្ញុំធ្វើតេស្តដោយគ្មានកុំព្យូទ័រយួរដៃ។ តើលទ្ធផលត្រូវបានរក្សាទុកទេ?','Yes. MiniDock Ultra stores historical results within the instrument (up to 6,000 entries) and syncs them when connected to the computer software.','បាទ/ចាស។ MiniDock Ultra រក្សាទុកលទ្ធផលចាស់ៗនៅក្នុងម៉ាស៊ីន (រហូតដល់ 6,000 លទ្ធផល) ហើយធ្វើសមកាលកម្ម (sync) ពេលភ្ជាប់ជាមួយកម្មវិធីកុំព្យូទ័រ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-04','DM-04','Data & Device Management','Worker wants to export results','ត្រូវទាញយកលទ្ធផលពីកម្មវិធីដោយរបៀបណា?','Pluslife''s software and app offer two ways to export data:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-04-Q01','DM-04','Data & Device Management','How do I export results?','តើខ្ញុំនាំចេញ (export) លទ្ធផលយ៉ាងម៉េច?','Pluslife''s software and app offer two ways to export data:
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-04-Q02','DM-04','Data & Device Management','How do I get a PDF report for one patient?','តើខ្ញុំបានរបាយការណ៍ PDF សម្រាប់អ្នកជំងឺម្នាក់យ៉ាងម៉េច?','On the History screen, select the result and tap the Share button to generate a PDF report, which you can save or share.','នៅអេក្រង់ History ជ្រើសរើសលទ្ធផល ហើយចុចប៊ូតុង Share ដើម្បីបង្កើតរបាយការណ៍ PDF ដែលអ្នកអាចរក្សាទុក ឬចែករំលែកបាន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-04-Q03','DM-04','Data & Device Management','export to excel / csv','នាំចេញទៅ Excel / CSV','On the History screen, long-press to select one or more results, then tap the CSV icon to generate a list in CSV format.','នៅអេក្រង់ History ចុចឱ្យជាប់ ដើម្បីជ្រើសរើសលទ្ធផលមួយ ឬច្រើន រួចចុចរូប CSV ដើម្បីបង្កើតបញ្ជីជាទម្រង់ CSV។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-04-Q04','DM-04','Data & Device Management','Can I export many results at once?','អាចនាំចេញលទ្ធផលច្រើនក្នុងពេលតែមួយបានទេ?','Yes. On the History screen, long-press to select one or more results, then tap the CSV icon.','បាទ/ចាស។ នៅអេក្រង់ History ចុចឱ្យជាប់ ដើម្បីជ្រើសរើសលទ្ធផលមួយ ឬច្រើន រួចចុចរូប CSV។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-05','DM-05','Data & Device Management','Worker wants to delete results','ត្រូវលុបលទ្ធផលក្នុងកម្មវិធីដោយរបៀបណា?','Results saved in the computer software and mobile app cannot be deleted individually; all results can only be deleted by deleting the database or uninstalling the app. Results stored in the MiniDock Ultra can be cleared after connecting it to the computer software by cable.','លទ្ធផលដែលរក្សាទុកក្នុងកម្មវិធីកុំព្យូទ័រ និង App ទូរស័ព្ទ មិនអាចលុបម្តងមួយៗបានទេ។ លទ្ធផលទាំងអស់អាចលុបបានតែតាមរយៈការលុបមូលដ្ឋានទិន្នន័យ (database) ឬការលុប (uninstall) App ប៉ុណ្ណោះ។ លទ្ធផលដែលរក្សាទុកក្នុង MiniDock Ultra អាចលុបបាន ក្រោយភ្ជាប់វាទៅកម្មវិធីកុំព្យូទ័រតាមខ្សែ។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-05-Q01','DM-05','Data & Device Management','How do I delete results?','តើខ្ញុំលុបលទ្ធផលយ៉ាងម៉េច?','Results saved in the computer software and mobile app cannot be deleted individually; all results can only be deleted by deleting the database or uninstalling the app. Results stored in the MiniDock Ultra can be cleared after connecting it to the computer software by cable.','លទ្ធផលដែលរក្សាទុកក្នុងកម្មវិធីកុំព្យូទ័រ និង App ទូរស័ព្ទ មិនអាចលុបម្តងមួយៗបានទេ។ លទ្ធផលទាំងអស់អាចលុបបានតែតាមរយៈការលុបមូលដ្ឋានទិន្នន័យ (database) ឬការលុប (uninstall) App ប៉ុណ្ណោះ។ លទ្ធផលដែលរក្សាទុកក្នុង MiniDock Ultra អាចលុបបាន ក្រោយភ្ជាប់វាទៅកម្មវិធីកុំព្យូទ័រតាមខ្សែ។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-05-Q02','DM-05','Data & Device Management','Can I delete one wrong result?','អាចលុបលទ្ធផលខុសមួយបានទេ?','No. Results saved in the computer software and mobile app cannot be deleted individually.','មិនបានទេ។ លទ្ធផលដែលរក្សាទុកក្នុងកម្មវិធីកុំព្យូទ័រ និង App ទូរស័ព្ទ មិនអាចលុបម្តងមួយៗបានទេ។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-05-Q03','DM-05','Data & Device Management','How do I clear the results stored in the Ultra?','តើខ្ញុំលុបលទ្ធផលដែលរក្សាទុកក្នុង Ultra យ៉ាងម៉េច?','Connect it to the computer software by cable; then the results stored in the MiniDock Ultra can be cleared.','ភ្ជាប់វាទៅកម្មវិធីកុំព្យូទ័រតាមខ្សែ បន្ទាប់មកលទ្ធផលដែលរក្សាទុកក្នុង MiniDock Ultra អាចលុបបាន។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-05-Q04','DM-05','Data & Device Management','delete history','លុបប្រវត្តិ','Results saved in the computer software and mobile app cannot be deleted individually; all results can only be deleted by deleting the database or uninstalling the app. Results stored in the MiniDock Ultra can be cleared after connecting it to the computer software by cable.','លទ្ធផលដែលរក្សាទុកក្នុងកម្មវិធីកុំព្យូទ័រ និង App ទូរស័ព្ទ មិនអាចលុបម្តងមួយៗបានទេ។ លទ្ធផលទាំងអស់អាចលុបបានតែតាមរយៈការលុបមូលដ្ឋានទិន្នន័យ (database) ឬការលុប (uninstall) App ប៉ុណ្ណោះ។ លទ្ធផលដែលរក្សាទុកក្នុង MiniDock Ultra អាចលុបបាន ក្រោយភ្ជាប់វាទៅកម្មវិធីកុំព្យូទ័រតាមខ្សែ។','Routine','Supervisor');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-06','DM-06','Data & Device Management','Only some results shown in History, or results seem missing','បើក «History» ហើយឃើញតែលទ្ធផលខ្លះៗ។ តើត្រូវរកលទ្ធផលដែលបាត់ដោយរបៀបណា?','Please set the start date of the filter to an earlier date to see the results under History.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-06-Q01','DM-06','Data & Device Management','Only some test results show in History.','History បង្ហាញតែលទ្ធផលតេស្តខ្លះប៉ុណ្ណោះ។ ត្រូវធ្វើម៉េច?','Please set the start date of the filter to an earlier date to see the results under History.','សូមកំណត់កាលបរិច្ឆេទចាប់ផ្តើមនៃតម្រង (filter) ឱ្យទៅមុនជាងនេះ ដើម្បីមើលលទ្ធផលនៅក្នុង History។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-06-Q02','DM-06','Data & Device Management','My old results are missing.','លទ្ធផលចាស់ៗរបស់ខ្ញុំបាត់។ ត្រូវធ្វើម៉េច?','If the app was not uninstalled, set the start date of the filter to an earlier date to see the results under History.','បើ App មិនត្រូវបានលុប (uninstall) សូមកំណត់កាលបរិច្ឆេទចាប់ផ្តើមនៃតម្រង (filter) ឱ្យទៅមុនជាងនេះ ដើម្បីមើលលទ្ធផលនៅក្នុង History។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-06-Q03','DM-06','Data & Device Management','result on phone gone','លទ្ធផលលើទូរស័ព្ទបាត់','Uninstalling the app will result in the loss of result data, which cannot be recovered. If the app was not uninstalled, set the start date of the filter to an earlier date.','ការលុប (uninstall) App នឹងធ្វើឱ្យបាត់ទិន្នន័យលទ្ធផល ហើយមិនអាចយកមកវិញបានទេ។ បើ App មិនត្រូវបានលុបទេ សូមកំណត់កាលបរិច្ឆេទចាប់ផ្តើមនៃតម្រង (filter) ឱ្យទៅមុនជាងនេះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-06-Q04','DM-06','Data & Device Management','I reinstalled the app. Can I get my results back?','ខ្ញុំបានដំឡើង កម្មវិធី ម្តងទៀត។ អាចយកលទ្ធផលមកវិញបានទេ?','No. Uninstalling the app will result in the loss of result data, which cannot be recovered.','មិនបានទេ។ ការលុប (uninstall) App នឹងធ្វើឱ្យបាត់ទិន្នន័យលទ្ធផល ហើយមិនអាចយកមកវិញបានទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-06-Q05','DM-06','Data & Device Management','Where are last week''s results?','តើលទ្ធផលសប្តាហ៍មុននៅឯណា?','Please set the start date of the filter to an earlier date to see the results under History.','សូមកំណត់កាលបរិច្ឆេទចាប់ផ្តើមនៃតម្រង (filter) ឱ្យទៅមុនជាងនេះ ដើម្បីមើលលទ្ធផលនៅក្នុង History។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-07','DM-07','Data & Device Management','Synced history has results but no patient information','ក្រោយធ្វើសមកាលកម្ម ខ្ញុំឃើញលទ្ធផលក្នុង «History» តែគ្មានព័ត៌មានអ្នកជំងឺ។ ហេតុអ្វី?','To protect patient information, the instrument itself does not store patient information. Therefore, data synced from the instrument contains only test results, not patient information.','ដើម្បីការពារព័ត៌មានអ្នកជំងឺ ម៉ាស៊ីនខ្លួនឯងមិនរក្សាទុកព័ត៌មានអ្នកជំងឺទេ។ ដូច្នេះ ទិន្នន័យដែលធ្វើសមកាលកម្ម (sync) ពីម៉ាស៊ីន មានតែលទ្ធផលតេស្តប៉ុណ្ណោះ គ្មានព័ត៌មានអ្នកជំងឺទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-07-Q01','DM-07','Data & Device Management','Why is there no patient name in the synced results?','ហេតុអ្វីបានជាគ្មានឈ្មោះអ្នកជំងឺ ក្នុងលទ្ធផលដែលធ្វើសមកាលកម្ម?','To protect patient information, the instrument itself does not store patient information. Therefore, data synced from the instrument contains only test results, not patient information.','ដើម្បីការពារព័ត៌មានអ្នកជំងឺ ម៉ាស៊ីនខ្លួនឯងមិនរក្សាទុកព័ត៌មានអ្នកជំងឺទេ។ ដូច្នេះ ទិន្នន័យដែលធ្វើសមកាលកម្ម (sync) ពីម៉ាស៊ីន មានតែលទ្ធផលតេស្តប៉ុណ្ណោះ គ្មានព័ត៌មានអ្នកជំងឺទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-07-Q02','DM-07','Data & Device Management','Does the device store patient information?','តើម៉ាស៊ីនរក្សាទុកព័ត៌មានអ្នកជំងឺទេ?','No. To protect patient information, the instrument itself does not store patient information.','ទេ។ ដើម្បីការពារព័ត៌មានអ្នកជំងឺ ម៉ាស៊ីនខ្លួនឯងមិនរក្សាទុកព័ត៌មានអ្នកជំងឺទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-07-Q03','DM-07','Data & Device Management','sync but no patient info','ធ្វើសមកាលកម្មហើយ តែគ្មានព័ត៌មានអ្នកជំងឺ','To protect patient information, the instrument itself does not store patient information. Therefore, data synced from the instrument contains only test results, not patient information.','ដើម្បីការពារព័ត៌មានអ្នកជំងឺ ម៉ាស៊ីនខ្លួនឯងមិនរក្សាទុកព័ត៌មានអ្នកជំងឺទេ។ ដូច្នេះ ទិន្នន័យដែលធ្វើសមកាលកម្ម (sync) ពីម៉ាស៊ីន មានតែលទ្ធផលតេស្តប៉ុណ្ណោះ គ្មានព័ត៌មានអ្នកជំងឺទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-08','DM-08','Data & Device Management','Worker needs to enter or correct patient/sample information','ត្រូវបញ្ចូល ឬកែព័ត៌មានអ្នកជំងឺ និងសំណាកនៅឯណា?','PC software: During the test or after the result, double-click the test row in the "Test Info List", enter the test information, and click "Modify". With software version 4.3.5 or later, you can also double-click the instrument card to open the information editing dialog. If you forgot to edit the information during the test, you can also double-click the result on the "History" page to edit it. Results whose information has already been edited cannot be modified again.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-08-Q01','DM-08','Data & Device Management','How do I enter patient information in the software?','តើខ្ញុំបញ្ចូលព័ត៌មានអ្នកជំងឺក្នុងកម្មវិធីយ៉ាងម៉េច?','PC software: During the test or after the result, double-click the test row in the "Test Info List", enter the test information, and click "Modify". With software version 4.3.5 or later, you can also double-click the instrument card to open the information editing dialog. If you forgot to edit the information during the test, you can also double-click the result on the "History" page to edit it. Results whose information has already been edited cannot be modified again.','កម្មវិធីកុំព្យូទ័រ៖ ពេលកំពុងធ្វើតេស្ត ឬក្រោយចេញលទ្ធផល ចុចពីរដងលើជួរតេស្តក្នុង "Test Info List" បញ្ចូលព័ត៌មានតេស្ត ហើយចុច "Modify"។ ជាមួយកំណែកម្មវិធី 4.3.5 ឬថ្មីជាងនេះ អ្នកក៏អាចចុចពីរដងលើកាតម៉ាស៊ីន (instrument card) ដើម្បីបើកផ្ទាំងកែព័ត៌មានបានដែរ។ បើភ្លេចកែព័ត៌មានពេលកំពុងធ្វើតេស្ត អ្នកក៏អាចចុចពីរដងលើលទ្ធផលនៅទំព័រ "History" ដើម្បីកែបានដែរ។ លទ្ធផលដែលបានកែព័ត៌មានរួចហើយ មិនអាចកែម្តងទៀតបានទេ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-08-Q02','DM-08','Data & Device Management','How do I add sample info in the app?','តើខ្ញុំបន្ថែមព័ត៌មានសំណាកក្នុង កម្មវិធី យ៉ាងម៉េច?','Before the test starts, tap the edit icon to enter sample information. You can also tap the edit icon while the test is running.','មុនតេស្តចាប់ផ្តើម ចុចរូបកែ (edit) ដើម្បីបញ្ចូលព័ត៌មានសំណាក។ អ្នកក៏អាចចុចរូបកែ ពេលតេស្តកំពុងដំណើរការបានដែរ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-08-Q03','DM-08','Data & Device Management','I typed the wrong name. Can I edit it again?','ខ្ញុំវាយឈ្មោះខុស។ អាចកែវាម្តងទៀតបានទេ?','No, if it was already edited. Patient information for each test record can be edited only once.','មិនបានទេ បើវាត្រូវបានកែរួចហើយ។ ព័ត៌មានអ្នកជំងឺសម្រាប់កំណត់ត្រាតេស្តនីមួយៗ អាចកែបានតែម្តងប៉ុណ្ណោះ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-08-Q04','DM-08','Data & Device Management','I forgot to enter patient info during the test.','ខ្ញុំភ្លេចបញ្ចូលព័ត៌មានអ្នកជំងឺ ពេលកំពុងធ្វើតេស្ត។ ត្រូវធ្វើម៉េច?','If it was never edited during the test, it can still be edited once after the test ends: double-click the result on the "History" page to edit it.','បើមិនដែលកែពេលកំពុងធ្វើតេស្តទេ នៅតែអាចកែបានម្តង ក្រោយតេស្តចប់៖ ចុចពីរដងលើលទ្ធផលនៅទំព័រ "History" ដើម្បីកែ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-08-Q05','DM-08','Data & Device Management','how many times edit patient info','កែព័ត៌មានអ្នកជំងឺបានប៉ុន្មានដង','Patient information for each test record can be edited only once. If it was edited during the test, it cannot be edited again after the test ends; if it was never edited during the test, it can still be edited once after the test ends.','ព័ត៌មានអ្នកជំងឺសម្រាប់កំណត់ត្រាតេស្តនីមួយៗ អាចកែបានតែម្តងប៉ុណ្ណោះ។ បើបានកែពេលកំពុងធ្វើតេស្ត មិនអាចកែម្តងទៀតក្រោយតេស្តចប់បានទេ។ បើមិនដែលកែពេលកំពុងធ្វើតេស្តទេ នៅតែអាចកែបានម្តង ក្រោយតេស្តចប់។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-08-Q06','DM-08','Data & Device Management','Can I edit the info while the test is running?','អាចកែព័ត៌មាន ពេលតេស្តកំពុងដំណើរការបានទេ?','Yes. In the PC software, double-click the test row in the "Test Info List"; in the app, tap the edit icon while the test is running.','បាទ/ចាស។ ក្នុងកម្មវិធីកុំព្យូទ័រ ចុចពីរដងលើជួរតេស្តក្នុង "Test Info List"។ ក្នុង App ចុចរូបកែ (edit) ពេលតេស្តកំពុងដំណើរការ។','Safety-critical','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-09','DM-09','Data & Device Management','Worker asks whether results can be sent to an LIS','អាចផ្ញើលទ្ធផលទៅប្រព័ន្ធព័ត៌មានមន្ទីរពិសោធន៍ (LIS) បានទេ?','Yes, it can connect to an LIS. Pluslife can provide test result data files in TXT format for compatibility, but the user''s LIS engineer needs to help debug the port.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-09-Q01','DM-09','Data & Device Management','Can the device connect to our LIS?','តើម៉ាស៊ីនអាចភ្ជាប់ទៅ LIS របស់យើងបានទេ?','Yes, it can connect to an LIS. Pluslife can provide test result data files in TXT format for compatibility, but the user''s LIS engineer needs to help debug the port.','បាទ/ចាស អាចភ្ជាប់ទៅ LIS បាន។ Pluslife អាចផ្តល់ឯកសារទិន្នន័យលទ្ធផលតេស្តជាទម្រង់ TXT ដើម្បីឱ្យត្រូវគ្នា ប៉ុន្តែវិស្វករ LIS របស់អ្នកប្រើ ត្រូវជួយដោះស្រាយ (debug) រន្ធភ្ជាប់ (port)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-09-Q02','DM-09','Data & Device Management','How do I send Ultra results to the LIS from the software?','តើខ្ញុំផ្ញើលទ្ធផល Ultra ទៅ LIS ពីកម្មវិធីយ៉ាងម៉េច?','1. Configure the IP address and set the communication protocol: https://drive.google.com/file/d/1dWo-4wUoX8El8iNWyn0nyB2196Qh8ymc/view?usp=sharing
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-09-Q03','DM-09','Data & Device Management','LIS setup','ការកំណត់ LIS','1. Configure the IP address and set the communication protocol: https://drive.google.com/file/d/1dWo-4wUoX8El8iNWyn0nyB2196Qh8ymc/view?usp=sharing
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-09-Q04','DM-09','Data & Device Management','What file format is used for the LIS?','តើប្រើទម្រង់ឯកសារអ្វី សម្រាប់ LIS?','Pluslife can provide test result data files in TXT format for compatibility.','Pluslife អាចផ្តល់ឯកសារទិន្នន័យលទ្ធផលតេស្តជាទម្រង់ TXT ដើម្បីឱ្យត្រូវគ្នា។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-09-Q05','DM-09','Data & Device Management','Do we need our IT to set up the LIS?','តើយើងត្រូវការបុគ្គលិក IT របស់យើង ដើម្បីកំណត់ LIS ទេ?','Yes. The user''s LIS engineer needs to help debug the port.','បាទ/ចាស។ វិស្វករ LIS របស់អ្នកប្រើ ត្រូវជួយដោះស្រាយ (debug) រន្ធភ្ជាប់ (port)។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-10','DM-10','Data & Device Management','With several devices, software icons don''t match the physical order','ខ្ញុំភ្ជាប់ម៉ាស៊ីនច្រើន តែរូបតំណាងក្នុងកម្មវិធីមិនត្រូវតាមលំដាប់ម៉ាស៊ីនលើតុ។ ត្រូវធ្វើម៉េច?','When multiple instruments are connected to a PC and powered on, the software identifies them automatically, but the order may not match the physical order. Click and hold an instrument icon and drag it to match the physical order — similar to moving icons on a phone.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-10-Q01','DM-10','Data & Device Management','The device icons in the software are in the wrong order.','រូបម៉ាស៊ីនក្នុងកម្មវិធី នៅខុសលំដាប់។ ត្រូវធ្វើម៉េច?','When multiple instruments are connected to a PC and powered on, the software identifies them automatically, but the order may not match the physical order. Click and hold an instrument icon and drag it to match the physical order — similar to moving icons on a phone.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-10-Q02','DM-10','Data & Device Management','Can I rearrange the device icons?','អាចរៀបចំរូបម៉ាស៊ីនឡើងវិញបានទេ?','Yes. Click and hold an instrument icon and drag it to match the physical order — similar to moving icons on a phone.','បាទ/ចាស។ ចុចឱ្យជាប់លើរូបម៉ាស៊ីន ហើយអូសវាឱ្យត្រូវតាមលំដាប់ពិតប្រាកដ — ដូចការរំកិលរូបតំណាងលើទូរស័ព្ទដែរ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-10-Q03','DM-10','Data & Device Management','How do I keep the icons in the same order as the devices?','តើខ្ញុំរក្សារូបតំណាងឱ្យនៅលំដាប់ដូចម៉ាស៊ីនយ៉ាងម៉េច?','Power on the instruments in order and wait 3 seconds between each one. We recommend adjusting at the start of the working day and leaving the instruments on to keep the corrected order.','បើកម៉ាស៊ីនតាមលំដាប់ ហើយរង់ចាំ 3 វិនាទី រវាងម៉ាស៊ីននីមួយៗ។ យើងណែនាំឱ្យរៀបចំនៅដើមថ្ងៃធ្វើការ ហើយទុកម៉ាស៊ីនឱ្យបើក ដើម្បីរក្សាលំដាប់ដែលបានកែ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-10-Q04','DM-10','Data & Device Management','multi device order wrong','ម៉ាស៊ីនច្រើន លំដាប់ខុស','When multiple instruments are connected to a PC and powered on, the software identifies them automatically, but the order may not match the physical order. Click and hold an instrument icon and drag it to match the physical order — similar to moving icons on a phone.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-11','DM-11','Data & Device Management','Results run from the computer needed on the phone','ខ្ញុំធ្វើតេស្តតាមកម្មវិធីលើកុំព្យូទ័រ។ តើមើលលទ្ធផលនោះលើទូរស័ព្ទបានដោយរបៀបណា?','Yes, the instrument syncs data automatically. However, sample information previously edited on the computer will not sync to the mobile app; the instrument only syncs test results and test card information.','បាទ/ចាស ម៉ាស៊ីនធ្វើសមកាលកម្ម (sync) ទិន្នន័យដោយស្វ័យប្រវត្តិ។ ប៉ុន្តែ ព័ត៌មានសំណាកដែលបានកែលើកុំព្យូទ័រពីមុន នឹងមិនធ្វើសមកាលកម្មទៅ App ទូរស័ព្ទទេ។ ម៉ាស៊ីនធ្វើសមកាលកម្មតែលទ្ធផលតេស្ត និងព័ត៌មានកាតតេស្តប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-11-Q01','DM-11','Data & Device Management','If I run a test with the computer, will results show on my phone?','បើខ្ញុំធ្វើតេស្តជាមួយកុំព្យូទ័រ តើលទ្ធផលនឹងបង្ហាញលើទូរស័ព្ទខ្ញុំទេ?','Yes, the instrument syncs data automatically. However, sample information previously edited on the computer will not sync to the mobile app; the instrument only syncs test results and test card information.','បាទ/ចាស ម៉ាស៊ីនធ្វើសមកាលកម្ម (sync) ទិន្នន័យដោយស្វ័យប្រវត្តិ។ ប៉ុន្តែ ព័ត៌មានសំណាកដែលបានកែលើកុំព្យូទ័រពីមុន នឹងមិនធ្វើសមកាលកម្មទៅ App ទូរស័ព្ទទេ។ ម៉ាស៊ីនធ្វើសមកាលកម្មតែលទ្ធផលតេស្ត និងព័ត៌មានកាតតេស្តប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-11-Q02','DM-11','Data & Device Management','Why is the patient info missing on my phone?','ហេតុអ្វីបានជាព័ត៌មានអ្នកជំងឺបាត់លើទូរស័ព្ទខ្ញុំ?','Sample information edited on the computer does not sync to the mobile app; the instrument only syncs test results and test card information.','ព័ត៌មានសំណាកដែលបានកែលើកុំព្យូទ័រ មិនធ្វើសមកាលកម្មទៅ App ទូរស័ព្ទទេ។ ម៉ាស៊ីនធ្វើសមកាលកម្មតែលទ្ធផលតេស្ត និងព័ត៌មានកាតតេស្តប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-11-Q03','DM-11','Data & Device Management','pc result to phone','លទ្ធផលពីកុំព្យូទ័រ ទៅទូរស័ព្ទ','Yes, the instrument syncs data automatically. However, sample information previously edited on the computer will not sync to the mobile app; the instrument only syncs test results and test card information.','បាទ/ចាស ម៉ាស៊ីនធ្វើសមកាលកម្ម (sync) ទិន្នន័យដោយស្វ័យប្រវត្តិ។ ប៉ុន្តែ ព័ត៌មានសំណាកដែលបានកែលើកុំព្យូទ័រពីមុន នឹងមិនធ្វើសមកាលកម្មទៅ App ទូរស័ព្ទទេ។ ម៉ាស៊ីនធ្វើសមកាលកម្មតែលទ្ធផលតេស្ត និងព័ត៌មានកាតតេស្តប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-12','DM-12','Data & Device Management','Moving data from an old phone/tablet to a new one','ត្រូវផ្ទេរទិន្នន័យពីទូរស័ព្ទ ឬថេប្លេតចាស់ទៅឧបករណ៍ថ្មីដោយរបៀបណា?','1. To sync all data (including patient information), open the Profile screen on your original phone or tablet, tap "Function Settings", then tap "Export Data". Share the exported file with your new phone or tablet.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-12-Q01','DM-12','Data & Device Management','How do I move my data to a new phone?','តើខ្ញុំផ្ទេរទិន្នន័យទៅទូរស័ព្ទថ្មីយ៉ាងម៉េច?','1. To sync all data (including patient information), open the Profile screen on your original phone or tablet, tap "Function Settings", then tap "Export Data". Share the exported file with your new phone or tablet.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-12-Q02','DM-12','Data & Device Management','new phone, old results how','ទូរស័ព្ទថ្មី លទ្ធផលចាស់ ធ្វើម៉េច?','1. To sync all data (including patient information), open the Profile screen on your original phone or tablet, tap "Function Settings", then tap "Export Data". Share the exported file with your new phone or tablet.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-12-Q03','DM-12','Data & Device Management','Can I uninstall the app on the old phone first?','អាចលុប កម្មវិធី លើទូរស័ព្ទចាស់មុនបានទេ?','No. Do not uninstall the app from your original phone before exporting the data, as this will result in the loss of your records, which cannot be recovered.','មិនបានទេ។ កុំលុប (uninstall) App ពីទូរស័ព្ទចាស់ មុននាំចេញទិន្នន័យ ព្រោះវានឹងធ្វើឱ្យបាត់កំណត់ត្រា ហើយមិនអាចយកមកវិញបានទេ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-12-Q04','DM-12','Data & Device Management','I only need the results, not patient info.','ខ្ញុំត្រូវការតែលទ្ធផល មិនត្រូវការព័ត៌មានអ្នកជំងឺទេ?','Simply connect the device to your new phone; the data stored on the device will automatically sync to the app once connected.','គ្រាន់តែភ្ជាប់ម៉ាស៊ីនទៅទូរស័ព្ទថ្មី។ ទិន្នន័យដែលរក្សាទុកក្នុងម៉ាស៊ីន នឹងធ្វើសមកាលកម្មទៅ App ដោយស្វ័យប្រវត្តិ ពេលភ្ជាប់រួច។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-12-Q05','DM-12','Data & Device Management','Where is the Export Data button?','តើប៊ូតុង Export Data នៅឯណា?','Profile screen → "Function Settings" → "Export Data".','អេក្រង់ Profile → "Function Settings" → "Export Data"។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-13','DM-13','Data & Device Management','Raw data requested','ត្រូវទាញយកទិន្នន័យដើម (raw data) របស់តេស្តនៅឯណា?','1. For software versions before 4.3.4, follow the video below to retrieve the raw data, or upgrade the software to version 4.3.4 or later and follow step 2: https://drive.google.com/file/d/1mfhqm45E5MLvLrFltL9zc2Xw2bDUGmiQ/view?usp=drive_link
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-13-Q01','DM-13','Data & Device Management','How do I get the raw data?','តើខ្ញុំយកទិន្នន័យដើម (raw data) យ៉ាងម៉េច?','1. For software versions before 4.3.4, follow the video below to retrieve the raw data, or upgrade the software to version 4.3.4 or later and follow step 2: https://drive.google.com/file/d/1mfhqm45E5MLvLrFltL9zc2Xw2bDUGmiQ/view?usp=drive_link
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-13-Q02','DM-13','Data & Device Management','Pluslife support asked for raw data. Where is it?','Pluslife support ស្នើសុំទិន្នន័យដើម (raw data)។ តើវានៅឯណា?','1. For software versions before 4.3.4, follow the video below to retrieve the raw data, or upgrade the software to version 4.3.4 or later and follow step 2: https://drive.google.com/file/d/1mfhqm45E5MLvLrFltL9zc2Xw2bDUGmiQ/view?usp=drive_link
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-13-Q03','DM-13','Data & Device Management','export raw data button not there','គ្មានប៊ូតុង Export raw data','The "Export raw data" button is in software version 4.3.4 and later. For older versions, follow the video or upgrade: https://drive.google.com/file/d/1mfhqm45E5MLvLrFltL9zc2Xw2bDUGmiQ/view?usp=drive_link','ប៊ូតុង "Export raw data" មាននៅក្នុងកំណែកម្មវិធី 4.3.4 និងថ្មីជាងនេះ។ សម្រាប់កំណែចាស់ សូមធ្វើតាមវីដេអូ ឬធ្វើបច្ចុប្បន្នភាព៖ https://drive.google.com/file/d/1mfhqm45E5MLvLrFltL9zc2Xw2bDUGmiQ/view?usp=drive_link','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-14','DM-14','Data & Device Management','Computer replaced; historical data needed on the new one','ខ្ញុំប្តូរកុំព្យូទ័រថ្មី។ ត្រូវយកប្រវត្តិលទ្ធផលចាស់មកវិញដោយរបៀបណា?','1. After installing the software on the new computer, simply connect the instrument to it, and the data will be transferred automatically. However, this data includes only the test card numbers and corresponding results; it does not include patient information.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-14-Q01','DM-14','Data & Device Management','We got a new computer. How do I move the old results?','យើងមានកុំព្យូទ័រថ្មី។ តើខ្ញុំផ្ទេរលទ្ធផលចាស់យ៉ាងម៉េច?','1. After installing the software on the new computer, simply connect the instrument to it, and the data will be transferred automatically. However, this data includes only the test card numbers and corresponding results; it does not include patient information.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-14-Q02','DM-14','Data & Device Management','If I connect the device to the new PC, will patient info come too?','បើខ្ញុំភ្ជាប់ម៉ាស៊ីនទៅកុំព្យូទ័រថ្មី តើព័ត៌មានអ្នកជំងឺនឹងមកដែរទេ?','No. Only the test card numbers and corresponding results transfer; patient information is not included.','ទេ។ មានតែលេខកាតតេស្ត និងលទ្ធផលដែលត្រូវគ្នាប៉ុណ្ណោះដែលផ្ទេរ។ ព័ត៌មានអ្នកជំងឺមិនត្រូវបានរួមបញ្ចូលទេ។','Routine','Supervisor / IT');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('DM-14-Q03','DM-14','Data & Device Management','new laptop data transfer','ផ្ទេរទិន្នន័យទៅកុំព្យូទ័រយួរដៃថ្មី','1. After installing the software on the new computer, simply connect the instrument to it, and the data will be transferred automatically. However, this data includes only the test card numbers and corresponding results; it does not include patient information.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-02','MT-02','Maintenance','Test card found leaking after the test','ធ្វើតេស្តចប់ហើយ ទើបឃើញកាតលេចទឹក។ ត្រូវធ្វើម៉េច?','1) Check the test card before testing. If the film is loose or there is bulging under the film, do not use it and notify sales staff promptly.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-02-Q01','MT-02','Maintenance','The card leaked after the test. What do I do?','កាតលេចធ្លាយក្រោយធ្វើតេស្ត។ តើខ្ញុំត្រូវធ្វើអ្វី?','Seal the card together with the instrument in a sealed bag and promptly inform your local Pluslife distributor, or report the issue to service@pluslife.com.','បិទកាតរួមជាមួយម៉ាស៊ីន ក្នុងថង់បិទជិត ហើយជូនដំណឹងឱ្យបានឆាប់ទៅអ្នកសម្របសម្រួលគម្រោង (study focal point) ដើម្បីបញ្ជូនទៅអ្នកចែកចាយ Pluslife ក្នុងតំបន់ ឬរាយការណ៍បញ្ហាទៅ service@pluslife.com។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-02-Q02','MT-02','Maintenance','The film on a new card is loose. Can I use it?','ស្រទាប់ផ្លាស្ទិក (film) លើកាតថ្មីរលុង។ អាចប្រើវាបានទេ?','No. If the film is loose or there is bulging under the film, do not use it and notify sales staff promptly.','មិនបានទេ។ បើស្រទាប់ផ្លាស្ទិក (film) រលុង ឬមានប៉ោងនៅក្រោមស្រទាប់នោះ កុំប្រើវា ហើយជូនដំណឹងទៅអ្នកសម្របសម្រួលគម្រោង (study focal point) ឱ្យបានឆាប់ ដើម្បីបញ្ជូនទៅបុគ្គលិកលក់។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-02-Q03','MT-02','Maintenance','card leak after test','កាតលេចធ្លាយក្រោយធ្វើតេស្ត','1) Check the test card before testing. If the film is loose or there is bulging under the film, do not use it and notify sales staff promptly.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-02-Q04','MT-02','Maintenance','Will the device be replaced if a card leaked inside?','តើម៉ាស៊ីននឹងត្រូវប្តូរទេ បើកាតលេចធ្លាយនៅខាងក្នុង?','Yes. Once leakage is confirmed, the instrument and test card must be replaced promptly.','បាទ/ចាស។ ពេលបញ្ជាក់ថាមានការលេចធ្លាយ ម៉ាស៊ីន និងកាតតេស្តត្រូវតែប្តូរឱ្យបានឆាប់។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-02-Q05','MT-02','Maintenance','How often do cards leak?','តើកាតលេចធ្លាយញឹកញាប់ប៉ុណ្ណា?','Known card leakage is mainly due to raw material issues, with a probability of less than 1 in 10,000.','ការលេចធ្លាយកាតដែលបានដឹង ភាគច្រើនបណ្តាលមកពីបញ្ហាវត្ថុធាតុដើម ដោយមានប្រូបាប៊ីលីតេតិចជាង 1 ក្នុង 10,000។','Safety-critical','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-03','MT-03','Maintenance','Worker asks about the built-in mainboard battery','ថ្មនៅលើបន្ទះសៀគ្វីក្នុងម៉ាស៊ីនប្រើសម្រាប់អ្វី?','It charges automatically once the power adapter is connected and the device is on; a full charge takes about 1 hour. It does not need replacing — it is a built-in rechargeable battery. The instrument can run tests normally while charging.','វាសាកដោយស្វ័យប្រវត្តិ ពេលភ្ជាប់អាដាប់ទ័រភ្លើង ហើយម៉ាស៊ីនបើក។ ការសាកពេញចំណាយពេលប្រហែល 1 ម៉ោង។ វាមិនចាំបាច់ប្តូរទេ — វាជាថ្មសាកបានដែលមាននៅខាងក្នុង។ ម៉ាស៊ីនអាចធ្វើតេស្តបានធម្មតា ពេលកំពុងសាក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-03-Q01','MT-03','Maintenance','How long does the built-in battery take to charge?','តើថ្មខាងក្នុងត្រូវសាករយៈពេលប៉ុន្មាន?','About 1 hour. It charges automatically once the power adapter is connected and the device is on.','ប្រហែល 1 ម៉ោង។ វាសាកដោយស្វ័យប្រវត្តិ ពេលភ្ជាប់អាដាប់ទ័រភ្លើង ហើយម៉ាស៊ីនបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-03-Q02','MT-03','Maintenance','Do I need to replace the mainboard battery?','តើខ្ញុំត្រូវប្តូរថ្មក្នុងបន្ទះមេ (mainboard) ទេ?','No. It is a built-in rechargeable battery.','ទេ។ វាជាថ្មសាកបានដែលមាននៅខាងក្នុង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-03-Q03','MT-03','Maintenance','Can I run tests while the battery is charging?','អាចធ្វើតេស្ត ពេលថ្មកំពុងសាកបានទេ?','Yes. The instrument can run tests normally while charging, unaffected.','បាទ/ចាស។ ម៉ាស៊ីនអាចធ្វើតេស្តបានធម្មតា ពេលកំពុងសាក ដោយមិនប៉ះពាល់អ្វីទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-03-Q04','MT-03','Maintenance','battery change?','ប្តូរថ្ម?','No need. It is a built-in rechargeable battery.','មិនចាំបាច់ទេ។ វាជាថ្មសាកបានដែលមាននៅខាងក្នុង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-03-Q05','MT-03','Maintenance','How do I charge the internal battery?','តើខ្ញុំសាកថ្មខាងក្នុងយ៉ាងម៉េច?','Connect the power adapter and turn the device on; it charges automatically.','ភ្ជាប់អាដាប់ទ័រភ្លើង ហើយបើកម៉ាស៊ីន។ វាសាកដោយស្វ័យប្រវត្តិ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-04','MT-04','Maintenance','Worker asks how to do daily maintenance on the Ultra','ត្រូវសម្អាត និងថែទាំ MiniDock Ultra ប្រចាំថ្ងៃដោយរបៀបណា?','1. Turn off the device, remove the reaction card, and check if the card is leaking and if there is any liquid residue inside the instrument.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-04-Q01','MT-04','Maintenance','How do I clean the device every day?','តើខ្ញុំសម្អាតម៉ាស៊ីនរាល់ថ្ងៃយ៉ាងម៉េច?','1. Turn off the device, remove the reaction card, and check if the card is leaking and if there is any liquid residue inside the instrument.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-04-Q02','MT-04','Maintenance','What can I wipe the device with?','អាចជូតម៉ាស៊ីនដោយប្រើអ្វី?','A soft, lint-free cloth moistened with neutral detergent or 75% alcohol; then dry with a dry cloth to prevent corrosion.','ក្រណាត់ទន់ គ្មានរោម ជ្រលក់សាប៊ូអព្យាក្រឹត (neutral detergent) ឬអាល់កុល 75%។ រួចជូតឱ្យស្ងួតដោយក្រណាត់ស្ងួត ដើម្បីការពារការច្រេះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-04-Q03','MT-04','Maintenance','How long is the UV disinfection?','តើការសម្លាប់មេរោគដោយកាំរស្មី UV ចំណាយពេលប៉ុន្មាន?','More than 30 minutes.','លើសពី 30 នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-04-Q04','MT-04','Maintenance','Do I turn the device off before cleaning?','តើខ្ញុំបិទម៉ាស៊ីនមុនសម្អាតទេ?','Yes. Turn off the device and remove the reaction card first.','បាទ/ចាស។ បិទម៉ាស៊ីន ហើយដកកាតប្រតិកម្មចេញជាមុនសិន។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('MT-04-Q05','MT-04','Maintenance','daily maintenance','ការថែទាំប្រចាំថ្ងៃ','1. Turn off the device, remove the reaction card, and check if the card is leaking and if there is any liquid residue inside the instrument.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-07','PI-07','Product Information','Worker asks what the "test card" or "releasing agent" is','កាតតេស្ត និងសូលុយស្យុង Releasing Agent ប្រើសម្រាប់អ្វី?','Test card = the card packed in silver aluminium film packaging in the test kit, used for testing, with 7 chambers and lyophilized reagent inside. It is generally labelled with the test item, card number and a QR code that contains both. Users may also call it cartridge / Reaction Card.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-07-Q01','PI-07','Product Information','What is the test card?','តើកាតតេស្ត (test card) ជាអ្វី?','Test card = the card packed in silver aluminium film packaging in the test kit, used for testing, with 7 chambers and lyophilized reagent inside. It is generally labelled with the test item, card number and a QR code that contains both. Users may also call it cartridge / Reaction Card.','កាតតេស្ត (test card) = កាតដែលខ្ចប់ក្នុងស្រោមអាលុយមីញ៉ូមពណ៌ប្រាក់ក្នុងកញ្ចប់តេស្ត ប្រើសម្រាប់ធ្វើតេស្ត មាន 7 រន្ធ និងមានសារធាតុស្ងួត (lyophilized reagent) នៅខាងក្នុង។ ជាទូទៅ វាមានស្លាកបង្ហាញប្រភេទតេស្ត លេខកាត និងកូដ QR ដែលមានព័ត៌មានទាំងពីរនេះ។ អ្នកប្រើខ្លះក៏ហៅវាថា cartridge / Reaction Card (កាតប្រតិកម្ម) ដែរ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-07-Q02','PI-07','Product Information','Is the reaction card the same thing as the test card?','តើកាតប្រតិកម្ម (reaction card) ដូចគ្នានឹងកាតតេស្ត (test card) ទេ?','Yes. Users may also call the test card cartridge / Reaction Card. Test card = the card packed in silver aluminium film packaging in the test kit, used for testing, with 7 chambers and lyophilized reagent inside. It is generally labelled with the test item, card number and a QR code that contains both. Users may also call it cartridge / Reaction Card.','បាទ/ចាស។ អ្នកប្រើខ្លះក៏ហៅកាតតេស្តថា cartridge / Reaction Card (កាតប្រតិកម្ម) ដែរ។ កាតតេស្ត (test card) = កាតដែលខ្ចប់ក្នុងស្រោមអាលុយមីញ៉ូមពណ៌ប្រាក់ក្នុងកញ្ចប់តេស្ត ប្រើសម្រាប់ធ្វើតេស្ត មាន 7 រន្ធ និងមានសារធាតុស្ងួត (lyophilized reagent) នៅខាងក្នុង។ ជាទូទៅ វាមានស្លាកបង្ហាញប្រភេទតេស្ត លេខកាត និងកូដ QR ដែលមានព័ត៌មានទាំងពីរនេះ។ អ្នកប្រើខ្លះក៏ហៅវាថា cartridge / Reaction Card ដែរ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-07-Q03','PI-07','Product Information','cartridge = test card?','cartridge = កាតតេស្ត?','Yes. Users may also call the test card cartridge / Reaction Card.','បាទ/ចាស។ អ្នកប្រើខ្លះក៏ហៅកាតតេស្តថា cartridge / Reaction Card (កាតប្រតិកម្ម) ដែរ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-07-Q04','PI-07','Product Information','What is the releasing agent?','តើ Releasing agent ជាអ្វី?','Releasing agent = the tube with liquid in the test kit, used for sample releasing.','Releasing agent = បំពង់ដែលមានទឹកក្នុងកញ្ចប់តេស្ត ប្រើសម្រាប់បញ្ចេញសំណាក (sample releasing)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-07-Q05','PI-07','Product Information','which one is the releasing agent tube','បំពង់មួយណាជាបំពង់ Releasing agent','Releasing agent = the tube with liquid in the test kit, used for sample releasing.','Releasing agent = បំពង់ដែលមានទឹកក្នុងកញ្ចប់តេស្ត ប្រើសម្រាប់បញ្ចេញសំណាក (sample releasing)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-07-Q06','PI-07','Product Information','What information is on the card label?','តើមានព័ត៌មានអ្វីខ្លះលើស្លាកកាត?','The card is generally labelled with the test item, card number and a QR code that contains both.','ជាទូទៅ កាតមានស្លាកបង្ហាញប្រភេទតេស្ត លេខកាត និងកូដ QR ដែលមានព័ត៌មានទាំងពីរនេះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-07-Q07','PI-07','Product Information','How many chambers does the test card have?','តើកាតតេស្តមានរន្ធប៉ុន្មាន?','The test card has 7 chambers with lyophilized reagent inside.','កាតតេស្តមាន 7 រន្ធ ដែលមានសារធាតុស្ងួត (lyophilized reagent) នៅខាងក្នុង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-08','PI-08','Product Information','Worker asks what other Pluslife products/test cards exist','Pluslife មានផលិតផល ឬកាតតេស្តប្រភេទអ្វីផ្សេងទៀត?','Please check the Pluslife official website: https://www.pluslife.com/testcards','សូមមើលគេហទំព័រផ្លូវការរបស់ Pluslife៖ https://www.pluslife.com/testcards','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-08-Q01','PI-08','Product Information','What products does Pluslife have?','តើ Pluslife មានផលិតផលអ្វីខ្លះ?','Please check the Pluslife official website: https://www.pluslife.com/testcards','សូមមើលគេហទំព័រផ្លូវការរបស់ Pluslife៖ https://www.pluslife.com/testcards','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-08-Q02','PI-08','Product Information','Which other test cards can I buy for this device?','អាចទិញកាតតេស្តផ្សេងអ្វីខ្លះទៀត សម្រាប់ម៉ាស៊ីននេះ?','Please check the Pluslife official website: https://www.pluslife.com/testcards','សូមមើលគេហទំព័រផ្លូវការរបស់ Pluslife៖ https://www.pluslife.com/testcards','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-08-Q03','PI-08','Product Information','product list pls','សូមបញ្ជីផលិតផល','Please check the Pluslife official website: https://www.pluslife.com/testcards','សូមមើលគេហទំព័រផ្លូវការរបស់ Pluslife៖ https://www.pluslife.com/testcards','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-08-Q04','PI-08','Product Information','Where can I see all Pluslife test cards?','អាចមើលកាតតេស្ត Pluslife ទាំងអស់នៅឯណា?','Please check the Pluslife official website: https://www.pluslife.com/testcards','សូមមើលគេហទំព័រផ្លូវការរបស់ Pluslife៖ https://www.pluslife.com/testcards','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09','PI-09','Product Information','Worker asks about device size or weight','ម៉ាស៊ីនមានទំហំ និងទម្ងន់ប៉ុន្មាន?','MiniDock Ultra: 101 × 91 × 65 mm, weight 240 g — about the same as an iPhone 14 Pro.','MiniDock Ultra៖ 101 × 91 × 65 mm ទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q01','PI-09','Product Information','How big is the MiniDock Ultra?','តើ MiniDock Ultra ធំប៉ុណ្ណា?','MiniDock Ultra: 101 × 91 × 65 mm.','MiniDock Ultra៖ 101 × 91 × 65 mm។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q02','PI-09','Product Information','How heavy is the device?','តើម៉ាស៊ីនធ្ងន់ប៉ុណ្ណា?','The MiniDock Ultra weighs 240 g — about the same as an iPhone 14 Pro.','MiniDock Ultra មានទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q03','PI-09','Product Information','device size and weight','ទំហំ និងទម្ងន់ម៉ាស៊ីន','MiniDock Ultra: 101 × 91 × 65 mm, weight 240 g — about the same as an iPhone 14 Pro.','MiniDock Ultra៖ 101 × 91 × 65 mm ទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q04','PI-09','Product Information','Is the device heavy to carry for outreach?','តើម៉ាស៊ីនធ្ងន់ពិបាកយកទៅធ្វើការចុះមូលដ្ឋាន (outreach) ទេ?','Not sure — that depends on your situation. For reference: MiniDock Ultra: 101 × 91 × 65 mm, weight 240 g — about the same as an iPhone 14 Pro.','មិនប្រាកដទេ — វាអាស្រ័យលើស្ថានភាពរបស់អ្នក។ សម្រាប់ជាឯកសារយោង៖ MiniDock Ultra៖ 101 × 91 × 65 mm ទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-09-Q05','PI-09','Product Information','dimension of minidock ultra?','ទំហំរបស់ MiniDock Ultra?','MiniDock Ultra: 101 × 91 × 65 mm, weight 240 g — about the same as an iPhone 14 Pro.','MiniDock Ultra៖ 101 × 91 × 65 mm ទម្ងន់ 240 g — ប្រហែលស្មើនឹង iPhone 14 Pro។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10','PI-10','Product Information','Worker asks how long one test takes','ធ្វើតេស្តម្តង ត្រូវរង់ចាំប៉ុន្មាននាទីទើបចេញលទ្ធផល?','It depends on which product you are using.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q01','PI-10','Product Information','How long does one TB test take?','តើតេស្តជំងឺរបេងមួយចំណាយពេលប៉ុន្មាន?','For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានចំណាយពេល 25 នាទី។ លទ្ធផលវិជ្ជមានត្រូវបានរាយការណ៍ក្នុងរយៈពេល 5–20 នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q02','PI-10','Product Information','how long until result come out','ប៉ុន្មាននាទីទើបលទ្ធផលចេញ?','For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានចំណាយពេល 25 នាទី។ លទ្ធផលវិជ្ជមានត្រូវបានរាយការណ៍ក្នុងរយៈពេល 5–20 នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q03','PI-10','Product Information','Why did my positive come out faster than the negative ones?','ហេតុអ្វីបានជាលទ្ធផលវិជ្ជមានរបស់ខ្ញុំចេញលឿនជាងលទ្ធផលអវិជ្ជមាន?','A positive result is reported earlier. For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','លទ្ធផលវិជ្ជមានត្រូវបានរាយការណ៍មុន។ សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានចំណាយពេល 25 នាទី។ លទ្ធផលវិជ្ជមានត្រូវបានរាយការណ៍ក្នុងរយៈពេល 5–20 នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q04','PI-10','Product Information','Is 25 minutes normal for a negative MTB result?','តើ 25 នាទី ជារឿងធម្មតាសម្រាប់លទ្ធផល MTB អវិជ្ជមានទេ?','Yes. For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','បាទ/ចាស។ សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានចំណាយពេល 25 នាទី។ លទ្ធផលវិជ្ជមានត្រូវបានរាយការណ៍ក្នុងរយៈពេល 5–20 នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q05','PI-10','Product Information','How long does a test take on a multiplex card?','តើតេស្តលើកាតច្រើនគោលដៅ (multiplex) ចំណាយពេលប៉ុន្មាន?','Multiplex products: a negative result takes 35 minutes; for a positive result, the time is determined by when the last target is detected.','ផលិតផលច្រើនគោលដៅ (multiplex)៖ លទ្ធផលអវិជ្ជមានចំណាយពេល 35 នាទី។ សម្រាប់លទ្ធផលវិជ្ជមាន រយៈពេលអាស្រ័យលើពេលដែលរកឃើញគោលដៅចុងក្រោយ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-10-Q06','PI-10','Product Information','test time?','រយៈពេលតេស្ត?','For MTB: a negative result takes 25 minutes; a positive result is reported within 5–20 minutes.','សម្រាប់ MTB៖ លទ្ធផលអវិជ្ជមានចំណាយពេល 25 នាទី។ លទ្ធផលវិជ្ជមានត្រូវបានរាយការណ៍ក្នុងរយៈពេល 5–20 នាទី។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11','PI-11','Product Information','Worker asks which technology Pluslife uses','Pluslife ប្រើបច្ចេកវិទ្យាអ្វីដើម្បីរកមេរោគ?','Pluslife POCT products are based on Pluslife''s proprietary RHAM technology, which is an optimization built on LAMP technology.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q01','PI-11','Product Information','What technology does Pluslife use?','តើ Pluslife ប្រើបច្ចេកវិទ្យាអ្វី?','Pluslife POCT products are based on Pluslife''s proprietary RHAM technology, which is an optimization built on LAMP technology.','ផលិតផល POCT របស់ Pluslife ផ្អែកលើបច្ចេកវិទ្យា RHAM ផ្ទាល់ខ្លួនរបស់ Pluslife ដែលជាការកែលម្អលើបច្ចេកវិទ្យា LAMP។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q02','PI-11','Product Information','Is this PCR or LAMP?','តើនេះជា PCR ឬ LAMP?','It is RHAM, Pluslife''s proprietary technology, which is an optimization built on LAMP technology.','វាជា RHAM ដែលជាបច្ចេកវិទ្យាផ្ទាល់ខ្លួនរបស់ Pluslife ហើយជាការកែលម្អលើបច្ចេកវិទ្យា LAMP។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q03','PI-11','Product Information','Is RHAM based on LAMP?','តើ RHAM ផ្អែកលើ LAMP ទេ?','Yes. Pluslife POCT products are based on Pluslife''s proprietary RHAM technology, which is an optimization built on LAMP technology.','បាទ/ចាស។ ផលិតផល POCT របស់ Pluslife ផ្អែកលើបច្ចេកវិទ្យា RHAM ផ្ទាល់ខ្លួនរបស់ Pluslife ដែលជាការកែលម្អលើបច្ចេកវិទ្យា LAMP។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q04','PI-11','Product Information','How does RHAM produce the fluorescence signal?','តើ RHAM បង្កើតសញ្ញាពន្លឺ (fluorescence signal) យ៉ាងម៉េច?','The RHAM reporting system consists of a nuclease and a probe. The probe is made of modified oligonucleotides and binds specifically to its complementary strand. When single-stranded, the probe is not cleaved by the nuclease; once bound to the complementary strand, the nuclease cleaves the probe, generating a fluorescence signal. As the reaction proceeds, new probes bind to complementary strands and continue new cycles, accumulating fluorescence. The instrument then detects the fluorescence signal and automatically analyzes the result.','ប្រព័ន្ធរាយការណ៍ RHAM មានអង់ស៊ីមកាត់អាស៊ីតនុយក្លេអ៊ីក (nuclease) និង probe។ Probe ត្រូវបានធ្វើពីអូលីហ្គោនុយក្លេអូទីតដែលកែប្រែ (modified oligonucleotides) ហើយភ្ជាប់ជាក់លាក់ទៅនឹងខ្សែបំពេញ (complementary strand) របស់វា។ ពេលនៅជាខ្សែទោល probe មិនត្រូវ nuclease កាត់ទេ។ ពេលភ្ជាប់ទៅខ្សែបំពេញហើយ nuclease កាត់ probe ហើយបង្កើតសញ្ញាពន្លឺ (fluorescence signal)។ ពេលប្រតិកម្មបន្ត probe ថ្មីៗភ្ជាប់ទៅខ្សែបំពេញ ហើយបន្តវដ្តថ្មី ធ្វើឱ្យពន្លឺកើនឡើង។ បន្ទាប់មក ម៉ាស៊ីនរកឃើញសញ្ញាពន្លឺ ហើយវិភាគលទ្ធផលដោយស្វ័យប្រវត្តិ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-11-Q05','PI-11','Product Information','rham technology explain','ពន្យល់បច្ចេកវិទ្យា RHAM','Pluslife POCT products are based on Pluslife''s proprietary RHAM technology, which is an optimization built on LAMP technology.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12','PI-12','Product Information','Releasing agent tube looks only partly filled (2 mL in a 5 mL tube)','បំពង់ Releasing Agent ចំណុះ 5 mL តែមានសូលុយស្យុងប្រហែល 2 mL។ តើធម្មតាទេ?','To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume. It is normal for the tube to be filled to about 40% of its capacity before opening.','ដើម្បីការពារកុំឱ្យទឹករំលាយ (diluent) ខ្ទាត ពេលកូរដងសំឡីយកសំណាក បំពង់ត្រូវទុកចន្លោះទំនេរខ្លះនៅខាងលើ។ លើសពីនេះ ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដែលដាក់។ ជារឿងធម្មតាដែលបំពង់មានទឹកប្រហែល 40% នៃចំណុះរបស់វា មុនពេលបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q01','PI-12','Product Information','The releasing agent tube is only half full. Is something wrong?','បំពង់ Releasing agent មានទឹកតែពាក់កណ្តាល។ តើមានបញ្ហាអ្វីទេ?','No. It is normal for the tube to be filled to about 40% of its capacity before opening. To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume.','ទេ។ ជារឿងធម្មតាដែលបំពង់មានទឹកប្រហែល 40% នៃចំណុះរបស់វា មុនពេលបើក។ ដើម្បីការពារកុំឱ្យទឹករំលាយ (diluent) ខ្ទាត ពេលកូរដងសំឡីយកសំណាក បំពង់ត្រូវទុកចន្លោះទំនេរខ្លះនៅខាងលើ។ លើសពីនេះ ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដែលដាក់។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q02','PI-12','Product Information','Why is 2 mL releasing agent packed in a 5 mL tube?','ហេតុអ្វីបានជា Releasing agent 2 mL ត្រូវបានខ្ចប់ក្នុងបំពង់ 5 mL?','To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume. It is normal for the tube to be filled to about 40% of its capacity before opening.','ដើម្បីការពារកុំឱ្យទឹករំលាយ (diluent) ខ្ទាត ពេលកូរដងសំឡីយកសំណាក បំពង់ត្រូវទុកចន្លោះទំនេរខ្លះនៅខាងលើ។ លើសពីនេះ ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដែលដាក់។ ជារឿងធម្មតាដែលបំពង់មានទឹកប្រហែល 40% នៃចំណុះរបស់វា មុនពេលបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q03','PI-12','Product Information','tube look not full, missing liquid?','បំពង់មើលទៅមិនពេញ ខ្វះទឹកទេ?','No. It is normal for the tube to be filled to about 40% of its capacity before opening.','ទេ។ ជារឿងធម្មតាដែលបំពង់មានទឹកប្រហែល 40% នៃចំណុះរបស់វា មុនពេលបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q04','PI-12','Product Information','Is it normal that the tube is only about 40% filled?','តើជារឿងធម្មតាទេ ដែលបំពង់មានទឹកតែប្រហែល 40%?','Yes. To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume. It is normal for the tube to be filled to about 40% of its capacity before opening.','បាទ/ចាស។ ដើម្បីការពារកុំឱ្យទឹករំលាយ (diluent) ខ្ទាត ពេលកូរដងសំឡីយកសំណាក បំពង់ត្រូវទុកចន្លោះទំនេរខ្លះនៅខាងលើ។ លើសពីនេះ ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដែលដាក់។ ជារឿងធម្មតាដែលបំពង់មានទឹកប្រហែល 40% នៃចំណុះរបស់វា មុនពេលបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-12-Q05','PI-12','Product Information','why big tube small liquid','ហេតុអ្វីបំពង់ធំ តែទឹកតិច?','To prevent the diluent from splashing while mixing the sampling swab, the tube leaves some headspace; also, when squeezing the tube to load the sample, sufficient space is needed to control the loading volume. It is normal for the tube to be filled to about 40% of its capacity before opening.','ដើម្បីការពារកុំឱ្យទឹករំលាយ (diluent) ខ្ទាត ពេលកូរដងសំឡីយកសំណាក បំពង់ត្រូវទុកចន្លោះទំនេរខ្លះនៅខាងលើ។ លើសពីនេះ ពេលច្របាច់បំពង់ដើម្បីដាក់សំណាក ត្រូវការចន្លោះគ្រប់គ្រាន់ ដើម្បីគ្រប់គ្រងបរិមាណដែលដាក់។ ជារឿងធម្មតាដែលបំពង់មានទឹកប្រហែល 40% នៃចំណុះរបស់វា មុនពេលបើក។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13','PI-13','Product Information','Worker asks at what temperature cards can be stored or used','កាតតេស្តត្រូវទុកនៅសីតុណ្ហភាពប៉ុន្មាន ហើយអាចប្រើនៅសីតុណ្ហភាពប៉ុន្មាន?','MTB test cards: storage 0–40 °C, operating 10–30 °C. Other test cards: storage 2 °C–28 °C, operating 15 °C–28 °C.','កាតតេស្ត MTB៖ រក្សាទុកនៅ 0–40 °C ប្រើនៅ 10–30 °C។ កាតតេស្តផ្សេងទៀត៖ រក្សាទុកនៅ 2 °C–28 °C ប្រើនៅ 15 °C–28 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q01','PI-13','Product Information','At what temperature should I store the TB test cards?','តើខ្ញុំគួររក្សាទុកកាតតេស្តជំងឺរបេង នៅសីតុណ្ហភាពប៉ុន្មាន?','MTB test cards: storage 0–40 °C.','កាតតេស្ត MTB៖ រក្សាទុកនៅ 0–40 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q02','PI-13','Product Information','Do the MTB cards need a fridge?','តើកាត MTB ត្រូវការទូទឹកកកទេ?','No. MTB test cards can be stored at 0–40 °C.','ទេ។ កាតតេស្ត MTB អាចរក្សាទុកនៅ 0–40 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q03','PI-13','Product Information','What room temperature is OK when I run the test with an MTB card?','តើសីតុណ្ហភាពបន្ទប់ប៉ុន្មានដែលល្អ ពេលខ្ញុំធ្វើតេស្តជាមួយកាត MTB?','MTB test cards: operating temperature 10–30 °C.','កាតតេស្ត MTB៖ សីតុណ្ហភាពប្រើប្រាស់ 10–30 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q04','PI-13','Product Information','Our room is 35 °C, can I still run the MTB test?','បន្ទប់របស់យើងមាន 35 °C តើខ្ញុំនៅតែអាចធ្វើតេស្ត MTB បានទេ?','No. The operating temperature for MTB test cards is 10–30 °C.','មិនបានទេ។ សីតុណ្ហភាពប្រើប្រាស់សម្រាប់កាតតេស្ត MTB គឺ 10–30 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q05','PI-13','Product Information','Can I keep the MTB cards in the storeroom at 38 °C?','អាចទុកកាត MTB ក្នុងឃ្លាំងដែលមាន 38 °C បានទេ?','Yes. MTB test cards can be stored at 0–40 °C.','បាទ/ចាស។ កាតតេស្ត MTB អាចរក្សាទុកនៅ 0–40 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-13-Q06','PI-13','Product Information','card storage temp','សីតុណ្ហភាពរក្សាទុកកាត','MTB test cards: storage 0–40 °C, operating 10–30 °C. Other test cards: storage 2 °C–28 °C, operating 15 °C–28 °C.','កាតតេស្ត MTB៖ រក្សាទុកនៅ 0–40 °C ប្រើនៅ 10–30 °C។ កាតតេស្តផ្សេងទៀត៖ រក្សាទុកនៅ 2 °C–28 °C ប្រើនៅ 15 °C–28 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14','PI-14','Product Information','Worker asks which parts of the system can be reused','ឧបករណ៍ ឬសម្ភារៈមួយណាខ្លះអាចប្រើឡើងវិញបាន?','The instrument is reusable; test cards are single-use. One test card per person per test.','ម៉ាស៊ីនអាចប្រើឡើងវិញបាន។ កាតតេស្តប្រើបានតែម្តងប៉ុណ្ណោះ។ កាតតេស្តមួយសម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q01','PI-14','Product Information','Are Pluslife products reusable?','តើផលិតផល Pluslife អាចប្រើឡើងវិញបានទេ?','Not all of them. The instrument is reusable; test cards are single-use. One test card per person per test.','មិនមែនទាំងអស់ទេ។ ម៉ាស៊ីនអាចប្រើឡើងវិញបាន។ កាតតេស្តប្រើបានតែម្តងប៉ុណ្ណោះ។ កាតតេស្តមួយសម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q02','PI-14','Product Information','Can I use one card for two patients?','អាចប្រើកាតមួយសម្រាប់អ្នកជំងឺពីរនាក់បានទេ?','No. Test cards are single-use. One test card per person per test.','មិនបានទេ។ កាតតេស្តប្រើបានតែម្តងប៉ុណ្ណោះ។ កាតតេស្តមួយសម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q03','PI-14','Product Information','Is the test card reusable?','តើកាតតេស្តអាចប្រើឡើងវិញបានទេ?','No. Test cards are single-use. One test card per person per test.','មិនបានទេ។ កាតតេស្តប្រើបានតែម្តងប៉ុណ្ណោះ។ កាតតេស្តមួយសម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q04','PI-14','Product Information','the device can use many time?','ម៉ាស៊ីនប្រើបានច្រើនដងទេ?','Yes. The instrument is reusable; the test cards are single-use.','បាទ/ចាស។ ម៉ាស៊ីនអាចប្រើឡើងវិញបាន។ កាតតេស្តប្រើបានតែម្តងប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-14-Q05','PI-14','Product Information','one card how many test','កាតមួយ ធ្វើតេស្តបានប៉ុន្មានដង','One test card per person per test — test cards are single-use.','កាតតេស្តមួយសម្រាប់មនុស្សម្នាក់ ក្នុងតេស្តមួយដង — កាតតេស្តប្រើបានតែម្តងប៉ុណ្ណោះ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15','PI-15','Product Information','Worker worries the heating module could overheat','ផ្នែកកម្តៅរបស់ MiniDock អាចឡើងកម្តៅខ្លាំងពេកទេ?','The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពនៅខាងក្នុង ដែលការពារដោយស្វ័យប្រវត្តិភ្លាមៗ ពេលសីតុណ្ហភាពលើសកម្រិតរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភពីសីតុណ្ហភាពឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q01','PI-15','Product Information','Can the device overheat because of the heater?','តើម៉ាស៊ីនអាចក្តៅពេកដោយសារម៉ាស៊ីនកម្តៅទេ?','No. The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','ទេ។ ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពនៅខាងក្នុង ដែលការពារដោយស្វ័យប្រវត្តិភ្លាមៗ ពេលសីតុណ្ហភាពលើសកម្រិតរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភពីសីតុណ្ហភាពឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q02','PI-15','Product Information','Is there a risk of temperature runaway?','តើមានហានិភ័យសីតុណ្ហភាពឡើងហួសការគ្រប់គ្រងទេ?','No. The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','ទេ។ ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពនៅខាងក្នុង ដែលការពារដោយស្វ័យប្រវត្តិភ្លាមៗ ពេលសីតុណ្ហភាពលើសកម្រិតរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភពីសីតុណ្ហភាពឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q03','PI-15','Product Information','The device gets warm, is it dangerous?','ម៉ាស៊ីនឡើងក្តៅ តើវាគ្រោះថ្នាក់ទេ?','Not sure what you are feeling, but the device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded.','មិនប្រាកដថាអ្នកកំពុងជួបអ្វីទេ ប៉ុន្តែម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពនៅខាងក្នុង ដែលការពារដោយស្វ័យប្រវត្តិភ្លាមៗ ពេលសីតុណ្ហភាពលើសកម្រិតរោទិ៍។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q04','PI-15','Product Information','Does the MiniDock have overheat protection?','តើ MiniDock មានការការពារការក្តៅពេកទេ?','Yes. The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','បាទ/ចាស។ ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពនៅខាងក្នុង ដែលការពារដោយស្វ័យប្រវត្តិភ្លាមៗ ពេលសីតុណ្ហភាពលើសកម្រិតរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភពីសីតុណ្ហភាពឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-15-Q05','PI-15','Product Information','heater safe?','ម៉ាស៊ីនកម្តៅ មានសុវត្ថិភាពទេ?','The device has a built-in temperature protection device that automatically provides real-time protection when the alarm temperature is exceeded, so there is no need to worry about temperature runaway.','ម៉ាស៊ីនមានឧបករណ៍ការពារសីតុណ្ហភាពនៅខាងក្នុង ដែលការពារដោយស្វ័យប្រវត្តិភ្លាមៗ ពេលសីតុណ្ហភាពលើសកម្រិតរោទិ៍ ដូច្នេះមិនចាំបាច់បារម្ភពីសីតុណ្ហភាពឡើងហួសការគ្រប់គ្រងទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16','PI-16','Product Information','Worker asks where to find sensitivity, specificity or LOD','តើអាចរកមើលព័ត៌មានអំពីភាពរសើប ភាពជាក់លាក់ និងកម្រិតទាបបំផុតដែលតេស្តអាចរកឃើញ (LOD) នៅឯណា?','In the IFU (Instructions for Use) of the corresponding product. Performance parameters may differ between products; technical confirmation and external replies should be based on the corresponding product''s IFU.','នៅក្នុង IFU (ឯកសារណែនាំការប្រើប្រាស់ - Instructions for Use) នៃផលិតផលនីមួយៗ។ ប៉ារ៉ាម៉ែត្រលទ្ធផលការងារអាចខុសគ្នារវាងផលិតផល។ ការបញ្ជាក់បច្ចេកទេស និងការឆ្លើយតបទៅខាងក្រៅ គួរផ្អែកលើ IFU នៃផលិតផលដែលពាក់ព័ន្ធ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16-Q01','PI-16','Product Information','Where can I find the sensitivity and specificity of the test card?','អាចរកភាពរសើប និងភាពជាក់លាក់របស់កាតតេស្តនៅឯណា?','In the IFU (Instructions for Use) of the corresponding product. Performance parameters may differ between products; technical confirmation and external replies should be based on the corresponding product''s IFU.','នៅក្នុង IFU (ឯកសារណែនាំការប្រើប្រាស់ - Instructions for Use) នៃផលិតផលនីមួយៗ។ ប៉ារ៉ាម៉ែត្រលទ្ធផលការងារអាចខុសគ្នារវាងផលិតផល។ ការបញ្ជាក់បច្ចេកទេស និងការឆ្លើយតបទៅខាងក្រៅ គួរផ្អែកលើ IFU នៃផលិតផលដែលពាក់ព័ន្ធ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16-Q02','PI-16','Product Information','What is the LOD of the card?','តើ LOD របស់កាតគឺប៉ុន្មាន?','Please check the IFU (Instructions for Use) of the corresponding product. Performance parameters may differ between products.','សូមពិនិត្យ IFU (ឯកសារណែនាំការប្រើប្រាស់ - Instructions for Use) នៃផលិតផលនីមួយៗ។ ប៉ារ៉ាម៉ែត្រលទ្ធផលការងារអាចខុសគ្នារវាងផលិតផល។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16-Q03','PI-16','Product Information','where LOD info','ព័ត៌មាន LOD នៅឯណា?','In the IFU (Instructions for Use) of the corresponding product. Performance parameters may differ between products; technical confirmation and external replies should be based on the corresponding product''s IFU.','នៅក្នុង IFU (ឯកសារណែនាំការប្រើប្រាស់ - Instructions for Use) នៃផលិតផលនីមួយៗ។ ប៉ារ៉ាម៉ែត្រលទ្ធផលការងារអាចខុសគ្នារវាងផលិតផល។ ការបញ្ជាក់បច្ចេកទេស និងការឆ្លើយតបទៅខាងក្រៅ គួរផ្អែកលើ IFU នៃផលិតផលដែលពាក់ព័ន្ធ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-16-Q04','PI-16','Product Information','Is the sensitivity the same for all Pluslife cards?','តើភាពរសើបដូចគ្នាសម្រាប់កាត Pluslife ទាំងអស់ទេ?','No. Performance parameters may differ between products; check the IFU of the corresponding product.','ទេ។ ប៉ារ៉ាម៉ែត្រលទ្ធផលការងារអាចខុសគ្នារវាងផលិតផល។ សូមពិនិត្យ IFU នៃផលិតផលដែលពាក់ព័ន្ធ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17','PI-17','Product Information','Worker asks how this test differs from an antigen (rapid) test','តេស្ត Pluslife ខុសពីតេស្តរហ័សរកអង់ទីហ្សែនត្រង់ណា?','Nucleic acid testing and antigen testing are two different methods. Compared with antigen testing, nucleic acid tests such as PCR and Pluslife have higher sensitivity: the target is continuously replicated during the test, so samples with very low viral load can be detected. Antigen tests detect proteins on the virus surface, which do not replicate or amplify, so more virus is needed for a positive result and false negatives are more common.','តេស្តអាស៊ីតនុយក្លេអ៊ីក និងតេស្តរកអង់ទីហ្សែន ជាវិធីពីរខុសគ្នា។ បើធៀបនឹងតេស្តរកអង់ទីហ្សែន តេស្តអាស៊ីតនុយក្លេអ៊ីក ដូចជា PCR និង Pluslife មានភាពរសើបខ្ពស់ជាង៖ គោលដៅត្រូវបានចម្លងជាបន្តបន្ទាប់ពេលធ្វើតេស្ត ដូច្នេះអាចរកឃើញសំណាកដែលមានបរិមាណមេរោគទាបខ្លាំង។ តេស្តរកអង់ទីហ្សែន រកប្រូតេអ៊ីននៅលើផ្ទៃមេរោគ ដែលមិនចម្លង ឬពង្រីកខ្លួនទេ ដូច្នេះត្រូវការមេរោគច្រើនជាង ដើម្បីបានលទ្ធផលវិជ្ជមាន ហើយលទ្ធផលអវិជ្ជមានក្លែងក្លាយកើតមានញឹកញាប់ជាង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17-Q01','PI-17','Product Information','What is the difference between this test and an antigen test?','តើតេស្តនេះ និងតេស្តរកអង់ទីហ្សែន ខុសគ្នាដូចម្តេច?','Nucleic acid testing and antigen testing are two different methods. Compared with antigen testing, nucleic acid tests such as PCR and Pluslife have higher sensitivity: the target is continuously replicated during the test, so samples with very low viral load can be detected. Antigen tests detect proteins on the virus surface, which do not replicate or amplify, so more virus is needed for a positive result and false negatives are more common.','តេស្តអាស៊ីតនុយក្លេអ៊ីក និងតេស្តរកអង់ទីហ្សែន ជាវិធីពីរខុសគ្នា។ បើធៀបនឹងតេស្តរកអង់ទីហ្សែន តេស្តអាស៊ីតនុយក្លេអ៊ីក ដូចជា PCR និង Pluslife មានភាពរសើបខ្ពស់ជាង៖ គោលដៅត្រូវបានចម្លងជាបន្តបន្ទាប់ពេលធ្វើតេស្ត ដូច្នេះអាចរកឃើញសំណាកដែលមានបរិមាណមេរោគទាបខ្លាំង។ តេស្តរកអង់ទីហ្សែន រកប្រូតេអ៊ីននៅលើផ្ទៃមេរោគ ដែលមិនចម្លង ឬពង្រីកខ្លួនទេ ដូច្នេះត្រូវការមេរោគច្រើនជាង ដើម្បីបានលទ្ធផលវិជ្ជមាន ហើយលទ្ធផលអវិជ្ជមានក្លែងក្លាយកើតមានញឹកញាប់ជាង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17-Q02','PI-17','Product Information','Is Pluslife more sensitive than a rapid antigen test?','តើ Pluslife រសើបជាងតេស្តរហ័សរកអង់ទីហ្សែនទេ?','Yes. Compared with antigen testing, nucleic acid tests such as PCR and Pluslife have higher sensitivity: the target is continuously replicated during the test, so samples with very low viral load can be detected.','បាទ/ចាស។ បើធៀបនឹងតេស្តរកអង់ទីហ្សែន តេស្តអាស៊ីតនុយក្លេអ៊ីក ដូចជា PCR និង Pluslife មានភាពរសើបខ្ពស់ជាង៖ គោលដៅត្រូវបានចម្លងជាបន្តបន្ទាប់ពេលធ្វើតេស្ត ដូច្នេះអាចរកឃើញសំណាកដែលមានបរិមាណមេរោគទាបខ្លាំង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17-Q03','PI-17','Product Information','Is Pluslife an antigen test?','តើ Pluslife ជាតេស្តរកអង់ទីហ្សែនទេ?','No. Pluslife is a nucleic acid test. Nucleic acid testing and antigen testing are two different methods. Compared with antigen testing, nucleic acid tests such as PCR and Pluslife have higher sensitivity: the target is continuously replicated during the test, so samples with very low viral load can be detected. Antigen tests detect proteins on the virus surface, which do not replicate or amplify, so more virus is needed for a positive result and false negatives are more common.','ទេ។ Pluslife ជាតេស្តអាស៊ីតនុយក្លេអ៊ីក។ តេស្តអាស៊ីតនុយក្លេអ៊ីក និងតេស្តរកអង់ទីហ្សែន ជាវិធីពីរខុសគ្នា។ បើធៀបនឹងតេស្តរកអង់ទីហ្សែន តេស្តអាស៊ីតនុយក្លេអ៊ីក ដូចជា PCR និង Pluslife មានភាពរសើបខ្ពស់ជាង៖ គោលដៅត្រូវបានចម្លងជាបន្តបន្ទាប់ពេលធ្វើតេស្ត ដូច្នេះអាចរកឃើញសំណាកដែលមានបរិមាណមេរោគទាបខ្លាំង។ តេស្តរកអង់ទីហ្សែន រកប្រូតេអ៊ីននៅលើផ្ទៃមេរោគ ដែលមិនចម្លង ឬពង្រីកខ្លួនទេ ដូច្នេះត្រូវការមេរោគច្រើនជាង ដើម្បីបានលទ្ធផលវិជ្ជមាន ហើយលទ្ធផលអវិជ្ជមានក្លែងក្លាយកើតមានញឹកញាប់ជាង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('PI-17-Q04','PI-17','Product Information','why antigen test more false negative','ហេតុអ្វីតេស្តរកអង់ទីហ្សែន មានអវិជ្ជមានក្លែងក្លាយច្រើនជាង?','Antigen tests detect proteins on the virus surface, which do not replicate or amplify, so more virus is needed for a positive result and false negatives are more common.','តេស្តរកអង់ទីហ្សែន រកប្រូតេអ៊ីននៅលើផ្ទៃមេរោគ ដែលមិនចម្លង ឬពង្រីកខ្លួនទេ ដូច្នេះត្រូវការមេរោគច្រើនជាង ដើម្បីបានលទ្ធផលវិជ្ជមាន ហើយលទ្ធផលអវិជ្ជមានក្លែងក្លាយកើតមានញឹកញាប់ជាង។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-01','QC-01','Quality Control','Worker asks for the QC video','មានវីដេអូបង្ហាញរបៀបធ្វើតេស្តត្រួតពិនិត្យគុណភាព (QC) ទេ?','https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','មើលឯកសារណែនាំ ឬវីដេអូតាមតំណនេះ៖ https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-01-Q01','QC-01','Quality Control','Is there a video on how to run QC?','តើមានវីដេអូអំពីរបៀបធ្វើ QC ទេ?','Yes: https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','បាទ/ចាស មាន៖ https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-01-Q02','QC-01','Quality Control','qc video','មានវីដេអូបង្ហាញរបៀបធ្វើ QC ទេ?','https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','មើលឯកសារណែនាំ ឬវីដេអូតាមតំណនេះ៖ https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-01-Q03','QC-01','Quality Control','How to run a quality control?','តើធ្វើការត្រួតពិនិត្យគុណភាព (QC) យ៉ាងម៉េច?','Video: https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','វីដេអូ៖ https://youtu.be/ercC1sav7-M?si=DTzfXa8UYWWIE49Y','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02','QC-02','Quality Control','Worker asks what QC is for and when to run it','ការធ្វើ QC មានប្រយោជន៍អ្វី ហើយត្រូវធ្វើពេលណា?','QC is used to monitor whether the experimental procedures are performed correctly, whether the reagents remain stable, whether the instrument is functioning properly, and whether there is any environmental contamination.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q01','QC-02','Quality Control','Does Pluslife have quality controls?','តើ Pluslife មានសម្ភារៈត្រួតពិនិត្យគុណភាព (QC) ទេ?','Yes. QC is used to monitor whether the experimental procedures are performed correctly, whether the reagents remain stable, whether the instrument is functioning properly, and whether there is any environmental contamination.','បាទ/ចាស។ QC (ការត្រួតពិនិត្យគុណភាព) ប្រើដើម្បីតាមដានថា នីតិវិធីពិសោធន៍ត្រូវបានអនុវត្តត្រឹមត្រូវឬទេ សារធាតុនៅមានស្ថិរភាពឬទេ ម៉ាស៊ីនដំណើរការបានល្អឬទេ និងមានការចម្លងរោគពីបរិស្ថានឬទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q02','QC-02','Quality Control','When do I need to run QC?','តើខ្ញុំត្រូវធ្វើ QC នៅពេលណា?','If there are no specific requirements, QC testing is recommended when changing kit batches, during annual instrument performance checks, and when laboratory contamination is suspected.','បើគ្មានតម្រូវការជាក់លាក់ទេ ណែនាំឱ្យធ្វើ QC ពេលប្តូរឡូត៍ (batch) កញ្ចប់តេស្ត ពេលពិនិត្យលទ្ធផលការងារម៉ាស៊ីនប្រចាំឆ្នាំ និងពេលសង្ស័យមានការចម្លងរោគក្នុងមន្ទីរពិសោធន៍។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q03','QC-02','Quality Control','Do I need QC every day?','តើខ្ញុំត្រូវធ្វើ QC រាល់ថ្ងៃទេ?','Not sure — it depends on the specific requirements and management protocols of the laboratory. If there are none, QC is recommended when changing kit batches, during annual instrument checks, and when contamination is suspected.','មិនប្រាកដទេ — វាអាស្រ័យលើតម្រូវការជាក់លាក់ និងពិធីការគ្រប់គ្រងរបស់មន្ទីរពិសោធន៍។ បើគ្មានទេ ណែនាំឱ្យធ្វើ QC ពេលប្តូរឡូត៍ (batch) កញ្ចប់តេស្ត ពេលពិនិត្យម៉ាស៊ីនប្រចាំឆ្នាំ និងពេលសង្ស័យមានការចម្លងរោគ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q04','QC-02','Quality Control','New kit batch arrived. Should I run QC?','កញ្ចប់តេស្តឡូត៍ថ្មីមកដល់។ តើខ្ញុំគួរធ្វើ QC ទេ?','Yes. QC testing is recommended when changing kit batches.','បាទ/ចាស។ ណែនាំឱ្យធ្វើ QC ពេលប្តូរឡូត៍ (batch) កញ្ចប់តេស្ត។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-02-Q05','QC-02','Quality Control','what qc for','QC សម្រាប់អ្វី?','QC is used to monitor whether the experimental procedures are performed correctly, whether the reagents remain stable, whether the instrument is functioning properly, and whether there is any environmental contamination.','QC (ការត្រួតពិនិត្យគុណភាព) ប្រើដើម្បីតាមដានថា នីតិវិធីពិសោធន៍ត្រូវបានអនុវត្តត្រឹមត្រូវឬទេ សារធាតុនៅមានស្ថិរភាពឬទេ ម៉ាស៊ីនដំណើរការបានល្អឬទេ និងមានការចម្លងរោគពីបរិស្ថានឬទេ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03','QC-03','Quality Control','Worker asks what the QC material is, how to store it, or what is in a set','សម្ភារៈ QC មួយឈុតមានអ្វីខ្លះ ហើយត្រូវទុកដោយរបៀបណា?','The quality control material is a plasmid in lyophilized microsphere form, and should be stored at 2–28 °C, valid for 13 months.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q01','QC-03','Quality Control','Is the QC material a plasmid or real bacteria?','តើសម្ភារៈ QC ជាប្លាស្មីត (plasmid) ឬបាក់តេរីពិត?','The quality control material is a plasmid in lyophilized microsphere form.','សម្ភារៈត្រួតពិនិត្យគុណភាព គឺជាប្លាស្មីត (plasmid) ក្នុងទម្រង់គ្រាប់ស្ងួត (lyophilized microsphere)។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q02','QC-03','Quality Control','How do I store the QC?','តើខ្ញុំរក្សាទុក QC យ៉ាងម៉េច?','Store at 2–28 °C; valid for 13 months.','រក្សាទុកនៅ 2–28 °C។ មានសុពលភាព 13 ខែ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q03','QC-03','Quality Control','What is in one QC set?','តើក្នុង QC មួយឈុតមានអ្វីខ្លះ?','1 set = 1 positive and 1 negative control.','1 ឈុត = សំណាកត្រួតពិនិត្យវិជ្ជមាន 1 និងអវិជ្ជមាន 1។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q04','QC-03','Quality Control','qc expire','QC ផុតកំណត់។ ត្រូវធ្វើម៉េច?','Valid for 13 months.','មានសុពលភាព 13 ខែ។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-03-Q05','QC-03','Quality Control','Can I keep the QC at 35 °C?','អាចទុក QC នៅ 35 °C បានទេ?','No. The QC material should be stored at 2–28 °C.','មិនបានទេ។ សម្ភារៈ QC គួររក្សាទុកនៅ 2–28 °C។','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-04','QC-04','Quality Control','Worker wants to test another company''s QC material on Pluslife','អាចប្រើសម្ភារៈ QC របស់ក្រុមហ៊ុនផ្សេងជាមួយ Pluslife បានទេ?','It is not recommended, as the target sequence of quality control materials from other manufacturers may differ from the target region used by Pluslife. Additionally, the preservation medium may contain components that inhibit Pluslife amplification.','មិនណែនាំទេ ព្រោះលំដាប់គោលដៅនៃសម្ភារៈត្រួតពិនិត្យគុណភាពរបស់ក្រុមហ៊ុនផលិតផ្សេង អាចខុសពីតំបន់គោលដៅដែល Pluslife ប្រើ។ លើសពីនេះ មជ្ឈដ្ឋានរក្សាទុក (preservation medium) អាចមានសារធាតុដែលរារាំងការពង្រីករបស់ Pluslife។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-04-Q01','QC-04','Quality Control','Can I use QC from another company with Pluslife cards?','អាចប្រើ QC របស់ក្រុមហ៊ុនផ្សេង ជាមួយកាត Pluslife បានទេ?','No. It is not recommended, as the target sequence of quality control materials from other manufacturers may differ from the target region used by Pluslife. Additionally, the preservation medium may contain components that inhibit Pluslife amplification.','មិនបានទេ។ មិនណែនាំទេ ព្រោះលំដាប់គោលដៅនៃសម្ភារៈត្រួតពិនិត្យគុណភាពរបស់ក្រុមហ៊ុនផលិតផ្សេង អាចខុសពីតំបន់គោលដៅដែល Pluslife ប្រើ។ លើសពីនេះ មជ្ឈដ្ឋានរក្សាទុក (preservation medium) អាចមានសារធាតុដែលរារាំងការពង្រីករបស់ Pluslife។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-04-Q02','QC-04','Quality Control','other brand control ok?','សំណាកត្រួតពិនិត្យម៉ាកផ្សេង បានទេ?','No. It is not recommended, as the target sequence of quality control materials from other manufacturers may differ from the target region used by Pluslife. Additionally, the preservation medium may contain components that inhibit Pluslife amplification.','មិនបានទេ។ មិនណែនាំទេ ព្រោះលំដាប់គោលដៅនៃសម្ភារៈត្រួតពិនិត្យគុណភាពរបស់ក្រុមហ៊ុនផលិតផ្សេង អាចខុសពីតំបន់គោលដៅដែល Pluslife ប្រើ។ លើសពីនេះ មជ្ឈដ្ឋានរក្សាទុក (preservation medium) អាចមានសារធាតុដែលរារាំងការពង្រីករបស់ Pluslife។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-04-Q03','QC-04','Quality Control','Why doesn''t the Xpert control work on Pluslife?','ហេតុអ្វីបានជាសំណាកត្រួតពិនិត្យ Xpert មិនដំណើរការលើ Pluslife?','Not sure for that specific control. In general, QC materials from other manufacturers may have a different target sequence from the Pluslife target region, and the preservation medium may contain components that inhibit Pluslife amplification.','មិនប្រាកដសម្រាប់សំណាកត្រួតពិនិត្យជាក់លាក់នោះទេ។ ជាទូទៅ សម្ភារៈ QC របស់ក្រុមហ៊ុនផលិតផ្សេង អាចមានលំដាប់គោលដៅខុសពីតំបន់គោលដៅរបស់ Pluslife ហើយមជ្ឈដ្ឋានរក្សាទុក (preservation medium) អាចមានសារធាតុដែលរារាំងការពង្រីករបស់ Pluslife។','Routine','Study team');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05','QC-05','Quality Control','Worker asks how to run QC and read the QC result','ត្រូវធ្វើ QC ដោយរបៀបណា ហើយមើលម៉េចដឹងថាលទ្ធផលត្រឹមត្រូវ?','1. Transfer the lyophilized bead into a Releasing Agent and mix well.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q01','QC-05','Quality Control','How do I do a QC test?','តើខ្ញុំធ្វើតេស្ត QC យ៉ាងម៉េច?','1. Transfer the lyophilized bead into a Releasing Agent and mix well.
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q02','QC-05','Quality Control','Is there a special QC mode on the Ultra?','តើ Ultra មានរបៀប QC ពិសេសទេ?','No. For PM001 Ultra, just run the QC test as a sample.','ទេ។ សម្រាប់ PM001 Ultra គ្រាន់តែធ្វើតេស្ត QC ដូចសំណាកធម្មតា។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q03','QC-05','Quality Control','How do I know the QC passed?','តើខ្ញុំដឹងយ៉ាងម៉េចថា QC ជាប់?','The positive control must yield a positive result, and the negative control must yield a negative result.','សំណាកត្រួតពិនិត្យវិជ្ជមាន ត្រូវតែចេញលទ្ធផលវិជ្ជមាន ហើយសំណាកត្រួតពិនិត្យអវិជ្ជមាន ត្រូវតែចេញលទ្ធផលអវិជ្ជមាន។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q04','QC-05','Quality Control','Negative control came out positive.','សំណាកត្រួតពិនិត្យអវិជ្ជមាន ចេញលទ្ធផលវិជ្ជមាន។ ត្រូវធ្វើម៉េច?','The QC did not pass: the negative control must yield a negative result.','QC មិនជាប់ទេ៖ សំណាកត្រួតពិនិត្យអវិជ្ជមាន ត្រូវតែចេញលទ្ធផលអវិជ្ជមាន។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('QC-05-Q05','QC-05','Quality Control','qc bead how','គ្រាប់ QC ធ្វើម៉េច?','Transfer the lyophilized bead into a Releasing Agent and mix well, then transfer the Releasing Agent to the card.','ផ្ទេរគ្រាប់សារធាតុស្ងួត (lyophilized bead) ចូលក្នុង Releasing Agent ហើយលាយឱ្យសព្វ រួចផ្ទេរ Releasing Agent ចូលកាត។','Routine','Study focal point → Pluslife');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-02','TR-02','Training Resources','Worker asks for the sample collection operation video','មានវីដេអូបង្ហាញរបៀបស្រង់សំណាកទេ?','https://youtu.be/MsYQhpQ-m8Y?si=8P56NfJE_V60hEBH','មើលឯកសារណែនាំ ឬវីដេអូតាមតំណនេះ៖ https://youtu.be/MsYQhpQ-m8Y?si=8P56NfJE_V60hEBH','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-02-Q01','TR-02','Training Resources','Is there a video for sample collection?','តើមានវីដេអូសម្រាប់ការស្រង់សំណាកទេ?','Yes: https://youtu.be/MsYQhpQ-m8Y?si=8P56NfJE_V60hEBH','បាទ/ចាស មាន៖ https://youtu.be/MsYQhpQ-m8Y?si=8P56NfJE_V60hEBH','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-02-Q02','TR-02','Training Resources','operation video','មានវីដេអូបង្ហាញរបៀបស្រង់សំណាកទេ?','https://youtu.be/MsYQhpQ-m8Y?si=8P56NfJE_V60hEBH','មើលឯកសារណែនាំ ឬវីដេអូតាមតំណនេះ៖ https://youtu.be/MsYQhpQ-m8Y?si=8P56NfJE_V60hEBH','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-02-Q03','TR-02','Training Resources','send me the sampling video','ផ្ញើវីដេអូស្រង់សំណាកមកខ្ញុំ','https://youtu.be/MsYQhpQ-m8Y?si=8P56NfJE_V60hEBH','មើលឯកសារណែនាំ ឬវីដេអូតាមតំណនេះ៖ https://youtu.be/MsYQhpQ-m8Y?si=8P56NfJE_V60hEBH','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-03','TR-03','Training Resources','Worker asks how to run a test (operation flow video)','មានវីដេអូបង្ហាញជំហានធ្វើតេស្ត Pluslife ទាំងអស់ទេ?','MTB: https://youtu.be/BT2BGlf3H8M?si=epbdfg7u8KmyvHx9','មើលឯកសារណែនាំ ឬវីដេអូតាមតំណនេះ៖ MTB: https://youtu.be/BT2BGlf3H8M?si=epbdfg7u8KmyvHx9','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-03-Q01','TR-03','Training Resources','How do I run a test? Is there a video?','តើខ្ញុំធ្វើតេស្តយ៉ាងម៉េច? មានវីដេអូទេ?','MTB: https://youtu.be/BT2BGlf3H8M?si=epbdfg7u8KmyvHx9','មើលឯកសារណែនាំ ឬវីដេអូតាមតំណនេះ៖ MTB: https://youtu.be/BT2BGlf3H8M?si=epbdfg7u8KmyvHx9','Routine','Study focal point (if not solved)');
INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-03-Q02','TR-03','Training Resources','test operation flow','លំដាប់ប្រតិបត្តិតេស្ត','MTB: https://youtu.be/BT2BGlf3H8M?si=epbdfg7u8KmyvHx9','មើលឯកសារណែនាំ ឬវីដេអូតាមតំណនេះ៖ MTB: https://youtu.be/BT2BGlf3H8M?si=epbdfg7u8KmyvHx9','Routine','Study focal point (if not solved)');
