INSERT INTO kb_qa (id,issue_id,category,question_en,question_km,answer_en,answer_km,priority,escalate_to) VALUES ('TR-04-Q03','TR-04','Training Resources','Is there a written guide for fixing device problems?','តើមានមគ្គុទ្ទេសក៍ជាលាយលក្ខណ៍អក្សរ សម្រាប់ដោះស្រាយបញ្ហាម៉ាស៊ីនទេ?','Yes. Pluslife MTB System Maintenance and Troubleshooting Protocol: https://docs.google.com/document/d/1D9181kvtKWy0w7Bp9Dw8-YpvUhrRKUWq/edit?usp=sharing&ouid=111148453576100834916&rtpof=true&sd=true','បាទ/ចាស មាន។ ពិធីការថែទាំ និងដោះស្រាយបញ្ហាប្រព័ន្ធ Pluslife MTB (Pluslife MTB System Maintenance and Troubleshooting Protocol)៖ https://docs.google.com/document/d/1D9181kvtKWy0w7Bp9Dw8-YpvUhrRKUWq/edit?usp=sharing&ouid=111148453576100834916&rtpof=true&sd=true','Routine','Study focal point (if not solved)');
